update content_bodies set title = 'Life of Migrants: Living in Satoyama | What is Migration? | Happy Life of Migrants | Kumano | Rural Migration | Sustainable', description = 'Oroshi, located in Mihama Town, Mie Prefecture, is an area with a high number of migrants. Thanks to the beautiful satoyama landscape and the warm welcome from local residents, many people have moved from urban areas in recent years. During a visit to Oroshi, I encountered a scene filled with happiness: children playing in nature and adults enjoying activities they couldn''t do in the city. The residents of Oroshi appear enviable even to us migrants. Mihama Town, located on the Pacific coast of the Kii Peninsula, is known for its year-round production of various citrus fruits, thanks to the warm climate and the Kuroshio Current. The town is a place where the blue mountains meet the blue sea, and it is considered a sacred area where spirits reside, offering a sense of renewal to visitors.' where id = '4O3yQinIUsVBBMWUCgHfn';
update content_bodies set title = '【移住者の暮らし】噂のジビエ肉？｜猟師の友人がくれた、ジビエで1番美味しいと噂のアナグマを食す', description = '三重県御浜町での田舎暮らしを紹介するこのエピソードでは、猟師の友人からアナグマをもらった著者が、その調理を始める様子が描かれています。猪の生ハムや鹿肉の燻製を作る準備をしながら、アナグマの独特な香りとラム肉のような味わいに期待を寄せています。アナグマはクミン塩で食べると絶品だとされ、御浜町は温暖な気候と豊かな自然に恵まれ、みかんが一年中収穫できる地域です。熊野の神秘的な山々と太平洋が出会うこの町は、訪れる人々に心の再生をもたらす場所とされています。' where id = 'vcyN3u_gq7Xp30dDOKlAj';
update content_bodies set title = 'Life of Migrants: Tasting the Rumored Delicious Game Meat - Badger from a Hunter Friend', description = 'In this episode, the author shares their experience of living in Mihama, Mie Prefecture, where they received a badger from a hunter friend. The author prepares to make prosciutto from wild boar and smoked venison while excitedly anticipating the unique flavor of the badger, which is said to be the best game meat. The badger is described as having a distinct aroma reminiscent of lamb, and it is best enjoyed with cumin salt. Mihama is located on the Pacific coast of the Kii Peninsula, known for its warm climate and abundant citrus fruits. The area is rich in natural beauty, with the sacred Kumano mountains and the Pacific Ocean meeting, making it a place of spiritual renewal.' where id = '_fbwA686C0VD7dQkfGpEI';
update content_bodies set title = '【移住者の暮らし】猪と鹿を燻製にする｜ジビエの燻製に初挑戦｜熊野｜地方移住｜サステナブル', description = 'この動画では、田舎暮らしの日常を紹介し、友人の猟師から貰った猪肉と鹿肉の燻製作りに挑戦します。猪肉は1ヶ月塩漬けした後、段ボール製のスモークマシーンで約4時間燻製し、さらに約2年間熟成させる予定です。舞台は三重県御浜町で、年中みかんが収穫できる美しい太平洋沿いの町です。この地域は自然の美しさと文化的な重要性を持ち、神聖な場所とされています。月に2本の動画をアップする予定で、視聴者にはいいねやコメント、チャンネル登録を促しています。' where id = '3zhsEJ_y2bss1zaxSqPRd';
update content_bodies set title = 'Living as a Migrant: Smoking Wild Boar and Deer - First Challenge with Game Meat - Kumano - Rural Relocation - Sustainable', description = 'This video showcases a day in the life of rural living in Japan, focusing on the process of making smoked wild boar and deer meat. The author receives the meat from a friend who is a hunter and follows a traditional method: salting the boar meat for a month, then smoking it for about four hours using a homemade cardboard smoke machine, with plans for a two-year aging process. The setting is Mihama Town in Mie Prefecture, known for its year-round mandarin oranges and beautiful coastal scenery along the Pacific Ocean. The region is rich in natural beauty and cultural significance, often referred to as a sacred place where spirits reside. The author plans to upload videos twice a month and encourages viewers to like, comment, and subscribe.' where id = '2GWCgtwZWaC1MotI0b-Gb';
update content_bodies set title = '移住者の暮らし：熊野での平凡な日常に見出す幸せ', description = 'この物語は、東京から三重県御浜町に移住した著者が、熊野での田舎暮らしの中で感じた日常の喜びを探求しています。朝は自然の音で目覚め、予期しないトラブルに巻き込まれながらも、庭にある茶の木を見つけることから始まります。著者は、サステナブルな暮らしの重要性を強調しつつ、田舎暮らしに適応する難しさも認めています。人生の複雑さにもかかわらず、平凡な日常を受け入れることに満足感を見出しています。パンデミックの最中に御浜町に移住する決断を下したことは、事前のつながりがない場所に定住する勇気を示しています。著者は、神聖な力を持つとされる熊野を訪れ、特別な冒険を体験することを他者に呼びかけています。' where id = '25iHJ0NW3Iqx-mME2Tu-g';
update content_bodies set title = 'Living as a Migrant in Kumano: A Daily Life Where Happiness is Found in Ordinary Moments', description = 'This narrative explores the simple joys of rural life in Kumano, where the author reflects on their experiences after moving from Tokyo to Mihama Town. The day begins with the sounds of nature, leading to unexpected challenges and the discovery of tea trees in the garden. The author emphasizes the importance of sustainable living while acknowledging the difficulties of adapting to rural life. Despite the complexities of life, there is a sense of fulfillment in embracing the ordinary. The decision to move to Mihama was made during the pandemic, highlighting the courage it took to settle in a place with no prior connections. The author invites others to visit Kumano, a place believed to possess sacred power, and to experience the unique adventures it offers.' where id = 'C-6X6MytYQCsnzm-4Lmyf';
update content_bodies set title = '移住直後 田舎で友達ができた日', description = '2020年7月、東京から三重県御浜町に移住しました。2週間の外出自粛を経て、ようやく普通の生活に戻り始めました。その中で、地元の人たちがBBQパーティーを企画してくれ、コロナの影響で夏を楽しめなかった気持ちが和らぎました。移住先探しは1月から始まり、3月には御浜町を訪れることができましたが、その後は他の場所を訪問できず、運命的な出会いを感じて移住を決断しました。縁も所縁もない町への移住は勇気がいりましたが、探し続けると何年もかかると思い、思い切って決めました。御浜町は自然と精神性に満ちた神聖な場所であり、ここでの経験を通じて人生の意味を探求したいと思っています。' where id = '98PEWUsYB2swQZHCy77Zy';
update content_bodies set title = 'A Day When I Made Friends in the Countryside Right After Moving', description = 'In July 2020, I moved from Tokyo to Mihama Town in Mie Prefecture. After a two-week period of self-isolation, I finally began to return to normal life. During this time, the locals organized a BBQ party for us, which made me feel like I had caught up with summer after feeling left out due to COVID-19 restrictions. I had started searching for a place to move in January, and I was fortunate to visit Mihama and the surrounding areas just before the lockdown in March. Despite the challenges of not being able to visit other locations afterward, I decided to move to Mihama, a town I had only briefly visited. This decision took courage, but I felt that continuing to search would delay my move for years. Mihama is known as a sacred place, rich in nature and spirituality, and I hope to explore its meaning of life through my experiences here.' where id = 'DRdkvLP-_fMwzH0hilzyb';
update content_bodies set title = '母からの贈り物｜母親からの小包｜田舎暮らし｜熊野｜地方移住｜サステナブル', description = '2020年7月、東京から三重県御浜町に移住しました。2週間の外出自粛を経て、ようやく普通の生活に戻り始めました。そんな中、母からの小包が届き、母の愛を改めて感じました。今年1月から移住先を探し始め、コロナの影響で訪問が難しい中、運良く3月に御浜町を訪れることができました。数時間の訪問で移住を決断するのは勇気がいりましたが、探し続けると何年もかかると思い、思い切って決めました。御浜町は神聖な場所であり、ここで人生の意味を見つけたいと思っています。今後、週1回または2週間に1本の動画をアップする予定で、インスタグラムも始めました。' where id = 'sFvUb235Gy3OIxH7ckrf8';
update content_bodies set title = 'A Gift from My Mother: A Parcel Filled with Love', description = 'In July 2020, I moved from Tokyo to Mihama Town in Mie Prefecture. After a two-week period of self-isolation, life began to feel normal again. One day, I received a parcel from my mother, which made me appreciate her love even more during these challenging times. I started searching for a new place to live in January, and despite the pandemic limiting my visits, I was fortunate to explore Mihama and the surrounding areas in March. Deciding to move to a town I had only briefly visited took courage, but I felt that continuing the search would delay my relocation for years. Mihama is known as a sacred place, rich in spiritual significance, and I hope to find meaning in life here. I plan to upload videos weekly or bi-weekly about my experiences and have also started an Instagram account.' where id = 'nLrfD7LequQE9wCKIXEmR';
update content_bodies set title = '移住初日：東京から三重へ', description = '2020年7月、東京から三重県御浜町へ移住しました。この動画では新しい田舎暮らしの初日を紹介します。移住先探しは1月から始まりましたが、コロナの影響で訪問が難しくなりました。幸運にも3月に御浜町で運命的な出会いがあり、短時間の訪問にもかかわらず町に魅了されました。縁も所縁もない町への移住を決断するのは勇気がいりましたが、探し続けると何年もかかると思い、思い切って新しい生活を始めることにしました。御浜町は静かな場所で、豊かな精神的雰囲気があり、その意味や美しさをさらに探求していきたいと思っています。' where id = '_8dzocecZouSAvxyPeHpj';
update content_bodies set title = 'A New Chapter Begins: Moving from Tokyo to Mie', description = 'In July 2020, we moved from Tokyo to Mihama, Mie Prefecture. This video captures our first day in this new rural life. Our search for a new home began in January, but due to COVID-19, we faced challenges visiting potential locations. Fortunately, we had a serendipitous encounter in Mihama in March, which led us to fall in love with the town despite only a brief visit. Making the decision to move to a place with no prior connections was daunting, but we felt that continuing the search would delay our relocation for years. Thus, we embraced this new chapter in our lives. Mihama is a serene place with a rich spiritual atmosphere, and we hope to explore its meaning and beauty further.' where id = 'WaSmZ-jU-ban-Z3yBfrAt';
update content_bodies set title = '【田舎の物語】ばあちゃんのみかん畑', description = '御浜町に移住する前は、青いみかんがあることすら知りませんでした。御浜町の強い夏の日差しの下で育った超極早生温州みかんは、糖度が高く、甘みと酸味の絶妙なバランスが特徴です。今年は天候が良く、みかんの日焼けが心配されましたが、無事に収穫が始まりました。みかんの表面の白い斑点は、ホワイトコートというカルシウム由来の日焼け防止剤です。御浜町では、年中さまざまな種類のみかんが出荷され、まさにみかんの町です。ちせ農園は92歳のばあちゃんから3年前に孫に受け継がれた農園で、家族総出での収穫の様子はこの町の家族の姿を象徴しています。みかんを収穫する際のハサミの音は心地よく、御浜町の秋の音を感じさせます。' where id = 'NjjlkrVzT2sHXyZwox9ut';
update content_bodies set title = 'The Story of the Countryside: Grandma''s Mandarin Orchard', description = 'Before moving to Mihama, I had no idea that blue mandarins existed. The ultra-early mikan, harvested from early September under the strong summer sun of Mihama, is known for its high sugar content due to the sunlight. The balance of sweetness and acidity makes these mandarins exceptionally delicious. This year, despite concerns about sunburn on the fruit, the harvest has begun successfully. The white spots on the surface of the mandarins are a calcium-based sunburn prevention agent called White Coat. Mihama produces various types of mandarins throughout the year, making it a town where mandarins are always available. The Chise farm, which has been passed down from a 92-year-old grandmother to her grandchild three years ago, captures the essence of family and tradition in the harvesting process. The sound of scissors during the harvest is a comforting reminder of autumn in Mihama, and the family working together embodies the spirit of this agricultural community.' where id = 'gf9a_YgHHteWXz8rW4svE';
update content_bodies set title = '移住のキッカケ: 移住を促したお米を作る農家に会いに行く', description = 'この物語は、三重県御浜町の農家を訪れた著者の体験を中心に展開され、移住のきっかけとなった出来事を描いています。3月の訪問時に農家から頂いたお米は非常に美味しく、地元の水で炊いたらさらに美味しくなるのではないかという疑問が生まれました。移住後、偶然にもその農家が著者の家族とつながっていることが判明し、稲刈りの様子を見学することができました。この経験は思い出深く、地元の水でお米を炊くという目標も達成し、日本の田舎生活の美しさを再確認する機会となりました。' where id = 'Iw0Co4HKPas5FJTFD2wCY';
update content_bodies set title = 'The Trigger for Relocation: Visiting a Rice Farmer Who Inspired My Move', description = 'This narrative revolves around the author''s experience of visiting a rice farmer in Mihama, Mie, Japan, which sparked their desire to relocate. During a previous visit in March, the author received rice from the farmer, which was exceptionally delicious. This led to a curiosity about cooking the rice with the local water, believing it would enhance the flavor. After moving, the author discovered that the farmer was connected to their family, allowing them to witness the rice harvesting process. The experience was memorable, fulfilling the goal of cooking the rice with local water, and highlighting the beauty of rural life in Japan.' where id = '4cnv4_1VwUhmpBaTLetzu';
update content_bodies set title = '移住を決めた風景 - 凪のあすから聖地巡礼', description = '移住地を探すために東紀州エリアを訪れ、一目惚れした風景に出会いました。この風景との出会いが、私たちの移住の決断につながったと思います。アニメ『凪のあすから』のモデルとなった波田須駅周辺は美しく、今でも多くの聖地巡礼者が訪れています。私たちは、勝手にトロロの木と名付けた大きなクスノキの下で広がる、波田須のリリカルな田舎の日常に魅了されました。熊野は「よみがえりの地」として知られ、精神的な歴史が豊かで、人々が心を癒すことができる神聖な場所とされています。私たちは2020年7月に三重県御浜町に移住し、東京、大阪、千葉での都会生活を経て田舎暮らしを始めました。' where id = 'JMWkCyKbCQSDD9gGW7dJV';
update content_bodies set title = 'The Scenery That Led to Our Move - Pilgrimage to the Sacred Sites of ''Nagi no Asukara''', description = 'We visited the East Kii Peninsula to find a place to settle and fell in love at first sight with the scenery. This encounter led us to decide to move to this area. The surroundings of Hadasu Station, which served as a model for the anime ''Nagi no Asukara'', are beautiful and still attract many pilgrims. We were captivated by the lyrical rural daily life under a large camphor tree, which we affectionately named the Totoro Tree. Kumano, known as the ''land of resurrection'', has a rich spiritual history and is considered a sacred place where people can rejuvenate their spirits. We moved to Mihama Town in Mie Prefecture in July 2020, seeking a rural lifestyle after enjoying urban life in Tokyo, Osaka, and Chiba.' where id = 'oB1JFdJNevPd_6Lo5gBvL';
update content_bodies set title = '移住した理由：都会から田舎への夫婦の旅', description = '紀伊半島の南端に位置する三重県御浜町は、都会の東京から移住した夫婦にとって、穏やかでリリカルな日常を提供しています。彼らは、よりセンチメンタルな生活を求めて田舎暮らしを選びましたが、これはすべての人に合うわけではありません。しかし、彼らにとっては喜びをもたらしています。2020年7月に移住してから、生活が落ち着き、彼らは新しい生活を共有するために動画を作成することに意欲的です。移住活動は1月に始まり、6ヶ月後にこの地での生活を始めたことに感謝しています。彼らは、御浜町の美しさと静けさを探求することを他の人々に勧めており、この地域の精神的な重要性や自己反省の機会を強調しています。彼らのコンテンツは、日本の田舎生活の本質を描写し、人生の意味や熊野での冒険を考えるきっかけを提供することを目指しています。' where id = '_qFKQncLzA8wzvMv22Ez8';
update content_bodies set title = 'Reasons for Moving: A Couple''s Journey from City to Countryside', description = 'Mihama Town, located in the southern part of the Kii Peninsula in Japan, has provided a serene and lyrical daily life for a couple who moved there from urban Tokyo. They made the decision to embrace rural living for a more sentimental lifestyle, which may not appeal to everyone but has brought them joy. After moving in July 2020, they have settled into their new life and are eager to share their experiences through videos. The couple reflects on their journey, which began with a search for rural living in January, and they express gratitude for the peaceful environment of Mihama. They invite others to explore the beauty and tranquility of this area, emphasizing its spiritual significance and the opportunity for personal reflection. Their content aims to illustrate the essence of rural life in Japan, encouraging viewers to consider the meaning of life and the adventures that await in Kumano.' where id = 'mYmozCuBUo5PIhuv4w_uz';
update content_bodies set title = '【北海道江別市公式観光PR動画】/ JAPAN - HOKKAIDO - EBETSU CITY Summer Ver 4K', description = 'この動画は、北海道江別市の公式観光PR動画です。江別の夏の魅力を4K映像で紹介し、「食と農」「豊かな自然」「歴史あるれんが」をテーマにしています。江別市を訪れることをぜひお勧めします！撮影場所には、THA芝木農園、野菜の駅ふれあいファームしのつ、アースドリーム角山農場、萩原農場、江別市セラミックアートセンター、EBRI、江別市ガラス工芸館、ノハナショウブ群生地、野幌森林公園、えべつ花火大会、酪農学園大学、野幌森林キャンプ場、ヒヌマフウフ、NORTH ISLAND BEERなどが含まれています。製作はEzo Explorerによるものです。' where id = 'gK2Ev-AVBRF7PhV5YGaRn';
update content_bodies set title = 'Hokkaido Ebetsu City Official Tourism PR Video / JAPAN - HOKKAIDO - EBETSU CITY Summer Ver 4K', description = 'This is the official tourism PR video for Ebetsu City, Hokkaido. It showcases the summer attractions of Ebetsu through 4K footage, focusing on ''food and agriculture,'' ''rich nature,'' and ''historical bricks.'' Visitors are encouraged to come and enjoy Ebetsu City! The video features various locations including THA Shibaki Farm, Vegetable Station Fureai Farm Shinotsu, Earth Dream Kaku Mountain Farm, Hagiwara Farm, Ebetsu City Ceramic Art Center, EBRI, Ebetsu City Glass Craft Museum, Nohana Iris Habitat, Noboribetsu Forest Park, Ebetsu Fireworks Festival, Rakuno Gakuen University, Noboribetsu Forest Campground, Hinuma Fufu, and NORTH ISLAND BEER. Produced by Ezo Explorer.' where id = 'IP-ZZMk2688_scKxlAYWf';
update content_bodies set title = '【北海道江別市公式観光PR動画】/ JAPAN - HOKKAIDO - EBETSU CITY Winter Ver ４K', description = 'この動画は、北海道江別市の公式観光PR動画で、冬の江別を1日周遊観光する様子を4K映像で撮影しています。江別市の魅力を紹介し、訪れることを促しています。撮影場所には、アースドリーム角山農場、江別市セラミックアートセンター、江別神社、江別 蔦屋書店、ぱん屋 ニレカゼ、Bakery & Vegefru ma chi no ki、野幌森林公園が含まれています。出演者は増井ほなみさんと清水理香子さんで、製作はEzo Explorerです。詳細は公式InstagramやYouTubeチャンネルをご覧ください。' where id = 'KsOa4mBu4TlV_0hgT5w7N';
update content_bodies set title = 'Hokkaido Ebetsu City Official Tourism PR Video / JAPAN - HOKKAIDO - EBETSU CITY Winter Ver 4K', description = 'This is the official tourism PR video for Ebetsu City, Hokkaido, showcasing a one-day winter sightseeing tour in stunning 4K resolution. The video invites viewers to explore the many attractions of Ebetsu City, including Earth Dream Kaku Mountain Farm, Ebetsu City Ceramic Art Center, Ebetsu Shrine, Tsutaya Bookstore, Bakery Nirekaze, Bakery & Vegefru ma chi no ki, and Nopporo Forest Park. The video features performances by Honami Masui and Rikako Shimizu, produced by Ezo Explorer. For more information, visit their Instagram and YouTube channels.' where id = 'ZzAN9n5T5ku0kZcD3rdeR';
update content_bodies set title = '【前編】江別市周遊観光PR動画', description = '江別市出身のモデル・タレント高田秋さんが江別市内の観光拠点や飲食店を訪れ、その魅力をPRする動画です。撮影箇所にはJR野幌駅、ホテルリボーン野幌、ノースライブコーヒー、トンデンファーム、町村農場ミルクガーデン、EBRI、EBEZZA、Ambitious Farm、ノースアイランドビール、江別市セラミックアートセンター、家庭料理なの花、小林酒造、酒米栽培グループ「すいせい」が含まれています。動画内ではこれらの名称が表示されています。後編は指定のリンクから視聴可能です。高田秋さんは立ち飲み屋巡りが趣味で、唎酒師の資格を持ち、YouTubeチャンネル「高田秋のほろ酔い気分」でも活動しています。' where id = 'Z2C87nMkFfFmF1rq05gSo';
update content_bodies set title = 'Ebetsu City Sightseeing PR Video (Part 1)', description = 'This collaboration video features Akira Takada, a model and talent from Ebetsu City, as she visits various tourist spots and restaurants in the city to promote its attractions. The filming locations include JR Nopporo Station, Hotel Reborn Nopporo, North Live Coffee, Tonden Farm, Chamura Farm Milk Garden, EBRI, EBEZZA, Ambitious Farm, North Island Beer, Ebetsu City Ceramic Art Center, Home Cooking Nanohana, Kobayashi Sake Brewery, and the Sui-sei sake rice cultivation group. The names are displayed in the video. The second part can be viewed at the provided link. Akira Takada has a YouTube channel where she shares her experiences, and she is known for her love of bar hopping and holds a sake tasting qualification.' where id = '5mB3nWqlsQZfNOLiyrMQO';
update content_bodies set title = '自然と伝統が重なる郡上八幡', description = '郡上八幡は、長良川の上流に位置する古い城下町で、特に夏に行われる郡上おどりで知られています。この町は、美しい澄んだ水が流れることが特徴で、地元の生活様式を感じることができます。郡上八幡のシンボルである宗祇水は、この地域の清らかな水を象徴し、自然の美しさを祝う存在です。' where id = 'T3jMnCto0SVAj53F-cp9N';
update content_bodies set title = 'Gujo Hachiman: Nature & Tradition', description = 'Gujo Hachiman is an old castle town located upstream of the Nagara River, renowned for its vibrant local lifestyle, particularly during the summer when the Gujo Odori dance takes place. The town is characterized by its stunningly clear waters, which are a significant aspect of its charm. A key feature of Gujo Hachiman is Sogi Spring, a local symbol that highlights the area''s pure water and serves as a celebration of its natural beauty.' where id = '8Swr3wZmvWQwn2JRc2Cso';
update content_bodies set title = '【後編】江別市周遊観光PR動画', description = '江別市出身のモデル・タレント高田秋さんが江別市内の観光拠点や飲食店を訪れ、その魅力をPRする動画です。撮影箇所にはJR野幌駅、ホテルリボーン野幌、ノースライブコーヒー、トンデンファームなどが含まれています。動画の前編もリンクから視聴可能です。高田秋さんは立ち飲み屋巡りが趣味で、唎酒師の資格を持ち、テレビ番組にも多数出演しています。江別市観光振興課の公式Instagramもフォローして、最新情報をチェックしてください。' where id = '9Xob6c5Ch-dSZxzX5BR8J';
update content_bodies set title = 'Ebetsu City Sightseeing PR Video (Part 2)', description = 'This collaboration video features Akira Takada, a model and talent from Ebetsu City, as she visits various tourist spots and restaurants in the city to promote its attractions. The video showcases locations such as JR Nopporo Station, Hotel Reborn Nopporo, North Live Coffee, Tonden Farm, and more. Viewers can also check out the first part of the video through the provided link. Akira Takada is known for her love of bar-hopping and holds a sake tasting qualification. She has appeared in numerous TV programs, including ''Waratte Koraete!'' and ''Asa made Hashigo Sake no Tabi.'' For more updates, follow the official Ebetsu City Tourism Promotion Instagram.' where id = 'O0AAN2u5yOvpWXRVlZuy1';
update content_bodies set title = '御食国 MIKETSUKUNI ～古代から愛されてきた美味～', description = '御食国MIKETSUKUNIは、約1200年前から美食の宝庫として知られ、福井県若狭、三重県志摩、兵庫県淡路島に位置しています。この地域は、歴史的に京都の朝廷に食材を献上してきました。和食文化と皇室の美食が出会うこの旅では、長い年月を経て磨かれた歴史的な味わいを堪能することができます。' where id = 'wHFgPePukDMsbhC4pvqdx';
update content_bodies set title = 'Royal Food of Japan MIKETSUKUNI～Delicacies cherished since ancient times～', description = 'MIKETSUKUNI, known as the ''Royal Food of Japan,'' is a region that has been celebrated for its culinary treasures since approximately 1200 years ago. Located in Fukui Prefecture, Wakasa, Mie Prefecture, Shima, and Hyogo Prefecture, Awaji Island, this area has historically supplied ingredients to the imperial court in Kyoto. The journey through this region offers a unique encounter with the refined culture of Japanese cuisine and royal delicacies, allowing visitors to savor the flavors that have been cherished throughout history.' where id = '2A_9i-2KDbO6AUBsQ71pK';
update content_bodies set title = '日本の王室料理 御食国～古代から愛されてきた美味～', description = '御食国は福井県若狭、三重県志摩、兵庫県淡路島に位置し、「御食国」として知られています。約1,200年前から、京都の朝廷に食材を奉納する美食の宝庫として栄えてきました。この旅では、長い歴史を経て磨かれた和食文化と王室料理の出会いを探求し、歴史的に大切にされてきた美味を味わいます。' where id = 'AmbASNGTCxNeo17EtFPsw';
update content_bodies set title = 'Royal Food of Japan MIKETSUKUNI – Delicacies cherished since ancient times', description = 'MIKETSUKUNI, known as the ''Land of Royal Food,'' is located in Fukui Prefecture, Wakasa, Mie Prefecture, Shima, and Hyogo Prefecture, Awaji Island. For approximately 1,200 years, it has been a treasure trove of culinary delights, supplying ingredients to the imperial court in Kyoto. This journey explores the rich history and refined culture of Japanese cuisine, highlighting the exquisite flavors that have been cherished through the ages.' where id = 'qjT3TEiruUfMkr_f3LrHb';
update content_bodies set title = '日本の御食国 MIKETSUKUNI', description = '御食国（MIKETSUKUNI）は、約1200年前から続く美食の宝庫であり、福井県若狭、三重県志摩、兵庫県淡路島に位置しています。この地域は、古くから京都の朝廷に食材を奉納してきたことで知られています。長い歴史を経て磨かれた和食文化と、皇室の美食との出会いを通じて、歴史に大切にされてきた美味を堪能する旅が展開されます。' where id = '-MWhdcT4haVQxjzRvy_GW';
update content_bodies set title = 'Royal Food of Japan MIKETSUKUNI', description = 'MIKETSUKUNI, known as the ''Royal Food of Japan,'' is a region that has been celebrated for its culinary heritage for approximately 1200 years. Located in Fukui Prefecture, Wakasa, Mie Prefecture, Shima, and Hyogo Prefecture, Awaji Island, this area has historically supplied ingredients to the imperial court in Kyoto. The journey through this rich food culture offers a unique encounter with royal delicacies, allowing one to savor the exquisite flavors that have been cherished throughout history.' where id = 'bEVRkxvvHjGlIe8U7acmz';
update content_bodies set title = '【繁体字】Royal Food of Japan MIKETSUKUNI～古代から愛される美味～', description = '福井県若狭、三重県志摩、兵庫県淡路島は「御食国」として知られ、約1,200年前から京都の朝廷に食材を奉納してきた美食の宝庫です。この旅では、長い歴史を経て磨かれた和食文化と、皇室の美味との出会いを探求します。歴史的な珍味を味わいながら、古代から受け継がれてきた美味を体験してください。' where id = '5tUM8v-rRsxikc6_stnWA';
update content_bodies set title = 'Royal Food of Japan MIKETSUKUNI～Delicacies cherished since ancient times～', description = 'The regions of Fukui Prefecture, Wakasa, Mie Prefecture, Shima, and Hyogo Prefecture, Awaji Island, are renowned as ''MIKETSUKUNI,'' a place celebrated for its culinary heritage. For approximately 1,200 years, these areas have served as a treasure trove of food, supplying ingredients to the imperial court in Kyoto. This journey explores the rich history and refined culture of Japanese cuisine, highlighting the encounter with royal delicacies. Experience the exquisite flavors that have been cherished through the ages.' where id = 'QBY8f6feDeB32IPsHhTl1';
update content_bodies set title = '万博とその先へ！関西を旅しよう。', description = '関西は、長い歴史によって育まれた文化や人々の営み、地域性や持続可能性が息づいています。万博と共に、関西への旅を始めてみませんか。あなたのいのちを輝かせる旅が、ここ関西で待っています。' where id = 'egFK9xo4Fzjx7-6-lsVmk';
update content_bodies set title = 'The Expo and Beyond! Travel All Around KANSAI, Japan.', description = 'Kansai is rich in culture shaped by its long history, showcasing the lives of its people and the region''s sustainability. Why not take a step towards exploring Kansai alongside the Expo? Embark on a journey that will illuminate your life here in Kansai.' where id = 'iJ4ne8ek4WfEGYfYUPy6G';
update content_bodies set title = '万博とその先！関西を旅しよう。', description = '万博では、様々な技術革新や未来社会のデザインに触れることで、私たち一人ひとりが主体となり「これから」のより良い社会を考える機会が得られます。新しい体験を通じて感性を磨き、これまで持っていなかった視点を得ることができます。関西には、長い歴史が育んだ文化や人々の営み、地域性や持続可能性があります。万博と共に、関西への旅を始めてみませんか。あなたのいのちを輝かせる旅がここ関西で待っています。' where id = 'o85DLv18DM8yF__vL8qaO';
update content_bodies set title = 'The World EXPO and Beyond! Travel All Around KANSAI, Japan.', description = 'The World Expo presents an opportunity for individuals to engage with various technological innovations and designs for future societies, encouraging us to think about a better future. Through new experiences, we can refine our sensibilities and gain perspectives we previously lacked. Kansai is rich in culture shaped by its long history, the activities of its people, and its commitment to sustainability and regional identity. Why not embark on a journey to Kansai alongside the Expo? Experience a trip that will illuminate your life here in Kansai.' where id = 'lJqEj6lAb6HT_g2NRgOtW';
update content_bodies set title = '関西の特別な探検: J trailer2/QR', description = 'かつて都が存在した関西には、和食、茶道、古典芸能、工芸、禅など、日本文化の源流が数多くあります。今もそれらを受け継ぐ方々がいて、関西の誇る“宝”に出会う旅へと皆さまをお連れします。一流の方が特別な空間で提供する“体験”を、動画で疑似体験できますが、実際の体験はここ関西で待っています。' where id = 'vGFbx7MEYSex_fGIbFsCi';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan: J trailer2/QR', description = 'Kansai, once the heart of Japan, is rich in cultural heritage, including traditional cuisine, tea ceremonies, classical arts, crafts, and Zen practices. This region continues to nurture these cultural treasures through dedicated individuals. The journey invites you to discover the ''gems'' of Kansai, where you can experience unique offerings from masters in special settings. The video provides a virtual glimpse into these experiences, while the real encounters await you in Kansai.' where id = 'qk0MrASe93MZQwHj1WIkA';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Wakayama [4K]', description = '紀伊山地に位置する熊野は、神秘的な山々と豊かな森林に囲まれた、日本三大霊場の一つであり、神聖な場所です。熊野本宮大社と他の二つの神社を結ぶ熊野古道は、古くから日本で最も重要な参拝道路とされてきました。熊野は「重生の聖地」として知られ、創始期からの多くの伝説が残されています。現在でも多くの参拝者が訪れています。本動画で紹介されている文化体験の詳細情報は、提供されたリンクを参照してください。' where id = 'prxfz2egr8JTP-RvVe5E3';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Wakayama [4K]', description = 'The Kumano region in the Kii Mountains is known for its mysterious mountains and lush forests. It is one of Japan''s three major spiritual sites and a sacred place. The Kumano Hongu Taisha Shrine, along with two other shrines, is connected by the Kumano Kodo, which has been regarded as one of Japan''s most important pilgrimage routes since ancient times. Kumano, known as a ''sacred land of rebirth,'' has many legends dating back to Japan''s founding period and continues to attract numerous worshippers. For detailed information about the cultural experiences featured in this video, visit the provided links.' where id = 'EBhkzMN2ZrHkJvhBQ28Iz';
update content_bodies set title = '関西日本の特別な探検 - 和歌山 [4K]', description = 'この動画では、紀伊山地に位置する熊野本宮大社を紹介しています。熊野は日本三大聖地の一つであり、神秘的な山々と豊かな森林に囲まれています。熊野古道を通じて他の神社と結ばれ、古くから重要な参拝道路とされてきました。熊野は「重生の聖地」として知られ、今でも多くの参拝者が訪れています。動画内では、文化体験に関する詳細情報や行程のリンクも提供されています。' where id = '_E0di_NmTuFVrjxYqOcpj';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Wakayama [4K]', description = 'The video highlights Kumano Hongu Taisha, a significant spiritual site in Japan''s Kii Mountain range, known for its lush forests and mystical mountains. Kumano is one of Japan''s three major sacred places and is connected to other shrines via the Kumano Kodo pilgrimage routes, which have been regarded as essential pilgrimage paths since ancient times. This area is celebrated as a ''sacred land of rebirth,'' attracting numerous visitors seeking spiritual experiences. The video also provides links for more information on cultural experiences and itinerary arrangements.' where id = '7vh7QKKYCDzJGpBkEvF-J';
update content_bodies set title = 'エクスクルーシブ・エクスペディション、関西日本 和歌山 [4K]', description = '紀伊山地の神秘的な山々と深い森に広がる熊野は、日本三大霊場の一つとして知られています。熊野本宮大社と二つの社を結ぶ熊野古道は、古代から現代、そして未来へと人々を受け入れる重要な参詣道です。日本の黎明期から数々の伝説を生んできた熊野は「甦りの聖地」として知られ、今でも多くの参詣者が訪れています。動画では、この地域での文化体験を紹介し、和歌山の旅の魅力を探求することを促しています。' where id = '5yJHCpp88c3RLAnLp7G2d';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan Wakayama [4K]', description = 'The Kumano region, located deep within the mystical Kii Mountains, is known as one of Japan''s three sacred sites. The Kumano Hongu Taisha Shrine and the Kumano Kodo pilgrimage routes connect two shrines, serving as a vital path for worshippers since ancient times. This area, rich in legends from Japan''s early history, is recognized as a ''sacred place of resurrection'' and continues to attract many visitors. The video highlights cultural experiences available in this region, inviting viewers to explore the allure of travel in Wakayama.' where id = 'BKi9p-ZEtjtESEo3djZAC';
update content_bodies set title = '関西日本の特別な探検 - 奈良[4K]', description = 'この動画では、金峯山寺の文化体験を紹介しています。金峯山寺は、7世紀に役行者によって設立された修験道の中心地であり、紀伊山地の吉野山の山腰に位置しています。世界遺産に登録されているこの寺院は、多くの有形文化財を保存しています。管長の五条良知は、主尊である藏王權現などの文化遺産を守る重要な役割を担っており、これらの遺産が未来にわたって受け継がれるよう努めています。文化体験の詳細や行程については、提供されたリンクを参照してください。' where id = 'wc_X-PYBgXHNppZSf7xDg';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Nara[4K]', description = 'This video highlights the cultural experience of Kimpusen-ji Temple, a center of Shugendo, a traditional Japanese mountain faith established in the 7th century by En no Gyoja. Located on the slopes of Yoshino Mountain in the Kii Mountain Range, Kimpusen-ji is a UNESCO World Heritage site that preserves numerous cultural assets. The head priest, Gojō Ryōchi, plays a crucial role in safeguarding these cultural treasures, including the main deity, Zōkō Gongen, ensuring their legacy for future generations. For more details on the cultural experience and itinerary, visit the provided links.' where id = 'ocK6yqe3uNC5VWWgFKfpp';
update content_bodies set title = '関西日本の特別な探検 - 奈良[4K]', description = 'この動画では、奈良の吉野にある金峰山寺を中心とした修験道の文化体験が紹介されています。金峰山寺は、7世紀に役行者によって創設され、修験道の重要な拠点として知られています。管長の五条良知は、本尊の藏王権現などの文化遺産を守る重要な役割を果たしており、これらの遺産が未来に引き継がれることを確実にしています。文化体験の詳細や行程については、提供されたリンクを参照してください。' where id = '51pZ_Oc_wzxTLnu8Lr4gP';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Nara[4K]', description = 'The video highlights the cultural experience of Shugendo, a traditional Japanese mountain faith, centered at Kinpusen-ji Temple in Yoshino, Nara. Founded in the 7th century by the ascetic monk En no Gyoja, Kinpusen-ji serves as a significant site for Shugendo practice and preserves numerous cultural assets. The temple''s abbot, Gojō Ryōchi, plays a crucial role in safeguarding important cultural heritage, including the main deity, Zōō Gongen, ensuring its transmission to future generations. For more details on the cultural experience and itinerary, visit the provided links.' where id = '7ISPYPaqPdIEB1jWdkKhe';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan 奈良 [4K]', description = 'この動画では、修験道の重要な拠点である金峯山寺を紹介しています。修験道は、厳しい修行を通じて悟りを得る日本古来の山岳信仰であり、金峯山寺は7世紀に役行者によって開かれました。紀伊山地の吉野山中腹に位置し、多くの有形文化財が収蔵されています。管長の五條良知氏は、本尊の蔵王権現を含む文化遺産を守り、未来へとつなげる重要な役割を担っています。動画で紹介されている文化体験の詳細については、提供されたリンクを参照してください。' where id = 'hX-_IPeVhcU9O5QHWz7HA';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan Nara [4K]', description = 'This video explores the sacred site of Kinpu Mountain Temple, a significant location for the practice of Shugendo, a traditional Japanese mountain faith that emphasizes rigorous ascetic training for enlightenment. Founded in the 7th century by the monk En no Gyoja, the temple is situated on the slopes of Yoshino Mountain in the Kii Mountain Range and houses numerous cultural assets. The temple''s abbot, Ryochi Gojo, plays a crucial role in preserving these cultural heritages, including the main deity, Zao Gongen, and ensuring their continuity for future generations. For more details on the cultural experiences featured in the video, visit the provided links.' where id = 'GF72MRDPSlmQXktprUxwd';
update content_bodies set title = '関西の特別な探検: Jトレーラー/QRなし', description = 'かつて都が存在した関西には、和食、茶道、古典芸能、工芸、禅など、日本文化の源流が数多くあります。今もそれらを受け継ぐ方々がいます。この旅では、関西の誇る“宝”に出会うことができます。一流の方々が特別な空間で提供する“体験”を、動画で疑似体験することが可能です。しかし、疑似体験を超えた実際の体験は、ここ関西でしか味わえません。' where id = 'JOk1V3MpvkChdRmO5_lkh';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan: J trailer/wo QR', description = 'Kansai, once the capital of Japan, is a treasure trove of Japanese culture, including traditional cuisine, tea ceremonies, classical arts, crafts, and Zen practices. This region continues to nurture these cultural legacies through dedicated individuals. The journey invites you to discover the ''treasures'' of Kansai, where you can experience unique offerings from masters in special settings. While the video provides a virtual glimpse into these experiences, the true essence can only be felt through actual participation in Kansai.' where id = 'tFXbnBoNsyEF4oUYXPSpQ';
update content_bodies set title = 'エクスクルーシブ・エクスペディション、関西日本：Jトレーラー/QR', description = 'かつて都が存在した関西には、和食、茶道、古典芸能、工芸、禅など数えきれないほどの日本文化の源流があり、今もそれらを受け継ぐ方がいます。関西が誇る“宝”に出会う旅へと皆さまをお連れします。特別な空間で一流の方が提供する“体験”を、動画でオンラインで疑似体験できます。実際の体験はここ関西で待っています。' where id = 'tF4jJSqWWq69s8qwz9AgV';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan: J trailer/QR', description = 'Kansai, once the capital of Japan, is a treasure trove of Japanese culture, including traditional cuisine, tea ceremonies, classical arts, crafts, and Zen practices. This region continues to preserve these cultural heritages through dedicated individuals. The journey invites you to encounter the ''treasures'' of Kansai, where you can experience unique offerings from masters in special settings. The video provides a virtual glimpse into these experiences, while the real encounters await you in Kansai.' where id = 'yQbLxireb3UxF9Ztha2IY';
update content_bodies set title = '独占的な探検、関西日本 - 兵庫[4K]', description = 'この動画では、神戸にある「天空の森」として知られる北野天満神社での伝統的な能楽の公演が紹介されています。この歴史ある神社は、学問の神である菅原道真公を奉るために1180年に設立されました。何世紀にもわたり、北野天満神社は美しい景色に囲まれた中で神々への奉納として能楽が上演され、多くの人々に愛され続けています。' where id = 'CzPikORaQ5xGcNnPS7d-0';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Hyogo[4K]', description = 'The video features a traditional Noh performance at Kitano Tenmangu Shrine, known as the ''Sky Forest'' in Kobe, Japan. This historic shrine, dedicated to Sugawara no Michizane, the deity of learning, was established in 1180. Over the centuries, the shrine has been a venue for Noh theater, which is performed as an offering to the gods, surrounded by beautiful scenery that attracts many visitors.' where id = 'h7DT6vLKZhIwkn04sG-9K';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Osaka[4K]', description = 'この動画では、大阪天満宮での伝統的な能楽の公演を紹介しています。能は14世紀に始まった世界最古の舞台芸術の一つであり、神秘的なストーリー、象徴的な面、華やかな衣装、形式化された動作が特徴です。公演は重要無形文化財保持者である上野朝義氏が主導し、彼の2人の兄弟も能楽師として参加しています。能は日本の独特な文化体験を提供しています。' where id = '5INzk9HxmxWg3RvqfKWW3';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Osaka[4K]', description = 'This video features a traditional Noh performance at Osaka Tenmangu Shrine, showcasing the art of Noh, one of the oldest theatrical forms in the world, which dates back to the 14th century. The performance is led by Ueno Tomoyoshi, a certified Important Intangible Cultural Asset holder, along with his two brothers, who are also Noh performers. Noh is characterized by its mysterious narratives, symbolic masks, elaborate costumes, and stylized movements, making it a unique cultural experience in Japan.' where id = 'CnhgVohfLWZvpkYAfH08G';
update content_bodies set title = '独占的な探検、関西日本 - 大阪[4K]', description = 'この動画では、大阪天満宮での伝統的な能の公演を紹介しています。能は14世紀に始まった世界最古の舞台芸術の一つであり、神秘的な物語、象徴的な面、華やかな衣装、形式化された動きが特徴です。公演は重要無形文化財保持者である上野朝義氏が主導し、彼の2人の弟も能楽師として参加しています。能は日本のユニークな文化体験を提供しています。' where id = '__e3vHjWR1pmtVfT3IOSh';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Osaka[4K]', description = 'This video features a traditional Noh performance at Osaka Tenmangu Shrine, showcasing the art of Noh, one of the oldest theatrical forms in the world, which originated in the 14th century. The performance is led by Asahi Ueno, a certified Important Intangible Cultural Asset holder, along with his two brothers, who are also Noh performers. Noh is characterized by its mysterious narratives, symbolic masks, elaborate costumes, and formalized movements, making it a unique cultural experience in Japan.' where id = 'LIh58JanYq14zVH1BrLaL';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - 兵庫[4K]', description = 'この動画では、神戸の北野坂に位置する北野天満神社での薪能の文化体験が紹介されています。北野天満神社は1180年に創建され、学問の神である菅原道真公を祀っています。神社からは神戸の街を一望でき、数世紀にわたり能が奉納されてきました。動画では、文化体験の詳細や地域の魅力を知るためのリンクも提供されています。' where id = 'HrlVDm2fXP5gryi4vbVU9';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Hyogo [4K]', description = 'The video highlights the cultural experience of ''Sakinō'' at Kitano Tenmangu Shrine, a historic shrine established in 1180, dedicated to Sugawara no Michizane, the deity of learning. Located on Kitano-zaka, it offers a stunning view of Kobe city. For centuries, Noh performances have been held at the shrine''s hall, captivating audiences with its rich cultural heritage. The video provides links for viewers to explore more about the cultural experiences and the attractions of the region.' where id = 'VGePwjOoK91KX6UwfkMsL';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Tottori[4K]', description = '鳥取県は日本で最も人口が少ない県であり、静かな環境が芸術創作に最適とされています。2013年に重要無形文化財保持者に認定された白磁作家の前田昭博もこの地に魅了されています。柔らかな自然光が白磁の純粋さを引き立て、彼の作品に存在感を与えています。前田が特に好む展示場所は、鳥取県智頭町にある石谷家住宅で、ここは日本庭園を中心に配置された近代和風建築の名作であり、国の重要文化財にも指定されています。' where id = '4POeuQGYDpbTZMeyi1ckQ';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Tottori[4K]', description = 'Tottori Prefecture, the least populated area in Japan, is renowned for its serene environment, ideal for artistic creation. Notably, Akihiro Maeda, a white porcelain artist recognized as a Living National Treasure in 2013, finds inspiration in this tranquil setting. The soft natural light enhances the purity of his white porcelain creations. A significant venue for Maeda''s work is the Ishiya House in Chizu Town, Tottori. This architectural masterpiece, centered around a Japanese garden, is celebrated for its modern Japanese style and is designated as an Important Cultural Property of Japan.' where id = 'haVfawGPDZtohSRORGLlL';
update content_bodies set title = '独占的な探検、関西日本 - 鳥取[4K]', description = '鳥取県は日本で最も人口が少ない県であり、多くのアーティストがこの静かな環境を創作に最適と考えています。2013年に重要無形文化財保持者に認定された白磁作家の前田昭博もその一人です。柔らかな自然光が彼の純白の磁器の存在感を引き立てます。前田が特に愛する展示場所は、鳥取県智頭町にある石谷家住宅です。この建築群は日本庭園を中心に配置されており、近代和風建築の傑作として知られ、国の重要文化財に指定されています。' where id = '7eLMNT4RfJYC7J4r3pZK1';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Tottori[4K]', description = 'Tottori Prefecture, known for having the smallest population in Japan, is a serene environment favored by many artists for creativity. Among them is Akihiro Maeda, a white porcelain artist recognized as an Important Intangible Cultural Asset in 2013. The soft natural light enhances the presence of his pure white porcelain. A beloved exhibition venue for Maeda is the Ishiya House in Chizu Town, Tottori Prefecture. This architectural complex, centered around a Japanese garden, is a renowned masterpiece of modern Japanese architecture and is designated as an Important Cultural Property.' where id = 'X4nkMb3A3qIzI-sASstGv';
update content_bodies set title = 'エクスクルーシブ・エクスペディション、関西日本 - 滋賀[4K]', description = '三井寺は比叡山の山麓に位置し、琵琶湖を望む場所にあります。平安時代の朝廷によって祈願所として設立された四大寺院の一つであり、寺院区域内には40以上の建物があり、650件以上の国宝や重要文化財が保存されています。1300年にわたり、三井寺はこれらの文化資産を守り続けており、長吏や僧侶たちはその重責を命がけで担っています。' where id = 'IzjMW-Zyfi67pMCwDkCkF';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Shiga[4K]', description = 'Mii-dera, located at the foot of Mount Hiei and facing Lake Biwa, is one of the four major temples established by the Heian period court for prayer. Within its temple complex, there are over 40 buildings that house more than 650 national treasures and important cultural assets. For 1,300 years, Mii-dera has been dedicated to preserving these cultural assets, a responsibility that the temple''s head priest and monks take on with utmost seriousness, often risking their lives.' where id = 'ODo2zCuHeCkCXTka9uH3P';
update content_bodies set title = 'エクスクルーシブ・エクスペディション、関西日本 - 兵庫[4K]', description = 'この動画では、神戸市の風景を一望できる北野坂上に位置する北野天満神社での伝統的な能楽の公演が紹介されています。この神社は学問の神、菅原道真公を祀り、1180年に創建されました。数世紀にわたり、北野天満神社の美しい景色に囲まれた境内では、神々への奉納として能楽が演じられ、多くの人々に愛されてきました。' where id = 'fccLjf4NG43phCqJUJjxe';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Hyogo[4K]', description = 'The video features a traditional Noh performance at Kitano Tenmangu Shrine, known as the ''Forest in the Sky,'' located on Kitano-zaka Hill, which offers a panoramic view of Kobe city. This historic shrine, dedicated to Sugawara no Michizane, the deity of learning, was established in 1180. For centuries, the shrine has been a beloved site for Noh theater performances, held in its scenic surroundings as offerings to the gods.' where id = 'qoh-aq8mBtbdCDyGmxlHn';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Tokushima[4K]', description = 'この動画では、四国の東部に位置する徳島での阿波人形浄瑠璃を紹介しています。この地域は、日本で最も多くの保存された農村舞台を有しており、江戸時代後期に地元住民が五穀豊穣に感謝して建てたものです。この屋外舞台では、地元の人々に長年愛されてきた阿波人形浄瑠璃が上演されており、代々受け継がれてきた重要な伝統芸能です。この文化体験に関する詳細情報は、提供されたリンクを訪れてご覧ください。' where id = '0pXja4H8ZRG2AxyYh7wiW';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Tokushima[4K]', description = 'This video showcases the Awa Puppet Theater, a traditional performance art in Tokushima, located in eastern Shikoku, Japan. The region boasts the highest number of preserved rural stages in the country, built by local residents during the late Edo period to express gratitude for bountiful harvests. The outdoor stage hosts the beloved Awa Puppet Theater, which has been passed down through generations and remains a significant cultural heritage. For more information about this cultural experience, visit the provided links.' where id = 'pjtXjnWbiWffYdDbmxz9J';
update content_bodies set title = '関西日本の特別探検 - 京都[4K]', description = 'この動画では、平安神宮の尚美館で行われる茶道の文化体験を紹介しています。第四代家元の尾崎米柏が登場し、茶道の歴史と美学について語ります。16世紀に千利休が茶道を再定義し、日本文化を融合させたことが強調され、古田织部が利休の弟子の一人として自身の流派を創設した経緯も触れられています。時代の変化により、织部派は「御法度流仪」に進化しました。この文化体験の詳細や行程については、提供されたリンクを参照してください。' where id = 'ebqAFx3py-ibhpvELUzCj';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan -Kyoto[4K]', description = 'This video highlights a cultural experience centered around the Japanese tea ceremony, featuring the fourth generation headmaster of the Urasenke school, Ozaki Beihaku, at the Heian Shrine''s Shobikan, a nationally designated scenic spot. The tea ceremony, redefined by Sen no Rikyū in the 16th century, blends various aspects of Japanese culture and elevates it to an aesthetic form. Furuta Oribe, one of Rikyū''s disciples, established his own school, which eventually evolved into the ''Gohatto-ryū'' due to changing times. For more details on this cultural experience and itinerary, visit the provided links.' where id = 'nq9ruZaOwdBXZTcsAy6sQ';
update content_bodies set title = 'エクスクルーシブ・エクスペディション、関西日本 -三重[4K]', description = 'この動画では、重要無形文化財に指定されている伊勢大神楽を、山本勘太夫社中が披露します。古くから人々は、一生に一度は伊勢神宮を参拝したいと願っていました。その願いを叶えるため、神楽師である山本勘太夫は、参拝できない人々のために全国を巡り、五穀豊穣や無災無難を祈願しています。この文化体験の詳細情報は、提供されたリンクを参照してください。' where id = 'cKSr0vIvLIBzE46sy-b38';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan -Mie[4K]', description = 'The video highlights the cultural experience of Ise Daikagura, performed by the Yamamoto Kanta group, which is recognized as an important intangible cultural asset. Historically, the people wished to visit Ise Jingu Shrine at least once in their lifetime. To fulfill this desire for those unable to make the pilgrimage, Kagura performers like Yamamoto Kanta travel across the country to pray for bountiful harvests and protection from disasters. For more detailed information about this cultural experience, visit the provided links.' where id = '7gK4qXpJ_8SUOp0x8_hx4';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Fukui[4K]', description = 'この動画では、福井県で1500年以上の伝統を持つ越前和紙の手作りの技術が紹介されています。特に第9代の人間国宝、岩野市兵衛氏が漉いた和紙は世界中で高く評価されています。越前和紙の文化体験に関する詳細情報が提供されており、この独特な工芸品が日本文化においてどのような重要性を持つかが強調されています。文化体験や行程についての詳細は、提供されたリンクを訪れることで確認できます。' where id = 'yjoB3e6lPP8YLq7XQQ9aK';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Fukui[4K]', description = 'The video showcases the traditional craft of Echizen washi, a type of Japanese paper that has been handmade in Fukui Prefecture for over 1500 years. The paper is renowned worldwide, particularly the creations of the 9th generation craftsman Iwano Ichibei, who is recognized as a Living National Treasure. The film provides insights into cultural experiences related to this unique craft, highlighting the significance of washi in Japanese culture. For more detailed information about the cultural experience and itinerary, viewers can visit the provided links.' where id = 'Ber9bYZ7iAwD5sTBEvNFt';
update content_bodies set title = 'エクスクルーシブ・エクスペディション、KASNAI日本 - 三重[4K]', description = 'この動画では、重要無形民俗文化財に指定されている伊勢大神楽の文化体験が紹介されています。古くから、一般の人々は一生に一度は伊勢神宮を訪れることを願っていました。山本勘太夫のような神楽師は、参拝できない人々のために全国を巡り、五穀豊穣や無災無難を祈願しています。この文化体験の詳細については、提供されたリンクを参照してください。' where id = '6EWbyD_rnqOVT_GS4FLlR';
update content_bodies set title = 'Exclusive Expeditions, KASNAI Japan - Mie[4K]', description = 'The video highlights the Ise Daikagura, a traditional Japanese cultural experience featuring the Yamamoto Kanta-ryu troupe, recognized as an Important Intangible Folk Cultural Asset. Historically, the common people''s wish was to visit Ise Jingu at least once in their lifetime. The Daikagura performers, like Yamamoto Kanta, travel across the country to bless those unable to make the pilgrimage, praying for abundant harvests and safety from disasters. For more details about this cultural experience, visit the provided links.' where id = 'Ytlt5A_UcJj7WfrSMpGD5';
update content_bodies set title = '独占的な探検、関西日本–京都[4K]', description = 'この動画では、平安神宮の尚美館で、茶道の第四代家元である尾崎米栢による文化体験が紹介されています。茶道は16世紀に千利休によって日本の様々な文化が融合され、新たな定義が与えられ、美学として昇華されました。古田織部は利休の七人の弟子の一人であり、自らの流派を創設しましたが、時代の流れに翻弄され、最終的には織部派は「御法度流儀」に進化しました。この文化体験の詳細情報は、提供されたリンクを参照してください。' where id = 'gfoSzxKW6prjRQ45XfFKp';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan–Kyoto[4K]', description = 'This video showcases a cultural experience centered around the tea ceremony, led by the fourth-generation head of the Oribe school, Ozaki Beikaku, at Heian Shrine''s Naobikan, a nationally designated scenic spot. The tea ceremony, redefined by Sen no Rikyū in the 16th century, blends various aspects of Japanese culture and elevates it to an aesthetic form. Furuta Oribe, one of Rikyū''s seven disciples, established his own school but faced challenges over time, leading to the evolution of the Oribe school into the ''Gohatto-ryū.'' For more details on this cultural experience, visit the provided links.' where id = 'Pj6cFrHEO9dwwutB4Q4d1';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - 京都 [4K]', description = 'この動画では、京都における茶道の芸術を探求し、四代目家元の尾﨑米栢が率いる織部流に焦点を当てています。16世紀に千利休によって再定義された茶道は、日本文化のさまざまな側面を融合させ、美的体験へと昇華させました。利休の七人弟子の一人である古田織部は独自の流派を確立しましたが、波乱の運命に翻弄され、織部流は禁じられた流派として知られるようになりました。この動画は、この文化体験についての洞察を提供し、関西地域の魅力をさらに探求するためのリンクも紹介しています。' where id = 'd86nDbDvuBBL2r6yQmpzn';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Kyoto [4K]', description = 'This video explores the art of tea ceremony in Kyoto, focusing on the Oribe school led by the fourth generation master, Ozaki Beikatsu. The tea ceremony, redefined by Sen no Rikyū in the 16th century, blends various aspects of Japanese culture and elevates them into an aesthetic experience. One of Rikyū''s seven disciples, Furuta Oribe, established his own unique style but faced a tumultuous fate, leading to the Oribe school being known as a forbidden practice. The video provides insights into this cultural experience and offers links for further exploration of the attractions in the Kansai region.' where id = 'ziT8q4lDdYMuVkSrpT3j4';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan -徳島[4K]', description = 'この動画は、四国の東部に位置する徳島の豊かな文化遺産を紹介しています。江戸時代から地元住民に愛されてきた伝統芸能である阿波人形淨琉璃を取り上げています。この屋外舞台は、五穀豊穣を祝うために地域住民によって建設され、日本で最も多くの保存された農村舞台を誇る地域です。この文化体験や行程の詳細については、提供されたリンクを訪れてください。' where id = 'TN5uI1iVByxgolVsuLEvE';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan -Tokushima[4K]', description = 'This video showcases the rich cultural heritage of Tokushima, located in eastern Shikoku, Japan. It highlights the Awa Puppet Theater, a traditional performance art that has been cherished by local residents since the Edo period. The outdoor stage, built by the community to celebrate bountiful harvests, is home to this unique form of entertainment. The region boasts the highest number of preserved rural stages in Japan, making it a significant cultural site. For more information about this cultural experience and itinerary details, visit the provided links.' where id = 'WInWIgm4cMuywX92rwb6p';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan -福井 [4K]', description = '福井県の越前地方では、1500年以上の歴史を持つ伝統的な和紙作りが行われています。特に、九代目岩野市兵衛氏は人間国宝として認められ、手作業で漉く和紙は世界中で最高の和紙と評されています。この動画では、和紙作りに関する文化体験が紹介されており、視聴者はこの伝統的な技術や関西地域の魅力についてさらに学ぶことができます。' where id = 'z7oWwjKmNO6zIea6S8uOi';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Fukui [4K]', description = 'In Fukui Prefecture, specifically in the Echizen region, traditional washi paper-making has been practiced for over 1,500 years. The ninth-generation craftsman, Iwano Ichibei, who is recognized as a Living National Treasure, continues to create washi paper using traditional methods. His paper is acclaimed worldwide as some of the finest washi available. The video showcases cultural experiences related to this craft, inviting viewers to learn more about the art of washi-making and the allure of traveling in the Kansai region.' where id = 'SjYxSSZY-j9qj7FF4-h_t';
update content_bodies set title = '大門酒造', description = 'この動画は大門酒造について紹介しています。' where id = 'xWyikk5HpQjITKcRB8KR-';
update content_bodies set title = 'Daimon Brewery', description = 'This video introduces Daimon Brewery.' where id = '01yf1OwXdY0VNTyD9FrOo';
update content_bodies set title = 'スピリチュアル関西、繁体字ダイジェスト', description = '関西地域は、ホスピタリティに満ちた場所であり、日本のスピリチュアルな中心地として浮上しています。旅行者は、生命の意味や共生の関係について深く考える機会を得ることができます。社会や経済が変化しても、生命の本質は変わらず続いています。関西での旅行は、自分自身を再発見し、すべての生き物のつながりを理解するための特別な機会を提供します。この地域は、日本におけるスピリチュアリティのメッカとして位置づけられ、訪れる人々に自らの道と生命の意味を考えさせることを促しています。' where id = 'JrnHdfx0gKjXWK88JfDcf';
update content_bodies set title = 'Spiritual KANSAI, Digest Traditional Chinese', description = 'The KANSAI region, known for its hospitality, is emerging as a spiritual hub in Japan. It invites travelers to explore profound questions about life, coexistence, and the essence of existence. Despite societal changes, the continuity of life remains. Traveling in KANSAI offers a unique opportunity for self-discovery and understanding the interconnectedness of all living things. This region is positioned as a Mecca for spirituality in Japan, encouraging visitors to reflect on their own paths and the meaning of life.' where id = 'gXFIfi0g0vkd3lN-fwHTL';
update content_bodies set title = 'スピリチュアル関西、ダイジェスト', description = '関西地域は、ホスピタリティに満ちた場所として知られ、日本のスピリチュアルな中心地として浮上しています。ここでは、存在の意味や自然の相互関係についての深い問いを探求することができます。社会や経済が変化しても、生命の本質は変わりません。関西を旅することは、自分自身を再発見し、この世界での自分の位置を理解するためのユニークな機会を提供します。この地域は、日本のスピリチュアリティのメッカとして称賛されており、生命の旅と存在の探求が深く結びついています。' where id = 'GB5aMxu9Uzn5ZsvCagWsc';
update content_bodies set title = 'Spiritual KANSAI, Digest', description = 'The KANSAI region, known for its hospitality, is emerging as a spiritual hub in Japan. It invites travelers to explore profound questions about life, such as the meaning of existence and the interconnectedness of nature. Despite societal and economic changes, the essence of life continues. Traveling in KANSAI offers a unique opportunity for self-discovery and understanding one''s place in the world. This region is celebrated as the Mecca of Japanese spirituality, where the journey of life and the exploration of existence are deeply intertwined.' where id = 'G46rmdFqfCjCK2Qe1Qxxm';
update content_bodies set title = 'スピリチュアル関西、温泉', description = '関西、日本の文化は千年以上の歴史を持ち、温泉、地元の料理、日本酒が楽しめる場所です。日常生活の疲れから解放され、心身をリフレッシュするためのエネルギーを提供します。温かい自然の湯と穏やかな環境、伝統的な日本のホスピタリティが融合し、心と体のスピリチュアルな解放をもたらします。温泉に浸かり、清らかな地下水で醸造された日本酒を味わい、地元の美味しい料理を楽しむことで、関西の魅力を存分に体験できます。関西は日本の精神的な心臓部です。' where id = 'N1QwDpbndIq6418n4d8yQ';
update content_bodies set title = 'Spiritual KANSAI, Onsen', description = 'Experience the enduring blessings of a culture that has thrived for over a thousand years in Kansai, Japan. This region is renowned for its hot springs, local cuisine, and Japanese sake, offering a perfect escape from the stresses of daily life. The natural hot waters and serene environment, combined with traditional Japanese hospitality, provide a spiritual rejuvenation for both body and mind. Visitors can immerse themselves in the healing warmth of the onsen, savor the exquisite sake brewed from pure subterranean waters, and enjoy the finest local dishes. Kansai is not just a destination; it is the spiritual heart of Japan.' where id = 'w_5UBGiTiTuvngokQmuFp';
update content_bodies set title = 'スピリチュアル関西、温泉', description = '関西、日本の文化は千年以上の歴史を持ち、温泉、地元の料理、日本酒が楽しめる場所です。温かい自然の湯と穏やかな環境、そして伝統的な日本のホスピタリティが融合し、心と体の両方を癒すスピリチュアルな体験を提供します。温泉に浸かり、清らかな地下水で醸造された日本酒を味わい、地元の美味しい料理を楽しむことで、日常生活の疲れを癒し、明日へのエネルギーを得ることができます。関西は日本の精神的な心であり、真のリラクゼーションとリフレッシュを見つけることができる場所です。' where id = 'KO5EKFjYye0mnG4HgOrYX';
update content_bodies set title = 'Spiritual KANSAI, Onsen', description = 'Experience the enduring blessings of a culture that has thrived for over a thousand years in Kansai, Japan. This region is renowned for its hot springs, local cuisine, and Japanese sake, offering a perfect escape from the stresses of daily life. The natural hot waters and serene surroundings, combined with traditional Japanese hospitality, provide a rejuvenating experience for both body and mind. Visitors can immerse themselves in the healing warmth of the onsen, savor the exquisite sake brewed from pure subterranean waters, and enjoy local delicacies. Kansai is not just a destination; it is a spiritual heart of Japan, where one can find true relaxation and refreshment.' where id = '_JQ_A2KUaaUC0fLIInJVA';
update content_bodies set title = 'スピリチュアル関西、武士道', description = '伝統的な日本の武道を体験し、鍛冶屋が鋼を打ち鍛える様子を目の前で見ながら、火花が飛び散る中で輝く剣が形作られる様子を楽しむことができます。そして、美しい城の天守閣に登り、純粋で誠実な生き方の強さを学びます。武士道の哲学は、仁、義、礼、智、信、忠といった価値観を重視し、関西という日本の精神的な地域に根付いています。自らの道徳心を見つめ直すことで、人格を高め、武士道の本質を受け入れることができるのです。' where id = 'BQ_VTrZVPowQu3bI7fPNv';
update content_bodies set title = 'Spiritual KANSAI, Bushido', description = 'Experience traditional Japanese martial arts as a blacksmith passionately shapes steel into a sword, with sparks flying from the fire. Climb a magnificent castle keep and learn the virtues of living a pure and honest life. The philosophy of Bushido, which emphasizes humanity, honesty, gratitude, wisdom, belief, and loyalty, is deeply rooted in Kansai, Japan''s spiritual region. By reflecting on our moral compass, we can elevate our character and embrace the essence of Bushido.' where id = 'lwxWNkuPAUMW3P8gS9TMB';
update content_bodies set title = 'スピリチュアル関西、心', description = '関西における感謝の表現や伝統芸能は、訪れる人々に深い体験を提供し、これらの実践に埋め込まれた情熱、精神的な強さ、歴史的な重要性を感じさせます。代々受け継がれてきた文化的要素は、人間の信仰や意識の本質を体現しており、時には目に見えない形で深く共鳴します。関西は先人への敬意と大地の恵みへの感謝を表し、日本の悠久の文化に出会う機会を提供します。12月28日にリリース予定のこの探求は、日本のスピリチュアルな心を発見することを促します。' where id = 'q_VbJSfiJYXV_JWdhIxL7';
update content_bodies set title = 'Spiritual KANSAI, Kokoro', description = 'The unique Japanese expressions of gratitude and traditional arts in KANSAI offer a profound experience that connects visitors to the passion, resilience, and historical significance embedded in these practices. These cultural elements, passed down through generations, embody the essence of human belief and consciousness, often manifesting in intangible forms that resonate deeply within. KANSAI serves as a tribute to ancestors and a celebration of the earth''s generous gifts, providing an opportunity to encounter the rich tapestry of Japan''s enduring culture. Scheduled for release on December 28th, this exploration invites you to discover the spiritual heart of Japan.' where id = 'M7_by0p7G8F0P8u4lF0p3';
update content_bodies set title = 'スピリチュアル関西、心', description = '関西における感謝の独自の表現や伝統芸能は、訪れる人々に情熱や精神的な強さ、そして歴史的な重みを感じさせる深い体験を提供します。これらの文化的要素は世代を超えて受け継がれ、人間の信仰や意識の本質を体現しています。それは時に目に見えない形で、心の奥深くに響きます。先人への敬意や大地の恵みに感謝する気持ちが込められています。関西は日本のスピリチュアルな心臓部として描かれ、地域を形作ってきた豊かで永続的な文化に出会える場所です。' where id = 'opcoiiGbx4IlJFNtuBkgy';
update content_bodies set title = 'Spiritual KANSAI, Kokoro', description = 'The unique Japanese expressions of gratitude and traditional arts in KANSAI offer a profound experience that connects visitors to the passion, resilience, and historical significance embedded in these practices. These cultural elements, passed down through generations, embody the essence of human belief and consciousness, often in intangible forms that resonate deeply within. They reflect a reverence for ancestors and gratitude for the earth''s generous offerings. KANSAI is portrayed as the spiritual heart of Japan, where one can encounter the rich and enduring culture that has shaped the region.' where id = 'qEM-o3-m8TfINnTpm1sBY';
update content_bodies set title = 'スピリチュアル関西、侘び寂び', description = '関西の美しい日本庭園を訪れ、正式な着物を着て、茶道を体験することができます。また、古くてシンプルな家々が残る村を訪れることも可能です。これらの体験は、シンプルなものの中に秩序と敬意を見出し、古いものの中に純粋な美を感じる「侘び寂び」の本質を体現しています。古き日本の雰囲気は、静けさ、誠実さ、自然や互いへの深い敬意に満ちています。関西では、侘び寂びの伝統的な美学が生き生きと表現され、完璧さの中にある不完全さを味わうことができます。この地域は、日本の精神的な心臓部であり、調和と純粋さが称えられています。' where id = 'DPSoKa6CSA4deE0uqyigy';
update content_bodies set title = 'Spiritual KANSAI, Wabi Sabi', description = 'Experience the serene beauty of Kansai, Japan, by visiting traditional Japanese gardens and dressing in formal kimonos. Engage in the art of tea preparation or explore quaint villages with simple, old homes. These experiences embody the essence of ''wabi-sabi,'' where one finds beauty in simplicity and the passage of time. The atmosphere of old Japan is characterized by tranquility, honesty, and a deep respect for nature and each other. In Kansai, the traditional aesthetics of wabi-sabi come to life, allowing visitors to appreciate the perfection found in imperfection. This region is a spiritual heart of Japan, where harmony and purity are celebrated.' where id = 'dpNpJWgenvGKcKhqpt7BA';
update content_bodies set title = 'スピリチュアル関西、武士道', description = '伝統的な日本の武道を体験し、鍛冶屋が鋼を打ち鍛える様子を目の前で見ながら、火花が飛び散る中で輝く剣が形作られる様子を感じてください。そして、美しい城の天守閣に登り、純粋で誠実な生き方を学びましょう。武士道の哲学は、仁、義、礼、智、信、忠といった価値観を重視し、関西という日本の精神的な地域に根付いています。自らの道徳心を見つめ直すことで、人格を高め、武士道の本質を受け入れることができます。' where id = 'xbL2q2pxvLMc85NFMB_Ph';
update content_bodies set title = 'Spiritual KANSAI, Bushido', description = 'Experience traditional Japanese martial arts as a blacksmith passionately shapes steel into a sword, with sparks flying from the fire. Climb a magnificent castle keep and learn the virtues of living a pure and honest life. The philosophy of Bushido, which emphasizes humanity, honesty, gratitude, wisdom, belief, and loyalty, is deeply rooted in Kansai, Japan''s spiritual region. By reflecting on our moral compass, we can elevate our character and embrace the essence of Bushido.' where id = 'NaBzhhjZxR95uAo4E6wPc';
update content_bodies set title = 'スピリチュアル関西、巡礼', description = 'スピリチュアル関西の全ルートを歩くことは、自然との調和を見出し、先人たちへの新たな敬意を抱く貴重な機会を提供します。この旅は数日間にわたり、参加者は自分自身を見つめ直し、新しい価値観を受け入れ、自然の中で再生を体験することができます。古い苔むした道は手つかずの風景を通り抜け、旅行者に精神的な旅を振り返るよう促します。啓発を求めた人々の足跡を辿ることで、参加者は関西地域の神聖さとの特別なつながりを感じることができるでしょう。この巡礼は、自然と地域の精神的遺産への深い感謝を促す変革的な体験を約束します。' where id = 'Br2gcukWMIwZi6e1fwOPe';
update content_bodies set title = 'Spiritual KANSAI, Pilgrimage', description = 'Walking the entire route of Spiritual KANSAI offers a profound opportunity to connect with nature and honor the legacy of past pilgrims. This journey, which spans several days, allows individuals to discover their inner selves, embrace new values, and experience a rebirth in the natural world. The ancient, moss-covered paths lead through untouched landscapes, inviting travelers to reflect on their spiritual journey. Following in the footsteps of those who sought enlightenment, participants can feel a unique connection to the sacredness of the Kansai region, Japan''s spiritual heart. This pilgrimage promises a transformative experience, encouraging a deeper appreciation for nature and the spiritual heritage of the area.' where id = 'V2H-oECJJtidY08kZco6I';
update content_bodies set title = 'スピリチュアル関西、巡礼', description = 'スピリチュアル関西の全ルートを歩くことは、自然と調和し、先人たちへの敬意を表す貴重な機会を提供します。この旅は数日間にわたり、内なる自己を探求し、自然の中での再生と新たな価値観の発見へと導きます。古い苔むした道は、関西、日本の聖なる地域を通り抜け、旅行者を清らかな風景へと導きます。啓発を求めた人々の足跡を辿ることで、過去との深い結びつきを感じ、この人生における新たな目的を再確認する変革の旅を体験できるかもしれません。' where id = 'KnQlGopXz7cDpqFIBhJrA';
update content_bodies set title = 'Spiritual KANSAI, Pilgrimage', description = 'Walking the entire route of Spiritual KANSAI offers a profound opportunity to connect with nature and honor the legacy of past pilgrims. This journey, which spans several days, allows individuals to explore their inner selves, leading to a rebirth in nature and the discovery of new values. The ancient, moss-covered paths guide travelers through pristine landscapes, evoking the spiritual essence of Kansai, Japan''s sacred region. As one follows in the footsteps of those who sought enlightenment, they may experience a transformative journey, feeling a deep connection to the past and a renewed sense of purpose in this lifetime.' where id = 'j4i3E_m8S7DP-JPatjVtS';
update content_bodies set title = 'スピリチュアル関西、瞑想', description = '美しい庭と豊かな歴史に囲まれた大きな寺院で、特別な座り方を採用し、筆を持って日本の和紙に心の内を表現する禅の瞑想を行います。その後、自然の恵みを感じる美味しい食事を楽しむことができます。このプログラムは、日本の精神文化を学びながら、心と体の完璧なバランスを再発見することを目的としています。世俗から離れ、自然と調和し、視覚、聴覚、触覚、味覚、嗅覚を再覚醒させることで、真の自分を見つけ出すことを促します。関西、日本のスピリチュアルな地域で、禅の本質を深く理解することができます。' where id = 'zNmRQtkSoxGpry2B9QscO';
update content_bodies set title = 'Spiritual KANSAI, Meditation', description = 'In a serene temple surrounded by a beautiful garden and rich history, participants engage in Zen meditation by adopting a special seating position, holding a writing brush, and expressing their inner thoughts on Japanese paper. This experience is complemented by a delicious meal that embodies the blessings of nature. The program aims to help individuals learn about Japan''s spiritual culture while rediscovering their own balance between body and mind. It encourages participants to detach from worldly distractions and reconnect with their senses—sight, sound, touch, taste, and smell—ultimately leading to a deeper understanding of oneself and the essence of Zen in the spiritual region of Kansai, Japan.' where id = 'wDDzWXr65b8cEamZkKTL2';
update content_bodies set title = 'スピリチュアル関西、瞑想', description = '美しい庭と豊かな歴史に囲まれた大きな寺院で、特別な座り方を採用し、筆を持って日本の和紙に心の内を表現する禅の瞑想を行います。その後、自然の恵みを感じる美味しい食事を楽しむことができます。このプログラムは、日本の精神文化を学びながら、心と体のバランスを再発見することを目的としています。世俗から離れ、感覚（視覚、聴覚、触覚、味覚、嗅覚）を再覚醒させ、自分自身を見つけ出すことを促します。関西、日本のスピリチュアルな地域で、禅の本質を理解する手助けをします。' where id = 'bUsjCr19jhqd_W23uha48';
update content_bodies set title = 'Spiritual KANSAI, Meditation', description = 'In a serene temple surrounded by a beautiful garden and rich history, participants engage in Zen meditation by adopting a special seating position, holding a writing brush, and expressing their inner thoughts on Japanese paper. This experience is complemented by a delicious meal that embodies the blessings of nature. The program aims to help individuals learn about Japan''s spiritual culture while rediscovering their own balance between body and mind. It encourages participants to detach from worldly distractions and reconnect with their senses—sight, sound, touch, taste, and smell—ultimately leading to a deeper understanding of oneself and the essence of Zen in the spiritual region of Kansai, Japan.' where id = '64-miJC17cybqv9vHmpoY';
update content_bodies set title = '松之山サステナブル・ダイニングin美人林2023', description = '2023年の松之山サステナブル・ダイニングは、日本の里山の持続可能性をテーマにしています。豪雪に何度も脅かされながらも、自然と共存し続ける里山の物語を、料理を通じて再構築するイベントです。今年で5回目を迎えるこの夏のイベントは、フランス・シャンパーニュの「TELMONT」の特別協賛を受けています。参加するシェフには、ニセコの高澤義明シェフ、西麻布の池尻綾介シェフ、世田谷の志賀勝栄シェフ、新富町の折笠龍馬シェフ、酒の宿玉城屋の栗山昭シェフ、ひなの宿ちとせの柳政道シェフが名を連ねています。特別協力をいただいた各所にも感謝の意が表されています。' where id = '4eRjcCeJvV2OzZ-kuRhfm';
update content_bodies set title = 'Matsunoyama Sustainable Dining in 美人林 2023', description = 'The Matsunoyama Sustainable Dining event in 2023 showcases the enduring spirit of Japan''s satoyama, which has thrived despite the challenges posed by heavy snowfall. This year''s event, featuring the culinary artistry of ''TAKAZAWA,'' reconstructs the grand story of satoyama through food. It marks the fifth summer of sharing this narrative, with special sponsorship from the French Champagne house ''TELMONT,'' which supports sustainable practices in the snow country. Renowned chefs participating include Yoshitaka Takazawa from Niseko, Ayasuke Ikeshiri from Ma Cuisine, Katsuaki Shiga from Signifiant Signifié, Ryoma Orikasa from Coulis, Akira Kuriyama from Sakeno Yado Tamakiya, and Masamichi Yanagi from Hinano Yado Chitose. Special thanks are extended to various partners and local tourism associations.' where id = '4HJKQP84NQu_CO16HjfkH';
update content_bodies set title = '喫煙場所編', description = 'このリソースは、関西地域における指定喫煙場所に関する情報を提供しています。関西ガイドのウェブサイトへのリンクや、FacebookやInstagramなどのソーシャルメディアプラットフォームへのリンクも含まれており、さらなる情報や更新を得ることができます。' where id = 'UAT8dUw5AC0C-w5Crqjcq';
update content_bodies set title = 'Knowing Where to Smoke', description = 'This resource provides information about designated smoking areas in the Kansai region. It includes links to the Kansai Guide website, as well as social media platforms like Facebook and Instagram for further engagement and updates.' where id = 'OxIQbXttvTpNfpExi-NK9';
update content_bodies set title = '雪国観光圏があなただけの旅をご提案します', description = 'あなたは旅になにを求めますか？自らの見識を広げる経験や地域社会、環境への配慮、本来の自分に戻る時間など、旅に求めるものは人それぞれです。雪国観光圏にお気軽に相談してみてください。雪国の自然や文化に根ざした本物の体験交流を通じて、あなただけの旅を組み立ててご提案します。' where id = 'LMr9DiGjeKT5lr-pJPZyw';
update content_bodies set title = 'Snow Country Tourism Area Offers a Unique Travel Experience Just for You', description = 'What do you seek in your travels? Expanding your knowledge, considering the local community and environment, or finding time to reconnect with your true self? Everyone has different desires when it comes to travel. Feel free to consult with the Snow Country Tourism Area. We will help you create a personalized journey based on authentic experiences rooted in the nature and culture of the snow country.' where id = 'nQaOb4Pe4vGDwrlXeWzSI';
update content_bodies set title = '多様性の中の調和 / 雪国のエコロッジ', description = '100年後も雪国であり続けるために、私たちは多様なものが多様性を失うことなく、ありのままに存在し、共存している姿を旅行者に体験してほしいと願っています。' where id = 'WW0QjzZ4J4ms_vPmtEKxS';
update content_bodies set title = 'Harmony in Diversity / Ecolodge Japan in YUKIGUNI', description = 'Our goal is to ensure that Snow Country remains vibrant and diverse for the next 100 years. We invite travelers to experience the beauty of coexistence, where various elements exist authentically and harmoniously without losing their uniqueness.' where id = '6FQxmUePiHNlnneeS-o3x';
update content_bodies set title = '松之山ダイニング in 美人林 2022', description = '持続可能性の象徴である日本の里山は、豪雪によって何度も寸断されながらも、自然と共存し、伝統を受け継いできました。この壮大な里山の物語を、料理を通じて再構築する松之山ダイニングは、今年で4回目を迎えます。『TAKAZAWA』によって語られる里山ストーリーは、今年の夏にどのような物語を魅せてくれるのでしょうか。' where id = 'FfogICH-36S52GKLQdY8J';
update content_bodies set title = 'Matsunoyama Dining in 美人林 2022', description = 'Sustainability is exemplified in Japan''s satoyama, which continues to thrive despite the relentless heavy snowfall that disrupts its activities. The satoyama lifestyle has been repeatedly challenged but has persevered, coexisting with nature and passing down its traditions. Matsunoyama Dining, reinterpreted through cuisine by ''TAKAZAWA'', tells this grand satoyama story for the fourth time this year. This summer, it promises to showcase a captivating narrative.' where id = 'I2xDJ0Q3oMnWlhL04f_1A';
update content_bodies set title = '雪によって形作られた生活 - 雪国の持続可能な価値「里山・ローカルガストロノミー・温泉」', description = 'この説明は、雪国に特有の体験や価値を強調しており、自然環境、文化、そして暮らしに焦点を当てています。特に「里山」と呼ばれる伝統的な農村風景、地域の食材を活用したローカルガストロノミー、そして文化的に重要な「温泉」の存在が強調されています。これらの要素は、雪に囲まれた風景と深く結びついた持続可能な生活様式を形成しています。' where id = 'RNw8NalnCHlEcdT1Yq3LV';
update content_bodies set title = 'Lives shaped by snow - Sustainable value of Snow country "Satoyama, local gastronomy, Onsen"', description = 'The description highlights the unique experiences and values found in snow country, focusing on its natural environment, culture, and lifestyle. It emphasizes the significance of ''Satoyama'' (a traditional rural landscape), local gastronomy that utilizes regional ingredients, and the cultural importance of ''Onsen'' (hot springs). These elements together create a sustainable way of life that is deeply connected to the snowy landscape.' where id = 'fmAjArKrWiWODq3WID1G_';
update content_bodies set title = '上信越高原国立公園の自然に囲まれた秘境の一軒宿', description = '文化財に指定された木造の建物を有し、伝統的な旅館の風情を楽しむことができる宿です。自然に湧き出る温泉を維持するためのモニタリングを行い、持続可能な経営に配慮しています。また、周辺の国有林の生物多様性を復元する取り組みにも参加しています。' where id = '9kDGuqPbYrT1qB5P1_d9a';
update content_bodies set title = 'A Hidden Inn Surrounded by Nature in Joshinetsu Kogen National Park', description = 'This inn features a wooden building designated as a cultural asset, allowing guests to experience the charm of a traditional ryokan. It conducts monitoring to maintain its naturally sourced hot springs and operates with a focus on sustainability. The inn also participates in efforts to restore biodiversity in the surrounding national forest.' where id = 'iQXiX-apJQQMlKjACAHhN';
update content_bodies set title = '松之山湯けむりダイニング by TAKAZAWA', description = '2021年11月12日、新潟県十日町市の松之山温泉で松之山湯けむりダイニングが開催されました。この一夜限りのダイニング体験では、温泉街を歩きながら松之山ならではのガストロノミーを楽しむことができました。' where id = 'gfoplCJRSqZ1BFy3P3nyC';
update content_bodies set title = 'Matsunoyama Dining by TAKAZAWA', description = 'On November 12, 2021, Matsunoyama Dining was held in Matsunoyama Onsen, Tokamachi City, Niigata Prefecture. This unique one-night dining experience allowed guests to enjoy the local gastronomy of Matsunoyama while strolling through the hot spring resort.' where id = 'ZeFcMbefgjIDw2HtJ1D19';
update content_bodies set title = '滋賀県愛荘町　観光プロモーション(歴史文化編)', description = 'この歴史文化編では、ここにしかない物語を紹介し、いにしえの記憶をたどる旅へと誘います。愛荘町の観光情報の詳細は、以下のURLをクリックしてください。https://www.town.aisho.shiga.jp/kankou/。お問い合わせは、愛荘町商工観光課（電話：0749-37-8057）までお願いします。' where id = 'eM4zsSagkQ-eSi3W2A1lh';
update content_bodies set title = 'Aisho Town, Shiga Prefecture - Tourism Promotion (Cultural History Edition)', description = 'This section focuses on the unique stories found only here, inviting visitors to embark on a journey tracing ancient memories. For more detailed information about tourism in Aisho Town, please click the following URL: https://www.town.aisho.shiga.jp/kankou/. For inquiries, contact the Aisho Town Commerce and Tourism Division at 0749-37-8057.' where id = 'NrTms39xdwTnYpol88TDr';
update content_bodies set title = '【Trip to Hokkaido】IWAMIZAWAプロモーション動画＿vlog full', description = '北海道旅行で日常+αを求めた「ちょっといい旅体験」をテーマにしたIWAMIZAWAプロモーション動画が公開されました。動画では、食・景色・アクティビティを楽しむ4人が登場し、岩見沢市内の立ち寄りスポット16箇所を紹介しています。グルメ、宿泊、キャンプ場、カフェ、お土産品購入など多彩な選択肢があり、岩見沢の美しい景色や魅力的な人々との出会いが、訪れる人々の旅を特別なものにすることを願っています。友達や家族と共に、岩見沢での「ちょっといい旅体験」を楽しむことを提案しています。' where id = 'xy9pRYMhf-icLA32DmFbX';
update content_bodies set title = 'Trip to Hokkaido: IWAMIZAWA Promotional Video - Vlog Full', description = 'This promotional video showcases a ''little good travel experience'' in Iwamizawa, Hokkaido, featuring four individuals enjoying the local food, scenery, and activities. The full video highlights 16 recommended spots in Iwamizawa, including diverse options for dining, lodging, camping, cafes, and souvenir shopping. The picturesque landscapes, unique atmosphere, and encounters with charming locals aim to make every visitor''s trip special. The video invites friends, family, and loved ones to embark on a memorable journey to Iwamizawa, promising an enriching travel experience.' where id = 'IkqAQkqhs1PpyCSTGwv0f';
update content_bodies set title = '岩見沢への旅 - PV_vlogショート - 日常＋αの岩見沢の楽しみ方（北海道旅行PR動画）', description = 'このプロモーション動画は、北海道岩見沢でのユニークな旅行体験を紹介しています。4人の旅行者が地元の景色や雰囲気、魅力的な人々との出会いを楽しむ様子が描かれています。ショートバージョンにはフルバージョンにはないカットが含まれており、必見です。この動画は、視聴者に岩見沢を次の旅行先として考えるよう促し、旅行を通じて特別な瞬間を創造することの重要性を強調しています。岩見沢へのアクセスは、新千歳空港から60分、札幌丘珠空港から50分、旭川空港から110分と便利です。詳細は岩見沢市観光協会のウェブサイトやインスタグラムをご覧ください。' where id = '8tv5CPleudI1nyEhukxeq';
update content_bodies set title = 'Trip to IWAMIZAWA HOKKAIDO - PV_vlog Short - Enjoying Daily Life + α in Iwamizawa (Hokkaido Travel PR Video)', description = 'This promotional video showcases a unique travel experience in Iwamizawa, Hokkaido, where four travelers enjoy the local scenery, atmosphere, and encounters with fascinating people. The short version of the vlog includes exclusive cuts not found in the full version, making it a must-watch. The video aims to inspire viewers to consider Iwamizawa for their next trip, highlighting the special moments that can be created through travel. Access to Iwamizawa is convenient, being just 60 minutes from New Chitose Airport, 50 minutes from Sapporo Okadama Airport, and 110 minutes from Asahikawa Airport via the Dōō Expressway. For more information, visit the Iwamizawa Tourism Association''s website and Instagram.' where id = 'PT07GQqclRRqWEdWmFmKi';
update content_bodies set title = '関まつり2025 パレードステージ', description = '令和7年4月19日(土)に関市の中心市街地で開催された「関まつり2025 パレードステージ」の様子をお届けします。ダンスや民踊、マーチングバンドなど、多彩な出演団体が沿道を華やかに盛り上げ、見応えのあるパレードステージが展開されました。熱気あふれる団体の一体感を、ぜひ動画でお楽しみください。' where id = 'v5dsx2zgB417QLzsC444q';
update content_bodies set title = 'Seki Festival 2025 Parade Stage', description = 'On April 19, 2025, the ''Seki Festival 2025 Parade Stage'' took place in the central area of Seki City. The event featured a vibrant parade with various performances, including dance, folk dances, and marching bands, which added to the festive atmosphere along the streets. The sense of unity and enthusiasm among the participating groups was palpable, making it a visually captivating experience. Enjoy the highlights in the video!' where id = 'WAOvAuk298H2jjqDeu0Ac';
update content_bodies set title = '三重県東紀州観光プロモーション動画/Japan Travel', description = '三重県南部に位置する「東紀州」地域をご存知ですか？美しい自然や世界遺産の熊野古道伊勢路、日本の始まりに繋がる歴史を持つこの地域をぜひ訪れてみてください。観光情報はリンクからご覧いただけます。また、「TripBlender三重・東紀州」を利用すれば、行きたい場所を選ぶだけで効率的な旅行プランを作成できます。この動画では、七里御浜や便石山、銚子川、楯ヶ崎など、地域の自然美や文化遺産を紹介しています。' where id = 'o30TRIYhPEYtRWFpUvXlI';
update content_bodies set title = 'Mie Prefecture Higashi-Kishu Tourism Promotion Video/Japan Travel', description = 'Have you heard of the Higashi-Kishu region located in the southern part of Mie Prefecture? This area boasts beautiful nature, the UNESCO World Heritage Kumano Kodo Iseji, and a rich history connected to the beginnings of Japan. We invite you to visit Higashi-Kishu. You can find more tourist information at the provided link. Additionally, the ''TripBlender Mie Higashi-Kishu'' allows you to create efficient travel plans by simply selecting the places you want to visit. The video showcases various spots, including Shichiri Mihama Beach, Binshiyama, Choshigawa, and many more, highlighting the natural beauty and cultural heritage of the region.' where id = 'E8psuzxhjRAi7-dxlgwHV';
update content_bodies set title = '2021年を振り返る', description = '弘前を愛する人々がインスタグラムで「#ecomeonhirosaki」を付けて投稿した素晴らしい写真を集めたスライドショー動画です。季節ごとに変わる美しい風景や弘前の隠れた魅力をじっくりと楽しむことができます。弘前の街の素晴らしさを再発見する機会です。' where id = '2-OY6-riKW0eeQ8c0aTHd';
update content_bodies set title = 'Looking back on 2021 with Instagram photos', description = 'This slideshow features wonderful photos shared on Instagram with the hashtag #ecomeonhirosaki by both locals and tourists who cherish Hirosaki. It showcases the beautiful seasonal scenery and the hidden charms of Hirosaki city, inviting viewers to appreciate the changing landscapes throughout the year.' where id = '9eJboPM4LQylkWgawDnS_';
update content_bodies set title = '仁淀川の四季', description = '高知県の仁淀川は、その透明度と青さから『仁淀ブルー』と称され、四季折々の美しさで訪れる人々を魅了します。神秘的な自然の風景や地域の人々の暮らし、伝統的な神事などを楽しむことができます。本映像は、長年にわたり仁淀川水系を撮影してきたネイチャーカメラマン・高橋宣之氏による貴重な映像です（一部を除く）。' where id = '_1tZWBDexkzeZjXUysNRP';
update content_bodies set title = 'The Four Seasons of Niyodo River', description = 'Niyodo River in Kochi Prefecture, known for its transparency and blue color referred to as ''Niyodo Blue,'' captivates visitors with its beauty throughout the four seasons. The film showcases the mystical natural landscapes, the lives of the local people, and the traditional rituals that have been passed down in the region. This valuable footage has been captured over many years by nature photographer Nobuyuki Takahashi, with some exceptions.' where id = 'AQQQQ-wmtUcudRyyzmn6U';
update content_bodies set title = 'NIYODO BLUE!　~春はすぐそこ。~', description = '仁淀川の春が近づいています。仁淀ブルーと共に花桃や桜が咲き乱れ、色とりどりの美しい景色が広がります。この高知県の地域では、訪れる人々が春の魅力を楽しむことができます。' where id = '1jUFRxHpyFqq_HbsFAgDE';
update content_bodies set title = 'NIYODO BLUE! ~Spring is around the corner.~', description = 'Spring is just around the corner in Niyodo River. The season brings vibrant colors as peach and cherry blossoms bloom alongside the famous Niyodo Blue, creating a picturesque landscape. Visitors can enjoy the beautiful scenery and the unique charm of this area in Kochi Prefecture.' where id = 'gluEFiHd0CHVdWk3vNwN0';
update content_bodies set title = '【高知県 仁淀川エリアPR動画】 ''究極のブルー編''', description = '多忙な日常や将来への不安を抱える中、仁淀川は心を解き放つ不思議な場所です。動画では、仁淀川の美しさを紹介し、訪れることで「究極のブルー」を体験できることを伝えています。日常のストレスから解放されるために、ぜひ仁淀川を訪れてみてはいかがでしょうか。' where id = '93u9gaOUBgG8ZOJmZkd43';
update content_bodies set title = 'PR Video of Niyodogawa Area, Kochi Prefecture: ''Ultimate Blue Edition''', description = 'In our busy lives filled with stress and uncertainty, Niyodogawa offers a unique escape where anyone can feel their heart relax. This video invites you to experience the ''Ultimate Blue'' of Niyodogawa, a place that can help you unwind from daily pressures. Discover the beauty of this area and consider visiting to see it for yourself.' where id = 'BBaOWHLHjM4yrifbW8Dj2';
update content_bodies set title = '仁淀ブルー女子旅 Ver2', description = '仁淀川流域での女子旅を提案します。美味しい食事を楽しみ、癒しの景色を堪能し、日常を離れた特別な旅を体験できます。' where id = 'cCGqj6w-fXs80TPgCIRSf';
update content_bodies set title = 'Niyodo Blue Women''s Trip Ver2', description = 'This proposal offers a ''women''s trip'' in the Niyodo River basin. Enjoy delicious food, relax in beautiful scenery, and experience an extraordinary journey!' where id = 'UYVU8rr_BS24KuJgNMtns';
update content_bodies set title = '仁淀ブルー女子旅 Ver1', description = '仁淀川流域での女子旅を提案します。美味しい食事を楽しみ、癒しの景色を堪能し、日常を離れた特別な旅を体験しましょう。' where id = '_OQp3kPYLQx0p2PlFfgJH';
update content_bodies set title = 'Niyodo Blue Girls'' Trip Ver1', description = 'This proposal suggests a ''girls'' trip'' in the Niyodo River basin. Enjoy delicious food, relax with beautiful scenery, and experience an extraordinary journey!' where id = '07IOLappGbJG38fbf3a_B';
update content_bodies set title = '大迫力な落差でマイナスイオン❝雨竜の滝❞', description = '雨竜の滝は中津渓谷の入口から約30分で到達可能です。迫力ある落差と、滝から発生するマイナスイオンが特徴です。' where id = 'RY3i58nEn_Wjyb4luiaDd';
update content_bodies set title = 'Impressive Waterfall with Negative Ions: ''Uryu Falls''', description = 'Uryu Falls can be reached in about 30 minutes from the entrance of Nakatsu Valley. It is known for its stunning drop and the refreshing negative ions it produces.' where id = 'uC8grXMwC1Q77rNR85PDy';
update content_bodies set title = '高知仁淀ブルーライド GREAT EARTH', description = '日本一の清流である仁淀川を巡るサイクリングイベント「GREAT EARTH 高知仁淀ブルーライド」が開催されます。このイベントでは、仁淀川流域の美しい風景を楽しみながら走ることができ、エイドステーションでは地元の美味しい料理も味わえます。' where id = 'znOZ69TsdgK4z1_wYlLZf';
update content_bodies set title = 'Kochi Niyodo Blue Ride GREAT EARTH', description = 'The GREAT EARTH Kochi Niyodo Blue Ride is a cycling event that takes participants along the Niyodo River, known as Japan''s clearest stream. Riders can enjoy the beautiful scenery of the Niyodo River basin and savor delicious local cuisine at aid stations along the route.' where id = 'WoQQbxqHilOFvIGT5w8fi';
update content_bodies set title = '川越 - KAWAGOE -', description = '日本滞在の最終日、メキシコに帰る準備をする2人は「小江戸川越」を訪れ、楽しかった日々を思い出しつつ少し寂しさを感じています。浴衣を着て外に出ると、街は人々で賑わい、まるで時間が流れているかのようです。自分たちの「時」を見つける旅に出かけ、懐かしい空間に浸りながらも、過去には戻れないことを実感します。最後に「時の鐘」にたどり着き、過去よりも未来が大切であることに気づきます。彼らは一瞬一瞬を大切にしながら、共に未来へ進むことを決意します。' where id = 'y1v96WOGM2d5rFA-wzk-P';
update content_bodies set title = 'Kawagoe - KAWAGOE -', description = 'On their last day in Japan, a couple visits the town of Kawagoe, feeling a mix of joy and sadness as they prepare to return to Mexico. Dressed in yukata, they notice the bustling streets filled with people, as if time itself is moving around them. They embark on a journey to find their own ''time,'' reflecting on the nostalgic atmosphere that surrounds them. Despite their search, they realize that they cannot return to the past. Their quest leads them to the ''Time Bell,'' where they come to understand that the future is more important than the past. They decide to cherish each moment together as they look forward to their future.' where id = 'lvlw1Y2tp8WDId9gVl6Is';
update content_bodies set title = '【盆踊り編】よみがえる下風呂小唄 〜下風呂温泉郷のいま〜（青森県風間浦村）', description = 'かつて温泉郷で歌い継がれていた「下風呂小唄」は、時代の流れとともに忘れ去られてしまいました。口伝えでかろうじて残されていたこの歌を蘇らせるプロジェクトが発足し、2022年夏に新たに収録されました。温泉郷の女将たちで構成される「下風呂温泉おかみの会」が振り付けを考案し、2023年夏には「下風呂温泉郷納涼夜店祭り」で初披露され、盆踊りとして復活を果たしました。' where id = 'RUj_OJn_dyjWgLJtfEDzF';
update content_bodies set title = 'Reviving Shimofuro Kouta: The Present of Shimofuro Onsen Town (Kazamaura, Aomori Prefecture)', description = 'The ''Shimofuro Kouta,'' once sung in the hot spring town, has been forgotten over time. A project was initiated to revive this song, which had barely survived through oral tradition, by adding accompaniment. In the summer of 2022, the newly recorded ''Shimofuro Kouta'' was choreographed by the members of the ''Shimofuro Onsen Okami Association,'' consisting of the innkeepers of the hot spring town. It was first performed at the ''Shimofuro Onsen Town Summer Night Festival'' in the summer of 2023, marking the revival of the town''s Bon Odori dance.' where id = '_p2qNrZsLrscdnytZf4Vd';
update content_bodies set title = '【2025年版　🌊2025/07/05OPEN】🌞今年も熱い！御殿場ウォーター亀ハウス！', description = '津市御殿場海岸には、日本最大のウォーターアスレチックがあることをご存知ですか？約2000台の駐車場が完備されており、アクセスも良好です。オープンから3年が経ち、毎年施設はパワーアップしています。小さなお子様から大人まで楽しめるアクティビティが揃っており、BBQ施設や海の家も完備されています。今年の厳しい夏に、ぜひ一度訪れてみてはいかがでしょうか？御殿場ウォーター亀ハウスは2025年7月5日から9月23日まで営業し、営業時間は9:00から16:30（最終受付）です。詳しい情報は観光三重サイトをご覧ください。' where id = 'DuxwyTmWk43YXh5wPM-qI';
update content_bodies set title = 'Gotenba Water Turtle House Opening on July 5, 2025!', description = 'Did you know that the largest water athletic facility in Japan is located at Gotenba Beach in Tsu City? With ample parking for about 2,000 vehicles, it offers excellent access for a fun day out. After three years of operation, the facility has been upgraded annually, providing enjoyment for both children and adults. There are BBQ facilities and beach houses available, allowing visitors to relax for a whole day. Why not take a trip this summer to escape the heat? Gotenba Water Turtle House will be open from July 5 to September 23, 2025, with operating hours from 9:00 AM to 4:30 PM (last entry). For detailed reports, check the Kankou Mie website.' where id = 'SgUTpvqQGKolACoi3r4re';
update content_bodies set title = 'お茶屋さん直営店🍵「深緑茶房」のお茶とスイーツで爽やかな夏を🍃', description = '三重県松阪市にある「深緑茶房」は、伊勢茶を生産するお茶農家が直営するお店です。ここでは、淹れたてのお茶や和菓子、お茶を使ったスイーツを楽しむことができます。人気のカキ氷は2025年7月19日から8月24日まで提供され、冷たい伊勢茶とスイーツで夏の始まりを爽やかに彩ります。営業時間は物販が9:00～17:30、日本茶カフェが10:00～16:00で、水曜日が定休日です。詳しくは観光三重トピックスをご覧ください。' where id = 'ttMO1c3iyXbT_finyQX1s';
update content_bodies set title = 'Refreshing Summer with Tea and Sweets at ''Shinryoku Sabo'' Directly Managed Store 🍵', description = 'Located in Matsusaka City, Mie Prefecture, ''Shinryoku Sabo'' is a direct store run by a tea farmer producing Ise tea. Visitors can enjoy freshly brewed tea, traditional Japanese sweets that pair well with tea, and desserts made with tea. The popular shaved ice will be available from July 19 to August 24, 2025, offering a refreshing way to celebrate the start of summer with cold Ise tea and sweets. The store is open for retail from 9:00 AM to 5:30 PM and the Japanese tea café from 10:00 AM to 4:00 PM, closed on Wednesdays. For more details, check the Mie Tourism Topics.' where id = 'noH-yTHNfCCxc7wMz_6LE';
update content_bodies set title = 'GWでも混まない穴場スポット！三重県内の花と新緑おすすめ5選💐', description = '三重県の奥伊勢エリアにある、GWでも混雑しない花と新緑のおすすめスポットを5つ紹介します。まず、藤棚が美しい野原農村公園は、VISONから車で8分の場所にあります。次に、大平つつじ山は自生するつつじが見られ、紀勢自動車道の大内山ICから車で5分です。真手公園では新緑のリフレクションと鯉が楽しめ、紀勢自動車道の大宮大台ICから12分の距離です。丸山公園は真手公園と共通のアクセスで、トトロの森が広がります。最後に、三瀬館跡・茶臼山は5台の駐車場があり、大宮大台ICから車で10分です。この投稿が面白いと思ったら、ぜひ「いいね＆保存」をお願いします！' where id = 'c8smFTlq_wV8HtTfiC5uw';
update content_bodies set title = 'Hidden Spots in Mie Prefecture for Flowers and Fresh Greenery During GW!', description = 'Discover five recommended spots in the Oku-Ise area of Mie Prefecture that remain uncrowded during Golden Week. Highlights include: 1) Nohara Rural Park, featuring beautiful wisteria, located 8 minutes from VISON by car. 2) Oohira Tsutsuji Mountain, known for its wild azaleas, just 5 minutes from Oouchiyama IC. 3) Mate Park, where you can enjoy reflections of fresh greenery and koi, located 12 minutes from Oomiya Oda IC. 4) Maruyama Park, home to new green Totoro Forest, shares access with Mate Park. 5) Sanseikan Ruins and Chausuyama, with a parking capacity of 5 cars, located 10 minutes from Oomiya Oda IC. If you find this post interesting, please like and save it!' where id = '3dhwNOwBtQjKJf7WBCx_r';
update content_bodies set title = 'レインボーチタンの焼き色付け体験！「クラフトアルマジロ」', description = '鈴鹿市で行われるレインボーチタンの焼き色付け体験は、モータースポーツの町ならではの特別な体験です。「クラフトアルマジロ」の工場で、オートバイのレース用マフラーなどのチタン製品を製造する中で、加熱によって色が変わるチタンの特性を活かした体験ができます。カップやバッジ、キーホルダーなどのコースから選び、世界に一つだけのオリジナルチタン製品を作成可能です。スタッフがマンツーマンで優しく指導してくれるため、初心者や子供でも安心して参加できます。ガスバーナーでチタンを炙り、色がついていく様子は神秘的です。体験後は、作ったチタンカップでコーヒーを楽しむことができます。価格は、キーホルダーやバッジコースが4,950円から、チタンカップコースは19,800円です。三重県鈴鹿市に位置し、白子駅からバスやタクシーでアクセス可能です。' where id = 'a2ZmjnMU4FAUu_fSfpEJG';
update content_bodies set title = 'Experience Coloring Rainbow Titanium at ''Craft Armadillo''!', description = 'Join a unique experience in Suzuka City, known for motorsports, where you can color rainbow titanium! At the ''Craft Armadillo'' factory, which manufactures titanium products like motorcycle racing exhausts, you can witness the special properties of titanium that change color with heat. Choose from various courses, including cups, badges, and keychains, to create your own original titanium product. The staff provides one-on-one guidance, making it suitable for beginners and children. The process of heating titanium with a gas burner to achieve beautiful colors is truly mystical! After the experience, enjoy coffee in your titanium cup. Prices start from 4,950 yen for keychains and badges, up to 19,800 yen for the titanium cup course. Located in Suzuka, Mie Prefecture, the factory is accessible by bus or taxi from Shiroko Station.' where id = 'pno9pRTLkBkloGmBh7S8D';
update content_bodies set title = 'とこしえの祈りを込めて　～「持続可能な観光地」三重～　15秒ver', description = '三重県は日本列島のほぼ中央に位置し、伊勢湾や熊野灘に面し、鈴鹿山脈や紀伊山地などの自然に恵まれています。また、二千年の歴史を持つ伊勢神宮や鳥羽志摩の海女など、伝統文化も豊かです。「持続可能」という言葉が注目される中、三重の自然や文化は大切に守られてきた宝物です。先人たちの想いが込められた美しい自然と伝統を未来へ繋ぐため、三重を訪れてみませんか？' where id = 'oB6bp3b19MoID4WDKQ5gA';
update content_bodies set title = 'Eternal Prayers: Sustainable Tourism in Mie - 15 Seconds Version', description = 'Mie Prefecture, located in the central part of Japan, is blessed with a rich natural environment featuring the Ise Bay, Kumano-nada Sea, and the Suzuka and Kii mountain ranges. It is also home to the Ise Jingu, a sacred site with a history of over 2000 years, and the traditional Ama divers of Toba and Shima. The concept of ''sustainability'' has gained prominence in recent years, yet the natural beauty and cultural heritage of Mie have been preserved as invaluable treasures. The desire to protect Mie''s beautiful nature and esteemed traditions for future generations is deeply rooted in the hearts of its ancestors. Why not visit Mie, a ''sustainable tourism destination'' infused with these eternal prayers?' where id = '0LreIyfDy-MM75G-bIK2g';
update content_bodies set title = '合格祈願に最適！日本で唯一の頭の神様！', description = '全国から参拝者が訪れる「頭之宮四方神社」は、試験の合格祈願で有名な神社です。ここでは合格祈願だけでなく、ヘルメットのお祓いも行っており、これは全国で唯一のサービスです。また、古くから湧き出る知恵の水を求める人々も多く訪れています。詳しくは観光三重のウェブサイトをご覧ください。' where id = 'zMkWNkw576dgbMjJhNOyR';
update content_bodies set title = 'The Only God of Wisdom in Japan for Exam Success!', description = 'Koubenomiya Yomou Shrine, known for its exam success prayers, is the only shrine in Japan dedicated to the God of Wisdom. Visitors from all over the country come to pray not only for passing exams but also for helmet blessings, a unique service offered here. Many also seek the ''wisdom water'' that has been flowing for ages. For more details, visit the Mie Tourism website.' where id = '9DDbXJuLI__LWhIdAz46y';
update content_bodies set title = 'ワンランク上のグランピング体験ができる！「LUXUNA伊勢志摩」', description = 'LUXUNA伊勢志摩は三重県志摩市、御座白浜から徒歩約200mの場所に位置しています。海が目の前にあるプライベート空間で、手ぶらで快適なグランピング体験が楽しめます。マリンアクティビティが充実しており、大自然の中でのテントサウナや、伊勢志摩の海の恵みを堪能できる贅沢なBBQも魅力です。焚き火ができるファイヤーピットや無料のデザートも用意されています。この夏、ぜひLUXUNA伊勢志摩に遊びに行ってみてはいかがでしょうか。日帰り客向けのアクティビティもあります。詳細は観光三重で紹介中です。' where id = 'FfTinu1DI1R1yD3ZZ3BIF';
update content_bodies set title = 'Experience a Premium Glamping Adventure at LUXUNA Ise-Shima!', description = 'LUXUNA Ise-Shima is located about 200 meters from Goza Shirahama in Shima City, Mie Prefecture. It offers a private space right by the sea, allowing for a comfortable glamping experience without the need to bring your own gear. Guests can enjoy a variety of marine activities, a tent sauna in the midst of nature, and a luxurious BBQ featuring the ocean''s bounty. There is also a fire pit for cozy campfires and complimentary desserts. This summer, consider visiting LUXUNA Ise-Shima for an unforgettable time. Day trip activities are also available! For more details, check out Kankomie.' where id = 'K7hTaDaaO4E_NcgCvoRh3';
update content_bodies set title = '男女一緒に楽しめるサウナラウンジ「いなべ阿下喜ベース」', description = '温泉・サウナ・宿泊・食事が楽しめる複合施設「いなべ阿下喜ベース」が2024年4月11日にオープンします。長年愛されている阿下喜温泉あじさいの里の温泉はそのまま残ります。サウナラウンジは、初心者から上級者まで楽しめるくつろぎの空間が魅力です。水着のレンタルもあり、手ぶらでの訪問も可能です。家族や恋人、友達と一緒にぜひ足を運んでみてください。詳細は観光三重のウェブサイトで紹介されています。' where id = 'XdOdiKMJfVc_XqGA9jbwV';
update content_bodies set title = 'A Sauna Lounge for Everyone: Inabe Ageki Base', description = 'The Inabe Ageki Base, a complex facility offering hot springs, saunas, accommodation, and dining, will open on April 11, 2024. The beloved Ageki Onsen Ajisai no Sato hot spring remains unchanged! The sauna lounge provides a relaxing atmosphere that appeals to both beginners and advanced sauna enthusiasts. Swimwear rental is available, making it convenient for visitors. Families, couples, and friends are encouraged to visit and enjoy the experience together. For more details, check out the Mie Tourism website.' where id = 'ENo4p43_-ipaoQSQrZQEN';
update content_bodies set title = '世界遺産登録20周年✨#熊野古道 伊勢路の魅力をご紹介🚶‍♂️', description = '熊野古道伊勢路は、世界遺産登録20周年を迎え、魅力的なスポットがたくさんあります。鬼ヶ城の迫力ある自然の造形や、馬越峠の美しい石畳、獅子岩の雄叫びが聞こえてきそうな景観を楽しめます。また、七里御浜では浜街道を歩きながら、ゴールデンウィークには鯉のぼりが泳ぐ光景も見られます。この素晴らしい巡礼路をぜひ訪れてみてください。詳細は特設サイトをご覧ください。' where id = '8NpnmFqpJ1Biayi4bGZyF';
update content_bodies set title = '20th Anniversary of World Heritage Registration: Discover the Charm of Kumano Kodo Ise Route', description = 'The Kumano Kodo Ise Route, celebrating its 20th anniversary as a World Heritage site, offers a variety of captivating spots. Experience the stunning natural formations at Onigajo, the beautiful stone pavement at Umakoshitoge, and the majestic Shishi Rock that seems to roar. Walk along the scenic Hamakaido at Shichiri Mihama, where colorful koi flags will be flying during Golden Week. Don''t miss the chance to explore this remarkable pilgrimage route. For more information, visit the special website.' where id = 'H1wwbbkqZ-X5XG0BSY1xU';
update content_bodies set title = '速報！かざはやの里の藤が見頃です！', description = '三重県津市に位置するかざはやの里は、三重県を代表する藤の名所の一つです。4月下旬から5月上旬にかけて、10種類の藤が1800本、10,000㎡の藤棚と58,000㎡の園内で開花します。早咲きの藤は一部落花が始まっており、これから開花する蕾も多く見られます。また、季節の花を使った花手水も写真映えすること間違いなしです！2024年4月13日から5月6日まで無休で営業し、営業時間は8:00から18:00です。ゴールデンウィーク期間中の土日には、近鉄「久居駅」からシャトルバスが運行されます。伊勢自動車道「久居IC」から車で5分の距離にあります。' where id = 't6F3olxh8u7Nay4Uy-MZA';
update content_bodies set title = 'Wisteria in Full Bloom at Kazahayano Sato!', description = 'Kazahayano Sato, located in Tsu City, Mie Prefecture, is one of the most famous wisteria spots in the region. From late April to early May, 1,800 wisteria plants of 10 varieties, including ''Shirokōhidan'', ''Murasakikōhidan'', ''Beni-fuji'', and ''Kuchibeni-fuji'', bloom across 10,000 square meters of wisteria trellises and 58,000 square meters of landscaped grounds. Some early-blooming varieties have already started to drop flowers, while many buds are yet to bloom. The seasonal flower water offerings, known as ''hanamizuhana'', are perfect for photos! The event runs from April 13 to May 6, 2024, with no days off, from 8:00 AM to 6:00 PM. Shuttle buses will operate from Kintetsu ''Hisai Station'' on weekends during the Golden Week. Kazahayano Sato is easily accessible by car from the Ise Expressway.' where id = 'M0ZlLQ-CnleldGeO-Os9m';
update content_bodies set title = '速報！津偕楽公園の紫ツツジ🌸', description = '津偕楽公園では、多くの木が満開を迎え、一部は花が落ち始めています。お花見はお早めに楽しんでください！桜の開花が遅れたため、春まつりと提灯のライトアップが4月14日まで延長されます。春まつり期間中は、茶店でグルメを楽しみながら、桜と紫ツツジの両方を堪能できます。5月にはヒラドツツジが咲き始めます。春まつりは2024年3月22日から4月14日まで開催され、ライトアップは18:00から22:00まで行われます。JR・近鉄津駅から徒歩3分、伊勢自動車道津インターから車で10分の場所にあります。桜の時期は混雑が予想されるため、公共交通機関の利用をお勧めします。駐車場は第1駐車場と第2駐車場合わせて約100台分あります。' where id = 'mDTzBNOs76xsdIqT9M_F5';
update content_bodies set title = 'Breaking News! Purple Azaleas at Tsukairaku Park 🌸', description = 'Many trees are in full bloom, while some have started to shed their flowers. Enjoy the cherry blossom viewing soon! Due to the delayed cherry blossom blooming, the spring festival and lantern light-up have been extended until April 14. During the festival, visitors can enjoy gourmet food at tea shops and appreciate both cherry blossoms and purple azaleas. In May, Hirado azaleas will begin to bloom. The Tsukairaku Park Spring Festival runs from March 22 to April 14, 2024, with light-up events from 6:00 PM to 10:00 PM. The park is a 3-minute walk from JR and Kintetsu Tsushima Station, and about a 10-minute drive from the Ise Expressway Tsushima Interchange. Please use public transportation during the cherry blossom season as it gets very crowded. Parking is available for about 100 cars.' where id = 'CNZ7pWWYTCMaz9YTl5R7r';
update content_bodies set title = 'なばなの里のダリアまつり', description = 'ダリアまつりが三重県桑名市長島町のなばなの里で開催中です。ここは三重屈指の観光スポットで、日本最大の花ひろばがあり、色とりどりのダリアの花々を楽しむことができます。このイベントは毎年11月下旬まで行われるため、限られた期間の美しい景色を体験するチャンスです。カメラを持って訪れることをお勧めします。' where id = 'RegL14iM-MYJBChCZjVVw';
update content_bodies set title = 'Dahlia Festival at Nabana no Sato', description = 'The Dahlia Festival is currently taking place at Nabana no Sato in Nagashima Town, Kuwana, one of Mie''s top tourist destinations. This event showcases Japan''s largest flower plaza, where visitors can enjoy the vibrant blooms of dahlias. The festival runs until the end of November each year, making it a limited-time opportunity to experience this beautiful display. Visitors are encouraged to bring their cameras to capture the stunning scenery.' where id = 'gihut81FPha_ldkreKFfX';
update content_bodies set title = 'アメリカ西海岸!?海辺の穴場カフェが三重県に⁉ #マリーナ河芸', description = '椰子の木に囲まれた港を眺めながら、海外旅行気分を味わえる穴場カフェ「マーメイド」が、伊勢湾最大級のマリーナ河芸にあります。人気のスイーツはレアチーズケーキで、さっぱりとしたクリーミーさと粗めのナッツが入ったザクザクの生地が楽しめます。詳しくはリンクをチェックしてください。カフェの所在地は三重県津市河芸町東千里854-3です。三重県の観光情報は、リンク先のアカウントで確認できます。' where id = 'Xsxhiocszujl4F4XEX0Jp';
update content_bodies set title = 'Hidden Seaside Cafe on the West Coast of America!? #MarinaKawage', description = 'Discover a hidden cafe that gives you a taste of the West Coast of America while enjoying views of a harbor surrounded by palm trees. Located at the largest marina in Ise Bay, Cafe Mermaid offers a popular dessert: rare cheesecake. This treat features a refreshing and creamy texture complemented by a crunchy crust made with coarse nuts. For more details, visit the provided link. The cafe is situated at 854-3 Higashisenri, Kawagei-cho, Tsu City, Mie Prefecture. Explore all the sightseeing options in Mie Prefecture through the linked account.' where id = 'Lwfpm0mwk_AE8pJdPEDGb';
update content_bodies set title = '「みえ食旅パスポート」で三重県を美味しく旅しよう！', description = 'みえ食旅パスポートについての紹介動画です。' where id = 'eEh9Pev46CeOYubD1Ui3T';
update content_bodies set title = 'Explore Mie Prefecture Deliciously with the Mie Food Travel Passport!', description = 'This is an introductory video about the Mie Food Travel Passport.' where id = 'ew3ikm2Z9y-d4k3AvBfy3';
update content_bodies set title = '何でも祈願できる？！　#彌都加伎神社', description = '1300年の歴史を持つ彌都加伎神社は、開運や金運、商売繁盛、良縁祈願など、さまざまなお願いができるパワースポットです。境内には22本の赤い鳥居が並ぶ彌都加伎稲荷神社や、夫婦円満祈願におすすめの夫婦岩など、見どころが豊富です。また、境内を彩るカラフルな和傘や、季節ごとに変わる花手水も人気を集めています。今、注目の神社です。' where id = 'BoUsz7vtjHUTUXFu6I9Td';
update content_bodies set title = 'A Shrine for All Wishes?! #Mizugaki Shrine', description = 'Mizugaki Shrine, with a history of 1300 years, is a power spot where you can pray for various wishes, including good luck, financial success, prosperous business, and good relationships. The shrine features a wide precinct with 22 red torii gates at the Yato Kaki Inari Shrine and the Meoto Rock, which is recommended for marital harmony. Visitors can also enjoy colorful Japanese umbrellas adorning the grounds and seasonal flower chozui, which are very popular. This shrine is currently attracting attention as a must-visit spot.' where id = 'sxBp4U4nzefr0sTNaGdtK';
update content_bodies set title = '女性人気のパワースポット！　#椿大神社', description = '椿大神社は、全国から参拝者が訪れる開運のパワースポットです。特に恋愛に関しては、別宮の椿岸神社に恋愛の神様が祀られており、夫婦円満や縁結びを願う女性たちに支持されています。また、椿岸神社の横に流れるかなえ滝は、待受画面にすると願い事が叶うと言われ、注目を集めています。詳細は公式ウェブサイトをご覧ください。' where id = '4mmBoVm7Fpcz9PRgE-Zz3';
update content_bodies set title = 'Popular Power Spot for Women! #Tsubaki Shrine', description = 'Tsubaki Shrine is a renowned power spot for good luck, attracting worshipers from across the country. It is particularly famous for its association with love, as the god of love is enshrined at the nearby Tsubakigishi Shrine. Women nationwide visit this shrine to pray for happy marriages and connections. Additionally, Kanae Falls, located next to Tsubakigishi Shrine, is gaining attention as a powerful spot where it is believed that wishes come true if the image is set as a standby screen. For more details, visit the official website.' where id = '3E2oeOWj_ux38Q_4-9p6v';
update content_bodies set title = '知らなきゃ損！　#なばなの里イルミネーション', description = '三重県のなばなの里では、お花の形をしたライトが輝き、幻想的な光の空間が広がります。今シーズン新登場の「光のドレープ」は藤棚を美しくライトアップし、まるで藤の花のように揺れる光のカーテンの中を進むことができます。100メートル続くトンネルでは、4色が鮮やかに移り変わり、その美しさに思わず見とれてしまいます。ロマンチックなひとときを過ごすのにぴったりの場所です。詳しくはリンクをチェックしてください。' where id = '8UIY4l7VIQX8ZyG2gAB9K';
update content_bodies set title = 'Don''t Miss Out! Nabana no Sato Illumination', description = 'Nabana no Sato offers a magical experience with flower-shaped lights creating a stunning illuminated space. This season features the new ''Drape of Light,'' which beautifully lights up the wisteria trellis, allowing visitors to walk through a curtain of light that sways like wisteria flowers. The 100-meter tunnel showcases a vibrant display of four changing colors, captivating visitors with its beauty. It''s the perfect setting for a romantic moment. For more details, visit the provided link.' where id = 'rZxENDHZeIUQoe0U-o-lz';
update content_bodies set title = '一度は食べたい！感動のクロワッサン　#Marbre Lapin', description = '鈴鹿市にある大人気のパン屋【Marbre Lapin】では、3日間かけて作られるこだわりのクロワッサンが楽しめます。外はパリッと、中はしっとりとした食感が特徴で、思わず食べたくなる美味しさです。また、オープンキッチンスタイルを採用しており、パン作りを間近で見ることができるのも魅力の一つです。人気のパンはすぐに売り切れてしまうため、午前中の訪問がオススメです。詳しくは公式サイトをご覧ください。' where id = 'M5WlvVjCGsXySutGtyL6i';
update content_bodies set title = 'A Must-Try! Incredibly Sold Out Croissants at Marbre Lapin', description = 'Marbre Lapin is a highly popular bakery in Suzuka City, known for its exquisite croissants that are made with great care over three days. The croissants feature a perfectly crispy exterior and a moist interior, creating an irresistible texture. The bakery also boasts a rare open kitchen style, allowing customers to enjoy watching the bread-making process up close. Due to the popularity of their baked goods, items often sell out quickly, so it''s recommended to visit in the morning for the best chance to try these delicious treats. For more details, visit their website.' where id = 'D8soPnU5V-ZToFXOoUp-l';
update content_bodies set title = '冬のイチオシ！老舗和菓子屋の絶品●●　#花乃舎', description = '創業150年以上の老舗和菓子屋「花乃舎」では、丹波大納言小豆を使用した甘さ控えめの絶品ぜんざいを楽しむことができます。寒い冬にぴったりのこのぜんざいは、併設の喫茶スペースで味わえる人気メニューです。冬以外にも、季節のお菓子と抹茶のセットや白玉が楽しめ、夏季にはかき氷や抹茶アイスクリームも提供されています。詳しくは公式サイトをご覧ください。' where id = 'pWrG2F5nr-7i_p-2c7xJl';
update content_bodies set title = 'Winter Recommendation! Exquisite Japanese Sweets from a Long-established Shop #Hananosha', description = 'Hananosha, a long-established Japanese confectionery shop with over 150 years of history, offers a delightful zenzai made with Tamba Dainagon red beans, perfect for warming up during the cold winter months. The attached café allows visitors to enjoy this popular winter menu item, which is highly sought after. In addition to zenzai, customers can also savor seasonal sweets paired with matcha, shiratama, and during the summer, shaved ice and matcha ice cream are available. For more details, visit their website.' where id = 'JoFarRq3IAToj9yv1NYF9';
update content_bodies set title = '日本でココだけのおもしろ動画施設！　#GINGAGA', description = 'ジャズドリーム長島にあるGINGAGAは、1月14日までスマホを使って楽しい動画を撮影できる施設です。宇宙から襲来した怪獣になりきった動画が撮れると人気で、お子様の成長記録や記念日を撮影するのに最適です。屋内にあるため、雨の日のお出かけにもおすすめです。詳しくは公式サイトをご覧ください。' where id = 'X0YxIoHmVBbZDjdCsmIoa';
update content_bodies set title = 'Unique Video Experience Facility in Japan! #GINGAGA', description = 'GINGAGA, located in Jazz Dream Nagashima, offers a unique opportunity to create fun videos using your smartphone until January 14th. Visitors can film themselves as if they are monsters invading from outer space, making it a popular spot for capturing memorable moments, such as children''s growth or special anniversaries. The facility is also ideal for rainy days, as it is situated indoors. For more details, visit their website.' where id = 'oBKm_1fPXWZNQEvDUTm5l';
update content_bodies set title = 'インスタ映え必至の花手水！ #金井神社 #花手水 #観光三重 #vlog #三重', description = '金井神社は800年以上の歴史を持つ神社で、色とりどりの花手水が話題です。境内は華やかに装飾され、季節ごとに花の種類や飾り付けが変わります。毎日手入れが行われており、訪れるたびに新しい発見があります。また、絵馬の代わりに願い事が書かれた風車が並ぶ様子も見どころです。心身ともに癒されるこの神社は、初詣にぜひ訪れてみてください。詳細は公式サイトをご覧ください。' where id = 'xPHkPsUNf_nDRHd1li-NL';
update content_bodies set title = 'Instagram-Worthy Flower Chozui! #KanaiShrine #FlowerChozui #TourismMie #Vlog #Mie', description = 'Kanai Shrine, a historic site over 800 years old, is renowned for its vibrant and photogenic flower chozui, which is beautifully decorated with seasonal flowers. The shrine''s precincts are maintained daily, ensuring that the types of flowers and decorations change gradually. Instead of traditional votive tablets, colorful windmills with written wishes add to the charm of the shrine. This serene location is perfect for soothing both body and soul, making it a recommended spot for New Year''s visits. For more details, visit their website.' where id = 'x8aGobhfeBqan0cSLfcob';
update content_bodies set title = '薪火で焼く！ホットドッグ！ #観光三重 #vlog #三重', description = '薪の香りが漂う中、噛んだ瞬間に肉汁があふれるホットドッグを楽しめます。ソーセージとパンは薪火で焼かれ、香ばしさが引き立ちます。「食肉加工屋FUCHITEI」は、いなべ市役所の隣にあるお店で、絶品のホットドッグを提供しています。自家製ソーセージから溢れ出る肉汁を、焼き目のついたパンが逃さず受け止めます。店主はフレンチシェフで、添加物を使わないことにこだわっています。ソーセージの他にも、パテやテリーヌも店内で手作りされています。詳しくは公式サイトをご覧ください。' where id = 'd51QiN8txy3ItmYJ-PH_i';
update content_bodies set title = 'Hot Dogs Roasted Over Firewood! #TourismMie #vlog #Mie', description = 'Experience the delightful aroma of firewood with hot dogs that burst with meat juices upon the first bite. Both the sausage and bread are roasted over a wood fire, enhancing their flavor. Located next to Inabe City Hall in Nigiwai no Mori, ''Meat Processing Shop FUCHITEI'' offers exquisite hot dogs. The homemade sausage releases juices that the perfectly baked bread captures without losing a drop. The owner, a French chef, is committed to avoiding additives. Besides sausages, the shop also produces pate and terrine in-house. For more details, visit their website.' where id = 'Wt6cucgD8WI-AJy77rbFZ';
update content_bodies set title = '感動の光のトンネル　なばなの里イルミネーション', description = '冬に特におすすめのなばなの里イルミネーションは、日本夜景遺産に選ばれた「光のトンネル」や、圧巻の水上イルミネーション「光の大河」を楽しむことができます。国内最大級のイルミネーションが夜空を照らし、広大な庭園は色とりどりの光に包まれ、幻想的な雰囲気を醸し出します。デートや家族での思い出作りに最適な場所です。点灯時間はリンクをチェックしてください。' where id = 'HOeDT__2feLa-KZYtvcev';
update content_bodies set title = 'Impressive Tunnel of Light at Nabana no Sato', description = 'The Nabana no Sato Illumination is especially recommended in winter. It features the ''Tunnel of Light,'' recognized as a Japan Night View Heritage Site and one of the world''s most spectacular views. The ''Taiga of Light'' showcases stunning water illuminations, making it Japan''s largest illumination event that lights up the night sky. The vast garden is enveloped in colorful lights, creating a magical atmosphere perfect for romantic dates or family memories. Visitors can check the lighting hours through the provided link.' where id = 'vvglFfsdBBpIwIQgETxiu';
update content_bodies set title = 'クマ型の最中がキュート！#東海道関宿 #gute #観光三重 #vlog #三重', description = '日本でここだけで味わえる「gute」は、亀山市関町の東海道関宿に位置するオシャレな和カフェです。古民家を改装したこの店は、可愛いクマ型のもなか専門店で、甘さ控えめの粒あんを炙りたてのサクサクの皮で包んだ一品が特徴です。食べ歩きやお土産にも最適で、関宿を観光する際にはぜひ立ち寄りたいお店です。' where id = '7p2zAYGHULxncPXObPIlX';
update content_bodies set title = 'Cute Bear-Shaped Monaka! #TokaidoSekijuku #gute #TourismMie #vlog #Mie', description = 'The only place in Japan where you can enjoy this! ''gute'' is located in Tokaido Sekijuku, Kameyama City, in a stylish Japanese cafe housed in a renovated old folk house. This shop specializes in adorable bear-shaped monaka, featuring lightly sweetened bean paste wrapped in freshly grilled, crispy skin. It''s perfect for eating on the go or as a souvenir. If you''re sightseeing in Sekijuku, this is a must-visit spot!' where id = 'hcm2_TjQW1Y4R52s_eOSV';
update content_bodies set title = '日本初の撮影エンターテインメント施設が上陸✨ #GINGAGA', description = '「GINGAGA -SPACE MOVIE STUDIO-」は、桑名市長島町のジャズドリーム長島に位置する、唯一無二の体験ができる施設です。友達やお子様との思い出作りに最適で、スマートフォンを使って誰でも簡単に映像クリエイターのように動画撮影が楽しめます。観光や旅行の思い出を最高の動画に残しませんか？この施設は2024年1月14日（日）までの期間限定でオープンしています。三重県の観光スポットがすべてここに集まっています！' where id = 'tBqvfZDMCl1kt7CgbgNy0';
update content_bodies set title = 'Japan''s First Filming Entertainment Facility Has Arrived✨ #GINGAGA', description = 'Experience something unique at ''GINGAGA -SPACE MOVIE STUDIO-'' located in Jazz Dream Nagashima, Kuwana Nagashima Town. This facility is perfect for creating memories with friends and children, allowing anyone to easily shoot videos like a professional using their smartphone. Capture the best moments of your sightseeing and travel adventures! The facility is open for a limited time until Sunday, January 14, 2024. Discover all the sightseeing opportunities in Mie Prefecture!' where id = 'ZzLhuaewnu9yKFgSTrkly';
update content_bodies set title = '伊賀忍者をイメージして作られた名物【本流 霧隠れうどん】#池澤湯', description = '忍者の里・伊賀を訪れるなら、ぜひ立ち寄りたいのが「うどん屋 池澤湯」です。三重県上野に位置するこの人気店は、メディアでもよく取り上げられています。名物の【本流 霧隠れうどん】は、伊賀忍者をイメージして作られたもので、真っ白なお出汁の中から真っ黒な太麺が現れます。伊賀牛コロッケをトッピングするのがオススメです。店内には多くの忍者グッズがあり、外国人観光客にも大人気です。家族旅行やカップル、友達同士でも楽しめる伊賀の必見スポットです。' where id = 'iIBs50HWfKDwq9fkuNC2W';
update content_bodies set title = 'Famous Dish Inspired by Iga Ninjas: Mainstream Kirigakure Udon at Ikezawayu', description = 'If you''re visiting Iga, the ninja village, make sure to stop by Ikezawayu, a popular udon restaurant in Ueno, Iga City, frequently featured in the media. Their specialty, Mainstream Kirigakure Udon, is inspired by Iga ninjas, featuring thick black noodles that emerge from a pure white soup stock. The restaurant recommends adding an Iga beef croquette as a topping. The interior is filled with ninja-themed merchandise, making it a hit among foreign tourists. This spot is perfect for families, couples, and friends exploring Iga.' where id = 'MHGRcevSfjUzGaEAXB8g6';
update content_bodies set title = '2023年最新の三重コスモス畑3選🌼✨', description = '三重県には、コスモスが一面に広がる花畑がたくさんあり、友達や家族、ペットと一緒に楽しめるフォトスポットも充実しています。秋のおでかけにぴったりなコスモス畑をぜひ訪れてみてください。おすすめのスポットは、なばなの里、志摩市観光農園、とことめの里一志の3か所です。過去の投稿では、さらに詳しい情報を紹介しているので、ぜひそちらもご覧ください。' where id = 'wfc8nOBQKWhyYSY4KxQQM';
update content_bodies set title = 'Top 3 Cosmos Fields in Mie Prefecture for 2023 🌼✨', description = 'Mie Prefecture is home to numerous flower fields where you can enjoy vast expanses of cosmos flowers. These locations are perfect for taking photos with friends, family, or pets. They are ideal spots for autumn outings, so be sure to visit a cosmos field! The top three recommended locations are: 1) Nabana no Sato, 2) Shima City Tourist Farm, and 3) Tokotome no Sato Ichishi. For more detailed information, check out our previous posts!' where id = 'EjUHN5vj14zXtN6spbIKE';
update content_bodies set title = '千鳥ヶ浜：三重県の美しい海水浴場', description = '千鳥ヶ浜海水浴場は、太平洋を望む全長500ｍの美しいビーチです。今年の5月に行われた三重県内の水浴場の水質調査で、最も水質の良いAAに認定されるほどの清潔さを誇ります。白砂のビーチと海の透明度は素晴らしく、鳥羽10景にも数えられる美しい景観を楽しむことができます。訪れる人々は、清潔で魅力的な環境での水泳やリラクゼーションを満喫できます。' where id = 'FJ49JhTgFF5t7IdY2IhDY';
update content_bodies set title = 'Chidorigahama Beach: A Stunning Seaside Spot in Mie Prefecture', description = 'Chidorigahama Beach in Toba City is a beautiful 500-meter long beach with a breathtaking view of the Pacific Ocean. This beach was recognized for its exceptional water quality, receiving an AA rating in a survey conducted in May this year. The pristine white sand and the remarkable transparency of the sea contribute to its reputation, making it one of the top ten scenic spots in Toba. Visitors can enjoy a clean and inviting environment, perfect for swimming and relaxation.' where id = 'AYkCrRsYOv4su-SYDCnbp';
update content_bodies set title = '【７月OPEN！】一流シェフの料理が作品の「食の美術館🍽」【三重県】', description = '三重県の人気複合施設「VISON」に、2023年7月24日（月）に新たに「AT CHEF MUSEUM」が開館しました。この美術館では、ミシュラン星付きシェフを含む18人のシェフによる和洋中の料理やスイーツ、ワインがリーズナブルに楽しめます。また、VISON内の「Gallery 泛白 uhaku」のソフトクリームや「肉屋台 baraque」のマンハッタン、「新兵衛屋」のパリパリえび天など、食べ歩きにぴったりの人気グルメも揃っています。詳細は公式サイトで確認できます。' where id = 'Ez-xxcwQcd-AC5dJfoLqr';
update content_bodies set title = 'Open in July! A Culinary Art Museum Featuring Dishes by Top Chefs 🍽【Mie Prefecture】', description = 'The highly popular complex facility ''VISON'' in Mie Prefecture has opened a new culinary art museum, ''AT CHEF MUSEUM,'' on July 24, 2023. This museum showcases dishes created by 18 chefs, including seven Michelin-starred chefs, offering a variety of Japanese, Western, and Chinese cuisines, as well as desserts and wines at reasonable prices. Visitors can also enjoy popular gourmet options like soft serve ice cream from ''Gallery 泛白 uhaku,'' Manhattan from ''肉屋台 baraque,'' and crispy shrimp tempura from ''新兵衛屋.'' For more details, check the official website.' where id = '5Jvhr1nCnDJ976pOhi6Q0';
update content_bodies set title = '話題沸騰！“モクモク”のクリームソーダ＠京口屋珈琲館☕', description = '“モクモク”のクリームソーダが話題沸騰中です！昔ながらのレトロ喫茶で、うっとりするほど美しいスイーツを提供しています。この“モクモク”の正体はドライアイスで、店主のご実家がドライアイスを販売する会社を営んでいるため、オープン以来このスタイルで提供されています。クリームソーダの他にも、コーヒーフロートもモクモク演出で楽しめます。スイーツやフードはすべて店主の手作りで、ランチメニューもコストパフォーマンスが非常に良いです。デザートは14：30から提供されるので注意が必要です。京口屋珈琲館は三重県津市にあり、営業時間は9：00～18：00で、水曜日が定休日です。駐車場は8台分あり、JR「高茶屋駅」から徒歩約10分の距離です。' where id = 'iRx-ZlT48r7dwmuc4m4tR';
update content_bodies set title = 'The Trending ''Mokumoku'' Cream Soda at Kyoguchi Coffee Shop ☕', description = 'The ''Mokumoku'' cream soda is currently trending! This retro-style café offers stunningly beautiful sweets. The secret behind the ''Mokumoku'' effect is dry ice, provided by the owner''s family business that sells dry ice. This unique presentation has been a staple since the café opened. In addition to cream soda, coffee floats are also served with the same ''Mokumoku'' effect. All sweets and food are handmade by the owner, and the lunch menu is very cost-effective. Note that desserts like pudding are available from 2:30 PM. Kyoguchi Coffee Shop is located in Tsu City, Mie Prefecture, and is open from 9 AM to 6 PM, closed on Wednesdays. Parking is available for 8 cars, and it is about a 10-minute walk from JR Takachaya Station.' where id = 'uyQGuqjVfdpQYC_yC3QkA';
update content_bodies set title = '光り輝くネオンサインがSNSで話題沸騰中!?「一乃湯」', description = '光り輝くネオンサインが話題の「一乃湯」は、創業70年以上の歴史を持つレトロな銭湯です。上野城下町に位置し、外観のネオン看板が目を引きます。館内は昭和の雰囲気が漂い、訪れる人々をタイムスリップさせるようなレトロ感が魅力です。今年7月には、銭湯を日本から消さないことをモットーとする「ゆとなみ社」が運営を引き継ぎました。時代に合わせて進化を続ける「一乃湯」に注目です。館内の撮影は特別な許可を得て行われています。詳細は「観光三重」で紹介されています。' where id = 'SRH5_Fxl5Mc9cALymXnkk';
update content_bodies set title = 'The Glowing Neon Sign of ''Ichinoyu'' is Making Waves on Social Media!?', description = 'The glowing neon sign of ''Ichinoyu'', a retro public bath with over 70 years of history, is currently trending on social media. Located in Ueno, the exterior of Ichinoyu stands out with its vibrant neon sign. Inside, visitors feel as if they''ve traveled back to the Showa era, surrounded by a nostalgic atmosphere. In July of this year, the management of Ichinoyu was taken over by ''Yutanami Co.'', a group dedicated to preserving public baths in Japan. They aim to continue evolving Ichinoyu to meet modern needs. Special permission was granted for photography inside the facility. For more details, visit ''Kankou Mie''.' where id = 'RwCG6B2I-S_c9ixERrWC9';
update content_bodies set title = '三重で遊ぼ！！', description = 'この動画では、三重県を構成する5つのエリアの中から人気の体験メニューを紹介します。非日常的な「アウトドア体験」や「動物とのふれあい」、さらには「手作り体験」や「グルメを堪能できる体験メニュー」など、五感を刺激する様々な体験を楽しむことができます。三重の魅力を感じることができる体験動画をぜひご覧ください！' where id = 'OAfzsy4H86xHw7c6ZJo3L';
update content_bodies set title = 'Let''s Play in Mie!! #MieExperiencePRVideo', description = 'This video introduces popular experience menus from the five areas that make up Mie Prefecture. Enjoy a variety of unique experiences that stimulate your senses, including outdoor adventures, interactions with animals, hands-on crafting, and gourmet food experiences. Discover the excitement of Mie through this engaging experience video!' where id = 'WqWt2uXohLxgPJXC9Xj23';
update content_bodies set title = 'Enjoy！ MIE National Park～', description = '三重県には、2つの国立公園と2つの国定公園があります。伊勢志摩国立公園は伊勢神宮とリアス海岸が特徴で、吉野熊野国立公園は奥深い自然と歴史が結びついています。鈴鹿国定公園は交通の便が良く、鈴鹿山脈と湯の山温泉が自慢です。室生赤目青山国定公園では、渓谷と連なる山々の雄大さを楽しむことができます。それぞれの公園には異なる魅力があり、三重の国立・国定公園でしか味わえない自然を楽しむことができます。' where id = 'P3js2XljUgvnVnpzc8VGl';
update content_bodies set title = 'Enjoy！ MIE National Park～', description = 'Mie Prefecture is home to two national parks and two quasi-national parks. The Ise-Shima National Park features the Ise Grand Shrine and a distinctive ria coastline. The Yoshino-Kumano National Park is known for its deep nature and historical connections. The Suzuka Quasi-National Park boasts excellent transportation access, with the Suzuka Mountains and Yunoyama Onsen as highlights. The Muro-Akame-Aoyama Quasi-National Park offers majestic mountains and valleys. Each park has its unique charm, inviting visitors to enjoy the exclusive nature found in Mie''s national and quasi-national parks.' where id = 'DKXOQXWcIJJh70IrO94pZ';
update content_bodies set title = 'なばなの里イルミネーション【ドローン撮影】(桑名市)｜観光三重｜三重県の観光・旅行情報', description = '三重県桑名市の観光スポット「なばなの里」のイルミネーションを、2020-2021年シーズンにドローンで撮影しました。このイルミネーションは国内最大級のスケールと最高峰のクオリティを誇り、毎年多くの観光客が訪れる人気のスポットです。撮影は特別な許可を得て行われており、通常営業時には撮影ができないことをご理解ください。' where id = 'VVhZLSYP25rpkIWU7HKdv';
update content_bodies set title = 'Nabana no Sato Illumination [Drone Footage] (Kuwana City) | Tourism Mie | Mie Prefecture Travel Information', description = 'The illumination at Nabana no Sato in Kuwana City, Mie Prefecture, was captured using drone footage for the 2020-2021 season. This illumination event is one of the largest and highest quality in Japan, attracting many tourists each year. Please note that the filming was done with special permission, and regular operations do not allow for such filming.' where id = 'eUXPEHUjxjpnbfU_LFknc';
update content_bodies set title = '「FEEL VIBRATIONS」～“みえ旅”で感動を！～　#三重の観光PR動画', description = '三重県が「Discover Japan」とタイアップし、まるで実際に旅しているかのような感覚を提供します。三重ならではの「VIBRATION」を感じてください！動画のコンセプト「FEEL VIBRATIONS」では、伊勢神宮や熊野古道の「神秘の波動」、高田本山や伊賀に根付く歴史の「息づかい」、英虞湾で感じる海の「鼓動」など、三重県のさまざまな「VIBRATION」を旅人の視点で紹介しています。' where id = 'UUCvFRzsLW1y9k3kmKEUH';
update content_bodies set title = 'FEEL VIBRATIONS - Experience the Emotions of Mie through ''Mie Travel''! - #Mie Tourism PR Video', description = 'Mie Prefecture collaborates with ''Discover Japan'' to create a sensation that feels like you are actually traveling. Experience the unique ''VIBRATION'' of Mie! The video concept ''FEEL VIBRATIONS'' introduces various ''VIBRATIONS'' from Mie, such as the ''mystical waves'' of Ise Jingu and Kumano Kodo, the ''breath'' of history rooted in Takada Hongan-ji and Iga, and the ''heartbeat'' of the sea felt in Ago Bay, all from the perspective of travelers experiencing them firsthand.' where id = 'gIxRBiQIHVgYpi2kZjWXj';
update content_bodies set title = '【三重弁】[自撮り] Moment Capturer  ~It''s gonna be your Stories~', description = '三重県はネイチャーアクティビティが豊富で、里山をのんびりサイクリングしたり、穏やかな海でシーカヤックを楽しんだり、青空の下でスカイダイビングをすることができます。楽しみ方は無限大で、ぜひ訪れてみてください！' where id = '8zFfwjLb1A-0dg5ajxwOu';
update content_bodies set title = 'Mie Dialect: Moment Capturer ~It''s gonna be your Stories~', description = 'Mie Prefecture offers a wealth of nature activities. You can enjoy leisurely cycling through the satoyama, relaxing sea kayaking on calm waters, and even skydiving under a clear blue sky. The possibilities for fun are endless. We invite you to visit!' where id = 'Q4D9Vw1CEis2_-DAhQrAz';
update content_bodies set title = '【三重弁】Moment Capturer  ~It''s gonna be your Stories~', description = '三重県はネイチャーアクティビティが豊富です。里山をのんびりサイクリングしたり、穏やかな海でシーカヤックを楽しんだり、青空の下でスカイダイビングを体験したりと、楽しみ方は無限大です。ぜひお越しください！' where id = 'bVcAS1dFm56IGSN9Yoeyp';
update content_bodies set title = 'Moment Capturer ~It''s gonna be your Stories~', description = 'Mie Prefecture offers a wealth of nature activities. You can enjoy leisurely cycling through the satoyama, relax with sea kayaking in calm waters, or experience the thrill of skydiving under a clear blue sky. The possibilities for enjoyment are endless. We invite you to visit!' where id = 'wUDRk_FKTwqBzNGON5RwI';
update content_bodies set title = '銚子川（ちょうしがわ：三重県紀北町）｜三重県大好き"兎の助"動画｜【公式】観光三重', description = '三重県の応援キャラクター「兎の助」が紹介する動画シリーズで、三重の観光スポットを紹介しています。特に、NHKスペシャル「見えないものが見える川～奇跡の清流 銚子川～」で取り上げられ、大きな反響を呼んだ銚子川が注目されています。' where id = 'G3loWhdTesDTeVIBc1UN8';
update content_bodies set title = 'Choshigawa (Choshigawa River: Kihoku Town, Mie Prefecture) | Mie Prefecture''s Favorite ''Usanosuke'' Video | Official Mie Tourism', description = 'This video series features ''Usanosuke'', the official mascot of Mie Prefecture, introducing various attractions in the region. One highlighted spot is the Choshigawa River, which gained significant attention through an NHK special titled ''The River Where Invisible Things Can Be Seen - The Miraculous Clear Stream of Choshigawa''.' where id = 'c0V2_fcQw8GdjOIk7dT-v';
update content_bodies set title = '国の名勝・天然記念物「鬼ヶ城」に行ってきました！(熊野市)', description = '熊野市の鬼ヶ城を訪れ、奥の木戸まで歩いてきました。鬼ヶ城は隆起、風化、波の浸食によって形成された自然の芸術で、熊野灘に面して1km続く国の名勝・天然記念物です。山頂には戦国時代の城跡があり、熊野古道・松本峠と連結するハイキングコースが整備されています。「鬼の見晴台」と呼ばれる展望台からは熊野灘を一望できます。山頂へ通じるハイキングコースは桜が植えられており、春には4種類の桜が次々と開花し、長期間観光客を楽しませます。' where id = 'LtwlmT7N1AC7zN5BcXhG9';
update content_bodies set title = 'Visit to the National Scenic Spot and Natural Monument ''Onigajo'' in Kumano City', description = 'I visited Onigajo in Kumano City, where I walked to the Oku no Kido area. This natural wonder, shaped by uplift, weathering, and wave erosion, stretches for 1 km along the Kumano Sea and is designated as a national scenic spot and natural monument. At the summit, there are ruins of a castle from the Sengoku period, and a hiking trail connects to the Kumano Kodo and Matsumoto Pass. From the observation deck known as ''Oni no Mihara'', visitors can enjoy a panoramic view of the Kumano Sea. The hiking trail leading to the summit is lined with cherry trees, and in spring, four varieties of cherry blossoms bloom successively, delighting tourists for an extended period.' where id = 'OwZ5vIf-bQsWt0Y5Uresx';
update content_bodies set title = '2019年3月16日OPEN！フォレストアドベンチャー湯の山(菰野町)｜観光三重｜三重県の観光・旅行情報', description = '三重県初のフォレストアドベンチャーが菰野町に2019年3月16日（土）にオープンしました。施設には、長さ100ｍを超える「ジップスライド」や、高さ約10mから飛び降りる「ターザンスイング」があり、最終コースでは「ダブルジップスライド」を通じて、家族や友達、カップルで爽快感や達成感を共有することができます。' where id = 'DeXUjS9tfltcHkq_N1b2T';
update content_bodies set title = 'Forest Adventure Yunoyama Opens on March 16, 2019! | Tourism Mie | Mie Prefecture Travel Information', description = 'The first Forest Adventure in Mie Prefecture opened in Komono Town on March 16, 2019. It features a zip slide over 100 meters long, a Tarzan swing that drops from about 10 meters high, and a double zip slide for sharing the thrill and sense of achievement with family, friends, or couples at the final course.' where id = 'vA2ms-cALzCbwrfCMbbrO';
update content_bodies set title = '観光三重2017　100号記念　11月のオススメ観光20セレクション', description = '秋の行楽シーズン真っ只中の11月に、三重県のおすすめ観光スポットを紹介します。' where id = 'M2Qiqu5uqheMR0Vg66o2-';
update content_bodies set title = 'Tourism Mie 2017: 100th Issue - Recommended 20 Tourist Spots for November', description = 'This article introduces recommended spots in Mie Prefecture for November, during the peak of the autumn sightseeing season.' where id = 'PUE0IzsHU9GOVj8_WR7-U';
update content_bodies set title = '氏郷まつり', description = '蒲生氏郷公を讃える盛大な祭りが三重県松阪市にて１１月３日に開催されます。祭りでは、冬姫や甲冑姿の武士、鉄砲隊など、総勢約200名の武者行列が町を練り歩きます。また、楽市楽座やステージイベントも行われ、訪れる人々に楽しんでもらえる内容となっています。' where id = 'NRgutQ_KWSVUTJX-WO480';
update content_bodies set title = 'Ushigo Festival', description = 'The Ushigo Festival, celebrating the legacy of Lord Ushi-go, will be held in Matsusaka City, Mie Prefecture, on November 3rd. The festival features a grand procession of approximately 200 participants, including armored warriors, gunmen, and the winter princess, parading through the town. Additionally, there will be a lively market and stage events for attendees to enjoy.' where id = 'fM-VWaBW83Fy1IEZ9Ur7g';
update content_bodies set title = '伊勢志摩エバーグレイズ', description = '伊勢志摩エバーグレイズは、快適性、くつろぎ、優雅さを融合させた上質なアウトドア空間を提供するグランピング施設です。プライベートカヌーで専用コースを楽しむことができ、夕食には本格的なアメリカンBBQを体験できます。詳細については、公式ウェブサイト「観光三重」をご覧ください。' where id = 'SpfX9kh_5BMu7P3YYewls';
update content_bodies set title = 'Ise-Shima Everglades', description = 'Ise-Shima Everglades offers a luxurious outdoor space that combines comfort, relaxation, and elegance through glamping. Guests can enjoy a private canoe experience on a dedicated course, followed by a genuine American BBQ dinner. For more details, please visit the official website ''Kanko Mie''.' where id = 'i8YkYQtDDu1Sbw74DwCtL';
update content_bodies set title = '「嵐」（ARASHI） 新ジェットコースターがナガシマスパーランドに登場！（三重県桑名市）', description = '4Dスピンコースター「嵐」（ARASHI）が2017年3月10日にナガシマスパーランドに登場しました。このジェットコースターは、予測不能な動きが特徴で、迫力満点の体験を提供します。詳細なレポートでは、「嵐」の大絶叫体験や、2016年度津クイーンの感想も紹介されています。また、ナガシマスパーランドの人気アトラクションや周辺の観光施設についても解説されています。三重県の観光情報やナガシマスパーランドの公式サイトもぜひご覧ください。' where id = '3kOpKYr74PXd_cBxX6SUS';
update content_bodies set title = 'New Roller Coaster ''ARASHI'' Debuts at Nagashima Spa Land (Kuwana City, Mie Prefecture)', description = 'The 4D spinning coaster ''ARASHI'' opened at Nagashima Spa Land on March 10, 2017. This thrilling roller coaster features unpredictable movements that provide an exhilarating experience. A detailed report is available, showcasing the excitement of ''ARASHI'' along with impressions from the 2016 Tsukui Queen. The report also covers popular attractions at Nagashima Spa Land and nearby facilities worth visiting. For more information, visit the official Nagashima Spa Land website and explore various tourist spots in Mie Prefecture.' where id = 'NBWDR0tbMwiyGFMuykiZN';
update content_bodies set title = '道の駅紀宝町ウミガメ公園', description = '道の駅紀宝町ウミガメ公園は、ウミガメの飼育と研究を行い、ウミガメ保護・啓発活動の拠点となっています。来園者はウミガメや紀宝町周辺に生息する生き物たちとのふれあいを楽しむことができ、特にウミガメへの餌やり体験が人気です。詳細については、観光三重のHPをご覧ください。' where id = 'LNOucKB3bhTNWbJFCL-5M';
update content_bodies set title = 'Michi-no-Eki Kihō Town Turtle Park', description = 'The Turtle Park serves as a base for the protection and awareness activities of sea turtles, focusing on their breeding and research. Visitors can enjoy interactions with sea turtles and other local wildlife in Kihō Town. A popular attraction is the feeding experience, where guests can feed the turtles.' where id = 'OmXzly43YICwn5QVgzyLF';
update content_bodies set title = 'かわいいイルカたちにも会える「鳥羽湾めぐりとイルカ島」　その１', description = '豪華な遊覧船で鳥羽湾を優雅に巡る「鳥羽湾めぐりとイルカ島」では、かわいいイルカたちに出会うことができます。この情報は観光三重のHPに掲載された取材レポートに基づいています。ぜひご覧ください。' where id = 'oDD_peFnd_oqaYux9jwnN';
update content_bodies set title = 'Meet Cute Dolphins on the ''Toba Bay Tour and Dolphin Island'' Part 1', description = 'Experience a luxurious cruise on Toba Bay! The ''Toba Bay Tour and Dolphin Island'' offers a chance to meet adorable dolphins. This article is featured in the Mie Tourism HP report. Be sure to check it out.' where id = 't8LMi4GAxMoG0sSfPoTCd';
update content_bodies set title = '御在所ロープウエイ', description = '御在所岳の山上からの夜景は感動的で、期間限定で御在所ロープウエイがナイター運転を行います。昼間とは異なる、ちょっぴりロマンティックな空中散歩を楽しむことができます。詳細については、観光三重のHPをご覧ください。' where id = 'LuCYjUpiKM0X12THuBF9r';
update content_bodies set title = 'Gozaisho Ropeway', description = 'The night view from the summit of Gozaisho Mountain is breathtaking. For a limited time, the Gozaisho Ropeway operates night rides. Enjoy a slightly romantic aerial stroll that differs from the daytime experience. For more details, please visit the Mie Tourism website.' where id = 'zFBhMKGTZgnL0VHQMoJHL';
update content_bodies set title = '里創人熊野倶楽部', description = '世界遺産の熊野古道を含む、熊野の大自然を体験できるリゾート施設です。詳細については、観光三重のHPをご覧ください。' where id = '_Jf4GIxQwUeAc3p4meNxt';
update content_bodies set title = 'Sato Soujin Kumano Club', description = 'A resort facility that allows visitors to experience the great nature of Kumano, including the World Heritage Kumano Kodo.' where id = '_Fl7BzIIzJt-O-RW5Xiyw';
update content_bodies set title = '鈴鹿の森庭園', description = 'カメラマンを魅了する梅の名所で、八重咲き品種の呉服枝垂を中心に、名人と呼ばれる職人が仕立てた200本ものしだれ梅の名木が揃っています。' where id = '84Nk5BdakkymVBCMUcMSv';
update content_bodies set title = 'Suzuka no Mori Garden', description = 'A renowned plum blossom spot that captivates photographers. The garden features 200 exquisite weeping plum trees, primarily showcasing the double-flowered variety known as ''Gofuku Shidare,'' crafted by master artisans.' where id = '-5kbPtPOJbB0mhVJp0NMz';
update content_bodies set title = '伊賀のかくれ宿　湯元赤目温泉隠れの湯　対泉閣', description = '赤目四十八滝まで歩いて5分の赤目渓谷の入り口に位置する旅館です。地下1000メートルから湧き出る日本療養温泉規定認定の良質なアルカリ性単純温泉を楽しむことができ、伊賀牛をはじめとした郷土料理も堪能できます。' where id = '_J9J_10s3klg60PZYZE8p';
update content_bodies set title = 'Iga''s Hidden Inn: Yumoto Akame Onsen Taisenkaku', description = 'Located at the entrance of Akame Valley, just a 5-minute walk from the Akame Forty-eight Waterfalls, this ryokan offers high-quality alkaline simple hot springs certified by Japanese therapeutic hot spring regulations, sourced from 1000 meters underground. Guests can also enjoy local cuisine, including Iga beef.' where id = 'Wqnq-JqT6meGTrgPSQRll';
update content_bodies set title = '御在所岳で初日の出', description = '2013年元旦に御在所ロープウェイを利用して、御在所岳の山上公園で初日の出を見た時の様子を収めた動画です。' where id = 'LGlglb9XDbgqT-QMNEHuI';
update content_bodies set title = 'First Sunrise at Mount Gozaisho', description = 'This video captures the experience of watching the first sunrise of 2013 from the summit park of Mount Gozaisho, accessed via the Gozaisho Ropeway.' where id = 'FN0TbCFRfOCdAqHdwN2rH';
update content_bodies set title = '御在所岳・スキーゲレンデ', description = '御在所岳・スキーゲレンデは、スキー愛好者に人気のあるスポットです。初心者から上級者まで楽しめる多様なコースがあり、スキーを楽しむには最適な場所です。このゲレンデは三重県に位置しており、美しい自然景観とアウトドアアクティビティで知られています。訪れる人々は、スキーだけでなく、周辺で他のウィンタースポーツやレジャー活動も楽しむことができます。' where id = 'HcS26fej3LqVOAyRmuZK1';
update content_bodies set title = 'Gozaisho Mountain Ski Resort', description = 'Gozaisho Mountain Ski Resort is a popular destination for skiing enthusiasts. It offers a variety of slopes suitable for different skill levels, making it an ideal location for both beginners and experienced skiers. The resort is located in Mie Prefecture, known for its beautiful natural scenery and outdoor activities. Visitors can enjoy not only skiing but also other winter sports and leisure activities in the area.' where id = 'rAkFNs7fJ9WlMx2ycxHKI';
update content_bodies set title = 'ぐるぐる鬼ヶ城', description = '天気が良かったので、七里御浜海岸をドライブし、鬼ヶ城をぐるっと回ってきました。大きな岩が迫力を持ち、熊野灘の景色も美しかったです。' where id = '26gNt66JGyikG344ptifF';
update content_bodies set title = 'Guruguru Onigajo', description = 'On a beautiful day, I drove along the Shichiri Mihama coast and took a tour around Onigajo. The large rocks were impressive, and the Kumano Sea was beautiful.' where id = '4AaM_O5vXFUFsxA-zgbt9';
update content_bodies set title = '大内山動物園とプライムリゾート賢島', description = '家族で大内山動物園に行きました。様々な種類の動物に餌をあげることができ、子供たちは大喜びでした。ホテルでは素晴らしい料理を楽しみ、リゾート気分を味わいました。' where id = '2PQfEeRrsX8Z6AvbU44pY';
update content_bodies set title = 'Ouchiyama Zoo and Prime Resort Kashikojima', description = 'I visited Ouchiyama Zoo with my family. The children were thrilled to feed various types of animals. At the hotel, we enjoyed wonderful cuisine and experienced a resort atmosphere.' where id = 'tBlrHPCc37UdQzlJPJ4tz';
update content_bodies set title = '2012年ローズフェア開催中！', description = 'イングリッシュガーデンのローズガーデンでは、107品種1600株のばらが咲き誇っています。ばらの甘い香りが漂うこのガーデンで、優雅なひとときをお過ごしください。見頃は5月末頃が予想されています。' where id = 'WFvsjx2ggP8IBEpZD5WRQ';
update content_bodies set title = '2012 Rose Fair in Progress!', description = 'The English Garden''s Rose Garden is in full bloom with 1,600 roses of 107 varieties. Enjoy an elegant moment in the garden filled with the sweet fragrance of roses. The best viewing period is expected around the end of May.' where id = 'ASzQ4LSAHLIj8RfLk0fvo';
update content_bodies set title = '四日市萬古まつり', description = '四日市市陶栄町の萬古神社周辺で萬古まつりが開催されました。' where id = 'QL6VUTnk2f0kiitZ6yMIc';
update content_bodies set title = 'Yokkaichi Banko Festival', description = 'The Banko Festival was held around Banko Shrine in Yokkaichi City, Tōei Town.' where id = 'Q2hEshVCb624E-NFnVPdv';
update content_bodies set title = 'ナガシマスパーランドの全景！', description = 'ナガシマスパーランドの全景を紹介します。スケールアップしたキッズタウンを含むこのテーマパークは、家族連れにとって楽しめるスポットです。さまざまなアトラクションや施設が整備されており、訪れる人々に多彩な体験を提供しています。' where id = 'KgvQPx2yJEUP0hiDmWZ1i';
update content_bodies set title = 'Overview of Nagashima Spa Land!', description = 'This is an overview of Nagashima Spa Land, including the expanded Kids Town!' where id = 'BztNd-daKVyePcqnIWXnZ';
update content_bodies set title = '大内山動物園でほのぼの癒されました', description = '初めて訪れた大内山動物園では、フレンドリーなヤギやポニー、やんちゃなおサルと触れ合い、意外にもネコっぽいトラに出会いました。楽しい一日があっという間に過ぎ、素晴らしい思い出ができました。' where id = 'BQC3IGxEudJn9Pq0NH5FN';
update content_bodies set title = 'A Relaxing Day at Ouchiyama Zoo', description = 'I visited Ouchiyama Zoo for the first time. I enjoyed interacting with friendly goats and ponies, as well as playful monkeys. I was surprised to see a tiger that resembled a cat. The day passed quickly, filled with fun memories.' where id = '4QXTmb93SgdjbabHYDV_S';
update content_bodies set title = '鈴鹿サーキット', description = '春休みに開場50周年を迎えた鈴鹿サーキットを訪れました。2歳児でも楽しめるアトラクションが豊富で、閉園までたっぷり遊ぶことができました。特に、ぶんぶんのパンケーキやさんは子供たちのお気に入りでした。' where id = 'mZHWPDcNQCvtLNlBEExAP';
update content_bodies set title = 'Suzuka Circuit', description = 'During spring break, I visited the Suzuka Circuit, which celebrated its 50th anniversary. There are many attractions suitable for toddlers, and we enjoyed playing until closing time. The ''Bunbun Pancake Shop'' is a favorite among the children.' where id = '9SRlyg8CYU_GHxKEMGbTv';
update content_bodies set title = '子どもがおおはしゃぎ！大内山動物園に行ってきました', description = '大内山動物園に行ってきました。リニューアルされていて、とてもきれいでした。たくさんの動物がいて、小さな子どもたちが大はしゃぎしていました！特に驚いたのは、トラが肉だけでなく草も食べるということでした。' where id = 'JlM3GNoJjan5erLPjpN1l';
update content_bodies set title = 'Children Having a Blast! We Visited Ouchiyama Zoo', description = 'We visited Ouchiyama Zoo, which has been beautifully renovated. There were many animals, and small children were having a great time! It was surprising to learn that tigers eat both meat and grass.' where id = 'YZWFf_2hLlE_eZgYx2jIa';
update content_bodies set title = '自分みがきスポット三重 -南伊勢版-', description = '南伊勢町の豊かな自然の中でスローライフを体験できます。絶景スポットであるハートの入江は、カップルや恋愛成就を願う女性たちに特に人気があります。また、南伊勢きらりふれあいの会の浅井さん家では、地元の鯛を使った鯛の塩釜焼き体験が楽しめるため、地域の特産を味わいながら、思い出に残る体験ができます。' where id = 'uv7LgsZfiDxCF8ddNjQWD';
update content_bodies set title = 'Self-Enhancement Spots in Mie - Minami-Ise Edition -', description = 'Experience a slow life in the rich nature of Minami-Ise Town! The breathtaking spot, Heart Bay, is popular among couples and women wishing for love to blossom. At the Asai family of the Minami-Ise Kirari Interaction Association, you can enjoy a salt-baked sea bream experience using local fish.' where id = 'Pi4KH3EQUjhMMq_HGjFrq';
update content_bodies set title = '自分みがきスポット三重 -伊賀版-', description = '伊賀焼のショップで、見る、味わう、作陶する体験ができます。江戸時代から使われてきた登り窯や、歴史的な建物、調度品が揃うレトロな大正館など、貴重な登録有形文化財を堪能できます。日常を忘れ、ロハスな時間を楽しむことができます。' where id = 'UDqbGITuW1WZkxS53CWu0';
update content_bodies set title = 'Self-Enhancement Spot in Mie - Iga Edition -', description = 'Experience the charm of Iga pottery at a shop where you can see, taste, and even create your own ceramics! Enjoy the retro atmosphere of the Taisho-kan, which features valuable registered tangible cultural properties, including a climbing kiln used since the Edo period, historical buildings, and furnishings. Indulge in a lohas time that allows you to forget your daily routine!' where id = 'qVgWR8BD4JpBr9JdFjiTI';
update content_bodies set title = '自分みがきスポット三重-ダイジェスト版-', description = '三重のガイドツアーの魅力を紹介します。三重には、地元を愛し、その魅力を楽しく伝えてくれる多くのガイドがいます。彼らと共に、自分を見つめ直し、新しい自分を発見する旅に出かけましょう。' where id = 'tb-uad-fHMXsm6Mv5m5jN';
update content_bodies set title = 'Self-Improvement Spots in Mie - Digest Version', description = 'Discover the charm of guided tours in Mie! The region is home to many passionate guides who love and know the area well, sharing its attractions in an enjoyable way. Join these guides on a journey of self-discovery to find a new version of yourself!' where id = 'LdiCmP6vwrHVnMATjVx-f';
update content_bodies set title = '近鉄レールパス アニメーション', description = '三重県の紹介です。' where id = 'nV-atfWsV2_bLxIA9tsxr';
update content_bodies set title = 'KINTETSU RAIL PASS Animation', description = 'Introduction to Mie Prefecture' where id = '49LjStOHocdZlKqUQro4i';
update content_bodies set title = '３６０度の光のトンネル！', description = 'なばなの里に行ってきましたが、当日は雨で少し落ち込んでいました。しかし、暖かい光のアーチが続くイルミネーションが地面に反射し、まるで３６０度の光のトンネルのようでした。とても美しかったです。' where id = 'AYRhj3VFokcXQ8IzyM1E4';
update content_bodies set title = '360-Degree Light Tunnel!', description = 'I visited Nabana no Sato, but it was raining on that day, which made me feel a bit down. However, the warm light arches of the illumination reflected on the ground, creating a stunning 360-degree light tunnel! It was very beautiful.' where id = 'fDzMeYnIwMFLQlP_Y-TFi';
update content_bodies set title = '◆もくもく収穫祭◆', description = 'もくもく手作りファームを訪れた際に撮影した写真です。ちょうど収穫祭のイベントが開催されており、その中でも特に「家畜追いダービー」が非常に面白かったです！参加者たちも大いに盛り上がっていました。' where id = 'b7EEDsxc811Dwx5DlzKcA';
update content_bodies set title = 'Mokumoku Harvest Festival', description = 'I took photos during my visit to Mokumoku Handmade Farm, where a harvest festival was taking place. The highlight of the event was the ''Livestock Chase Derby,'' which was incredibly entertaining! Everyone was having a great time!' where id = 'FTP0IjN9x-NREF8QWwEii';
update content_bodies set title = 'みえのみどころええとこ・鳥羽市相差の海女小屋体験', description = 'この記事では、鳥羽市相差の海女小屋体験について紹介しています。海女さんのお話しがとても楽しく、このふれあいが体験をより豊かにしました。この交流によって、海の幸がさらに美味しく感じられました。' where id = 'Fb2kG1bxA9Gpsj-XAknhC';
update content_bodies set title = 'Experience the Ama Hut in Toba City, Mie', description = 'This article highlights the experience of visiting an ama hut in Toba City, Mie. The stories shared by the ama divers were very enjoyable, enhancing the overall experience. This interaction made the seafood even more delicious.' where id = 'ySAlZmMaats2723pdhNXn';
update content_bodies set title = '元気いっぱいの安濃津よさこい', description = '元気いっぱいの安濃津よさこいを見てきました。息の揃った演舞に感動し、思わず涙が出るほどでした。小さな娘もおしりをフリフリしながら楽しそうに踊っていました。' where id = 'wNFuZ580QiG3SmDLSYgiH';
update content_bodies set title = 'Energetic Anotsu Yosakoi at Tsu Festival', description = 'I attended the lively Anotsu Yosakoi performance and was deeply moved by the synchronized dances, even to the point of tears. My little daughter was also dancing happily, shaking her hips!' where id = 'Yvdf2eUeWdaFgRNcg6ifK';
update content_bodies set title = '近っ！ナガスパのスチールドラゴン', description = 'ジャズドリーム長島が大きくなったので、訪れてみました。とても満足しました！ナガスパのスチールドラゴンがすぐ近くを通り、迫力満点の体験ができました。' where id = '5H9ITBpepSBhPxI1QlSBF';
update content_bodies set title = 'Close Encounter with the Steel Dragon at Nagashima Spa Land', description = 'I visited the expanded Jazz Dream Nagashima and was thoroughly satisfied! The Steel Dragon at Nagashima Spa Land passed right by me, providing an impressive experience.' where id = 'VV6XeFVCy9m5v7bLTekqe';
update content_bodies set title = '福王神社に参拝しました！', description = '福王神社に参拝しました。お昼には菰野富士に行き、昼食を取りました。展望が良く、景色は最高でした。' where id = 'ekBeObIOwiIGifTOGRZC4';
update content_bodies set title = 'Visited Fukuou Shrine!', description = 'I visited Fukuou Shrine. For lunch, I went to Komono Fuji, where the view was excellent and the scenery was amazing.' where id = 'XP4zADJjRK7Bd3Ck-m8Lr';
update content_bodies set title = 'パルケエスパーニャのナイトパレード', description = 'ナイトパレードは美しく、楽しいイベントです。フィナーレでは迫力満点の花火が間近で見ることができ、観客を魅了します。' where id = 'YAFAe2gjGQIo-rKH-95Ss';
update content_bodies set title = 'Night Parade at Parque España', description = 'The Night Parade is beautiful and enjoyable. The finale features fireworks that can be seen up close, providing an impressive experience.' where id = '6c-KAvSBJP-xbr-qB5YHE';
update content_bodies set title = 'ミキモト真珠島の海女さんのショー', description = 'ミキモト真珠島で海女さんのショーを観覧しました。美しい真珠の工芸品は本当に素晴らしく、感動しました。また、海女さんのショーも非常に興味深く、楽しむことができました。' where id = 'nObO9TVBNeGOd5mevIWkJ';
update content_bodies set title = 'Ama Show at Mikimoto Pearl Island', description = 'I watched the ama show at Mikimoto Pearl Island. The gorgeous pearl crafts are simply amazing. Additionally, the ama show was very interesting.' where id = 'PHdaCDtiCQxv57STDY1Nw';
update content_bodies set title = 'ナガシマスパーランド花火', description = 'ナガシマスパーランドの花火を見てきました。迫力満点で、来年もぜひ見に行きたいと思います。' where id = 'KaTV9GhydUsNR_NzdU7ua';
update content_bodies set title = 'Nagashima Spa Land Fireworks', description = 'I went to see the fireworks at Nagashima Spa Land. They were spectacular, and I definitely want to go again next year!' where id = '13xt_4fJyiKqTnpgbXD0q';
update content_bodies set title = '青山高原の風車群と雄大な眺め', description = '青山高原の風車を子供と見に行きました。穏やかな風だったので、リラックスした時間を過ごしました。少し曇っていましたが、海から山々にかけての景色は雄大でした。' where id = 'xP_ASgyZgtx7IDM-GUiFR';
update content_bodies set title = 'Wind Turbines and Majestic Views at Aoyama Plateau', description = 'I visited the wind turbines at Aoyama Plateau with my child. The gentle breeze made it a relaxing experience. Although it was a bit cloudy, the view from the sea to the mountains was magnificent.' where id = 'cPZcpt4qcq1n2yueuaNry';
update content_bodies set title = 'メナード青山リゾートでゆったりのんびり', description = '家族でメナード青山リゾートに行きました。涼しい高原でゆったりのんびり過ごし、かわいいウッドクラフトを楽しみました。また行きたいと思います。' where id = 'hYmJ2Uzm54nvb52qzRYjI';
update content_bodies set title = 'Relaxing at Menard Aoyama Resort', description = 'I visited Menard Aoyama Resort with my family. We spent a relaxing time in the cool highlands. The wooden crafts were adorable. I would love to go again.' where id = '1sd0LmE59VHuNvT29-uv8';
update content_bodies set title = 'カメだよー！', description = '先日、友人の子供たちと一緒に二見シーパラダイスに出かけました。そこで初めて見る大きなカメに、子供たちは大喜びでした。彼らの楽しそうな様子が印象的でした。' where id = 'cWVguK6mrlGFnd8n3KkCg';
update content_bodies set title = 'It''s a Turtle!', description = 'Recently, I went to the Futami Sea Paradise with my friend''s children. The kids were thrilled to see a large turtle for the first time!' where id = 'XJMu4kmhfWJ-vkL3shuBA';
update content_bodies set title = 'ナローゲージのキュートな電車', description = '帰省中に北勢線に乗りました。高校時代に毎日利用していた電車です。ナローゲージは非常に珍しく、貴重な存在だと感じました。小さくて、ガタゴトと進む可愛らしい電車でした。' where id = '3zyRznSR9QQSTaeXV03DW';
update content_bodies set title = 'Cute Narrow Gauge Train', description = 'During my visit home, I took a ride on the Kitase Line, a train I used to take every day in high school. Narrow gauge trains are quite rare and valuable. It was a charming little train that moved along with a delightful clattering sound.' where id = 'O4UGPba9JHK6dYEhxha-j';
update content_bodies set title = '鈴鹿サーキットの花火大会', description = '今年も鈴鹿サーキットの花火大会に行ってきました。間近で見ることができ、迫力満点でした。花火はとても美しかったです☆.。.:*・゜' where id = 'PTbcg3tFrJUwYAJPSPLYJ';
update content_bodies set title = 'Fireworks Festival at Suzuka Circuit', description = 'I attended the fireworks festival at Suzuka Circuit this year. The experience was thrilling as I could see the fireworks up close. They were beautiful!' where id = 'KG8nYWrZ8BhfzUQUS2JDX';
update content_bodies set title = '四日市港ポートビル＠四日市コンビナート夜景クルーズ', description = '先日、みえのみどころを取材するために四日市コンビナート夜景クルーズに参加しました。クルーズでは様々な観光名所を巡り、工場の夜景を楽しんだ後、高さ100メートルの四日市港ポートビルからの夜景を堪能しました。その光景は非常に幻想的で素晴らしいものでした。' where id = 'M1wBV1jeFocs5YqghMhMp';
update content_bodies set title = 'Yokkaichi Port Building @ Yokkaichi Industrial Complex Night View Cruise', description = 'Recently, I went on the Yokkaichi Industrial Complex Night View Cruise to cover the attractions of Mie. During the cruise, I enjoyed various sightseeing spots and the factory night views, culminating in a breathtaking view from the 100-meter-high Yokkaichi Port Building. The scenery was incredibly magical and stunning!' where id = '2-k-FOWVRHtpUu2FMYco9';
update content_bodies set title = '伊勢・安土桃山文化村の安土城からの眺め', description = '先日、みえのみどころええとこの取材のために伊勢・安土桃山文化村を訪れました。時代考証に基づいて造られた安土城からの眺めは、最高に気持ちよく、素晴らしい体験でした。' where id = 'PVZCi4H_T-ke0H_jGFvEk';
update content_bodies set title = 'View from Azuchi Castle in Ise and Azuchi-Momoyama Cultural Village', description = 'Recently, I visited the Ise and Azuchi-Momoyama Cultural Village to cover the attractions of Mie. The view from Azuchi Castle, which is said to be constructed based on historical research, was incredibly pleasant.' where id = 'sJBrs6xN5i9jaX5L5QmsE';
update content_bodies set title = 'よさこいソーランフェスティバルin朝熊', description = '伊勢志摩スカイラインの山頂で開催された「よさこいソーランフェスティバル」では、13チーム、総勢280名の踊子たちが秋の朝熊山頂で華麗な舞を披露しました。参加者たちは、地域の伝統を生かした踊りを通じて、観客に感動を与えました。' where id = 'Z2tRg7qWGYIswTGW5-pD7';
update content_bodies set title = 'Yosakoi Soran Festival in Asakuma', description = 'The ''Yosakoi Soran Festival'' was held at the summit of Ise-Shima Skyline, featuring 13 teams with a total of 280 dancers. They showcased their splendid performances against the backdrop of the autumn scenery at the top of Asakuma Mountain.' where id = 'KxDg8g1xukBATtUzYyQf-';
update content_bodies set title = 'サンタのコチラファミリー☆', description = '鈴鹿サーキットに行ってきました。コチラファミリーはサンタバージョンで、気分は「メリークリスマス」。とても楽しい時間を過ごしました。コチラちゃんと写真を撮り、握手もしましたが、彼女の手はとてもふわふわでした。' where id = 'D2UmXq2sdyK6a43t6JeEu';
update content_bodies set title = 'Santa''s Kochira Family☆', description = 'We visited Suzuka Circuit, where the Kochira family was in a Santa version! The atmosphere was filled with ''Merry Christmas'' and we had a lot of fun. We took pictures with Kochira-chan and shook hands! Her hands were very fluffy.' where id = 'cyT9WF3ZTsMNqqZ8Uoiem';
update content_bodies set title = '安乗ふぐ〜シーズン到来〜', description = '志摩市渡鹿野島の福寿荘で安乗ふぐをいただきました。これは天然のとらふぐで、最高の味わいです。' where id = 'hd2dcvEqZIm2qbk9C87fV';
update content_bodies set title = 'Anori Fugu - Season Arrival', description = 'I enjoyed Anori fugu at Fukujuso on Watarukano Island in Shima City. It is natural tiger pufferfish and is the best.' where id = '99GJdryX7XfiPuMdZwl7i';
update content_bodies set title = '鈴鹿がイチバン', description = 'F1日本グランプリに行ってきました。決勝は天気にも恵まれ、素晴らしいレースが展開されました。鈴鹿は本当に最高の場所です！小林可夢偉選手も素晴らしいパフォーマンスを見せてくれました。これからの展開が楽しみです。' where id = 'mv0XU0Vh36TugboUr7kn1';
update content_bodies set title = 'Suzuka is the Best', description = 'I attended the F1 Japanese Grand Prix. The weather was perfect for the race, and Suzuka is amazing! Kamui Kobayashi was impressive. I''m looking forward to what comes next.' where id = 'q6nUzIrltZKJI9ef35JK-';
update content_bodies set title = 'ジャンボ', description = '暑い日には、海のようなプールが最高です。' where id = 'vmRVwq6weHn0AUXVQTwra';
update content_bodies set title = 'Jumbo', description = 'On hot days, a pool that resembles the sea is the best.' where id = 'YUHxO7QlYwZA0bYvgcSNo';
update content_bodies set title = '石取祭', description = '石取祭は「日本一やかましい祭り」として知られ、2日間にわたって賑やかな雰囲気が続きます。この短い動画では1台の祭車の賑わいを捉えていますが、約40台の祭車が一斉に鳴らしたらどれほどの騒音になるでしょうか。祭りは翌朝の午前4時頃まで続きます。' where id = 'MLnjB-P6__LqH0wkZFFj3';
update content_bodies set title = 'Ishitore Festival', description = 'The Ishitore Festival is known as the ''loudest festival in Japan,'' with a lively atmosphere that lasts for two days. The short video captures the excitement of just one festival float, but imagine the noise when around 40 floats sound off simultaneously! The festivities continue until around 4 AM the next morning.' where id = '1I7MUffybCm73B-Av9cTy';
update content_bodies set title = '七夕', description = '伊勢神宮を参拝した後、おかげ横丁に行きました。七夕の日に、短冊に願い事を書いて笹にかけてきました。良いことがありますように。' where id = 'asB5YLCnkX9iLdtKctuuM';
update content_bodies set title = 'Tanabata', description = 'After visiting Ise Jingu, I went to Okage Yokocho. It was Tanabata, and I wrote my wishes on small strips of paper and hung them on a bamboo tree. I hope good things will come.' where id = 'hXr8fCSl8HQlkPbm3uI61';
update content_bodies set title = '2010ハーレーダビッドソンＢＢＱパーティー', description = '2010年4月11日（日）、約200台のハーレーが伊勢志摩スカイラインに集まりました。参加者たちは、桜が満開の中を気持ちよく走り抜け、楽しいひとときを過ごしました。' where id = 'AVjGGTrwoSluG2-Z3yRj-';
update content_bodies set title = '2010 Harley-Davidson BBQ Party', description = 'On April 11th, approximately 200 Harley motorcycles gathered at the Ise-Shima Skyline. Participants enjoyed a pleasant ride under the full bloom of cherry blossoms.' where id = '1JVEb4cC-LUBl2fL8treZ';
update content_bodies set title = '三重県観光プロモーション｜観光三重', description = '三重県の観光用プロモーション映像です。公式サイト「観光三重」では、観光、旅行、イベント、宿泊予約に関する情報が提供されています。伊勢神宮や鳥羽水族館、地元のグルメなど、訪れるべきスポットが紹介されています。また、公式SNSを通じて最新情報やコンテンツが発信されています。特定の観光地に関心がある方には、人気の観光地や文化体験、ユニークなアクティビティに関する詳細なレポートも用意されています。' where id = 'ROB0-h3Vp1CDabnV6mQDS';
update content_bodies set title = 'Mie Prefecture Tourism Promotion | Kankomie', description = 'This is a promotional video for tourism in Mie Prefecture. The official site ''Kankomie'' provides comprehensive information on sightseeing, travel, events, and accommodation bookings in Mie. Visitors can explore recommended spots, including Ise Jingu Shrine, Toba Aquarium, and various local delicacies. The site also features links to social media platforms for updates and additional content. For those interested in specific attractions, there are detailed reports on popular destinations, cultural experiences, and unique activities available in the region.' where id = 'rc1uW7Qj8sgMXMjkqTS4q';
update content_bodies set title = '東京のすぐ北にある埼玉のライブ配信', description = 'この動画は東京のすぐ北に位置する埼玉について紹介しています。埼玉は日本の重要な都市の一つであり、東京に近いことから多くの人々に利用されています。埼玉の魅力や特徴を知ることができる内容となっています。' where id = 'G20ahPv8Ru4aimPTsYrhL';
update content_bodies set title = 'Live Stream of Saitama Japan Just North of Tokyo', description = 'This video introduces Saitama, Japan, located just north of Tokyo.' where id = 'VrruhLgERJRfFMT7YUeDB';
update content_bodies set title = '埼京線ツアー', description = '埼京線ツアーは、日本の埼玉県にあるさまざまな観光名所を探索するユニークな体験を提供します。主な見どころには、さまざまな芸術的パフォーマンスやイベントを展示する「埼玉県立芸術劇場」が含まれています。また、リラックスやアウトドア活動に最適な静かな場所である「別所沼公園」の自然の美しさも楽しめます。さらに、盆栽の栽培技術を鑑賞できる「盆栽村」も訪れる価値があります。最後に、「西湖ドーマン緑地公園」は、レクリエーションやレジャーのための広々としたエリアを提供し、家族や自然愛好者にとって完璧な目的地となっています。' where id = '8HHIj0nmzdEm8uOYDCSVs';
update content_bodies set title = 'Saikyo Line Tour', description = 'The Saikyo Line Tour offers a unique exploration of various attractions in Saitama, Japan. Key highlights include the Sainokuni Saitama Arts Theater, which showcases a variety of artistic performances and events. Visitors can also enjoy the natural beauty of Besshonuma Park, a serene location ideal for relaxation and outdoor activities. The Bonsai Village is another notable stop, where guests can appreciate the art of bonsai cultivation. Lastly, Saiko Doman Green Park provides a spacious area for recreation and leisure, making it a perfect destination for families and nature lovers.' where id = 'QaH0UGyYS_lkSHC1a_LI6';
update content_bodies set title = 'IN TOYAMA short ver.', description = 'この映像作品は、外国人観光客に向けて「富山」の魅力を伝えることを目的としています。春夏秋冬の美しさをじっくりと楽しむことができる内容となっており、詳細な観光情報も提供されています。富山の四季を感じたい方は、リンクから映像を視聴することができます。また、富山観光ナビのウェブサイトを通じて、より詳しい観光情報を得ることができます。' where id = 'Jzq2R_1ubyBTt4ungLHiH';
update content_bodies set title = 'IN TOYAMA short ver.', description = 'This video showcases the attractions of Toyama, aimed at foreign tourists with various interests. It highlights the beauty of the region throughout the four seasons. For those interested in a more in-depth view of Toyama''s seasonal scenery, a link to a detailed video is provided. Additionally, more comprehensive tourist information can be accessed through the Toyama Tourism Navigation website.' where id = 'bJR32GfVK_Uy_rPiwKZur';
update content_bodies set title = '（Full ver.）Magical Journey Fukushima 01  - A New Leaf, A New Day -', description = '「水」をテーマに、源流から海へとたどる旅を通じて、福島の名産である美味しい日本酒や農産物、温泉の魅力を紹介します。また、現地の方々のこれまでの取り組みや思い、検査の状況などを通じて、安全性についても伝えます。' where id = '7HUopg5yw-GfLJE4ldTBX';
update content_bodies set title = 'Magical Journey Fukushima 01 - A New Leaf, A New Day', description = 'This project explores the theme of ''water,'' tracing its journey from the source to the sea. It highlights the appeal of Fukushima''s local specialties, including delicious sake, agricultural products, and hot springs, all derived from high-quality water. The initiative also shares the efforts and sentiments of local residents, as well as information regarding safety measures and testing protocols.' where id = '9WVlAG-Bi_eUzY_r1Ns5_';
update content_bodies set title = '（5min ver.）Magical Journey  Fukushima 01  - A New Leaf, A New Day -', description = 'このプレゼンテーションでは「水」をテーマに、源流から海へとその旅をたどります。美味しい水から作られる福島の名産品、例えば日本酒や農産物、温泉などの魅力を紹介します。また、地元の方々の取り組みや思い、検査の状況を通じて、安全性についても伝えます。' where id = 'wvbF-Y0--J0mILI2Jhvs_';
update content_bodies set title = 'Magical Journey Fukushima 01 - A New Leaf, A New Day (5min ver.)', description = 'This presentation explores the theme of ''water,'' tracing its journey from the source to the sea. It highlights the appeal of Fukushima''s local specialties, including delicious sake, agricultural products, and hot springs, all made from high-quality water. Additionally, it conveys the safety measures and efforts of local residents, sharing their experiences and the current status of inspections.' where id = 'vvedDXALNHZgWaX28K6I6';
update content_bodies set title = '（5min ver.）Magical Journey  Fukushima 02  - 新たな一歩、新たな日 -', description = 'このプレゼンテーションでは「水」をテーマに、源流から海へとたどる旅を紹介します。美味しい水から作られる福島の名産品である日本酒や農産物、温泉の魅力を伝えます。また、現地の方々の取り組みや思い、検査状況を通じて、安全性についてもお伝えします。' where id = '_60ltSn1UK4wftD4nBPzB';
update content_bodies set title = 'Magical Journey Fukushima 02 - A New Leaf, A New Day (5min ver.)', description = 'This presentation explores the theme of ''water,'' tracing its journey from the source to the sea. It highlights the appeal of Fukushima''s local specialties, including sake made from delicious water, agricultural products, and hot springs. Additionally, it conveys the safety measures and efforts of local residents, as well as the current status of inspections.' where id = 'mUNCIBKi2XoKhozc6l-2O';
update content_bodies set title = '（5min ver.）Magical Journey Tohoku - 新しい葉、新しい日 -', description = '全長1,000キロの「みちのく潮風トレイル」を巡り、景勝地や日本有数のカキ産地など、外国人観光客から注目を集める人気スポットを紹介します。現地の魅力や人々の取り組み、思いを伝えることを目的としています。' where id = 'dLoU1cYDHuQygqmnqa5zc';
update content_bodies set title = 'Magical Journey Tohoku - A New Leaf, A New Day - A 5-Minute Version', description = 'This journey explores the Michinoku Coastal Trail, spanning 1,000 kilometers, highlighting scenic spots and renowned oyster production areas that attract foreign tourists. The program aims to convey the local charm, the efforts of the people, and their heartfelt stories.' where id = 'M6G0eFQpHSNkS-Y8C3RiH';
update content_bodies set title = '（1min ver.）Magical Journey  Fukushima 01  -A New Leaf, A New Day-', description = '「水」をテーマに、源流から海へと流れる様子を追いながら、美味しい水から作られる福島の名産である日本酒や農産物、温泉などの魅力を紹介します。また、現地の方々のこれまでの取り組みや思い、検査の状況を通じて、これらの製品の安全性についても伝えます。' where id = 'HuHzr4f6Xtsh3E8JsBnNQ';
update content_bodies set title = '(1min ver.) Magical Journey Fukushima 01 -A New Leaf, A New Day-', description = 'This presentation explores the theme of ''water'' as it flows from the source to the sea, highlighting the appeal of Fukushima''s local specialties such as sake, agricultural products, and hot springs, all made from delicious water. It also conveys the safety of these products through the efforts and thoughts of local residents, as well as the current status of inspections.' where id = 'hLEiEC4aqS1dKhnK4FfKf';
update content_bodies set title = '（1min ver.）Magical Journey  Fukushima 02  - A New Leaf, A New Day -', description = 'この動画では「水」をテーマに、源流から海へとたどる旅を紹介します。美味しい水から作られる福島の名産品である日本酒や農産物、温泉の魅力を伝えます。また、現地の方々の取り組みや思い、検査状況を通じて、これらの製品の安全性についても触れています。' where id = 'Oq7otsZ-haHCKp7E03fwl';
update content_bodies set title = '(1min ver.) Magical Journey Fukushima 02 - A New Leaf, A New Day -', description = 'This video explores the theme of ''water,'' tracing its journey from the source to the sea. It highlights the appeal of Fukushima''s local specialties, including sake made from delicious water, agricultural products, and hot springs. The video also conveys the safety of these products through the efforts and thoughts of local residents, as well as the current status of inspections.' where id = 'VZbkQCtOVXil6ell2_DDO';
update content_bodies set title = '（1min ver.）Magical Journey Tohoku - A New Leaf, A New Day -【ゆりやんレトリィバァさんと行く東北旅】', description = '全長1,000キロの「みちのく潮風トレイル」を巡り、景勝地や日本でも有数のカキ産地など、外国人観光客からも注目を集める人気のスポットを通して、現地の魅力や人々の取り組み、思いを伝えます。' where id = '8_dNprQ3rrjfQSy_oSOuc';
update content_bodies set title = 'Magical Journey Tohoku - A New Leaf, A New Day - A Trip to Tohoku with Yuriyan Retriever', description = 'This journey covers the Michinoku Coastal Trail, spanning 1,000 kilometers, showcasing scenic spots and renowned oyster production areas that attract foreign tourists. The program aims to convey the local charm, the efforts of the people, and their heartfelt stories.' where id = 'vry75X2ZilwEZ2JpFeTuW';
update content_bodies set title = '神秘的な東北・旅', description = '神秘的な東北は、日本の東北地方の深い文化を体験できる新しい旅行プランを提供しています。東北は「みちのく」と呼ばれ、東京から本州の先端まで広がる日本の北部に位置し、手つかずの自然が豊かです。この地域は、土着信仰や神道の影響を受けた独自の文化を形成してきました。祭りや神事は、豊穣や家内安全、自然への畏敬の念を表現し、東北の精神を体現しています。神秘的な東北のプログラムは、東北の心に触れるユニークな体験を提供し、日本の隠れた喜びや不思議を明らかにします。' where id = '5j_IdoGBf6lLn5-DKNlLd';
update content_bodies set title = 'Mystical TOHOKU・Journey', description = 'Mystical TOHOKU offers new travel plans that allow you to experience the deep culture of the Tohoku region in Japan. Tohoku, known as ''Michinoku'' meaning ''the depth of the road'', is located in the northern part of Japan, stretching from Tokyo to the tip of Honshu island. This region is rich in unspoiled nature and has developed a unique culture influenced by indigenous beliefs and Shintoism. Festivals and rituals in Tohoku embody the region''s spirit, focusing on themes such as fertility, family safety, and reverence for nature. The Mystical TOHOKU programs provide unique experiences that connect you with the soul of Tohoku, revealing hidden delights and mysteries of Japan.' where id = 'ShpoXQcm4o3c8Kf4uIcCi';
update content_bodies set title = '東北の夏祭り', description = '東北地方の6つの県で行われる夏祭りを、今までにない大胆な視点で表現したノンバーバルの動画です。青森ねぶた祭り、盛岡さんさ踊り、仙台七夕祭り、秋田竿燈祭り、山形花笠祭り、相馬野馬追いが取り上げられています。東北は青森、岩手、宮城、秋田、山形、福島の各県で構成されています。この動画は、WOW inc.による映像とMitsu the Beatsの音楽を使用し、再構築機構によって制作されました。' where id = 'bN_6mDqFnfzexidf5eaVt';
update content_bodies set title = 'Summer Festivals in TOHOKU JAPAN', description = 'The summer festivals in the six prefectures of the Tohoku region are showcased in a dynamic and unique way that offers perspectives and staging not typically seen. The festivals highlighted include the Aomori Nebuta Festival, Morioka Sansa Odori Festival, Sendai Tanabata Festival, Akita Kanto Festival, Yamagata Hanagasa Festival, and Soma Nomaoi. The Tohoku region comprises Aomori, Iwate, Miyagi, Akita, Yamagata, and Fukushima prefectures. This non-verbal video, produced by Reconstruction Agency, features visuals by WOW inc. and music by Mitsu the Beats.' where id = 'zFVdeKH8w91mZbkgdR9H3';
update content_bodies set title = '福島海岸物語 - この愛によって動かされて', description = 'Futaba Town Story Tourのコンセプト動画で、原子力災害によって止まってしまった町が地域愛によって再び動き出す様子を表現しています。この地域が再生に向かって歩む姿を紹介しています。' where id = 'UplRhgni9lWbx68_IU-Po';
update content_bodies set title = 'Fukushima Seaside Story - fueled by this love', description = 'This concept video for the Futaba Town Story Tour illustrates how the town, which was halted by a nuclear disaster, begins to move forward again through community love. It showcases the region''s journey towards regeneration.' where id = 'FK1bMbxnz27r54S1dMoiv';
update content_bodies set title = '福島海岸物語 - 私たちの愛する故郷 -', description = '福島Seasideのコンセプト動画で、地域の人々が愛する風景や自然、文化を多くのカットで表現しています。福島沿岸地域の魅力を視覚的に伝えることを目的としています。' where id = '8eR8m5Y65x5w42VuF7YJC';
update content_bodies set title = 'Fukushima Seaside Story - hometown we love –', description = 'This concept video for Fukushima Seaside showcases the beloved landscapes, nature, and culture of the local community. It visually conveys the charm of the Fukushima coastal region through a variety of expressive cuts.' where id = 'AqIg14MPblY21ohOC3YFr';
update content_bodies set title = '宇和島', description = 'この動画は宇和島について紹介しています。' where id = 'QbbGjGTdpGOzEeRrIPS7h';
update content_bodies set title = 'Uwajima', description = 'This video introduces Uwajima.' where id = 'G-VByrsnzfUo_8q87upYL';
update content_bodies set title = '日本、長野の冬 - 祭り、日本食、スキー', description = '長野の冬は本当に魔法のようで、旅行者にとって最高の冬のアクティビティを紹介します。私たちは、かまくらで美味しい鍋を楽しみ、飯山の戸狩温泉スキーリゾートでスキーやスノーボードをしました。この地域は美しい冬の風景と活気ある祭りで知られており、冬の旅行者にとって理想的な目的地です。' where id = 'Sn815Aa2YzNOVjrIQNco9';
update content_bodies set title = 'Winter in Nagano, Japan - Festivals, Japanese Food and Skiing', description = 'Winter in Nagano, Japan offers a magical experience filled with various activities. Visitors can enjoy delicious hot pot meals served in igloos, known as Kamakura, and partake in skiing and snowboarding at Togari Ski Resort in Iiyama. The region is known for its beautiful winter landscapes and vibrant festivals, making it an ideal destination for winter travelers.' where id = '2AHQqMMtzWemDS1tkB6Xz';
update content_bodies set title = '日本の農泊！ - 秋田での伝統的な日本旅行体験', description = '地元の農家の家に招かれ、秋田県大館市での農泊を通じて日本文化を体験しました。山内さんとその妻と共に、切りたんぽという伝統料理を作りました。切りたんぽは、串に刺したマッシュライスを炭火で焼き、味噌のグレーズをかけて食べる料理です。温泉を訪れた後、夜遅くまで飲みながら楽しい時間を過ごしました。翌日、山内さんが町を案内してくれ、観光客では知り得ない情報を教えてくれました。秋田犬にも触れることができ、限られた日本語でも山内さん夫妻はとても親切で、素晴らしい体験をさせていただきました。' where id = '7aGwVje2e_dB2jqOTIBMH';
update content_bodies set title = 'FARM STAY in JAPAN! - Traditional Japanese travel experience in Akita', description = 'Experience Japanese culture by staying with a local farmer in Odate, Akita. During the stay with Yamauchi-san and his wife, we cooked Kiritanpo, a traditional dish made of mashed rice cooked on a stick over an open fire, served with miso glaze or in hotpot. We enjoyed a visit to an onsen and spent the evening sharing drinks and laughter. The next day, Yamauchi gave us a personal tour of the town, sharing insights that typical tourists might miss. We also had the chance to see and pet the famous Akita Inu dogs. Despite our limited Japanese, Yamauchi-san and his wife were very accommodating, making our experience memorable.' where id = '63lvDbc4rwCmto-VAJv7k';
update content_bodies set title = '日本の冬の温泉 - 温泉旅館での宿泊', description = '私たちは、雪に囲まれた冬の時期に、伝統的な日本の旅館に宿泊し、露天風呂を楽しむ素晴らしい機会を得ました。冬に日本を訪れる際には、この体験を強くお勧めします。私たちが宿泊したのは秋田のガニバ温泉で、滞在中には伝統的な多コースの日本料理の夕食と朝食も堪能しました。' where id = 'Bp9lt6x9qIrbgu7anEQCH';
update content_bodies set title = 'WINTER ONSEN IN JAPAN - Staying in a Japanese inn with hot springs', description = 'We had the wonderful experience of staying at a traditional Japanese inn, known as a ryokan, during winter. Surrounded by snow, we enjoyed an outdoor onsen, which was a truly magical experience. If you plan to visit Japan in winter, we highly recommend this unique opportunity. Our stay was at Ganiba Onsen in Akita, where we also indulged in a traditional multi-course Japanese dinner and breakfast, showcasing the rich culinary culture of Japan.' where id = 'GzMzACdFbBj4BbjesM5y7';
update content_bodies set title = '日本のロードトリップ | 祖谷渓の探検', description = '祖谷渓は、私たちの日本を巡る3週間のキャンピングカー旅行の重要な目的地でした。四国という日本の小さな島に位置するこの山岳地域は、美しい渓谷やかわいらしい村、息をのむような景色で知られています。私たちは、見つけた小さな食堂で地元の料理を味わい、危険な一方通行の道路を走り、1800メートルの高さを誇る三嶺の頂上に登りました。' where id = 'ETf-NgzU8aOb-pN6Dijxq';
update content_bodies set title = 'JAPAN ROAD TRIP | Exploring Iya Valley', description = 'Iya Valley was a key stop on our three-week campervanning journey through Japan. Located on Shikoku, one of Japan''s smaller islands, this mountainous area is known for its stunning gorges, charming villages, and breathtaking vistas. During our adventure, we sampled local cuisine from various small eateries, navigated potentially hazardous one-way roads, and ascended Mt. Miune, which stands at 1,800 meters tall.' where id = '_QkuxfaCIvtCiLSlXl8QR';
update content_bodies set title = '馬籠宿を歩く', description = '馬籠宿は中仙道の43番目の宿場で、江戸（東京）と京都を結ぶ古い黄金のルートとして知られています。美しい景色が広がるこの場所では、伝統的なスタイルの家々が中仙道に沿って立ち並んでおり、宿場の底から頂上までの道を歩く様子が描かれています。' where id = '8GcdfjuWdOFXhIwH8P684';
update content_bodies set title = 'Walking around Magome-juku, the 43th station of the Nakasendo', description = 'Magome-juku, the 43rd station of the Nakasendo, is renowned for its stunning scenery along the historic route connecting Edo (Tokyo) and Kyoto. The video captures a walk through this picturesque area, showcasing traditional houses that line the sloping road from the base of the station to its summit.' where id = 'yIFsHG7msNvlggl41gDbD';
update content_bodies set title = '由岐ふれあいホール ぽっぽマリンコース（美波町）【「道の駅日和佐サテライトステーション」推進協議会】', description = '由岐ふれあいホール ぽっぽマリンは、道の駅日和佐サテライトステーションに指定されており、美波町由岐周辺の魅力的なエリアを紹介する中心的なスポットです。このコースでは、阿波沖海戦小公園やミニ四国八十八ヶ所、田井ノ浜海水浴場などの注目スポットが含まれています。' where id = '4me18Hd4fhjkU3UxXHoZn';
update content_bodies set title = 'Yuki Fureai Hall Poppo Marine Course (Minami Town) - Promoted by the Road Station Hiyorasa Satellite Station Council', description = 'The Yuki Fureai Hall Poppo Marine, designated as a Road Station Hiyorasa Satellite Station, serves as a central point to introduce the attractive areas around Yuki in Minami Town. The course includes notable spots such as the Awa-Oki Naval Battle Memorial Park, the Mini Shikoku 88 Temples, and the Tai no Hama Beach.' where id = 'SPpto_gTmLRy6KOJ_HYyc';
update content_bodies set title = 'アウトドアスポーツの楽園 | 徳島県南部', description = '徳島県南部は、SUP（スタンドアップパドルボード）、トレイルランニング、カヤック、サイクリング、サーフィンなど、さまざまなアウトドアスポーツが楽しめる場所です。海と山に囲まれた大自然の中で、アクティブな冒険や探検をするには最適な環境が整っています。' where id = 'PcXkK9BhNk6cnUE4B2lyT';
update content_bodies set title = 'An Outdoor Sports Paradise - アウトドアスポーツの楽園 | South Tokushima', description = 'South Tokushima is a haven for outdoor sports enthusiasts, offering a variety of activities such as stand-up paddleboarding, trail running, kayaking, cycling, and surfing. Surrounded by stunning natural landscapes, including mountains and the sea, this region provides the perfect backdrop for adventure and exploration.' where id = 'Mt_7DlOnPXRSpVt7Vs0D8';
update content_bodies set title = '伝統を受け継ぐ　地域の祭り', description = '徳島県南部には、地域の魅力が溢れる多彩な祭りがあり、世代を超えて伝統を受け継ぐ人々がいます。これらの祭りは単なるイベントではなく、地域社会によって大切に守られ、祝われる豊かな文化遺産を象徴しています。' where id = 'rN41KtswNOgSLYIi8j1mQ';
update content_bodies set title = 'Inheriting Tradition, Local Festivals', description = 'In South Tokushima, you can experience a variety of vibrant festivals that showcase local culture. These festivals are not just events; they represent a rich heritage that is passed down through generations, ensuring that traditions are preserved and celebrated by the community.' where id = 'yAtGf3Hx3G6mQfRw9EH3U';
update content_bodies set title = '豊かな自然と歴史を訪ねて | 徳島県南部', description = '徳島県南部には、手つかずの美しい自然が広がっています。懐かしさを感じる原風景や情緒あふれる町並みがあり、訪れる人々に温かい雰囲気を提供しています。ぜひ、徳島県南部の豊かな自然と歴史を体感してください。' where id = '-nvWvr-pi9oXDevW85Xtd';
update content_bodies set title = 'Explore Rich Nature and History - South Tokushima', description = 'South Tokushima is characterized by its untouched and expansive natural landscapes. The region features nostalgic scenery and charming townscapes that evoke a sense of warmth and history. Visitors are encouraged to experience the rich nature and historical essence of South Tokushima.' where id = 'q0vvQOd-MEWsZFYcC7UI6';
update content_bodies set title = '[360°VR] アウトドアスポーツの楽園 - 徳島県南部', description = '[360°VR] 徳島県南部は、SUP（スタンドアップパドルボード）、トレイルランニング、カヤック、サイクリング、サーフィンなどのアウトドアスポーツが楽しめる楽園です。海と山に囲まれたこの地域は、豊かな自然に恵まれており、アウトドア愛好者にとって理想的な目的地となっています。' where id = 'RKqysdjXQE9FBGChaK5FC';
update content_bodies set title = '[360°VR] An Outdoor Sports Paradise - South Tokushima', description = '[360°VR] South Tokushima is an outdoor sports paradise, offering activities such as stand-up paddleboarding, trail running, kayaking, cycling, and surfing. Surrounded by the sea and mountains, this region is blessed with abundant nature, making it an ideal destination for outdoor enthusiasts.' where id = '_qwI41_XB9QN9smv_qJgO';
update content_bodies set title = 'サーフィン【海陽町】', description = '「四国の右下」ファンが連携して体験型観光VRコンテンツを制作しました。徳島県南部の5市町と南部総合県民局は「四国の右下」若者創生協議会を組織し、サテライトオフィス（SO）誘致などを推進しています。このたび、県南に集積するSO企業や「四国の右下ファン」（㈱あわえ、㈱イーツリーズ・ジャパン、㈱ぴやまる、阿南工業高等専門学校）が協力して、体験型観光VRコンテンツを完成させました。多くの方々に県南の魅力を楽しんでいただきたいと思います。' where id = 'YTk-Hcz72MSPYOzJjwLcx';
update content_bodies set title = 'Surfing in Kaiyo Town', description = 'A collaborative effort by fans of ''Shikoku''s Lower Right'' has led to the creation of an experiential tourism VR content. The five cities and towns in the southern part of Tokushima Prefecture, along with the Southern Comprehensive Prefectural Bureau, have organized the ''Shikoku''s Lower Right Youth Creation Council'' to promote initiatives such as attracting satellite offices (SO). Recently, companies based in the southern region, along with ''Shikoku''s Lower Right fans'' (including Awae Co., Eatsリーズ・ジャパン, Piyamaru Co., and Anan National College of Technology), have come together to complete this experiential tourism VR content. We hope many people will enjoy the attractions of the southern region.' where id = 'IQIqxAYcwgnnsZEMEWlWv';
update content_bodies set title = '[360°VR] サーフィン【海陽町】', description = '「四国の右下」ファンが協力して体験型観光VRコンテンツを制作しました。徳島県南部の5市町と南部総合県民局は「四国の右下」若者創生協議会を組織し、サテライトオフィス（SO）誘致などの推進に取り組んでいます。このたび、県南に集まるSO企業や「四国の右下ファン」（㈱あわえ、㈱イーツリーズ・ジャパン、㈱ぴやまる、阿南工業高等専門学校）が力を合わせて、体験型観光VRコンテンツを完成させました。多くの方々に県南の魅力を楽しんでいただけることを願っています。' where id = 'QYohMUMyEWUnyln4m2hg9';
update content_bodies set title = '[360° VR] Surfing in Kaiyo Town', description = 'A collaborative effort by fans of ''Shikoku''s Lower Right'' has led to the creation of an experiential tourism VR content. The five cities and towns in the southern part of Tokushima Prefecture, along with the Southern Comprehensive Prefectural Bureau, have organized the ''Shikoku''s Lower Right Youth Creation Council'' to promote initiatives such as attracting satellite offices (SO). Recently, companies based in the southern region, along with ''Shikoku''s Lower Right Fans'' (including Awae Co., Eatsリーズ・ジャパン, Piyamaru Co., and Anan National College of Technology), have come together to produce this immersive VR content. We hope many people will enjoy the attractions of the southern region.' where id = 'fSfwjWAznvx19Ag66HZJv';
update content_bodies set title = '日和佐八幡神社秋季例大祭【美波町】', description = '「四国の右下」ファンが連携して体験型観光VRコンテンツを制作しました。徳島県南部の5市町と南部総合県民局は「四国の右下」若者創生協議会を組織し、サテライトオフィス（SO）誘致などを推進しています。このたび、県南に集積するSO企業や「四国の右下ファン」（㈱あわえ、㈱イーツリーズ・ジャパン、㈱ぴやまる、阿南工業高等専門学校）が協力して、体験型観光VRコンテンツを完成させました。多くの方々に県南の魅力を楽しんでいただきたいと思います。' where id = 'IAGjrC4Frza2bwpC0TO8j';
update content_bodies set title = 'Hiyowasa Hachiman Shrine Autumn Festival【Minami Town】', description = 'A collaborative effort by fans of ''Shikoku''s Lower Right'' has resulted in the creation of an experiential tourism VR content. The five cities and towns in the southern part of Tokushima Prefecture, along with the Southern Comprehensive Prefectural Bureau, have organized the ''Shikoku''s Lower Right Youth Revitalization Council'' to promote initiatives such as attracting satellite offices (SO). Recently, companies based in the southern region, along with ''Shikoku''s Lower Right fans'' (including Awae Co., Eatsリーズ・ジャパン, Piyamaru Co., and Anan National College of Technology), have come together to complete this experiential tourism VR content. We hope many people will enjoy the attractions of the southern region.' where id = 'qf3AUogSxEqLfwANQjQwe';
update content_bodies set title = 'ＤＭＶ【海陽町】', description = '「四国の右下」ファンが連携して体験型観光ＶＲコンテンツを制作しました。徳島県南部の5市町と南部総合県民局は「四国の右下」若者創生協議会を組織し、サテライトオフィス（SO）誘致などを推進しています。このたび、県南に集積するSO企業や「四国の右下ファン」（㈱あわえ、㈱イーツリーズ・ジャパン、㈱ぴやまる、阿南工業高等専門学校）が協力し、体験型観光ＶＲコンテンツが完成しました。多くの方々に県南の魅力を楽しんでいただきたいと思います。' where id = 'CTrPn3giLQ5_cAUTQcLN0';
update content_bodies set title = 'DMV [Kaihyo Town]', description = 'Fans of ''Shikoku''s Lower Right'' have collaborated to create an experiential tourism VR content! The five cities and towns in the southern part of Tokushima Prefecture, along with the Southern Comprehensive Prefectural Bureau, have organized the ''Shikoku''s Lower Right Youth Creation Council'' to promote initiatives such as attracting satellite offices (SO). Recently, companies gathered in the southern region, along with ''Shikoku''s Lower Right fans'' (Awae Co., Eatsリーズ・ジャパン Co., Piyamaru Co., and Anan National College of Technology), have joined forces to complete the experiential tourism VR content. We hope many people will enjoy the charm of the southern region.' where id = 'B5qADeiolbSaBfGUhGlII';
update content_bodies set title = '[360°VR] 日和佐八幡神社秋季例大祭【美波町】', description = '「四国の右下」ファンが協力して体験型観光VRコンテンツを制作しました。徳島県南部の5市町と南部総合県民局は「四国の右下」若者創生協議会を組織し、サテライトオフィス（SO）誘致などの推進に取り組んでいます。このたび、県南に集まるSO企業や「四国の右下ファン」（㈱あわえ、㈱イーツリーズ・ジャパン、㈱ぴやまる、阿南工業高等専門学校）が力を合わせて、体験型観光VRコンテンツを完成させました。多くの方々に県南の魅力を楽しんでいただけることを願っています。' where id = 'VuvBOLeWRV80jx3q_D7MR';
update content_bodies set title = '[360° VR] Hiyowasa Hachiman Shrine Autumn Festival [Minami Town]', description = 'A collaborative effort by fans of ''Shikoku''s Lower Right'' has resulted in the creation of an experiential tourism VR content. The five cities and towns in the southern part of Tokushima Prefecture, along with the Southern Comprehensive Prefectural Bureau, have organized the ''Shikoku''s Lower Right Youth Creation Council'' to promote initiatives such as attracting satellite offices (SO). Recently, companies based in the southern region, along with ''Shikoku''s Lower Right fans'' (including Awae Co., Eatsリーズ・ジャパン, Piyamaru Co., and Anan National College of Technology), have come together to produce this experiential tourism VR content. We hope many people will enjoy the attractions of the southern region.' where id = 'FEgTlDBTFjI_y1eaBbubP';
update content_bodies set title = '[360°VR] DMV【海陽町】', description = '「四国の右下」ファンが協力して体験型観光VRコンテンツを制作しました。徳島県南部の5市町と南部総合県民局は「四国の右下」若者創生協議会を組織し、サテライトオフィス（SO）誘致などの推進に取り組んでいます。このたび、県南に集まるSO企業や「四国の右下ファン」（㈱あわえ、㈱イーツリーズ・ジャパン、㈱ぴやまる、阿南工業高等専門学校）が力を合わせて、体験型観光VRコンテンツを完成させました。多くの方々に県南の魅力を楽しんでいただけることを願っています。' where id = '_Y016B1vaZN0lb0hje0tA';
update content_bodies set title = '[360° VR] DMV [Kaihyo Town]', description = 'Fans of ''Shikoku''s Lower Right'' have collaborated to create an experiential tourism VR content! The five cities and towns in the southern part of Tokushima Prefecture, along with the Southern Comprehensive Prefectural Bureau, have organized the ''Shikoku''s Lower Right Youth Creation Council'' to promote initiatives such as attracting satellite offices (SO). Recently, companies gathered in the southern region, along with ''Shikoku''s Lower Right fans'' (Awae Co., Ltd., Eatsリーズ・ジャパン Co., Ltd., Piyamaru Co., Ltd., and Anan National College of Technology), have joined forces to complete this experiential tourism VR content. We hope many people will enjoy the charm of the southern region.' where id = '4ByeIdwkuqxX4_UGXCMec';
update content_bodies set title = '［TOKUSHIMA］Experience more Japan', description = 'この動画は、徳島県の自然景観、文化、グルメをコンパクトにまとめたものです。徳島の魅力を紹介し、視聴者にこの地域をさらに探求することを促しています。' where id = 'pQTZvSPFYM_lh5iY1fZ_g';
update content_bodies set title = 'Experience more Japan', description = 'This video provides a brief overview of Tokushima Prefecture, showcasing its natural landscapes, rich culture, and delicious cuisine. It serves as an introduction to the unique experiences that Tokushima has to offer, inviting viewers to explore the region further.' where id = 'QnqFnV4O7D_94uRzZ0b28';
update content_bodies set title = '阿波藍アート「藍のけしき」', description = '「藍のけしき」は、10カ国から451名が参加した阿波藍アートの制作を記録した映像です。この映像は、平成30年1月に行われた空間展示の様子を捉えています。阿波藍に関する詳細情報は、提供されたリンクを参照してください。また、関連動画として「AI - TOKUSHIMA : SOMETHING BLUE」や「AI - TOKUSHIMA : THE STORY OF JAPAN BLUE」も視聴可能です。' where id = 'mBnUnMprDbg_XvgjquQEX';
update content_bodies set title = 'Ai no Keshiki Indigo Views', description = '"Ai no Keshiki Indigo Views" is a recorded film showcasing the Awa indigo art installation that took place in January, featuring the participation of 451 individuals from 10 different countries. This video captures the essence of the installation, highlighting the collaborative effort in creating this unique art form. For more information about Awa Indigo, you can visit the provided link. Additionally, related videos are available, including "AI - TOKUSHIMA: SOMETHING BLUE" and "AI - TOKUSHIMA: THE STORY OF JAPAN BLUE."' where id = 'rpUPyJB0FArWiFgkqkVOi';
update content_bodies set title = '遊山箱-ＹＵＳＡＮＢＡＫＯ-［徳島］', description = '徳島は長い間、木材を生産してきました。江戸時代（1603–1868）には、阿波藩の強力な海軍を支えるために、船大工の高い木材加工技術が発展し、代々受け継がれてきました。遊山箱は、薄い木の板を使った木工技術「木張り」を活用し、美しい塗装が施されています。これは、野外や山でのレジャーや雛祭りの際に使用されていた三段重ねの箱です。' where id = 'IEwtn3dThhNRukjcKOtxk';
update content_bodies set title = 'Yusanbako -遊山箱- [Tokushima]', description = 'Tokushima has a long history of lumber production, with high-quality processing techniques developed by shipwrights during the Edo Period (1603–1868) to support the powerful navy of Awa-Han. These skills have been passed down through generations. The Yusanbako, a three-tiered box, showcases carpentry skills known as Mokuhari, which involves crafting thin wood sheets, and features beautiful paintwork. Traditionally, it was used as a lunch box for outdoor activities and during Doll’s Festivals.' where id = 'D8suGOR9Il14dktIKco03';
update content_bodies set title = '大塚国際美術館［徳島］', description = '徳島県鳴門市に位置する大塚国際美術館は、陶板に再現された名画を展示する美術館です。陶板に施された色彩は、紙やキャンバスに比べて劣化しにくく、元の絵画の色やサイズを忠実に再現しています。このため、訪れる人々は、まるでオリジナルの絵画の前にいるかのような迫力とリアリティを体験できます。美術館は、耐久性のある形式で著名な作品を鑑賞するユニークな機会を提供しています。' where id = '1d_PTNeBVkPQ-W9Tv7Lpm';
update content_bodies set title = 'OTSUKA MUSEUM OF ART［Tokushima］', description = 'The Otsuka Museum of Art, located in Naruto City, Tokushima Prefecture, showcases masterpieces reproduced on porcelain panels. These reproductions maintain the original colors and sizes of the paintings, ensuring that the vibrant hues do not fade over time, unlike those on paper or canvas. Visitors can experience the art in a realistic manner, as the reproductions are displayed in their original dimensions, allowing for an immersive experience akin to viewing the original works. The museum offers a unique opportunity to appreciate renowned artworks in a durable format.' where id = 'BtPSWwnMUGIXEuh0HSa7L';
update content_bodies set title = '徳島第九フラッシュモブ', description = '平成28年9月13日、東京都渋谷区の表参道ヒルズで「第九フラッシュモブ」が行われました。このイベントは、アジア初演の地である徳島県を紹介するもので、2018年に迎える第九初演100周年に向けたPRイベントです。指揮は松井慶太、独唱には熊田祥子、藤井奈生子、岸浪愛学、浅井隆仁が参加し、とくしま国民文化祭記念管弦楽団と武蔵野合唱団が演奏を行いました。' where id = '0EPWHsle0lZJLG6IKBLpx';
update content_bodies set title = 'Flash mob “Beethoven’s Symphony No. 9”', description = 'On September 13, 2016, a flash mob performance of Beethoven’s Symphony No. 9 took place at Omotesando Hills in Shibuya, Tokyo. This event highlighted Tokushima Prefecture, known as the site of the first performance of Beethoven’s Symphony No. 9 in Asia. The flash mob served as a promotional event leading up to the 100th anniversary of this historic performance, which will be celebrated in 2018. The performance featured conductor Keita Matsui, soloists Shoko Kumada, Naoko Fujii, Aigaku Kishinami, and Takahito Asai, along with the Tokushima Kinen Orchestra and the Musashino Chorus.' where id = '2izlzV3MAtXg-pWFLaVYV';
update content_bodies set title = 'GO FORWARD SUDACHIKUN　［徳島］', description = '徳島県のマスコット「すだちくん」が、池田湖で初めてウェイクボードに挑戦します。このイベントは、2018年に池田湖で開催されたアジア初のウェイクボード世界選手権を記念するもので、地域の重要なマイルストーンとなっています。池田湖の美しさとウェイクボードの楽しさを広くアピールする機会です。' where id = 'MpBg3T8HBlMAXupAC23LM';
update content_bodies set title = 'GO FORWARD SUDACHIKUN [Tokushima]', description = 'Sudachi-kun, the mascot of Tokushima, is making his wakeboarding debut at Lake Ikeda in Tokushima Prefecture. This event marks the first-ever Wakeboard World Championship held in Asia, which took place at Lake Ikeda in 2018. The championship is a significant milestone for the region, showcasing the beauty of the lake and the excitement of wakeboarding.' where id = 'KGh3PbuvQzmLYsmxVywiM';
update content_bodies set title = '剣山物語ビート［徳島］', description = '日常生活では味わえない「人」との出会い、「自然」の美しさに感動し、「文化」に触れることができるツアーです。にし阿波徳島の歴史や自然、そして地元の人々の温かいおもてなしを体験しながら、まるでその土地に住んでいるかのように深く物語を辿ることができます。' where id = '-eQrY1DzA-aEWeGnhLQs7';
update content_bodies set title = 'Tsurugi Story Beat［Tokushima］', description = 'Experience the rich history, stunning nature, and warm hospitality of Nishi-Awa Tokushima. This tour offers a unique opportunity to connect with the local culture, allowing you to meet the people, appreciate the natural beauty, and engage with the traditions of the area. You''ll feel like a true local as you delve into the stories that define this region.' where id = 'oKpjkzLe-f_nbAcORSdz-';
update content_bodies set title = '中津川の美酒探訪！', description = '中津川市には4つの酒蔵があり、それぞれが独自の銘酒を提供しています。これらの美酒と中津川市の幻想的な冬、温泉、地元の料理との組み合わせは、訪れる人々にとって最高の体験を生み出します。お酒の風味は地域の水質や天候に大きく影響されますが、中津川は美味しいお酒を生産するための理想的な環境が整っています。訪れた際には、ぜひ地元の酒を味わってみてください！' where id = 'OWUMDsAm2iuZ6CQHwFE38';
update content_bodies set title = 'Exploring the Fine Sake of Nakatsugawa', description = 'Nakatsugawa City is home to four sake breweries, each offering unique signature sakes. The combination of these fine sakes with the city''s enchanting winter, hot springs, and local cuisine creates a perfect experience for visitors. The flavor of sake is significantly influenced by the region''s water quality and weather conditions. Nakatsugawa has the ideal environment for producing delicious sake, ensuring that visitors can enjoy clear and flavorful drinks. If you visit Nakatsugawa, be sure to sample the local sake!' where id = '00oTItGzv6h6p3dE8Ub4a';
update content_bodies set title = '徳島遊覧飛行', description = '「徳島遊覧飛行」は、第7回ICT（愛して—愛する）徳島グランプリの「パナソニックシステムソリューションズジャパングランプリ」を受賞しました。この作品は、ドローンで撮影された徳島のさまざまな場所の4K解像度の空撮映像を集めたもので、徳島の魅力を前例のない角度から紹介しています。' where id = 'tvZr8zi_SjcPnbqlmRLvf';
update content_bodies set title = 'A sightseeing flight over Tokushima', description = 'The project ''A sightseeing flight over Tokushima'' has been awarded the 7th ICT (Aishite—love it) Tokushima Grand Prize, specifically the ''Panasonic System Solutions Japan Grand Prize''. This work features a collection of video clips showcasing 4K resolution aerial images captured by drones, highlighting various locations in Tokushima. The footage presents the beauty and attractions of Tokushima from unique and unprecedented perspectives.' where id = 'd53ouAnHq_My5yRISSOkA';
update content_bodies set title = '中津川 観光', description = '中津川市の観光モデルコースを紹介する動画です。中山道に沿った古い街並みや建物を巡り、実際に歩くことで歴史を肌で感じることができます。中津川駅や中津川宿、落合宿などの名所を訪れ、落合の石畳や馬籠宿近くのサンセットポイントなどの美しい景色を楽しむことができます。また、地元の食事や宿泊、五平餅づくりなどの体験も可能です。車が通れない場所が多く、昔の日本の雰囲気を残している中山道を歩くことで、歴史との感動的なつながりを体験できることを強調しています。ぜひ中津川市を訪れてみてください！' where id = 'AXqUypFqyj7KQl6-YmFJ7';
update content_bodies set title = 'Walk the Nakasendo and experience the essence of Japan!', description = 'This video presents a sightseeing course in Nakatsugawa City, Japan, focusing on the historical Nakasendo Trail. It highlights key locations such as Nakatsugawa Station, Nakatsugawa-Juku, and Ochiai-Juku, showcasing the traditional cobblestone paths and the scenic Sunset Point near Magome-Juku. Visitors can enjoy local meals, accommodations, and activities like making Gohei-mochi. The Nakasendo Trail offers a unique opportunity to explore Japan''s history by walking through areas where cars cannot access, preserving the traditional atmosphere. The experience emphasizes the emotional connection to history that can only be felt on foot, inviting travelers to visit Nakatsugawa City.' where id = '7T8xUFrwy2yRBaAEymBeI';
update content_bodies set title = '中津川 観光', description = '岐阜県中津川市の観光モデルコースです。レンタカーを借りて、中津川を隅々まで楽しむことができます。歴史的な建物や美しい景色を訪れ、苗木城跡、道の駅きりら坂下、夕森渓谷、付知峡、かしも明治座などを巡ります。中津川市ならではの体験を通じて、日本の風情を五感で感じることができるでしょう。ぜひ、中津川市の魅力を発見しに来てください！' where id = 'Sqg8mW4X0tkyMcMXOpcf0';
update content_bodies set title = 'Experience the Heart of Japan!', description = 'This is a sightseeing sample course in Nakatsugawa City, Gifu Prefecture. Rent a car to explore the city thoroughly and enjoy its historic buildings and stunning landscapes. The course includes visits to Naegi Castle Ruins, Roadside Station Kirira Sakashita, Yumori Valley, Tsukechi Gorge, and Kashimo Meijiza, among others. By experiencing the unique charm of Nakatsugawa, you can immerse yourself in the authentic essence of Japan through your senses. Nakatsugawa City invites you to discover its beauty!' where id = '2kjrzQGZioZi6z_Axd-n-';
update content_bodies set title = '中津川 観光', description = 'この動画では、中津川の観光スポットを紹介しています。紹介されているスポットは、苗木城跡（00:00）、中山道馬籠宿（00:03）、恵那醸造（00:13）、64カフェ（00:20）、ちこり村（00:24）、かしも明治座（00:30）、常盤座地歌舞伎公演（00:33）、あぎの里のひなまつり・つるしかざり（00:39）、道の駅加子母（00:49）、付知峡倉屋温泉おんぽいの湯（00:51）、道の駅きりら坂下（00:55）、俵屋（01:00）、馬籠宿氷雪の灯まつり（01:06）です。' where id = 'pjvZBFRVxMLQd0LsxDn0O';
update content_bodies set title = 'Nakatsugawa sightseeing', description = 'The video introduces various sightseeing spots in Nakatsugawa, Japan, in the following order: 00:00 Naegi Castle Ruins, 00:03 Nakayama Road Magome-juku, 00:13 Ena Brewing, 00:20 Cafe 64, 00:24 Chicory Village, 00:30 Kashimo Meijiza, 00:33 Tokiwaza Kabuki Performance, 00:39 Aginosato Hina Matsuri, 00:49 Roadside Station Kashimo, 00:51 Chikuhon Kuraya Onsen, 00:55 Roadside Station Kirira Sakashita, 01:00 Tawara-ya, and 01:06 Magome-juku Ice and Snow Lantern Festival.' where id = 'jeeAUeFMNgKERA3s-Sdtj';
update content_bodies set title = '中津川観光', description = 'この動画では、中津川の冬の観光スポットを紹介しています。紹介されている場所には、中山道の馬籠宿、加子母、恵那醸造（福岡）、かしも明治座、常盤座の地歌舞伎公演（福岡）、苗木城跡、64カフェ（坂下）、道の駅きりら坂下、付知峡倉屋温泉おんぽいの湯、めぐりーん産地直売所（坂本）、加子母森林組合モクモクセンター、ストーンミュージアム博石館（蛭川）があります。各スポットの詳細はリンクを参照してください。' where id = '8nXB4N8slG1hySRJcfEtG';
update content_bodies set title = 'Nakatsugawa sightseeing', description = 'This video introduces various sightseeing spots in Nakatsugawa during winter. The featured locations include: Nakadōri Magome-juku, a historic post town; Kachimo; Ena Brewery in Fukuoka; Kachimo Meijiza theater; Tokiwaza Kabuki performances in Fukuoka; Naegi Castle ruins; Cafe 64 in Sakashita; Michi-no-Eki Kirira Sakashita; Onpoinoyu at Chikuhō Gorge; Megurin direct sales shop in Sakamoto; Kachimo Forest Association Mokumoku Center; and the Stone Museum Hakusekikan in Hirukawa. Each location is linked for more information.' where id = 'wit5zKqOlRVeH1mZhpcrT';
update content_bodies set title = '中津川 観光', description = 'この動画では、日本の中津川市にある観光スポットを紹介しています。紹介されているスポットは以下の通りです。1) 付知峡 不動公園、2) 不動滝ひろづき、3) 栗cafe ISSADO、4) 岩魚の里 峡、5) 宮島キャンプ場、6) 付知峡上田屋ブルーベリー園、7) 苗木城跡、8) ランプの宿 渡合温泉、9) 富士見台高原、10) HillBilly Coffee Company、11) 中山道 馬籠宿です。各スポットの詳細については、動画内のリンクを参照してください。' where id = '7Zp5dDHJ40BUERmwhkAw9';
update content_bodies set title = 'Nakatsugawa sightseeing', description = 'This video introduces various sightseeing spots in Nakatsugawa, Japan, in the following order: 1) Tsukechi Gorge Fudo Park, 2) Fudo Falls Hirozuki, 3) Kuricafe ISSADO, 4) Iwana no Sato Hazama, 5) Miyajima Campground, 6) Tsukechi Gorge Uedayama Blueberry Farm, 7) Naegi Castle Ruins, 8) Lamp''s Inn Wataoi Onsen, 9) Fujimidai Kogen, 10) HillBilly Coffee Company, and 11) Nakasendo Magome-juku. The video provides links for more information about each location.' where id = 'Gq0bFSxkMcWTLRNbogE8s';
update content_bodies set title = '信楽の赤い村「作品」', description = '信楽は、特に信楽焼として知られる伝統的な陶器で有名です。信楽焼は、その素朴な外観と土の色合いが特徴です。この村は独特の赤土と、地域の文化遺産を反映した陶器を作る技術で知られています。ハッシュタグ #shigaraki は、日本の陶芸におけるこの村の重要性を強調しています。' where id = 'Hf0TJmM7ju_zY-iNrwqed';
update content_bodies set title = 'Scarlet village of Shigaraki ''work''', description = 'Shigaraki is known for its traditional pottery, particularly Shigaraki ware, which is characterized by its rustic appearance and earthy tones. The village is famous for its unique red clay and the craftsmanship involved in creating pottery that reflects the region''s cultural heritage. The hashtag #shigaraki highlights the significance of this village in the context of Japanese ceramics.' where id = 'Qy9koGYJ-J-L3FwaNFmxa';
update content_bodies set title = '信楽の赤い村「思い」', description = '信楽は、特に信楽焼として知られる伝統的な陶器で有名です。信楽焼は、その素朴な外観と土の色合いが特徴です。この村は、独自の文化的アイデンティティと芸術的遺産を反映する赤色にしばしば関連付けられています。ハッシュタグ #shigaraki は、日本の陶芸におけるこの村の重要性と、現代アートにおけるその影響を強調しています。' where id = 'c6hUJ-e_e4pj_MNIQHpzM';
update content_bodies set title = 'Scarlet village of Shigaraki ''thought''', description = 'Shigaraki is known for its traditional pottery, particularly Shigaraki ware, which is characterized by its rustic appearance and earthy tones. The village is often associated with the color scarlet, reflecting its unique cultural identity and artistic heritage. The hashtag #shigaraki highlights the significance of this village in the context of Japanese ceramics and its ongoing influence in contemporary art.' where id = 'UZ630uADYqgk1LG2-oFa9';
update content_bodies set title = '緋色の里紫香楽30秒「信楽焼」篇', description = 'この短いセグメントでは、信楽焼について紹介しています。信楽焼は、日本の伝統的な陶器であり、その独特の特徴と職人技が評価されています。' where id = 'cZAPFPWpZeFuLtJ3BYFHW';
update content_bodies set title = 'Shigaraki Ware - 30 Seconds of Scarlet Village', description = 'This brief segment highlights Shigaraki ware, a traditional Japanese pottery known for its unique characteristics and craftsmanship.' where id = 'Se44Hrlg6g58DhMH4eFcP';
update content_bodies set title = '緋色の里紫香楽30秒「人物」篇', description = 'この作品は、信楽焼に焦点を当てたもので、独特の質感と土の色合いが特徴の伝統的な日本の陶器です。動画では、信楽焼の職人技と文化的意義が強調され、これらの美しい作品を作り出す職人たちが紹介されています。地域の伝統と陶芸の関係を反映し、コミュニティと陶器の芸術とのつながりを強調しています。' where id = 'x8zb8gC4rckinqyxkrEFy';
update content_bodies set title = 'Scarlet Village Shigaraki 30 Seconds ''Character'' Edition', description = 'This piece focuses on Shigaraki ware, a traditional Japanese pottery known for its unique textures and earthy colors. The video highlights the craftsmanship and cultural significance of Shigaraki ware, showcasing the artisans who create these beautiful pieces. It emphasizes the connection between the community and the art of pottery, reflecting the rich heritage of the region.' where id = 'Bs9E-qe2XxOy8IhV0WPCg';
update content_bodies set title = '珠洲市CM', description = '第12回石川ふるさとCM大賞において、珠洲市のCMが準グランプリを受賞しました。この賞は地域の魅力を伝えるためのCMを評価するもので、珠洲市のCMはその独自性や地域性が評価されました。受賞を通じて、珠洲市の魅力がさらに広がることが期待されています。' where id = 'p2MGkO5WLsn4G2fSfQYMc';
update content_bodies set title = 'Suzushi City CM', description = 'The Suzushi City commercial won the runner-up prize at the 12th Ishikawa Hometown CM Awards.' where id = 'x-Se7ejJ-A3qUhYP51Dgc';
update content_bodies set title = 'モデルコース１「能登シーサイドドライブ」', description = 'このコースは、能登半島沿いの美しい海岸線をドライブし、地元の観光名所や自然の美しさを楽しむことができるように設計されています。能登地域の文化遺産を探求したい方に最適です。' where id = 'kB2X6w1S7PNKQZXf22hI5';
update content_bodies set title = 'Model Course 1: Noto Seaside Drive', description = 'This course offers a scenic drive along the Noto Peninsula, showcasing beautiful coastal views and local attractions. It is designed for those who wish to explore the natural beauty and cultural heritage of the Noto region.' where id = 'sn3pQ3k_2NQ0fdcXJCnvm';
update content_bodies set title = '第33回 サハラマラソン2018　４stage', description = '「世界で最も過酷なマラソン」と称される「サハラマラソン」に、大分市に住む水岡紗希さんが挑戦しました。彼女の挑戦は、厳しい環境の中で行われるこのマラソンの過酷さを物語っています。サハラ砂漠の過酷な条件の中で、参加者は体力と精神力を試されることになります。水岡さんの挑戦は、多くの人々に感動を与えることでしょう。' where id = 'KfaktMsK_4qtJO8QVTdBl';
update content_bodies set title = '33rd Sahara Marathon 2018 - Stage 4', description = 'Saki Mizuoka, a resident of Oita City, took on the challenge of the ''Sahara Marathon,'' known as the most grueling marathon in the world.' where id = 'J55y_PtxfA2Pq-ZrpYdd0';
update content_bodies set title = '【石川県観光ＰＲ動画】ゆるーっといしかわ', description = 'マルチクリエイターの“まこち”が、石川県の旅をゆるりと紹介する動画です。動画では、山中温泉や鶴仙渓、ひがし茶屋街、千里浜なぎさドライブウェイ、輪島朝市、金沢21世紀美術館、金沢城の鼠多門・鼠多門橋、兼六園、あかり坂、卯辰山公園など、石川県のさまざまな観光名所が紹介されています。' where id = 'F3gbyV5hFCWMESlJMHC0p';
update content_bodies set title = 'Ishikawa Prefecture Tourism PR Video: Relaxing Ishikawa', description = 'Multi-creator ''Makochi'' leisurely introduces a trip to Ishikawa. The video showcases various attractions in Ishikawa, including Yamanaka Onsen, the scenic Tsurusen Valley, the historic Higashi Chaya District, the beautiful Chirihama Nagisa Driveway, the vibrant Wajima Morning Market, the contemporary Kanazawa 21st Century Museum of Contemporary Art, Kanazawa Castle''s Nezumi Gate and Nezumi Bridge, Kenrokuen Garden, Akari Saka, and Utatsuyama Park.' where id = 'w6RBZMpfLgYoKTrgfIDRr';
update content_bodies set title = '本物に出会う石川県へ', description = '石川県観光大使で俳優の篠井英介氏が、映像を通じて石川県の魅力を語ります。彼は絶景、温泉、伝統・文化、美食の4つの要素を取り上げ、自身の思いを込めて紹介しています。白米千枚田や山代温泉、長町武家屋敷跡、兼六園など、石川県の美しさと魅力が詰まった内容です。' where id = '7fmMx1MG1MAVtHfvR4GbI';
update content_bodies set title = 'Discover the Authenticity of Ishikawa Prefecture', description = 'Ishikawa Prefecture''s tourism ambassador, actor Eisuke Shinoi, shares the allure of Ishikawa through stunning visuals and personal reflections. He highlights four key attractions: breathtaking landscapes, hot springs, traditional culture, and exquisite cuisine.' where id = 'nYQPfLzDvRcTqYDnyjXnW';
update content_bodies set title = '金勝寺 特別体験プログラム紹介動画', description = '滋賀県栗東市にある金勝寺は、金勝山の頂上近くに位置する静かな天台宗の寺院です。約1300年前に創立され、国家の平安を祈願する場として知られています。金勝寺は70種類以上の苔が自生する名所であり、苔の専門家と共に観察する苔フィールドワーク、精神を統一する座禅体験、自然のエネルギーを感じる森林浴ヨガの3つの体験を通じて、日本の文化と美を楽しむことができます。これらの体験は、歴史ある仏殿や四季折々の植物に囲まれた澄んだ空気の中で行われます。' where id = '1Tq18fyE-vW67Yp8lMtN1';
update content_bodies set title = 'KONSHOJI TEMPLE PREMIUM TOUR - Experience Japan''s Beauty and Culture', description = 'Konshoji Temple, located near the summit of Mount Konsho in Ritto City, Shiga Prefecture, is a serene Tendai Buddhist temple founded about 1300 years ago by the monk Ryoben. It became a place for monks to gather and pray for national peace. The temple is renowned for its beautiful scenery and coexistence with nature, featuring a historic main hall and a variety of seasonal plants. Visitors can enjoy three unique experiences centered around Japanese culture and beauty: 1) Moss Fieldwork, where you can observe over 70 varieties of moss with a professional guide; 2) Zazen Experience, a meditative practice in the main hall that promotes self-reflection; and 3) Forest Bathing Yoga, an outdoor yoga session at the temple''s highest point, allowing you to connect with nature and find inner peace.' where id = '7F_Ix23OApWmSKIDu_BLR';
update content_bodies set title = '金勝寺プレミアムツアー 2023年開催 モニターツアーの様子', description = '金勝寺プレミアムツアーは、2023年に実施されたモニターツアーで、訪問者は副住職による境内の案内を受けながら、自然と共生する金勝寺の静寂な空間で日本の文化と美を体験できます。2024年10月20日には、坐禅と苔フィールドワークをテーマにした特別イベントも予定されています。詳細やお問い合わせ、予約は特設WEBサイトをご覧ください。ツアーは滋賀県栗東市観光協会が主催しています。' where id = 'CjmCg6r9FuN4Adp6e3L66';
update content_bodies set title = 'KONSHOJI TEMPLE PREMIUM TOUR - Held in 2023 Monitoring Tour', description = 'The Konshoji Temple Premium Tour, held in 2023, offers visitors a unique experience of Japanese culture and beauty in a serene natural setting. Participants can enjoy a guided tour of the temple grounds led by a deputy priest, highlighting the temple''s harmonious existence with nature. A special event featuring Zazen meditation and moss fieldwork is scheduled for October 20, 2024. For more details, inquiries, and reservations, please visit the special website. The tour is organized by the Ritto Tourism Association, located in Shiga, Japan.' where id = '0vpgWAkKvVQxV713SWTni';
update content_bodies set title = '草津温泉', description = 'この動画は、日本の有名な温泉地である草津温泉を夏の季節に4K（ウルトラHD）で紹介しています。視聴者は、公式ウェブサイトやソーシャルメディアのリンクを通じて、さらに詳細を学ぶことができます。制作には、榎川幸が関わり、音楽は加木戸直が担当しており、西日本新聞メディアラボによって制作されています。' where id = 'DX0PKgnqk6TYTNEvO0SIy';
update content_bodies set title = 'Kusatsu Onsen, JAPAN - Summer - 4K (Ultra HD)', description = 'This video showcases Kusatsu Onsen, a famous hot spring resort in Japan, during the summer season in stunning 4K Ultra HD. Viewers can learn more about the destination through the official website and social media links provided. The production features contributions from Yuki Eikawa, with music by Nao Kakimoto, and is produced by Nishinippon Shimbun Media Lab.' where id = 'djnGwZdF_fWkY8f0yk__G';
update content_bodies set title = '日本遺産ツーリズム（東近江編）～水と暮らしの文化 永源寺を訪ねて～', description = '滋賀県東近江市に位置する永源寺は、650年以上の歴史を持つ臨済宗永源寺派の大本山です。境内には国内屈指の大きさを誇るヨシ葦屋根の本堂や県指定の有形文化財があり、四季折々の美しい風景を楽しむことができます。特に秋には真っ赤な紅葉が境内を彩り、関西有数の紅葉の名所として多くの参拝者が訪れます。普段は立ち入り禁止の場所も、ボランティアガイドと共に特別に見学できる機会があります。紅葉が映える永源寺の魅力をぜひ映像でお楽しみください。' where id = 'ZpX-QLx3z41ZxUcS6WY-o';
update content_bodies set title = 'Japan Heritage Tourism (Higashiomi) - Visiting Eigenji, a Culture of Water and Living', description = 'Eigenji, located in Higashiomi City, Shiga Prefecture, is the head temple of the Rinzai sect with a history of over 650 years. The temple features one of Japan''s largest thatched-roof main halls and is designated as a tangible cultural asset by the prefecture. Surrounded by deep nature, the temple complex showcases seasonal beauty, particularly its stunning red autumn leaves, attracting many visitors from across the country. While certain areas are usually off-limits to the public, special guided tours with volunteers allow for unique access. Enjoy the captivating scenery of Eigenji, especially during the autumn foliage.' where id = 'Ur1-wi1dFYFhOatWAywjF';
update content_bodies set title = '「非日常」が「日常」福井県', description = '「幸福度日本一」の福井県は、自然、文化、人々の魅力にあふれています。しかし、福井を訪れる外国人観光客の数はまだ「日本一」には達していません。そこで、福井在住の外国人に注目し、彼らの視点から福井の魅力を伝えることを目指しました。ナレーションやロケ地の選定、出演に協力してもらい、福井の知られざる魅力を満載した映像（全3部作）が完成しました。最終的な目標は、訪日外国人客数で全国1位を目指すことです。' where id = '15KwZIiNbf7Cr9xjXmcjk';
update content_bodies set title = '"Extraordinary" is "everyday" Fukui Prefecture', description = 'Fukui Prefecture, known for its high happiness levels, boasts a wealth of natural beauty, friendly people, and rich culture. Despite its many attractions, the number of foreign tourists visiting Fukui has not yet reached the top in Japan. To effectively convey Fukui''s charm to international visitors, the focus has been on foreign residents living in Fukui. Their firsthand experiences and insights have been utilized in narration, location selection, and participation in a video series that showcases the hidden gems of Fukui. The goal is to make Fukui the top destination for foreign tourists in Japan.' where id = 'Qa_N7JAwdMfiaA0Sy3njA';
update content_bodies set title = '春の栃木（8K） - 日光・那須', description = 'この動画では、春の栃木県の美しさを紹介しています。あしかがフラワーパークの大藤や、歴史的な野木町煉瓦窯、真岡木綿など、さまざまな風景が楽しめます。また、渡良瀬遊水地のメタセコイアや、うなぎ魚登久の美味しいグリルうなぎ、足利織姫神社の静けさも捉えています。市貝町芝ざくら公園や那須ハートフルファーム、石畑の棚田なども登場し、最後には中禅寺湖の美しい景色が映し出され、栃木の自然と文化的な魅力を総合的に紹介しています。' where id = '7My1JEO-QBjeQdqnwBdDM';
update content_bodies set title = 'Spring Tochigi Japan in 8K - Nikko and Nasu', description = 'This video showcases the beauty of Tochigi, Japan during spring, featuring various scenic locations. Highlights include the Big Wisteria at Ashikaga Flower Park, the historic Nogi Town Brick Kiln, and the picturesque Moka Cotton. The video also captures the stunning Metasequoia trees at Watarase Yusui Park, delicious grilled eel from Uotoku, and the serene Ashikaga Orihime Shrine. Other notable spots include Ichikai Town Shibazakura Park, Nasu Heartful Farm, and the scenic Ishibatake Terraced Rice Fields. The video concludes with views of Lake Chūzenji, providing a comprehensive glimpse into Tochigi''s natural and cultural attractions.' where id = '3VulbJwrIYncINwUvTwhK';
update content_bodies set title = '四季で楽しむ栃木の自然', description = '栃木県は四季折々の自然の魅力を楽しむことができます。春には、あしかがフラワーパークの大藤や、市貝町芝桜公園の美しい芝桜、焼森山のミツマタ群生地が見どころです。夏には、鬼怒川ライン下りや那須高原の美しい風景、若竹の杜若山農場を訪れることができます。秋には、茶臼岳の雄大な景色、那須フラワーワールドの色とりどりの花、中禅寺湖の美しい風景が楽しめます。冬には、華厳滝の壮大な景観、八丁の湯でのリラックス、湯西川温泉のかまくらでのユニークな体験が待っています。栃木の多様な風景と季節の美しさは、自然愛好者にとって理想的な目的地です。' where id = 'MD_xAd1uYzskpsJ9KnAMH';
update content_bodies set title = 'Nature of Tochigi to enjoy in four seasons', description = 'Tochigi offers a variety of natural attractions throughout the year. In spring, visitors can enjoy the stunning Big Wisteria at Ashikaga Flower Park, the beautiful Shibazakura at Icikai Town Shibazakura Park, and the Yakemoriyama Oriental Paper Bush. Summer activities include the Kinugawa River Boat Tour, exploring the scenic Nasu Kogen, and visiting Wakatake-no-mori Wakayama Farm. Autumn highlights feature the majestic Mount Chausu, the vibrant Nasu Flower World, and the picturesque Lake Chuzenji. In winter, the breathtaking Kegon Falls, the relaxing Hatcho-no-yu hot spring, and the unique Kamakura Snow House in Yunishigawa Onsen provide memorable experiences. Tochigi''s diverse landscapes and seasonal beauty make it a perfect destination for nature lovers.' where id = '6kGgqEbCaWwaGMXzlGgji';
update content_bodies set title = '栃木の秋 - 日光・那須の8K映像', description = 'この映像は、栃木県の日光と那須の美しい秋の風景を紹介しています。明智平展望台や日光二荒山神社中宮祠、男体山、那須ロープウェイなど、さまざまな名所が登場します。鮮やかな紅葉や美しい風景を捉え、栃木の自然美と文化遺産を視覚的に旅する内容です。日光東照宮や宇都宮みんみん、足利学校などの名所も取り上げられ、昭和ふるさと村や龍王峡などの地元の魅力も紹介されています。映像は、映像監督・編集の栄川幸、撮影の松村隆、空撮の馬場基成によって制作されています。' where id = 'NvNY5i6B86EfgYOnhDufs';
update content_bodies set title = 'Autumn Tochigi Japan in 8K - Nikko and Nasu', description = 'This video showcases the stunning autumn scenery of Tochigi, Japan, featuring various iconic locations. Highlights include Akechidaira Observatory, Nikko Futarasan Jinja Chugushi Shrine, Mount Nantai, and the Nasu Ropeway. The film captures the vibrant autumn leaves and beautiful landscapes, providing a visual journey through Tochigi''s natural beauty and cultural heritage. Notable sites such as Nikko Toshogu, Utsunomiya Minmin, and the Ashikaga School are also featured, along with local attractions like the Showa Furusato Village and the Ryuokyo gorge. The video is directed and edited by Yuki Eikawa, with photography by Takashi Matsumura and aerial shots by Motonari Baba.' where id = 'm1Na1szOpoV59WX2q3iyf';
update content_bodies set title = '栃木の秋 - 日光・那須を8Kで', description = 'この動画は、栃木県の美しさを特に秋に焦点を当てて紹介しています。いろは坂や明智平展望台、日光東照宮や日光山輪王寺などの文化的な名所が登場します。また、宇都宮餃子や佐野らーめんなどの地元の料理も紹介されています。才能ある写真家や映像作家によって捉えられた息をのむような秋の風景が、栃木の自然と文化遺産を生き生きと体験させてくれます。詳細は栃木観光のウェブサイトをご覧ください。' where id = 'gb-cv_Z6jCx21cwYAo46j';
update content_bodies set title = 'Tochigi Japan in 8K - Nikko and Nasu', description = 'This video showcases the beauty of Tochigi, Japan, particularly during autumn. It features stunning locations such as Iroha Slope, Akechidaira Observatory, and various cultural sites like Nikko Toshogu and Nikkozan Rinnoji Temple. The video also highlights local cuisine, including Utsunomiya gyoza and Sano ramen. The breathtaking autumn scenery is captured through the lens of talented photographers and filmmakers, providing viewers with a vivid experience of Tochigi''s natural and cultural heritage. For more information, viewers can visit the Tochigi tourism website.' where id = '63tyfhiXJIibjweY_DAKX';
update content_bodies set title = '冬の栃木を8Kで体験', description = 'この動画では、冬の栃木県の美しさを8K解像度で紹介しています。いろは坂や明智平展望台などの名所や、飯沼銘醸での日本酒の仕込み、幸乃湯温泉、山帰来での蕎麦など、地元の魅力が満載です。また、小島農園のいちごや那須どうぶつ王国、湯西川温泉のかまくらも取り上げられています。詳細はYouTubeでフル動画を視聴し、栃木についての情報を提供するリンクを参照してください。' where id = 'YSAlKps8lV3NbpNvjNUTQ';
update content_bodies set title = 'Winter/Digest: Tochigi Japan in 8K', description = 'This video showcases the beauty of Tochigi, Japan during winter in stunning 8K resolution. It features various locations including Irohazaka, Akechidaira Observatory, and local attractions such as Japanese sake brewing at Iinuma Meijo, Sachi-no-yu Onsen, and delicious soba at Sankirai. The video also highlights Ojima Farm''s strawberries, Nasu Animal Kingdom, and the unique Kamakura snow houses at Yunishigawa Onsen. For more information, viewers can access the full video on YouTube and learn more about Tochigi through the provided links.' where id = 'ngG9VNC8z7sX8eFH4hfMS';
update content_bodies set title = '【兵庫県赤穂市日本遺産PR動画】Sel de la vie -Traveling is the salt of life-', description = '「セル ドゥ ラ ヴィ」はフランス語で「人生の塩」を意味します。2人のシェフがキッチンバスで赤穂を巡り、地域の自然や文化、人々、食材と触れ合いながら、最高の料理を提供します。この心温まるムービーは、塩のスパイスを通じて赤穂の魅力を引き立てます。赤穂市は2019年に日本遺産に認定され、41の塩に関連する歴史的・文化的遺産があります。' where id = 'P3vDXy5XpBiGJWpvKNEki';
update content_bodies set title = 'PR Video of Ako City, Hyogo Prefecture - Sel de la vie - Traveling is the salt of life -', description = 'Sel de la vie, meaning ''salt of life'' in French, features two chefs traveling in a kitchen bus throughout Ako, engaging with the region''s nature, culture, people, and ingredients to create exquisite dishes. This heartwarming movie highlights the charm of Ako through the spice of salt. Ako was certified as a Japan Heritage site in 2019, boasting 41 salt-related historical and cultural heritages.' where id = 'ePhuHFiOuIAA2iF_nDl9B';
update content_bodies set title = '宇和島', description = 'この動画は宇和島について紹介しています。' where id = 'JIMT59cgsXfFXJzE6d7f6';
update content_bodies set title = 'Uwajima', description = 'This video introduces Uwajima.' where id = 'Wy6TUSKxnnO4E5zy_JT-6';
update content_bodies set title = '【兵庫県赤穂市PR動画】「AKO SALT OF THE SEA」', description = '日本の食文化に欠かせない『塩』。このPR動画では、赤穂塩の歴史や製法に焦点を当て、伝統的な製法によって生まれた塩の魅力を伝えています。また、塩の未来や可能性を探る新たな試みも紹介されており、赤穂塩の重要性を再認識させる内容となっています。' where id = 'AOz8Z42ql9SiLD0LhYs9w';
update content_bodies set title = 'PR Video of Ako City, Hyogo: ''AKO SALT OF THE SEA''', description = 'Salt, a fundamental element in Japanese food culture and various other fields, is the focus of this PR video. It highlights the history and production methods of Ako salt, as well as new initiatives that emphasize traditional techniques. The video expresses the future and potential of salt.' where id = 'NtVtxYwzVQvVk-Ckm15gs';
update content_bodies set title = '2022 KUSHIRO Hokkaido Japan in 8K - 釧路 [夏]', description = 'この動画は、釧路の美しさを8K解像度で紹介しています。釧路湿原ノロッコ号やアイヌ文化ガイド、細岡展望台などの観光名所が取り上げられています。また、鹿肉の鉄板焼きや和商市場の勝手丼などの地元料理も紹介されています。阿寒湖のマリモツアーや幣舞橋、Cool KUSHIROモニュメントなども登場します。釧路・阿寒湖の観光公式サイトでは、観光、交通、宿泊、イベント情報など、釧路の魅力を詳しく知ることができます。' where id = 'ti_YDrcWm3PxFzKrYFAbc';
update content_bodies set title = '2022 KUSHIRO Hokkaido Japan in 8K - Kushiro [summer]', description = 'This video showcases the beauty of Kushiro, Hokkaido, in stunning 8K resolution. It highlights various attractions, including the Kushiro Shitsugen Norroko Train, Ainu cultural guides, and the Hosooka Observatory. The video also features local cuisine such as teppan grilled venison and the Katte-Don at Washo Market. Other notable sites include the Marimo Tour at Lake Akan, Nusamai Bridge, and the Cool KUSHIRO Monument. For more information, visit the official tourism website for Kushiro and Lake Akan, which offers details on sightseeing, transportation, accommodations, and local events.' where id = 'hxw9WjjXgEZY_uySFSNT6';
update content_bodies set title = '2023 KUSHIRO Hokkaido Japan in 8K - 釧路 [冬]', description = 'この動画は、冬の釧路の美しさを8K解像度で紹介しています。釧路川や阿寒湖のモーニングカフェツアー、SL冬の湿原号、釧路そばなど、さまざまな観光名所が登場します。また、阿寒国際ツルセンターやアイヌ文化ガイドなどの文化体験も強調されています。釧路湿原でのカヌーや細岡展望台の訪問など、アクティビティも楽しめます。制作には多くのアーティストや専門家が関わっており、視覚的にも聴覚的にも豊かな体験が提供されています。' where id = 'y5c5CC5au7Sr9vSVZFgQe';
update content_bodies set title = '2023 KUSHIRO Hokkaido Japan in 8K - Kushiro [winter]', description = 'This video showcases the beauty of Kushiro, Hokkaido, during winter in stunning 8K resolution. It features various attractions such as the Kushiro River, Lake Akan Morning Cafe Tour, SL Winter Marshland, and local delicacies like Kushiro Soba. The video also highlights cultural experiences, including visits to the Akan International Crane Center and Ainu cultural guides. Viewers can enjoy activities like canoeing in Kushiro Marsh and visiting the Hosooka Observatory. The production includes contributions from various artists and professionals, ensuring a rich visual and auditory experience.' where id = '4mWAAoWUXYyJ33nqpi_Nm';
update content_bodies set title = '2023 KUSHIRO Hokkaido Japan in 8K - 釧路 [冬]', description = 'この動画は、冬の釧路の美しさを8K解像度で紹介しています。釧路川や阿寒湖のモーニングカフェツアー、SL冬の湿原号、細岡展望台など、さまざまな観光名所が登場します。阿寒国際ツルセンターや福司酒造を訪れ、釧路そばやスパカツなどの地元の美味しい料理を楽しむことができます。また、アイヌ文化ガイドや釧路湿原でのカヌー体験など、文化的な体験も含まれています。多くのアーティストや専門家の協力により、視覚的にも聴覚的にも豊かな体験が提供されています。' where id = 'i0Bf491P2yaBgkCJRPAqK';
update content_bodies set title = '2023 KUSHIRO Hokkaido Japan in 8K - Kushiro [winter]', description = 'This video showcases the beauty of Kushiro, Hokkaido, during winter in stunning 8K resolution. It highlights various attractions including the Kushiro River, Lake Akan Morning Cafe Tour, SL Winter Marshland, and Hosooka Observatory. Visitors can explore the Akan International Crane Center, Fukutsukasa Sake Brewery, and enjoy local delicacies like Kushiro Soba and Spakatsu. The video also features cultural experiences such as Ainu cultural guides and activities like canoeing in Kushiro Marsh. The production includes contributions from various artists and professionals, ensuring a rich visual and auditory experience.' where id = 'CqjzshIRpqhpHNyRH7kYZ';
update content_bodies set title = '【SL&FUN】SL冬の湿原号と釧路の大地　編【4K】', description = 'SL冬の湿原号は、釧網本線の釧路－標茶間を約1時間半かけて走る、北海道で唯一のSLです。2022年から2023年にかけて全客車がリニューアルされ、SLの持つレトロ感やノスタルジックな雰囲気が一層感じられるようになりました。このSLが運行する釧路地域には、北海道内でもここでしか味わえない体験がたくさんあります。沿線周辺の冬の観光情報は、提供されたリンクからご覧いただけます。' where id = 'WRqRrTa5eGXIkC9lPSILu';
update content_bodies set title = 'SL Winter Wetland Train and the Land of Kushiro - 4K', description = 'The SL Winter Wetland Train runs for about an hour and a half between Kushiro and Shibecha, making it the only steam locomotive in Hokkaido. From 2022 to 2023, all passenger cars were renewed, enhancing the retro and nostalgic atmosphere of the train. The train operates in the eastern Hokkaido region of Kushiro, which offers unique experiences that can only be found here in Hokkaido. For winter tourism information around the railway line, visit the provided link.' where id = 'qJbV7EXhHsq_CJn45Rf2a';
update content_bodies set title = 'KUSHIRO Hokkaido Japan in 8K HDR - 釧路 [冬バージョン]', description = 'この動画は、8K HDRの美しい映像で釧路の魅力を紹介しています。釧路川や釧路フィッシャーマンズワーフMOO、釧路湿原、阿寒湖、雄阿寒岳や雌阿寒岳などの観光名所が登場します。また、丹頂鶴や地元のグルメ、寿司や炉端焼きも紹介されています。釧路や周辺地域の観光公式サイトでは、歴史や文化、旅行のヒントなどの情報が提供されており、さらに深く釧路を知ることができます。' where id = '83ZlpoyuC5tio2lXVnWbw';
update content_bodies set title = 'KUSHIRO Hokkaido Japan in 8K HDR - Kushiro [winter ver.]', description = 'This video showcases the beauty of Kushiro, Hokkaido, in stunning 8K HDR quality. It highlights various attractions such as the Kushiro River, Kushiro Fisherman’s Wharf MOO, Kushiro Marsh, and Lake Akan, along with the majestic Mt. Oakan and Mt. Meakan. The video also features the iconic Tancho cranes and local cuisine, including sushi and Robata Yaki. For more information, viewers can explore the official tourism websites for Kushiro and the surrounding areas, which provide insights into history, culture, and travel tips.' where id = 'n9XpREy7jvWf8S-iX_1xK';
update content_bodies set title = '草津温泉', description = 'この動画は、日本の草津温泉の秋の美しさを4K（ウルトラHD）で紹介しています。草津温泉についての詳細は、公式ウェブサイトを訪れることで確認できます。ここでは、この有名な温泉地に関するガイドやリソースが提供されています。制作チームには、PLとして榮川幸、MUとして柿本直、PRとして野路陽二、PMとして馬場基成が参加しており、西日本新聞メディアラボによって制作されています。' where id = 'hqCgDCDODHGaU8gjNXbUb';
update content_bodies set title = 'Kusatsu Onsen, JAPAN - Autumn - 4K (Ultra HD)', description = 'This video showcases the beauty of Kusatsu Onsen in Japan during the autumn season, presented in stunning 4K Ultra HD. For more information, visit the official website of Kusatsu Onsen, where you can find guides and resources about this famous hot spring destination. The production team includes Yuki Eikawa as PL, Nao Kakimoto as MU, Yoji Nomura as PR, and Motonari Baba as PM, with the project produced by Nishinippon Shimbun Media Lab.' where id = 'YRM1l1h0_QuOyiN1mZ4KG';
update content_bodies set title = '草津温泉8D立体音響', description = 'この音声体験は、眠りにつく時やリラックスしたい時、気持ちを上げたい時など、さまざまなシーンで楽しむことができます。温泉の湧き出る音や広大な自然、人々の賑わう街並みの音を通じて、草津の雰囲気を感じることができるでしょう。草津温泉をイメージしたオリジナルの8D音源を体感することをお勧めします。8Dオーディオは、周囲の全方向から音が聞こえるように設計されており、ヘッドフォンやイヤフォンでの視聴が推奨されています。' where id = 'URChSI1_M_8oftt0e8XHo';
update content_bodies set title = 'Kusatsu Onsen Japan in 8D Audio-streaming night-/草津温泉8D立体音響', description = 'This audio experience is designed for various moments such as falling asleep, relaxing, or uplifting your mood. It captures the sounds of hot springs, vast nature, and the lively streets of Kusatsu, allowing listeners to immerse themselves in the atmosphere of the town. The original 8D audio source inspired by Kusatsu Onsen is highly recommended for an authentic experience. 8D audio is engineered to create a surround sound effect, making it feel as if sounds are coming from all directions. It is best enjoyed with headphones or earphones.' where id = 'uJSPgoszAkqXZxGSWhPRJ';
update content_bodies set title = '草津温泉8D立体音響', description = 'この音声体験は、リラックスや眠り、気分を高めたい時など、さまざまなシーンに合わせて設計されています。温泉の湧き出る音や広大な自然、人々の賑わう街並みを感じることができ、目を閉じると草津の雰囲気に浸ることができます。草津温泉をイメージしたオリジナルの8D音源はぜひ体感してみてください。8Dオーディオは、周囲の全方向から音が聞こえるように設計されており、ヘッドフォンやイヤフォンを使用することが推奨されています。' where id = '-gWPaTAFSueYd3XNjGSSs';
update content_bodies set title = 'Kusatsu Onsen Japan in 8D Audi-lapis lazuli-', description = 'This audio experience is designed for various moments such as relaxation, sleep, or uplifting your mood. It captures the sounds of the hot springs, the vast nature, and the lively streets of Kusatsu. By closing your eyes, you can immerse yourself in the atmosphere of Kusatsu. The original 8D audio source inspired by Kusatsu Onsen is a must-try. 8D audio is engineered to create a surround sound experience, making it feel like sounds are coming from all directions. It is recommended to use headphones or earphones for the best experience.' where id = 'BgVzyXO0eu_Gz6NOrihb3';
update content_bodies set title = '草津温泉8D立体音響', description = '眠りにつく時やリラックスしたい時、気持ちを上げたい時にぴったりな「音」を体験できる草津温泉のオリジナル8D音源です。温泉の湧き出る音や広大な自然、人々の賑わう街並みを感じながら、草津の雰囲気に浸ることができます。8Dオーディオは立体音響で、周囲の全方向から音が聞こえるように設計されていますので、ヘッドフォンやイヤフォンの使用をおすすめします。著作権はCOOTS Inc.により作成され、音楽はミヤザキ カイによるものです。草津温泉観光協会が提供しています。' where id = 'V5vZKNv0Yd4omailZYnb8';
update content_bodies set title = 'Kusatsu Onsen Japan in 8D Audio-Spring heart town-', description = 'Experience the soothing sounds of Kusatsu Onsen through original 8D audio designed for relaxation, sleep, or uplifting your mood. The audio captures the essence of the hot springs, the vast nature, and the lively streets of Kusatsu, allowing listeners to immerse themselves in the atmosphere of the town. It is recommended to use headphones or earphones to fully appreciate the 8D audio, which creates a surround sound experience. Created by COOTS Inc. and featuring music by Kai Miyazaki, this audio experience is brought to you by the Kusatsu Onsen Tourism Association.' where id = 'E55eJ547IKyWT9fAZy3gR';
