update content_bodies set title = 'Kusatsu Onsen Japan in 8D Audio', description = 'This audio experience is designed for various moments such as falling asleep, relaxing, or uplifting your mood. It captures the sounds of hot springs, vast nature, and the lively streets of Kusatsu. By closing your eyes, you can immerse yourself in the atmosphere of Kusatsu. The original 8D audio source inspired by Kusatsu Onsen is a must-try. 8D audio is engineered to create a surround sound experience, making it feel as if sounds are coming from all directions. It is recommended to use headphones or earphones for the best experience.' where id = 'pyYW3ERZTzp9BWkO1l6U7';
update content_bodies set title = '草津温泉8D立体音響', description = '眠りにつく時やリラックスしたい時、気持ちを上げたい時にぴったりな「音」を体験できる草津温泉のオリジナル8D音源です。温泉の湧き出る音や広大な自然、人々の賑わう街並みを感じながら、草津の雰囲気に浸ることができます。立体音響の特性を活かすため、ヘッドフォンやイヤフォンの使用を推奨します。この音源はCOOTS Inc.によって制作され、音楽はミヤザキ カイが担当しており、著作権は（一社）草津温泉観光協会に帰属します。' where id = 'h4FGqLudQ1T1s22eMH1E5';
update content_bodies set title = 'Kusatsu Onsen Japan in 8D Audio', description = 'Experience the soothing sounds of Kusatsu Onsen through original 8D audio designed for relaxation, sleep, or uplifting your mood. The audio captures the essence of the hot springs, the vast nature, and the lively streets of Kusatsu, allowing listeners to immerse themselves in the atmosphere of the town. It is recommended to use headphones or earphones to fully appreciate the surround sound experience. This audio is created by COOTS Inc. and features music by Kai Miyazaki, with copyright held by the Kusatsu Onsen Tourism Association.' where id = 'paXbn5CtLKPSiyi1HrdV6';
update content_bodies set title = '草津温泉8D立体音響', description = '眠りにつく時やリラックスしたい時、気持ちを上げたい時にぴったりな「音」を体験できる草津温泉のオリジナル8D音源です。温泉の湧き出る音や広大な自然、人々の賑わう街並みを感じることができ、目を閉じると草津の雰囲気に浸ることができます。立体音響で設計されているため、ヘッドフォンやイヤフォンの使用が推奨されています。音楽はアレックス・クルーズによるもので、草津温泉観光協会が提供しています。' where id = 'TRSs2XCVH3Zczkhdi3VT_';
update content_bodies set title = 'Kusatsu Onsen Japan in 8D Audio', description = 'Experience the soothing sounds of Kusatsu Onsen through original 8D audio designed for relaxation, sleep, or uplifting your mood. The audio captures the essence of the hot springs, the vast nature, and the lively streets of Kusatsu, allowing listeners to immerse themselves in the atmosphere of the town. It is recommended to use headphones or earphones to fully appreciate the surround sound experience. Created by COOTS Inc. with music by Alex Cruz, this audio experience is brought to you by the Kusatsu Onsen Tourism Association.' where id = 'jOfxFq-yiSERKaLx8gjQG';
update content_bodies set title = '草津温泉8D立体音響', description = '眠りにつく時やリラックスしたい時、気持ちを上げたい時に最適な音の体験です。温泉の湧き出る音や広大な自然、人々の賑わう街並みを感じることができ、目を瞑ると草津の雰囲気に浸ることができます。草津温泉をイメージしたオリジナルの8D音源をぜひ体感してみてください。8Dオーディオは立体音響で、周囲の全方向から音が聞こえるように設計されています。ヘッドフォンやイヤフォンの使用をおすすめします。' where id = 'rpKsQmThYOF5p787Z0b8j';
update content_bodies set title = 'Kusatsu Onsen Japan in 8D Audio-walking nature-', description = 'This audio experience is designed for various moments such as falling asleep, relaxing, or uplifting your mood. It captures the sounds of hot springs, vast nature, and the lively streets of Kusatsu. By closing your eyes, you can immerse yourself in the atmosphere of Kusatsu Onsen. The original 8D audio source inspired by Kusatsu Onsen is a must-try. 8D audio is engineered to create a three-dimensional sound experience, allowing you to hear sounds from all directions. It is recommended to use headphones or earphones for the best experience.' where id = 'M2V3zSamTqNCeYoZzxpXQ';
update content_bodies set title = 'フェリシダ: 静岡県森町の幸せ', description = 'このショートムービーは、静岡県西部に位置する森町の人々の暮らしを1年間にわたり撮影したものです。美しい自然と伝統を大切にするこの町は「遠州の小京都」と呼ばれています。スペインから大久保集落に移住したフランセスク・プラナスさんのナレーションで、森町三倉地区の人々の生活が描かれています。視聴者に森町を訪れることを勧め、心に響く何かを見つけてほしいというメッセージが込められています。森町ツーリズム研究会が制作し、地域おこし協力隊や地元の協力者が参加しています。' where id = 'cVGwqPlyW9NdjL079BWPw';
update content_bodies set title = 'Felicidad: Happiness in Morimachi, Shizuoka', description = 'This short film showcases the life of the people in Morimachi, a town located in the western part of Shizuoka Prefecture, known for its beautiful nature and rich traditions. Often referred to as ''Little Kyoto of Enshu,'' the film captures a year in the lives of the residents, narrated by Francesc Planas, who moved to the Okubo community in the Mikura district from Spain. The film invites viewers to experience the essence of Morimachi, encouraging them to visit and discover something that resonates with their hearts. Produced by the Morimachi Tourism Research Association and featuring contributions from local organizations, the film highlights the town''s charm and cultural heritage.' where id = 'qXaODUxu7p9aSHE5G2lLM';
update content_bodies set title = '飛騨小坂の自然観光', description = '飛騨小坂は岐阜県の中部に位置する静かな山村で、下呂温泉と飛騨高山の中間にあります。小さな町ながら、活火山の御嶽山の恵みを受けて、3つの異なる温泉と216か所の5m以上の滝を有し、日本一滝の多い町です。春にはハナモモの花を愛でながらのE-Bikeサイクリング、秋には色づく森の中でのカフェ、冬には雪の中でのサウナや氷瀑巡り、夏には渓流釣りやキャンプなど、四季折々のアクティビティが楽しめます。下呂から車で30分、高山から40分と交通の便は良くないため、1泊して訪れることをお勧めします。一度訪れれば、その魅力に病みつきになることでしょう。' where id = '48VlvJgax-q0304flk53T';
update content_bodies set title = 'Nature tourism IN Hida-Osaka', description = 'Hida-Osaka is a tranquil mountain village located in Gifu Prefecture, situated between major tourist destinations such as Gero Onsen and Takayama. Despite its small size, it boasts three different hot springs and is home to 216 waterfalls, making it the town with the most waterfalls in Japan. Visitors can enjoy various activities throughout the year, including E-Bike cycling along the blooming peach trees in spring, relaxing in hammocks at stylish cafes amidst autumn foliage, and winter activities like sauna experiences and ice waterfall trekking. Summer offers a plethora of outdoor activities such as stream fishing, camping, and waterfall exploration. Hida-Osaka is not easily accessible, being a 30-minute drive from Gero and 40 minutes from Takayama, so an overnight stay is recommended to fully enjoy the area. Once you visit, you are sure to become captivated by its charm.' where id = '8JSlSPvYgA0PdzghoJdJj';
update content_bodies set title = '【2泊3日夏の群馬Trip】食べてばかりの大人のリトリート旅。疲れた心を癒すグランピング｜絶景スポット｜四万温泉｜サウナ｜積善館', description = 'この旅行は、心と身体をリセットしたい30代の大人向けに設計されています。グランピングや絶景スポットの訪問、四万温泉でのリラクゼーションなど、多彩な体験が含まれています。旅程には、MOOSKA DE STUBENやふたみみなどの地元の飲食店、カフェのCafé l’Atelier Bleuが含まれています。また、四万湖でのカヌー体験や少林山達磨寺の訪問も紹介されています。InstagramやThreadsなどのプラットフォームを通じて情報が共有されており、視聴者にさらなる旅行情報の購読を促しています。' where id = 'JzpE67xnqcqPu38ibL87R';
update content_bodies set title = '2-Night, 3-Day Summer Trip in Gunma: A Retreat for Adults Filled with Food, Glamping, Scenic Spots, Shima Onsen, Sauna, and Sekizenkan', description = 'This trip is designed for adults in their 30s looking to reset both mind and body. It features a variety of experiences, including glamping, visits to scenic spots, and relaxation at Shima Onsen. The itinerary includes stops at local eateries like MOOSKA DE STUBEN and futamimi, as well as cafes such as Café l’Atelier Bleu. The trip also highlights activities like canoeing at Shima Lake and a visit to Shorinzan Darumaji Temple. The content is shared through various platforms, including Instagram and Threads, encouraging viewers to subscribe for more travel insights.' where id = 'AmjAc5Zs1qBAgItu028hN';
update content_bodies set title = 'BIRD''S EYE3「２６　八ッ場ダム周辺の風景①」｜建設企画課｜群馬県', description = 'この番組は、令和元年９月２８日・２９日に群馬テレビで放映されました。土木施設は私たちの生活に欠かせないものであり、群馬県内には重要文化財や最新技術を駆使した施設が多数存在します。これらの施設の役割や魅力を広く伝え、将来を担う子どもたちに興味を持ってもらうために、県内の土木施設を紹介する番組が制作されました。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。長野原町の八ッ場ダムは、長い建設期間を終えようとしており、今見られる風景を楽しむ最後の時期でもあります。新しく生まれ変わる長野原町の前に、八ッ場ダム周辺の風景をお楽しみください。' where id = 'U8FnOpj48E_lXmEty-nIU';
update content_bodies set title = 'BIRD''S EYE3 ''26 Yamba Dam Surroundings①'' | Construction Planning Division | Gunma Prefecture', description = 'This program aired on Gunma TV on September 28 and 29, 2019. Civil engineering facilities are essential to our lives, and Gunma Prefecture is home to many significant structures, including important cultural properties and those utilizing the latest technology. To convey the roles and attractions of these facilities and spark interest in future generations, a program showcasing civil engineering structures in the prefecture was produced. Utilizing drone footage, the program aims to capture the scale and dynamism unique to these structures. The Yamba Dam in Naganohara Town, Gunma Prefecture, is nearing the end of its long construction period, marking a moment to appreciate the current landscape before it transforms. Enjoy the scenery around Yamba Dam before the changes take place.' where id = 'AgqxAzvlI-oHq6pgXqmf0';
update content_bodies set title = 'BIRD''S EYE3「３１　日本国道最高地点より望む風景」｜建設企画課｜群馬県', description = 'この番組は令和元年11月2日・3日に群馬テレビで放映されました。土木施設は私たちの生活に欠かせないもので、群馬県内には重要文化財や最新技術を駆使した施設が多数存在します。これらの施設の役割や魅力を広く伝え、将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組が制作されました。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。特に、群馬県と長野県の県境近くにある国道292号の最高地点は、標高2,172メートルで、天候によっては雲海を望むことができ、多くの観光客が訪れます。平野部より気温が低いため、外出時には厚めの服装をお勧めします。' where id = 'GD5EE1WCYmhADTUHRMC7H';
update content_bodies set title = 'BIRD''S EYE3: ''31 - The View from the Highest Point of National Route in Japan'' | Construction Planning Division | Gunma Prefecture', description = 'This program aired on Gunma TV on November 2nd and 3rd, 2019. Civil engineering facilities are essential to our lives, and Gunma Prefecture is home to many significant structures, including important cultural properties and those utilizing the latest technology. To promote the roles and attractions of these facilities and spark interest among future generations, a program showcasing civil engineering structures in the prefecture was created. Utilizing drone footage, the program conveys the scale and dynamism unique to these structures. One notable site is the highest point of National Route 292 near the border of Gunma and Nagano Prefectures, located close to the summit of Mount Shirane, at an elevation of 2,172 meters. Visitors can enjoy a view of the sea of clouds depending on the weather, but temperatures are significantly lower than in the plains, so warmer clothing is recommended.' where id = 'gK519l75kfoylOrLWtegC';
update content_bodies set title = 'BIRD''S EYE3「万座三叉路」を望む風景', description = 'この番組は、令和元年11月9日・10日に群馬テレビで放映され、私たちの生活に欠かせない土木施設を紹介しています。群馬県には重要文化財や最新技術を駆使した土木施設が多く存在し、将来に語り継ぐ価値があります。これらの施設の役割や魅力を広く伝え、次世代の子どもたちに興味を持ってもらうことを目的としています。ドローン映像を使用し、土木施設ならではのスケール感やダイナミックさを伝えます。万座三叉路は群馬県吾妻郡嬬恋村にあり、国道292号と県道牧干俣線が交差する地点です。国道292号は長野原町から上越市を結び、県道牧干俣線は高山村から嬬恋村に至ります。また、「浅間・白根・志賀さわやか街道」としても知られ、秋の行楽シーズンにはドライブに最適な場所です。' where id = 'jHs6ILXlqLg6RFAvlqplC';
update content_bodies set title = 'BIRD''S EYE3: A View of ''Manza Sanjaku''', description = 'This program, aired on Gunma TV on November 9 and 10, 2019, highlights the essential civil engineering structures in our lives. Gunma Prefecture is home to numerous civil engineering facilities, including important cultural properties and those utilizing the latest technologies, which hold significant value for future generations. The aim is to widely communicate the roles and attractions of these structures and to spark interest among children who will carry on the legacy. The program features drone footage to convey the scale and dynamism unique to civil engineering. Manza Sanjaku, located in Tsumagoi Village, Agatsuma District, is an intersection where National Route 292 and Prefectural Road Makikamata Line meet. National Route 292 connects Nagano Prefecture''s Nagano Town to Joetsu City in Niigata Prefecture, while the Makikamata Line runs from Takayama Village in Nagano to Tsumagoi Village in Gunma. It is also known as the first scenic road in Kanto, ''Asama, Shirane, and Shiga Refreshing Road,'' making it a popular driving destination, especially during the autumn season.' where id = 'yX2UGOqoygmaJCQ6m2cka';
update content_bodies set title = 'BIRD''S EYE3「３５　越本床固群から望む風景」', description = 'この番組は、令和元年１１月３０日・１２月１日に群馬テレビで放映されました。土木施設は私たちの生活に欠かせないもので、群馬県内には重要文化財や最新技術を用いたものなど、将来に語り継ぐ価値のある施設が多く存在します。これらの役割や魅力を広く伝え、子どもたちに興味を持ってもらうために、県内の土木施設を紹介する番組が制作されました。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを伝えます。片品村の片品川には越本床固群があり、床固は川の流れによる川底や護岸の削れを防ぐ土木施設です。普段は見慣れた構造物ですが、近くで見ると魚道など自然に配慮した工夫が施されています。' where id = 'EYRzRpP_XkNtEPLrkOorE';
update content_bodies set title = 'BIRD''S EYE3: A View from the Koshimoto Toko-gata Group', description = 'This program aired on Gunma TV on November 30 and December 1, 2019. Civil engineering facilities are essential to our daily lives, with many significant cultural properties and modern structures in Gunma Prefecture that are worth preserving for future generations. To promote the roles and attractions of these facilities and spark interest among children, a program showcasing civil engineering structures in the region was produced. Utilizing drone footage, the program conveys the scale and dynamism unique to these structures. The Koshimoto Toko-gata Group, located along the Katashina River in Katashina Village, features a ''toko-gata'' structure designed to prevent erosion of the riverbed and banks. While these structures may seem ordinary in our daily lives, they incorporate thoughtful designs, such as fish passages, to consider the natural environment.' where id = 'HIO3w2442tlsQSqL3sb1P';
update content_bodies set title = 'BIRD''S EYE3「３８　上毛電気鉄道沿線の風景」', description = 'この番組は、令和元年１２月２１日・２２日に群馬テレビで放映されました。群馬県内には、重要文化財や最新技術を用いた土木施設が多く存在し、これらの役割や魅力を広く伝えることを目的としています。ドローン映像を駆使し、土木施設のスケール感やダイナミックさを伝えます。上毛電気鉄道は前橋市と桐生市を結び、車窓からは赤城山の景色が楽しめます。また、自転車を持ち込めるサイクルトレインが特徴で、季節やイベントに応じた飾り付けも行われ、利用者を楽しませています。' where id = 'PssaaVYOc34Ja4qHQr2WF';
update content_bodies set title = 'BIRD''S EYE3: Scenery Along the Jomo Electric Railway', description = 'This program aired on Gunma TV on December 21 and 22, 2019. It highlights the essential civil engineering structures in Gunma Prefecture, including important cultural properties and those utilizing the latest technologies. The aim is to convey the significance and appeal of these structures to the public and inspire interest in future generations. The program features drone footage to showcase the scale and dynamism of these civil engineering works. The Jomo Electric Railway connects Maebashi and Kiryu cities, offering views of Mount Akagi from the train windows. A unique feature of the railway is its ''cycle train,'' which allows passengers to bring bicycles on board. Additionally, the train is decorated according to seasons and events to enhance the experience for users.' where id = 'Tj6G9KmPMuiFZ-rzPrgD6';
update content_bodies set title = 'BIRD''S EYE3「３９　Gメッセ群馬周辺の風景」｜建設企画課｜群馬県', description = 'この番組は、令和２年１月１１日・１２日に群馬テレビで放映され、群馬県内の土木施設の重要性を紹介しています。重要文化財や最新技術を用いた施設など、将来に語り継ぐ価値のある土木施設が数多く存在し、その役割や魅力を広く伝えることを目的としています。ドローン映像を活用し、土木施設ならではのスケール感やダイナミックさを表現しています。2020年の最初の放送では、4月に高崎市にオープンする大型コンベンション施設「Ｇメッセ群馬」を特集。11万㎡の敷地に柱のない大展示場や17の会議スペースを備え、北関東最大の規模を誇ります。約400名の作業員の姿や、12月の建設状況も紹介され、施設の完成後も街の進化が続く様子が描かれています。' where id = 'mUKKp0TLOMuG-pDyCeOUA';
update content_bodies set title = 'BIRD''S EYE3 ''39 Scenery Around G-Messe Gunma'' | Construction Planning Division | Gunma Prefecture', description = 'This program, aired on Gunma TV on January 11 and 12, 2020, highlights the essential civil engineering facilities in Gunma Prefecture. It showcases various structures, including important cultural properties and those utilizing the latest technologies, which hold significant value for future generations. The aim is to communicate the roles and attractions of these facilities and to spark interest among children who will carry on the legacy. Utilizing drone footage, the program captures the scale and dynamism unique to civil engineering. The first broadcast of 2020 features the G-Messe Gunma, a large convention facility opening in April in Takasaki City. Covering 110,000 square meters, it includes a column-free exhibition hall and 17 meeting spaces, making it the largest convention facility in North Kanto. The program also introduces the approximately 400 workers involved in its construction and the progress made by December. The evolution of the city is driven by the efforts of these workers and the future users of the facility.' where id = 'tfghZTirbVqZcjZ868nTk';
update content_bodies set title = 'リトリートカード-Retreat Card- ぐんまで極上の癒やし旅（旅人 井森美幸）｜観光魅力創出課｜群馬県', description = '「リトリート」とは、日常から離れ、疲れた人々に癒やしを与える旅です。ぐんま大使の井森美幸さんが、群馬県という「リトリートの聖地」で、食や自然を通じて極上の癒やし旅を体験します。自分自身と向き合う時間を持つこともリトリートの一環であり、井森さんは自身の芸能生活や群馬県にまつわるエピソードを語ります。あなたも、心と体の赴くままに、群馬県でゆったりとした時間を過ごしてみませんか。' where id = 'YQSUBug0WCr3Skm8oKO7u';
update content_bodies set title = 'Retreat Card - A Luxurious Healing Journey in Gunma (Traveler Miyuki Imori) | Tourism Attraction Development Division | Gunma Prefecture', description = 'The ''Retreat'' is a journey that provides healing for those tired of their daily lives. Miyuki Imori, the Gunma ambassador, experiences a luxurious healing journey in Gunma, known as the ''sacred place of retreat,'' through ''food'' and ''nature.'' Taking time to reflect on oneself is also part of the retreat experience. Imori shares stories from her entertainment career and her hometown of Gunma. You are invited to spend a relaxing time in Gunma, a place where you can cherish yourself and let your heart and body guide you.' where id = 'vpdBUmSz2TnrhQS-50cCC';
update content_bodies set title = 'リトリートカード-Retreat Card- ぐんまで極上の癒やし旅（旅人 中山秀征）｜観光魅力創出課｜群馬県', description = '「リトリート」とは、日常から離れ、疲れた人々に癒やしを与える旅です。ぐんま大使の中山秀征さんが、群馬県という「リトリートの聖地」で、「食」「温泉」「自然」を通じて極上の癒やし旅を体験します。自分自身と向き合う時間を作ることもリトリートの一環であり、中山さんは自身の芸能生活や群馬県にまつわるエピソードを語ります。あなたも、心と体の赴くままに、群馬県でゆったりとした時間を過ごしてみませんか。' where id = 'lA7UoH9aYhkKIdjPT6CJ2';
update content_bodies set title = 'Retreat Card - A Luxurious Healing Journey in Gunma (Traveler Hidetaka Nakayama) | Tourism Attraction Development Division | Gunma Prefecture', description = 'The ''Retreat'' is a journey that provides healing for those tired of their daily lives. Hidetaka Nakayama, a Gunma ambassador, experiences a luxurious healing journey in Gunma, known as the ''sacred place of retreat,'' through ''food,'' ''hot springs,'' and ''nature.'' Taking time to reflect on oneself is also part of the retreat experience. Nakayama shares stories from his entertainment career and his hometown of Gunma. You are invited to spend a relaxing time in Gunma, a place where you can cherish yourself and let your heart and body guide you.' where id = 'apil5Hvq5UyqN-rqF_Q67';
update content_bodies set title = '侍 尺八カバー | 久石譲「Oriental Wind」', description = 'この動画は、プロの尺八演奏家である川村葵山さんが演奏する久石譲の「Oriental Wind」のカバーを特集しています。侍の美学と音楽芸術が融合したこの作品は、尺八の力強い音色を際立たせています。撮影は千葉県で行われ、必要な許可を得て制作されています。プロデューサー兼監督のUKITA光生さんや、撮影助手の中屋和人さん、ロケハン助手のエビさんがこの芸術的なプロジェクトに貢献しています。視聴者は、この独特なミュージックビデオで美しいメロディーと映像を楽しむことができます。' where id = 'i9zSYh2E2crpOLLu48gzx';
update content_bodies set title = 'Oriental Wind cover | Joe Hisaishi | SAMURAI PLAYS BAMBOO FLUTE', description = 'This video features a captivating performance of Joe Hisaishi''s ''Oriental Wind'' played on the shakuhachi, a traditional Japanese bamboo flute, by Kizan Kawamura. The production showcases a unique blend of samurai aesthetics and musical artistry, highlighting the powerful sound of the shakuhachi. The filming took place in Chiba, Japan, with all necessary permissions obtained. The producer, director, and cinematographer KoSEI UKITA, along with videography assistant Kazuto Nakaya and location hunting assistant Ebi, contributed to this artistic endeavor. Viewers are encouraged to enjoy the beautiful melodies and visuals presented in this distinctive music video.' where id = 'FKACWdFP_kT1KsHpZ-vGj';
update content_bodies set title = 'パイレーツオブカリビアン テーマソングカバー | 侍 尺八演奏', description = 'この動画では、侍文化と海賊テーマを融合させた独特なシチュエーションで、川村葵山さんによる尺八のカバー演奏が披露されています。パイレーツオブカリビアンのテーマソングを演奏し、視覚的にも楽しめる作品となっています。プロデューサー兼監督のKoSEI UKITAが制作を手掛け、撮影は千葉県で行われ、現地自治体の許可を得ています。伝統的な和楽器と西洋の人気テーマの融合を楽しむことができる、力強い演奏をぜひご覧ください。' where id = 'sgEe7v4NvcFK52TbY1M45';
update content_bodies set title = 'Pirates of the Caribbean Theme Song cover | SAMURAI PLAYS BAMBOO FLUTE', description = 'This video features a unique cover of the Pirates of the Caribbean theme song performed on the shakuhachi, a traditional Japanese bamboo flute, by Kizan Kawamura. The performance is set against a backdrop that combines elements of samurai culture and pirate themes, creating an intriguing visual experience. The production is directed and produced by KoSEI UKITA, with assistance from Kazuto Nakaya and Ebi for location scouting. The filming took place in Chiba, Japan, with proper permissions obtained. This project showcases the fusion of traditional Japanese music with popular Western themes, inviting viewers to enjoy this powerful and artistic rendition.' where id = 'C-UA6vzYPUXSjCO8L9za5';
update content_bodies set title = 'BMPCC4K + 12-100オリンパスズイコー || 東京の風景 || 手持ち撮影テスト || シネマティック', description = 'この動画は、BMPCC4KカメラとM.ZUIKO DIGITAL ED 12-100mm F4.0 IS PROレンズを使用して東京で行ったテスト撮影を紹介しています。制作者は視聴者がこの映像体験を楽しんでくれることを願い、サポートに感謝の意を表しています。動画にはチャンネル登録やInstagramフォローのリンク、Artlist.ioからの音楽ソースに関する情報が含まれています。また、仕事の問い合わせ用の連絡先や、使用した機材（BMPCC4Kカメラ、レンズ、編集ソフトDavinci Resolve Studio）も記載されています。' where id = 'fSdeeW9LC4ZHM-jZnjZMO';
update content_bodies set title = 'BMPCC4K + 12-100 Olympus Zuiko || TOKYO Landscape || Handheld Shooting Test || Cinematic', description = 'This video showcases a test shoot in Tokyo using the BMPCC4K camera paired with the M.ZUIKO DIGITAL ED 12-100mm F4.0 IS PRO lens. The creator expresses hope that viewers will enjoy the visual experience and appreciates their support. The video includes links for subscribing to the channel, following on Instagram, and information about the music source from Artlist.io. Additionally, it provides contact information for work inquiries and lists the gear used, including the BMPCC4K camera, lens, and editing software, Davinci Resolve Studio.' where id = '8lN0w9Ysw2EDbkU-4wU-t';
update content_bodies set title = '情熱大陸 × 侍 尺八カバー', description = '本作品は、尺八演奏家の川村葵山さんが葉加瀬太郎の「情熱大陸」をカバーした異色のミュージックビデオです。力強い尺八の音色とユニークな映像が融合し、侍の姿で演奏する様子が印象的です。川村さんはYouTubeでも多くの楽曲を披露しており、視聴者は彼の音楽を楽しむことができます。プロデューサー兼監督のKoSEが映像制作を手掛け、千葉県で撮影されました。この作品はメディアにも取り上げられ、その芸術的価値が評価されています。お問い合わせやお仕事の依頼は、提供された連絡先から可能です。' where id = 'BIS_E-0LLlDpq6uuvqAqK';
update content_bodies set title = 'Samurai Bamboo Flute Cover of JONETSU TAIRIKU', description = 'This unique music video features Kizan Kawamura performing a cover of Hakase Taro''s ''JONETSU TAIRIKU'' on the bamboo flute, showcasing the powerful sound of this traditional instrument. The production combines stunning visuals with the captivating performance of the samurai bamboo flute player. Kizan Kawamura regularly shares his music on YouTube, where viewers can explore more of his work. The project was produced and directed by KoSE, who also handled cinematography and editing. The filming took place in Chiba, Japan, and the work has garnered media attention, highlighting its artistic value. For inquiries and collaborations, contact is provided.' where id = 'lU1kaUbwtPLXPeOleZuWU';
update content_bodies set title = 'SONY a7Ⅳ シネマティック4K || サンシャイン水族館 || 池袋東京', description = 'この動画は、東京池袋にあるサンシャイン水族館を紹介しています。ショッピングセンターの上に位置するこの水族館は、子供から大人まで楽しめる素晴らしい場所で、多様な魚や水生哺乳類を観賞できます。新しいSONY a7Ⅳカメラを使って撮影した映像は、テスト撮影のもので、音響効果は使用していません。水族館を楽しみながら編集したこの動画を通じて、訪問者にその魅力を伝えています。水族館の詳細は公式ウェブサイトを訪れて確認し、クリエイターのSNSもフォローしてください。' where id = '44ToMKta42Y6nds4RqbQd';
update content_bodies set title = 'SONY a7Ⅳ Cinematic 4K at Sunshine Aquarium Ikebukuro, Tokyo', description = 'This video showcases the Sunshine Aquarium located in Ikebukuro, Tokyo, which is highly recommended for visitors. Situated atop a shopping center, the aquarium offers a delightful experience for both children and adults, featuring a variety of fish and aquatic mammals. The footage was captured using the new SONY a7Ⅳ camera, serving as a test shoot without any sound effects. The creator enjoyed the aquarium and edited the video to share the experience. For more information about the aquarium, visit their website, and follow the creator on social media for updates.' where id = 'L83KxjZCxD-JRFq7ZQ8cA';
update content_bodies set title = '北海道大沼グレートラン・ウォーク 〝 health beauty power 〟', description = '「北海道大沼グレートラン・ウォーク2024」が2024年10月6日（日）に開催されることが決定しました。2023年10月には、5年ぶりに北海道七飯町大沼で「グレートラン・ウォーク」が開催され、スローガン「健康はhealth、美しくbeauty、力強いpower」が表現されました。この大会の様子はプロモーションビデオとして映像化され、参加者は心と体の健康を実感し、美しい環境でのランニング（ウォーキング）を楽しみました。2024年のエントリーは6月中旬を予定しており、詳細は公式ホームページやSNSで発表されます。' where id = 'f4Bfnj8Mm-3vdCEXvTcrN';
update content_bodies set title = 'Hokkaido Onuma Great Run & Walk ''Health Beauty Power''', description = 'The ''Hokkaido Onuma Great Run & Walk 2024'' is scheduled for October 6, 2024. After a five-year hiatus, the running event in Onuma, Nanae Town, was successfully held in October 2023. The 2023 event showcased the slogan ''Health, Beauty, Power'' through a promotional video, emphasizing the importance of physical and mental well-being. Participants experienced a beautiful and invigorating environment at Onuma National Park, with stunning views of Mount Komagatake and Onuma Lake. The upcoming event will open entries in mid-June 2024, with further details available on the official website and social media.' where id = '5RbWp_0nTRirdWuuUlhii';
update content_bodies set title = 'Drive Ishikari', description = 'この動画は、石狩市、厚田地区、浜益地区のエリア別の映像を紹介しています。観光で石狩を訪れた際に、ついでに立ち寄りたくなるスポットや、帰りに寄ってみたい場所を多数取り上げています。' where id = 'KLa0TztduawxNIpQg1f96';
update content_bodies set title = 'Drive Ishikari', description = 'This video showcases different areas of Ishikari, Atsuta, and Hamamasu. It highlights various spots that visitors can consider stopping by when they come to Ishikari for sightseeing, making it easy to plan a visit or a return trip.' where id = '7jC9xSvhAnq9wvUJFuHGv';
update content_bodies set title = 'Breath of OKINAWA - 沖縄［4K］Long ver.', description = '沖縄県は日本で唯一、全域が亜熱帯地域に属する県です。青い海と空、世界自然遺産の森の深い緑、そして大海原に沈む夕日の茜色など、色鮮やかな魅力に包まれています。この動画は、まだ知られていない沖縄の魅力を発見することを促し、自然の美しさや独特の風景を紹介しています。沖縄本島、渡嘉敷島、石垣島、西表島などの様々な場所で撮影されており、地域の素晴らしい景観と文化的な重要性を強調しています。' where id = 'Qp1SdkiVrvonMMk67uutc';
update content_bodies set title = 'Breath of OKINAWA - 沖縄［4K］Long ver.', description = 'Okinawa is the only prefecture in Japan that is entirely located in the subtropical zone. It is surrounded by vibrant colors, including the blue of the ocean and sky, the deep green of the World Natural Heritage forests, and the rich hues of sunsets over the ocean. This video invites viewers to discover the lesser-known charms of Okinawa, showcasing its natural beauty and unique landscapes. Filmed in various locations such as Okinawa Main Island, Tokashiki Island, Ishigaki Island, and Iriomote Island, it highlights the region''s stunning scenery and cultural significance.' where id = 'hKuD6U8eMuu7EpqZzVW4b';
update content_bodies set title = 'Breath of OKINAWA - 沖縄［4K］ショートバージョン', description = '沖縄県は日本で唯一、全域が亜熱帯地域に属しています。青い海と空、世界自然遺産の森の深い緑、そして大海原に沈む夕日の茜色など、色鮮やかな魅力に包まれています。このショートビデオは、まだ知らない沖縄の魅力を発見することを促しています。' where id = 'ER7nxOZPOj3lZrSxgvTxI';
update content_bodies set title = 'Breath of OKINAWA - Okinawa [4K] Short ver.', description = 'Okinawa is the only prefecture in Japan that is entirely located in the subtropical zone. It is surrounded by vibrant colors, including the blue of the ocean and sky, the deep green of the World Natural Heritage forests, and the rich hues of the sunset over the sea. This short video invites viewers to discover the captivating beauty of Okinawa that they may not yet know.' where id = '7spG5XUwUdllGbYYYtvHh';
update content_bodies set title = '何度でも新しいおきなわ4K（ハイライト）', description = 'この動画は、何度でも新しいおきなわ4Kのハイライトを紹介しています。沖縄の美しい風景や文化を4K映像で楽しむことができ、視聴者に新たな魅力を伝える内容となっています。' where id = 'vlgldzmsVbWqen5LXf7bq';
update content_bodies set title = 'New Okinawa 4K (Highlights)', description = 'This video introduces the highlights of New Okinawa 4K.' where id = 'LbxUlEPGW_sjdbJ87IgOz';
update content_bodies set title = '何度でも新しいおきなわ（アクティブ篇）', description = 'この動画は「何度でも新しいおきなわ（アクティブ篇）」について紹介しています。沖縄のアクティブなライフスタイルや冒険の機会に焦点を当て、様々な側面を紹介しています。' where id = 'okSnYQ4vXlpqP-12wBJMn';
update content_bodies set title = 'Always a New Okinawa (Active Edition)', description = 'This video introduces ''Always a New Okinawa (Active Edition).'' It showcases various aspects of Okinawa, emphasizing its active lifestyle and opportunities for adventure.' where id = 'bj2GKMm2b-bzt5Be4VmBx';
update content_bodies set title = 'アトサヌプリトレッキングツアー', description = 'アトサヌプリトレッキングツアーは、弟子屈町で認定ガイドの同行を条件に行われるトレッキング体験です。アトサヌプリ（硫黄山）でのこのツアーは、自然の美しさを楽しむことができる貴重な機会です。ツアーに参加するには、認定されたガイドが必要です。ツアーの申し込み詳細については、弟子屈なびのウェブサイトをご覧ください。' where id = '0u7kKEmy9pTk38ytVT9Do';
update content_bodies set title = 'Atosanupuri Trekking Tour', description = 'The Atosanupuri Trekking Tour is a guided trekking experience that takes place at Atosanupuri (Sulfur Mountain) in Teshikaga Town. Participation in the tour requires an accredited guide. For more details on how to apply for the tour, please visit the Teshikaga Navi website.' where id = 'XQb6iqP4UGaePSfiaroRr';
update content_bodies set title = '北海道弟子屈町　春夏', description = '北海道弟子屈町の三大観光地である摩周湖、屈斜路湖、硫黄山を紹介するPR動画（春夏バージョン）です。美しい春と夏の風景が楽しめる内容となっています。' where id = 'EQRezHITeot5apUMP2a8P';
update content_bodies set title = 'Hokkaido Teshikaga town spring/summer', description = 'This is a promotional video for the three major tourist attractions in Teshikaga, Hokkaido: Lake Mashu, Lake Kussharo, and Iouzan, showcasing the beauty of the spring and summer seasons.' where id = 'SDzfdRNhjt9GouUJKkFz1';
update content_bodies set title = '飯道山～近畿に誇れる低山～', description = '飯道山は近畿地域において誇り高い低山として知られています。2023年の甲賀映像祭において、甲賀市民部門で水口青年会議所理事長賞を受賞しました。' where id = 'zXxCB8x2_nVPYtZKiOXsj';
update content_bodies set title = 'Iidoyama - A Proud Low Mountain of Kinki', description = 'The Iidoyama mountain is recognized as a notable low mountain in the Kinki region. It has been awarded the Mizuguchi Youth Chamber of Commerce Chairman''s Award at the 2023 Koka Film Festival in the Koka City Citizen Division.' where id = 'AbnCuU4Sn84cPpuOoa-9V';
update content_bodies set title = 'ええとこなんやけどなぁ～15秒ver', description = '甲賀市ロケーション推進協議会が、甲賀市の素晴らしいロケーションを紹介する短い映像です。ロケに関するお手伝いを提供しており、甲南・岩尾山、息障寺、水口・水口城、甲賀・油日神社、信楽・窯元散策路など、さまざまなスポットを強調しています。これらのロケーションの美しさとプロジェクトへの可能性を伝えています。' where id = 'FEiun3EbGIgSouQAaHrBN';
update content_bodies set title = 'It''s a Great Place, You Know? - 15 Seconds Version', description = 'The Koka City Location Promotion Council presents a brief overview of the many wonderful locations in Koka City. They offer assistance for filming and location scouting, highlighting various sites such as Konan Iwao Mountain, Suiguchi Castle, Ayuhiji Shrine, Shigaraki Pottery Walking Path, and more. The council emphasizes the beauty and potential of these locations for various projects.' where id = '_ViSBDm2sKLZRVq8hcJwE';
update content_bodies set title = '【ミッドナイトおおいた】おんせん県の人を知る。おおいたをもっと好きになる。 vol.2 full [公式/大分県]', description = '「ミッドナイトおおいた」は、温泉で知られる大分県の魅力を深く掘り下げるプロジェクトです。夕暮れから深夜にかけて楽しめるスポットを紹介し、初めて訪れる人もリピーターも大分の夜の魅力を体験できるようにしています。ドキュメンタリータッチで、人々や場所、食に焦点を当て、大分の夜を楽しむ人々の生き生きとした声を伝えます。大分の夜がなぜ特別で、観光客が体験すべきなのかを探求し、まだ見ぬ魅力に触れる機会を提供します。' where id = '0N0RBXZM9paWOJYiATf9E';
update content_bodies set title = 'Midnight Oita: Discover the People of the Onsen Prefecture and Fall in Love with Oita More - vol.2 full [Official/Oita Prefecture]', description = 'Midnight Oita highlights the charm of Oita Prefecture, known for its hot springs but offering much more. This initiative showcases the best spots to enjoy from dusk to midnight, inviting both first-time visitors and returning guests to explore the unique allure of Oita''s nightlife. The documentary-style presentation focuses on the people, places, and food that define Oita''s evening atmosphere, capturing the vibrant voices of those who enjoy the night. It emphasizes why Oita''s nightlife is a must-experience for tourists and reveals the untapped charm that awaits both newcomers and those familiar with the region.' where id = 'ShTtoT3Dfte5SX9Fm9Nj7';
update content_bodies set title = '北海道 弟子屈町', description = '北海道弟子屈町の四季を体験できます。' where id = 'r7oGCz0c1O9wB8NK5t2WH';
update content_bodies set title = 'TESHIKAGA HOKKAIDO JAPAN', description = 'Experience the four seasons of Teshikaga Town in Hokkaido, Japan.' where id = 'D0eXpH1_dT5VeR0FukCGw';
update content_bodies set title = '【大分県】おんせん県おおいた観光動画　～由布市：アクティビティver.～', description = '大分県の観光PR動画「由布市：アクティビティ」では、日本一の温泉県である大分県内の18市町村の魅力を紹介しています。具体的には、お箸作り体験や由布院のステンドグラス制作などのアクティビティが取り上げられています。旅行の参考にぜひご覧ください。' where id = 'OyYq9gu1hcCcV98ZaJXiU';
update content_bodies set title = 'Oita Prefecture: Yufu City Activity Tourism Video', description = 'This promotional video showcases activities in Yufu City, part of Oita Prefecture, known as Japan''s top hot spring area. The video highlights experiences such as chopstick-making and stained glass workshops. It serves as a great reference for travelers looking to explore the attractions of Oita Prefecture.' where id = 'hdAORDYhvXUIzLuNUA8OH';
update content_bodies set title = '日本の境港市のツアー', description = '「旅色」ウェブマガジンの特集として、鳥取県に位置する境港市の魅力を紹介しています。この記事では、境港市の観光名所や文化、独自の特徴についての情報が提供されており、読者にこの地域を探索することを促しています。この特集は「Tabiiro FO-CAL」シリーズの一部で、日本のさまざまな旅行先に焦点を当てています。' where id = 'JnMN-ujQDd9ccW488YLYr';
update content_bodies set title = 'A tour of Sakaiminato city in Japan', description = 'This web magazine feature highlights Sakaiminato city, located in Tottori prefecture, Japan. It provides insights into the city''s attractions, culture, and unique characteristics, inviting readers to explore the area. The article is part of the ''Tabiiro FO-CAL'' series, which focuses on various travel destinations in Japan.' where id = '2YxeU1uL_TQJr7NjjEb7r';
update content_bodies set title = '比嘉愛未｜広島・竹原を巡るさんぽ旅 60秒Ver【旅色Movie】', description = '比嘉愛未さんが映画『吟ずる者たち』のロケ地である広島・竹原を巡る旅に出かけます。レトロな街並みを散策し、野生のうさぎに出会う様子を楽しむことができます。まるで一緒に旅をしているかのような気分を味わってください。' where id = 'bExS1simpvqd__q_dj0rl';
update content_bodies set title = 'Manami Higa''s Walking Trip in Takehara, Hiroshima - 60 Seconds Version [Tabiiro Movie]', description = 'Join Manami Higa on a journey through Takehara, Hiroshima, a filming location for the movie ''Ginzuru Monotachi.'' Explore the retro streets and encounter wild rabbits. Enjoy the experience as if you are traveling alongside her.' where id = 'KNIxSmc7tGq6-ALWg09fp';
update content_bodies set title = '大野いと｜島根・大田でノスタルジックジャーニー 【旅色Movie】', description = '大野いとさんと共に、世界遺産の石見銀山や鳴砂で有名な琴ヶ浜などがある島根県大田市を旅します。悠久の歴史を感じることができ、まるでタイムスリップしたかのような不思議な体験が待っています。旅のハイライトには、琴ヶ浜での鳴砂体験、オーシャンビューのチーナカ豆での休憩、仁摩サンドミュージアムの世界最大の砂時計、三瓶山への訪問、さんべ縄文の森ミュージアムでの歴史体験、そして地元の名物である穴子丼の試食が含まれています。最後には、大森の街並みや石見銀山を散策し、旅を締めくくります。' where id = 'r1IZtAFDYiLWwxBGfGIn_';
update content_bodies set title = 'Ono Ito | Nostalgic Journey in Oda, Shimane | Tabiiro Movie', description = 'Join Ono Ito on a nostalgic journey through Oda City in Shimane Prefecture, home to UNESCO World Heritage Site Iwami Ginzan and the famous sound-producing sands of Koto Beach. Experience the rich history of the area, making you feel as if you''ve traveled back in time. Enjoy the journey as if you are traveling alongside her, with highlights including a sand sound experience at Koto Beach, a break with an ocean view at Chinaka Mame, the impressive largest sand clock at the Iwami Sand Museum, a visit to Mount Sanbe in Daisen-Oki National Park, and a taste of the local delicacy, anago-don. The adventure concludes with a stroll through the historic streets of Omori and the Iwami Ginzan area.' where id = 'egmBNG0ZLzlIwtfGqZ4Ku';
update content_bodies set title = '加藤ローサ｜はじまりのまち 日本一のふもと富士市【旅色Movie】', description = '加藤ローサさんが静岡県富士市を訪れ、富士山と駿河湾の絶景を楽しむ旅を紹介します。地元のグルメとして田子の浦しらすや味噌づくりを体験し、市の魅力を伝えます。冨嶽三十六景にも描かれた風景を見に、旅の始まりを感じる内容です。大淵笹場での富士山と茶畑の眺望、佐野製茶所での富士のお茶、岩本山公園でのハイキング、神戸醤油店での味噌づくり、しらすの八幡での新鮮なしらす、ふじのくに田子の浦みなと公園での散策など、見どころが満載です。' where id = 'A9ENWu2oZNosrLi0IvtK_';
update content_bodies set title = 'Kato Rosa | The Town of Beginnings at the Foot of Mount Fuji - Fuji City【Tabiiro Movie】', description = 'In this travel feature, Kato Rosa explores Fuji City in Shizuoka Prefecture, a place where Mount Fuji and Suruga Bay meet. The video showcases not only breathtaking views but also local delicacies such as fresh shirasu (whitebait) and miso-making experiences. The scenery, reminiscent of Hokusai''s ''Thirty-six Views of Mount Fuji,'' invites viewers on a journey to discover the beauty and culture of this remarkable town. Highlights include visiting the Oobuchi Sasaba for stunning views of Mount Fuji and tea fields, enjoying local tea at Sano Tea Shop, hiking at Iwamoto Park, making miso at Kobe Soy Sauce Shop, tasting fresh shirasu at Hachiman, and strolling along Suruga Bay at Tago no Ura Minato Park.' where id = 'Q57xdIaAHUCo-9F9Gu2s8';
update content_bodies set title = '安中市 -四季-', description = '映像をご覧いただきありがとうございます。安中市は群馬県の西部に位置し、西側は長野県軽井沢町と接しています。春、夏、秋、冬の四季をテーマにした映像があり、他にも良い映像がたくさんあるので、ぜひご覧ください。' where id = 'XDBRIbUsn9eqgcMb2tJ4J';
update content_bodies set title = 'Annaka City - The Four Seasons', description = 'Thank you for watching the video. Annaka City is located in the western part of Gunma Prefecture, bordering the town of Karuizawa in Nagano Prefecture to the west. There are many other good videos available, so please take a look at them.' where id = 'LXaz9PDMxsLgMo1ICSzNb';
update content_bodies set title = '伊勢と奈良、神話からの古代の道', description = '伊勢と奈良は、日本の神話と精神性に深く根ざした重要な地域です。伊勢神宮は神道の中心的な聖地であり、日本文化と政治の起源を象徴しています。奈良は、古代の仏教寺院や神社で知られ、8世紀には日本の政治と宗教の中心地でした。この地域には、世界最古の木造建築である法隆寺があり、シカが生息する緑豊かな公園に囲まれています。紀伊半島は、神々が数世紀にわたり崇拝されてきた聖なる山々と古代の杉の森に恵まれています。伊勢神宮は日本の魂の揺りかごと見なされています。また、地域は相撲や酒造りなどの古代の伝統を守り、真珠や海産物を求めて潜る海女文化もその歴史的重要性を高めています。' where id = 'HYenAH-VlmrvuAVByddt5';
update content_bodies set title = 'ISE and NARA, Ancient paths from mythology', description = 'Ise and Nara are significant regions in Japan, deeply rooted in mythology and spirituality. Ise Jingu, a central site of Shintoism, represents the origins of Japanese culture and politics. Nara, known for its ancient Buddhist temples and Shinto shrines, was the political and religious heart of Japan in the 8th century. The area is home to the oldest wooden building, Hōryū-ji, and is surrounded by lush parks inhabited by Sika deer. The Kii Peninsula, rich in sacred mountains and ancient cedar forests, is where kami have been worshipped for centuries. Ise Shrine is considered a cradle of the Japanese soul. The region also preserves ancient traditions like sumo and sake brewing, while the coastal culture of ama women, who dive for pearls and seafood, adds to its historical significance.' where id = 'MuOgyPpLYgODLBL_FMcm9';
update content_bodies set title = '関西再発見の旅！「THE EXCITING KANSAI」丹波編', description = '関西は、日本を代表する世界遺産や悠久の歴史に裏打ちされた伝統・文化が息づく地域です。今回は、京都府と兵庫県にまたがる丹波を訪れ、まだ知られていない魅力を探る旅に出かけませんか。丹波は大自然に囲まれた癒しの世界で、日本の原風景が広がっています。' where id = 'Jl2_EGbOumd5lwIAtqNTd';
update content_bodies set title = 'Discovering Kansai: The Exciting Tamba Edition', description = 'Kansai, a region rich in Japan''s cultural heritage and home to world-renowned UNESCO sites, invites you to explore its lesser-known attractions. This journey takes you to Tamba, an area straddling Kyoto and Hyogo prefectures, where you can experience the serene beauty of Japan''s original landscapes surrounded by nature. Join us for a delightful adventure in this healing world.' where id = 'auKhVO59MAR6zKbWt2V22';
update content_bodies set title = '関西新発見の旅！「THE EXCITING KANSAI」淡路島・徳島編', description = '関西は、日本を代表する世界遺産や悠久の歴史に裏打ちされた伝統・文化が息づく地域です。ここにはまだ知られていない魅力がたくさんあります。今回は、海の恩恵を受けながら共に歴史を育んできた淡路島と徳島を舞台に、オーシャントリップを楽しむ旅をお届けします。' where id = 'WcnklbKUjxrx6y3IbLQY9';
update content_bodies set title = 'Discover Exciting Kansai! Awaji Island and Tokushima Edition', description = 'Kansai, a region rich in Japan''s world heritage and traditional culture backed by a long history, invites you to explore its many hidden charms. This journey focuses on the oceanic trip in Awaji Island and Tokushima, areas that have developed their history alongside the blessings of the sea.' where id = '5fpDw1FfadRT_wNQZzRKx';
update content_bodies set title = '【石川 恋】福井県坂井市へ1泊2日の旅＜旅色＞180秒ver', description = '福井県坂井市は、東尋坊のゴツゴツした岸壁や明智光秀ゆかりの称念寺、市民に愛される丸岡城など多くの見どころがあります。また、冬の味覚である越前がにをはじめとした美味しい料理も楽しめます。石川恋さんがナビゲートする1泊2日の坂井市の旅は、観光スポットを効率よく巡ることができる内容です。' where id = 'PngCC4938nGllMiEDRQIS';
update content_bodies set title = 'A 1-Night, 2-Day Trip to Sakai City, Fukui Prefecture with Ren Ishikawa', description = 'Sakai City in Fukui Prefecture offers a variety of attractions, including the rugged cliffs of Tojinbo overlooking the sea, Shonen-ji Temple associated with Akechi Mitsuhide, and Maruoka Castle, affectionately known as ''Oten-shu'' by locals. Visitors can also enjoy delicious winter delicacies, such as the famous Echizen crab. Ren Ishikawa guides a perfect 1-night, 2-day trip to explore the highlights of Sakai City.' where id = 'x_pEtQg_ffXvWTI1au53K';
update content_bodies set title = 'えになる北九州「映 ～ Shine ～ 」', description = '北九州には「え」になる景色がたくさんあります。「え」がつく5つのキーワードを通じて、特別な風景を素敵な音楽と共に紹介します。4つ目のキーワードは「映 ～ Shine ～」。この「映」は映画の「映」や、映えるという意味の「ばえ」とも読まれます。心惹かれるコントラストや別世界感があり、特に夜の街は絵のように美しいです。さあ、北九州の「映」ワールドの旅に出かけましょう。' where id = '3cy6naKDu_VWnZZ9jXoqS';
update content_bodies set title = 'Kitakyushu''s ''E'' World: Shine', description = 'Kitakyushu is filled with picturesque scenes that embody the essence of ''E''. This presentation highlights five key themes, with the fourth being ''Shine''. The term ''E'' refers to both the concept of film and the idea of beauty, pronounced as ''bae''. The city offers captivating contrasts and an immersive atmosphere, especially at night, making it a visual delight. Join us on a journey through the enchanting ''E'' world of Kitakyushu.' where id = 'H2O1DkQBk5jse4SYkmnHh';
update content_bodies set title = 'ESSENCE OF KITAKYUSHU 15秒CM -風景編-', description = 'この15秒のCMは、北九州の本質を紹介し、その美しい風景を強調しています。詳細なコンテンツは、説明にリンクされた再生リストでご覧いただけます。' where id = 'qeWXuJdAuvfA4KYGvznkf';
update content_bodies set title = 'ESSENCE OF KITAKYUSHU 15-Second CM -Scenery Edition-', description = 'This is a 15-second commercial showcasing the essence of Kitakyushu, highlighting its beautiful landscapes. For more content, you can check the playlist linked in the description.' where id = 'E9kOpirO96JW50BsV3tBz';
update content_bodies set title = 'IT''S LIFE,Travels in IyaValley  ~空から秘境へ~', description = 'ヘリコプターで日本三大秘境の一つ、祖谷へ旅するユニークな体験ができます。世界農業遺産に認定された急傾斜地での農業体験や、古い集落の散策、地域の方と共に作る郷土料理、茅葺き古民家での宿泊などが楽しめます。この旅では、貴重な時間を祖谷の魅力に充て、自然の美しさを体験することができます。祖谷へのヘリコプター旅行に関する詳細は、穴吹トラベルまでお問い合わせください。' where id = 'L8IVrTqcgWu80sN2lIEo7';
update content_bodies set title = 'An exclusive trip to Iya Valley, Japan  ~From the sky to mysterious lands~', description = 'Experience a unique helicopter journey to Iya Valley, one of Japan''s three mysterious lands. Engage in farming on steep hillsides recognized as a World Agricultural Heritage Site, explore hidden hamlets, and prepare traditional dishes with local residents. Stay in a centuries-old thatched-roof house equipped with modern amenities. This trip allows you to maximize your time in the beautiful Iya region, immersing yourself in the charm of the Japanese countryside. For more details about helicopter travel to Iya Valley, please reach out to Anabuki Travel Inbound Division.' where id = '7v_znGnaHnpY7ZQiGdoj8';
update content_bodies set title = '新しい生活様式に対応した観光コンテンツ', description = '新型コロナウィルスの影響により、観光業界は新しい生活様式に適応したコンテンツを提供しています。これにより、旅行者は安全に楽しめる観光体験を得ることができるようになっています。' where id = 'OqE8oGJJ8wNeLzHchqDPI';
update content_bodies set title = 'New Normal Tourism Contents', description = 'This content introduces tourism options that have adapted to the new lifestyle changes brought about by the COVID-19 pandemic.' where id = 'QuaWuVLZJyugTTQftoWwH';
update content_bodies set title = '新型コロナウィルスに対応した観光コンテンツ', description = '新型コロナウィルスの影響により、私たちの生活様式が変化しました。この新しい生活様式に対応した観光コンテンツを紹介します。観光業界は、感染症対策を講じながら、旅行者に安全で快適な体験を提供するために新たな取り組みを行っています。これにより、観光地やアクティビティがどのように変わっているのかを知ることができます。' where id = 'DPftg0Rg5zSpPF2a5-dht';
update content_bodies set title = 'New Normal Tourism Contents', description = 'This content introduces tourism options that have adapted to the new lifestyle changes brought about by the COVID-19 pandemic.' where id = 'oCwyGoMccHXm22zOjzTR4';
update content_bodies set title = '安中市 -夏-', description = '1940年に生まれた蒸気機関車SLぐんまよこかわは、機関士と機関助士のチームワークで運行されており、機関車を「生き物」と表現しています。2024年の夏には、特別運行が予定されており、7月6日、14日、20日、28日、8月にも様々な列車が走ります。また、磯部温泉大花火大会は70年以上の歴史を持ち、8月15日に開催され、16日には仕掛け花火や灯籠流しも行われます。この祭りは地域の寄付によって支えられ、江戸時代からの伝統があります。磯部温泉は美肌の湯として知られ、地域の観光や文化イベントの振興に力を入れています。松井田高校の野球部は地域貢献や持続可能な取り組みを重視し、SNSを通じて活動を発信しています。コロナ禍の影響を受けた地域に明るい気持ちを広げることを目指しています。' where id = 'rVk8YYzb7heEG9KsT27MD';
update content_bodies set title = 'ANNAKA CITY - Summer -', description = 'The steam locomotive SL Gunma Yokokawa, born in 1940, operates with teamwork between the engineer and assistant engineer, who describe the train as a living entity. In summer 2024, various train services will run, including special events on July 6, 14, 20, and 28, as well as in August. The Isobe Onsen Grand Fireworks Festival, a local tradition for over 70 years, will take place on August 15, with additional events on the 16th. The festival is supported by local donations and has a rich history dating back to the Edo period. Isobe Onsen is known for its beautiful hot springs, and the local community actively promotes tourism and cultural events. The Matsuidahigh School baseball team emphasizes community involvement and sustainability, engaging in volunteer activities and promoting their efforts through social media. The aim is to create a positive atmosphere for both residents and visitors, especially in the wake of the COVID-19 pandemic.' where id = 'kglXyA7u29ZiJH_qJBoYZ';
update content_bodies set title = '【安中市 -秋-】', description = '2018年10月14日に始まった碓氷峠のガイド付きウォーキングツアーは、毎年1000名以上が参加する人気のイベントとなり、特に秋の紅葉シーズンが好評です。11月上旬には、夕方5時に軽井沢に到着すると美しい夕陽が見られます。また、中山道の碓氷峠区間でのトレイルランニングも人気で、地元の力餅を楽しみながら歴史的な景色を堪能できます。10月と11月にはELレトロ列車が運行され、鉄道の150周年を祝います。群馬県の運動会では上毛三山をテーマにしたチーム分けが行われ、色鮮やかな競技が展開されます。碓氷湖には遊歩道があり、湖の周りを散策することができます。めがね橋では、煉瓦の色に注目し、橋の力強さを感じることができます。' where id = 'm20Y7vLDauS6vB6yrWnBy';
update content_bodies set title = 'ANNAKA CITY - Autumn -', description = 'The guided walking tour of the Usui Pass, which started on October 14, 2018, has become popular, attracting over 1,000 participants annually, especially during the autumn foliage season in early November. The sunset at 5 PM paints the sky red as visitors arrive in Karuizawa. Trail running has gained popularity along the historic Nakasendo route, where participants can enjoy local snacks and the beautiful scenery. The EL retro train service operates on specific dates in October and November, celebrating the 35th anniversary of the D51 locomotive. The annual sports festival in Gunma features team divisions based on the three mountains of Jomo, with vibrant colors representing each team. Lake Usui, known for its song monument, offers a scenic walking path around the lake. The Usui Third Bridge, a historical railway structure, showcases unique brickwork that emphasizes its strength. Celebrating 150 years of railway history, visitors are encouraged to explore local railways and share memories with family.' where id = 'i6_GsGi12D682cRAzCz24';
update content_bodies set title = '安中市 -冬-', description = '群馬県の安中市は、鉄道のまちとしての歴史的な重要性を持っています。1893年に開通した鉄道は、旅人たちが碓氷峠を越えるための玄関口となりました。1958年に横川駅で初めて販売された「峠の釜めし」は、約1億7000万個が販売されており、陶器の容器に入った温かい弁当として人気です。また、めがね橋という重要な煉瓦アーチ橋や、鉄道の歴史を学べる「碓氷峠廃線ウォーク」もあり、地域の経済発展に寄与した鉄道の重要性を強調しています。さらに、碓氷峠鉄道文化むらでは、家族向けの鉄道テーマパークとして楽しめるアトラクションが用意されています。' where id = 'e0vuNo-7GveuJ1afc41cp';
update content_bodies set title = 'ANNAKA CITY - Winter -', description = 'An overview of Annaka City in Gunma Prefecture, focusing on its historical significance as a railway town. The town became a gateway for travelers crossing the Usui Pass when the railway opened in 1893. The famous ''Toge no Kamameshi'' (a type of railway bento) was first sold at Yokokawa Station in 1958 and has since sold around 170 million units. The dish is served in a ceramic container, inspired by travelers'' desire for warm meals during long journeys. The area also features the Megane Bridge, a significant brick arch bridge, and the Usui Pass Walking Tour, which highlights the historical importance of the railway in Japan''s economic development. Additionally, the Usui Pass Railway Culture Village offers a family-friendly experience with railway-themed attractions.' where id = 'bsrP8hEKnyWDbh-OiRtYf';
update content_bodies set title = '安中市 -春-', description = '安中市の春の観光名所を紹介します。SLぐんまよこかわは、高崎駅140周年を祝う特別運行日があり、4月と5月に運行されます。安中総合学園和太鼓部は2022年に全国高校生太鼓甲子園に出場しました。秋間梅林は群馬三大梅林の一つで、約35,000本の梅が咲き誇り、毎年2月中旬から3月末にかけて梅祭りが開催されます。後閑城址公園では、桜まつり花火大会が2024年3月31日に行われ、春の夜空に花火が打ち上げられます。妙義山は独特な岩石群があり、登山や紅葉狩りに訪れる人々に人気です。横川ナイトパークではナイトミュージアムが開催され、特別な列車サービスも提供され、地域の文化体験が充実しています。' where id = 'kmz_96AMu7Jbu4Y-FTzTR';
update content_bodies set title = 'ANNAKA CITY - Spring -', description = 'An overview of attractions in Annaka City during spring, including the SL Gunma Yokokawa train service celebrating the 140th anniversary of Takasaki Station with special operation dates in April and May. The Annaka Sogo High School Taiko Club participated in the National High School Taiko Championship in 2022. The Akima Plum Grove, one of Gunma''s top three plum groves, features around 35,000 plum trees and hosts a festival from mid-February to the end of March. Visitors can enjoy local food from nearby stalls. The park at the site of the historic Gokan Castle offers scenic views, especially during the cherry blossom festival on March 31, 2024. The unique rock formations of Mount Myogi attract many visitors for hiking and autumn foliage. The Yokokawa Night Park features a night museum and special train services, enhancing the cultural experience of the area.' where id = '7UE5391SjLUNmVfXo8unP';
update content_bodies set title = '【2020年 新緑】碓氷峠廃線ウォーク', description = '碓氷峠廃線ウォークは群馬県と長野県の県境に位置する碓氷峠で行われます。1893年にアプト式鉄道が開業し、1963年に新線が開通しましたが、1997年に横川から軽井沢間の11.2kmが廃線となりました。現在もトンネルや線路は当時のまま残っています。2020年5月13日に撮影された新緑の映像は4K対応の高画質です。このウォークは「安中ヘルメットプロジェクト」を支援しており、子どもたちに防災ヘルメットを届ける活動を行っています。「ANNAKA CITY Tシャツ」の販売利益は、安中の子どもたちに還元されます。映像には「アナカルチア」イベントのライブ音源が使用されています。コロナウイルスが終息したら、安中市の観光地を訪れることをお勧めします。' where id = 't_t29yDE9maJb7pQOk93p';
update content_bodies set title = '2020 Fresh Green: Usui Pass Abandoned Line Walk', description = 'The Usui Pass Abandoned Line Walk takes place at the Usui Pass, which separates Gunma and Nagano Prefectures. The Abt-style railway opened in 1893 and was replaced by a new line in 1963. The section between Yokokawa and Karuizawa was abandoned in 1997, and the tracks and tunnels remain intact after being transferred to Matsuidamachi. This video, filmed on May 13, 2020, showcases the fresh greenery of Usui Pass in high-quality 4K. The walk supports the Annaka Helmet Project, which aims to enhance disaster awareness among children in Annaka by providing helmets. Profits from the sale of ''ANNAKA CITY T-shirts'' will be used to provide disaster helmets for local children. The video features live audio from the ''Anakalkia'' event organized by the ''Anaka Association.'' Visitors are encouraged to explore Annaka City’s attractions once the COVID-19 pandemic is over.' where id = '94xGe1YrY1jonqSrXxxvx';
update content_bodies set title = '喜びの島 | 喜界島', description = '喜界島は鹿児島から南に約380km、奄美大島の東25kmに位置する美しいサンゴ礁の島です。青い海と緑豊かな大地が織りなす自然環境が魅力で、島の文化やゆったりとした時間、優しい島民との出会いが訪れる人々に喜びをもたらします。喜界島は年間平均2mmずつ隆起し続ける貴重な島で、サトウキビ畑が広がり、黒糖や黒糖焼酎が特産品として知られています。また、国内最大の白ゴマの産地でもあります。名所には奄美十景の一つである百之台公園、美しいスギラビーチやハワイビーチ、古いサンゴの石垣などがあり、近年はダイビングスポットとしても注目されています。' where id = 'hzZdZGSZut6bwDdnS5vyy';
update content_bodies set title = 'Island of Smiles [Kikai Island, Japan]', description = 'Kikai Island, located approximately 380 km south of Kagoshima and 25 km east of Amami Oshima, is a beautiful coral island known for its stunning natural environment. The island features a rich landscape where the blue sea meets lush green land, creating a vibrant ecosystem. Visitors can experience the island''s unique culture, relaxed pace of life, and warm interactions with the friendly locals, making for a joyful travel experience. Kikai Island is scientifically significant as it continues to rise at an average rate of 2 mm per year. The island is famous for its sugarcane fields, producing local specialties such as brown sugar and brown sugar shochu, and is also the largest producer of white sesame in Japan. Notable attractions include Hyakunodai Park, Sugirabeach, Hawaii Beach, and ancient coral stone walls, with the island gaining popularity as a diving destination in recent years.' where id = 'y-E9ls9tC2FfUDyCWmUGu';
update content_bodies set title = '未だ見ぬ世界（ふくい）へ【地味にすごい、福井動画コンテスト入賞作品】', description = '本作品は、「地味にすごい、福井」をテーマにした福井県の動画コンテストの入賞作品です。福井市の映像制作会社セブンディを運営する今城晃治と高島千枝の二人が制作しました。2016年からYouTubeに福井の普通の景色をテーマにした動画をアップしており、福井の素晴らしさを考えました。福井の魅力は、観光地だけでなく、日常の風景にも溢れています。動画では、観光地と共に、隠れた美しい景色を紹介し、視聴者に自分だけの特別な景色を見つけに福井に来てほしいというメッセージを込めています。タイトルには、雲海に隠れた福井の景色を見つめ直し、未だ見ぬ世界を探求してほしいという思いが込められています。動画は4Kで制作され、美しい福井を再現するために苦労しました。' where id = '-BWZm7z0HYd1grh18D6wX';
update content_bodies set title = 'The Unseen World (Fukui) - Award-winning Work of the ''Subtly Amazing Fukui'' Video Contest', description = 'This work is an award-winning entry in a video contest organized by Fukui Prefecture, themed ''Subtly Amazing Fukui.'' The creators, Koji Imajo and Chie Takashima, run a video production company called Seven D in Fukui City. Since 2016, they have been uploading videos on YouTube that showcase the ordinary yet beautiful landscapes of Fukui. They reflect on what makes Fukui amazing, emphasizing its breathtaking scenery and nature, which remain constant despite changing times. The video combines well-known tourist spots with hidden gems, encouraging viewers to discover their own special places in Fukui. The title suggests a desire for viewers to look beyond the foggy landscapes and explore the unseen beauty of Fukui. The video is produced in 4K, showcasing the creators'' efforts to capture the beauty of Fukui.' where id = '29SK9QMOmlF6zXbWHv5bR';
update content_bodies set title = '熱唱！崖っぷち東尋坊ツアー！！', description = 'イタリア出身のダニエラと南アフリカ出身のプリスカが、福井県の日本海にある絶壁「東尋坊」を訪れました。彼女たちはショッピングや食べ歩きに夢中になり、無事に東尋坊にたどり着けるのかが気になります。東尋坊は柱状節理で知られる絶壁で、プリスカが思わずしたことも話題に。きっとこの体験は他の人にも真似したくなることでしょう。現在はコロナウイルスの影響で県外への旅行が難しいですが、状況が落ち着いた際にはぜひ福井を訪れてほしいです。' where id = 'kK04XcspUBrT4IQYb0uZj';
update content_bodies set title = 'Singing! The Cliff-Edge Tojinbo Tour!!', description = 'Daniella from Italy and Priska from South Africa visit Tojinbo, a famous cliff on the Sea of Japan in Fukui Prefecture. They quickly get caught up in shopping and street food, raising the question of whether they will reach Tojinbo safely. Known for its unique columnar jointing, Priska does something unexpected at the cliff. This experience is sure to inspire others to try it as well. Although travel and tourism outside the prefecture are currently challenging due to the COVID-19 pandemic, visitors are encouraged to come to Fukui when the situation stabilizes.' where id = 'QEOtXKhee0o0ncd60g8ot';
update content_bodies set title = '目と胃袋が幸せに！癒しと香ばしの若狭旅', description = 'イタリア出身のダニエラと南アフリカ出身のプリスカが絶景のデートスポットを訪れ、ダニエラはその美しさに「パラダイス」とつぶやきます。二人は理想の相手についても語り合い、260年の伝統を誇る「浜焼き鯖」を楽しみます。この旅は目とお腹を満たす満足のひとときです。現在、コロナウイルスの影響で県外への旅行が難しい状況ですが、落ち着いた際にはぜひ福井を訪れてほしいと呼びかけています。次回は、二人があわら温泉で遊ぶ様子をお届けします！' where id = 'J1OxM_bnXap6PuJDToB8K';
update content_bodies set title = 'A Happy Journey for the Eyes and Stomach! A Healing and Fragrant Trip to Wakasa', description = 'Daniella from Italy and Priska from South Africa visit a breathtaking date spot! Daniella whispers ''paradise'' upon seeing the stunning view. The two friends also share their ideal partners while enjoying delicious ''Hama-yaki saba,'' a traditional grilled mackerel with a 260-year history. This trip satisfies both their eyes and appetites. Although travel and tourism outside the prefecture are currently challenging due to the COVID-19 pandemic, they encourage everyone to visit Fukui when things settle down. Stay tuned for the next episode where the two beauties enjoy a fun time at Awara Onsen!' where id = 'TTHi3jLbC0kael7UIJNv8';
update content_bodies set title = '白熱！！めがね競技世界大会 開幕', description = 'めがねミュージアムで、モクタールとハンターが「めがね競技世界大会」で各国を代表して対決します。鯖江市では、めがねフレームのシェアが95%以上を占める中、「めがね競技」というユニークな競技が存在します。参加者たちはすぐにユニフォームに着替え、本気で挑みます。「メガネダッシュ」では、モクタールがやる気を出しすぎてトラブルが発生。ハンデをもらったハンターは、金メガネリストに勝てるのでしょうか？次回のエピソード「Japanese Katanaみたいな料理包丁を作ろう！」もお楽しみに！' where id = 'J8KiOrkzUcnLdOGWAnp5u';
update content_bodies set title = 'Intense!! Opening of the Glasses Competition World Championship', description = 'At the Glasses Museum, Mokutaru and Hunter are going head-to-head representing their countries in the ''Glasses Competition World Championship.'' In Sabae City, where over 95% of glasses frames are produced, there exists a unique competition called ''Glasses Competition.'' The participants quickly change into their uniforms and get serious about the event! During the ''Glasses Dash,'' Mokutaru gets overly enthusiastic, leading to some trouble. Can Hunter, with a handicap, defeat the Gold Glasses List champion? Stay tuned for the next episode titled ''Let''s Make a Japanese Katana-like Cooking Knife!''' where id = 'xPOV2ysMeczEHGtXS5bx6';
update content_bodies set title = '【15秒CM】【武商吹部 ver.】福井県民下手ラップ『きてみね～の！』', description = '福井県立武生商業・武生商工高等学校吹奏楽部が登場するミュージックビデオ「下手ラップ」は、福井県の魅力を歌ってPRしています。この吹奏楽部は、全国大会に7回出場した実績を持ち、「日本一ファンキーなバンド」として注目されています。彼らのパフォーマンスは躍動感にあふれ、印象的な「ふっく〜い　きてみね〜の！」のメロディーで視聴者を楽しませます。現在はコロナウイルスの影響で旅行が難しいですが、落ち着いた際にはぜひ福井を訪れてほしいというメッセージも込められています。' where id = '9HtVlD7agj1FTGyfpBrE7';
update content_bodies set title = '15-Second Commercial: Fukui Prefecture''s Local Rap ''Kitemine-no!'' by Takefu Commercial High School Brass Band', description = 'This music video features the Takefu Commercial and Takefu Shoko High School Brass Band, known for their vibrant performances and as a representative of Hokuriku with seven national competition appearances. They promote the charm of Fukui Prefecture through a catchy local rap, ''Kitemine-no!'', which is memorable and encourages viewers to sing and dance along. The video highlights the band''s unique style, referred to as ''the funkiest band in Japan.'' Despite current travel restrictions due to COVID-19, the message invites everyone to visit Fukui when the situation improves.' where id = 'hldBeUZW_7fF8NtsdP3fC';
update content_bodies set title = '釧路、阿寒、摩周、川湯の自然と共生する - 手付かずの北海道 2023 -', description = '手付かずの北海道は、釧路湿原、阿寒湖、摩周湖を含む東北海道の地域で、素晴らしい自然美を誇ります。先住民族アイヌの人々は、自然のすべてに神（カムイ）が宿ると信じ、土地とその資源との深い結びつきを育んできました。この地域は、希少なブレキストン魚フクロウを含む多様な生物が生息しており、冬にはタンチョウやオジロワシを観察することができます。手付かずの北海道は、古代から自然と調和して保存されてきた場所であり、北アメリカプレートに位置することで独特の植生と動物相が形成されています。' where id = 'bbYEs7DbnPpbvapsYMtFi';
update content_bodies set title = 'Co-existing with nature in Kushiro, Akan, Mashu and Kawayu(short ver.) -Untouched HOKKAIDO 2023-', description = 'Untouched Hokkaido is a region in East Hokkaido, home to the Kushiro Shitsugen Wetland, Lake Akan, and Lake Mashu, showcasing stunning natural beauty. The indigenous Ainu people believe that deities, known as Kamuy, inhabit all elements of nature, fostering a deep connection with the land and its resources. This area is rich in biodiversity, including rare species like the Blakiston''s fish owl, and offers opportunities to observe red-crowned cranes and Steller''s sea eagles in winter. Untouched Hokkaido represents a harmonious coexistence with nature, preserved since ancient times, and is characterized by its unique flora and fauna, shaped by its geographical location on the North American Plate.' where id = 'AmKZi_FdxPG0BSYiRTTwz';
update content_bodies set title = '釧路川源流クルーズ・鏡の間', description = '屈斜路湖から流れ出る唯一の川、釧路川は釧路湿原へとつながり、最終的には海へ流れ出ます。その脇に位置する「鏡の間」は、透明度の高い湧き水から成る神秘的なスポットです。水温は四季を通じて10度以下で、触れるとひんやりとした感触があります。釧路川とは異なる清涼な空気、鏡面の水面、そして豊かな緑が広がり、訪れる者を魅了する空間となっています。' where id = 'RPx2o9kFgi4bib8zdvEHc';
update content_bodies set title = 'Kagami no Ma Cruise in the Headwaters of the Kushiro River', description = 'The Kushiro River is the only river flowing from Lake Kussharo, connecting to the Kushiro Shitsugen Wetland before reaching the sea. Nearby lies a magical place known as Kagami no Ma, or ''mirror room,'' named for its remarkably clear spring water. The water temperature remains below 10°C year-round, providing a refreshing experience. This area offers a stark contrast to the Kushiro River, featuring cool air, crystal-clear water, and lush greenery, making Kagami no Ma a captivating destination for visitors.' where id = '8qv8MiaRDVgFsQaOlnmla';
update content_bodies set title = '阿寒湖・阿寒川フィッシング', description = 'マリモの生息で有名な阿寒湖には、手つかずの自然の姿がそのまま残る。阿寒湖はネイティブトラウトの宝庫で、多くのアングラーのあこがれの地であり、フライフィッシングやルアーフィッシングの聖地とも呼ばれる。5月1日の解禁日から秋にかけては、釣り三昧の休日を過ごせるベストシーズンで、初心者でもニジマス・アメマス・ヒメマス釣りを楽しむことができる。2003年に北海道で初めてキャッチ＆リリースが規則化され、阿寒川湖流出口から雄観橋下流端はキャッチ＆リリースエリアに設定されている。遊漁料1日1,500円が必要で、事前支払いが求められる。' where id = 'z3eXRQ7OrT8FqF1cx32ES';
update content_bodies set title = 'Fishing in Lake Akan and the Akan River', description = 'Lake Akan is renowned for its marimo moss balls and pristine natural surroundings. It is home to a variety of native trout species, making it a popular destination for both fly fishing and lure fishing enthusiasts. Fishing is prohibited until April 30 each year to protect the fish population, but from May 1 to autumn, it becomes a paradise for anglers. Beginners can easily catch rainbow trout, Japanese char, and kokanee in Lake Akan. Notably, the area from the mouth of the Akan River at Lake Akan to the Yukan Bridge is designated as a catch-and-release zone, the first of its kind in Hokkaido, established in 2003. A recreational fishing fee of JPY 1,500 per day is required and must be paid in advance.' where id = 'lqzy295LBUFozlrYaOVnR';
update content_bodies set title = 'Untouched Hokkaido ダイジェスト（夏）', description = '東北海道は、日本でありながら北米プレートに位置するため、珍しい植生が広がるユニークな地域です。この土地には希少な野生生物が生息し、地元の人々が長年守り続けてきた自然が残されています。これが『Untouched Hokkaido』の概念です。地域は豊かな清流でつながり、日本の特別天然記念物である美しいタンチョウが住んでいます。北海道の先住民族アイヌの言葉で、タンチョウは『サロルンカムイ』と呼ばれ、湿原に住む神を意味します。水は生命を育み、さまざまな形に変化し、魔法のような環境を作り出しています。' where id = '-1CH0bO17g-EjfyNEXBpz';
update content_bodies set title = 'Untouched Hokkaido Digest (Summer)', description = 'Eastern Hokkaido is a unique region in Japan, located on the North American tectonic plate, resulting in a diverse range of rare plant species. This area is home to many rare wildlife and is protected by local communities who have preserved its natural beauty for generations, embodying the concept of ''Untouched Hokkaido.'' The region is interconnected by rich, clear streams and is inhabited by the elegant and beautiful Japanese crane, a special natural monument. In the Ainu language, the crane is referred to as ''Sarorunkamui,'' meaning ''god of the wetlands.'' Water plays a vital role in nurturing life and transforms into various forms, creating a magical environment.' where id = 'ETdyT3HpdC_HUPJK3VtUg';
update content_bodies set title = '硫黄山', description = '硫黄山は川湯温泉から約3kmの場所に位置し、アイヌ語で「アトサヌプリ」と呼ばれています。硫黄の独特な香りと、通常より低い標高で育つ高山植物が特徴で、まるで別の惑星のような景観を呈しています。現在も山の各所から硫黄の噴煙が上がり、轟音が響いています。かつては大規模な硫黄採掘が行われ、テシカガ町の発展に寄与しました。現在、落石の危険があるため、硫黄山は一般公開されていません。東北海道は北アメリカの地殻プレート上に位置し、非常に珍しい植物が生息しています。この地域の住民は、国立公園内の野生動物と共存し、手つかずの自然が多く残されています。' where id = 'y-lh8Lo6LCOov4iyU5MYr';
update content_bodies set title = 'Mt. Io: Untouched Hokkaido', description = 'Mt. Io, located near Kawayu Hot Springs, is a unique geological site characterized by sulfur emissions and unusual alpine vegetation. Known as Atosa-nupuri in Ainu, the mountain features a distinct sulfur smell and a rumbling sound from its active geothermal activity. Historically, it was a site for large-scale sulfur mining, contributing to the development of Teshikaga Town. Currently, Mt. Io is closed to the public due to safety concerns regarding falling rocks. Eastern Hokkaido, where Mt. Io is situated, is on the North American tectonic plate, leading to a rich diversity of rare plant life and wildlife. The region remains largely untouched by human activity, preserving its natural beauty.' where id = 'tUS0FT6kBOvlp6dc7856F';
update content_bodies set title = '富山｜TOYAMA SUMMER MOVIE 4K', description = 'この夏の映画は、日本の富山の美しい風景と観光名所を紹介しています。見どころには、壮大な黒部峡谷や称名滝、風光明媚な黒部峡谷トロッコ、そしてリラックスできる足湯があります。立山地域を探索し、弥陀ヶ原や象徴的な黒部ダムを訪れることができます。また、9月1日から3日まで開催されるおわら風の盆祭りなどの文化イベントも特集されています。他にも、みくりが池、室堂、黒部平、伝統的な合掌造りの五箇山集落などが登場します。映画は、国宝瑞龍寺や鈴木忠志・SCOTの芸術的な貢献にも敬意を表しています。' where id = 'SQ2osOIq0bblozfmpNAxB';
update content_bodies set title = 'Toyama | TOYAMA SUMMER MOVIE 4K', description = 'This summer movie showcases the stunning landscapes and attractions of Toyama, Japan. Highlights include the majestic Kurobe Gorge and Shomyo Falls, the scenic Kurobe Gorge Railway, and relaxing footbaths. Visitors can explore the Tateyama region, including Midagahara and the iconic Kurobe Dam. The film also features cultural events like the Owara Kazenobon festival, held from September 1st to 3rd. Other notable locations include Mikurigaike, Murodo, and Kurobedaira, as well as the historic Gokayama village with its traditional Gassho-style houses. The film pays homage to the National Treasure Zuiryu-ji Temple and the artistic contributions of Suzuki Tadashi and the Suzuki Company of Toga.' where id = 'vS_-1MgSmXjUxHD6rL8NW';
update content_bodies set title = '富山｜TOYAMA AUTUMN MOVIE 4K', description = 'この映像は、富山の美しい秋の風景を紹介しています。黒部、称名滝、黒部峡谷トロッコ、黒薙温泉、立山、弥陀ヶ原、みくりが池、黒部ダム、室堂、雷鳥荘、黒部平、そして五箇山の相倉合掌造り集落など、さまざまな観光名所が登場します。秋の季節におけるこれらの場所の美しさを捉え、鮮やかな色彩と静かな風景を強調しています。また、富山の著名なレストラン「レヴォ」や、いなみの瑞泉寺についても言及されています。' where id = '061XFvyIOz6RgAXcmrAkJ';
update content_bodies set title = 'Toyama | TOYAMA AUTUMN MOVIE 4K', description = 'This video showcases the stunning autumn scenery of Toyama, featuring various attractions such as Kurobe, Shomyo Falls, Kurobe Gorge Railway, Kuronagi Hot Spring, Tateyama, Midagahara, Mikurigaike, Kurobe Dam, Murodo, Raichoso, Kurobedaira, and the Gokayama Historic Village of Gassho style Houses. The film captures the beauty of these locations during the fall season, highlighting the vibrant colors and serene landscapes. Additionally, it includes a mention of L’évo by Eiji Taniguchi, a notable restaurant in Toyama, and Inamibetsuin Zuisenji, a temple in Inami.' where id = 'SndQWnWEULfKD52DKhzyi';
update content_bodies set title = '立山黒部｜TOYAMA SPRING MOVIE 4K', description = 'この映像は、立山黒部地域のさまざまな美しいスポットを紹介しています。伊織橋、立山、黒部平、黒部ダム、室堂、雷鳥荘、みくりが池、立山黒部アルペンルート、称名滝などが登場し、それぞれの場所の自然の美しさや特徴が強調されています。' where id = 'B-baaeQOYno9yXF938A6D';
update content_bodies set title = 'Tateyama Kurobe | TOYAMA SPRING MOVIE 4K', description = 'The video showcases various scenic locations in the Tateyama Kurobe area, including Iori Bridge, Tateyama, Kurobedaira, Kurobe Dam, Murodo, Raichoso, Mikurigaike, the Tateyama Kurobe Alpine Route, and Shomyodaki. Each site highlights the natural beauty and unique features of this stunning region.' where id = 'MjSSdyNyviVEWcl6h-_dq';
update content_bodies set title = '宇和島', description = 'この動画は宇和島について紹介しています。' where id = '1us8zSj7_kHGqclSuApfe';
update content_bodies set title = 'Uwajima', description = 'This video introduces Uwajima.' where id = 'Y3hnMgMtByn5-qq2dgpnx';
update content_bodies set title = '富山｜TOYAMA WINTER MOVIE 4K', description = 'このプロモーション動画は、富山の冬の魅力をまとめたものです。撮影ロケ地には、雨晴海岸から見える立山連峰（朝日）、呉羽山公園からの立山連峰、立山山麓スキー場、立山博物館、越中八尾ベースOYATSU（八尾）、氷見漁港、ホテル延楽が含まれています。' where id = 'jE657Fg4CF2LEBr_ON0Og';
update content_bodies set title = 'Toyama | TOYAMA WINTER MOVIE 4K', description = 'This promotional video showcases the winter attractions of Toyama. Filming locations include the Tateyama Mountain Range viewed from Amanohashidate Coast (Asahi), the Tateyama Mountain Range from Kureha Park, Tateyama Ski Resort, Tateyama Museum, OYATSU in Yatsuo, Himi Fishing Port, and Hotel Enraku.' where id = 'L3q7ZB5SmFhAxKhD-2DrJ';
update content_bodies set title = 'あなたとしまねを結ぶ旅「むすぶらり」', description = '地元ガイドと共に、しまねの魅力を感じながらぶらりと歩いてみませんか？現在、ウェブサイトオープンキャンペーンを実施中で、対象期間は平成30年4月1日から11月30日までです。詳細はhttp://www.kankou-shimane.com/musuburari/をご覧ください。「むすぶらり」では、地域を知り尽くした地元ガイドが案内し、定時ガイドのため予約は不要です。また、観光地の魅力が詰まったコースが用意されています。' where id = 'vn2YDDwfhAmC9zkchCdso';
update content_bodies set title = 'Your Journey Connecting with Shimane: Musuburari', description = 'Experience the charm of Shimane by strolling with local guides! A web campaign is currently underway from April 1, 2018, to November 30, 2018. For more details, visit http://www.kankou-shimane.com/musuburari/. Musuburari features knowledgeable local guides who know the area well, no reservations are needed for scheduled tours, and the courses are packed with the attractions of the sightseeing spots.' where id = 'tMTVYYCXCIlbTdp6xi1l6';
update content_bodies set title = '油門全踩之坡！', description = '島根の絶景を紹介する。美しい日本の精神と原風景が広がる場所で、車を魔爪のように掴む急な橋があり、ドライバーはアクセルを全開にすることを促される。' where id = 'Ia4y8f6Nr2P9PEJFIYUQq';
update content_bodies set title = 'The Steep Slope of Full Throttle!', description = 'A breathtaking view in Shimane, showcasing the beauty of Japan''s spirit and its natural landscapes. The steep bridge, gripping the car like a claw, invites drivers to push the accelerator to the limit.' where id = 'KTWai7lAb9UQpfH7i9oxD';
update content_bodies set title = '日刀保踏鞴', description = '日刀保踏鞴は、日本の古代の制鉄技術を象徴しており、島根県の美しい風景を強調しています。「悠悠扶桑景 楚楚大和心」というフレーズは、静かな風景と日本の深い文化的本質を表現しています。' where id = 'eHE2xuSreYckVt8Icuf9u';
update content_bodies set title = 'Nihon Tōhō', description = 'Nihon Tōhō is a representation of Japan''s ancient iron-making tradition, highlighting the beauty of Shimane Prefecture. The phrase ''悠悠扶桑景 楚楚大和心'' reflects the serene landscapes and the deep cultural essence of Japan.' where id = 'FdCVnxlrZB4jx-lhhWI30';
update content_bodies set title = '道 - 南紀熊野における私の人生の旅', description = '海外から南紀熊野に移住して20年が経った著者は、地元の人々の信仰に今なお神秘を感じています。彼は地域の滝や石、木、島々を訪れる旅に出かけ、これらが何世代にもわたって人々に崇拝されてきたことを学びます。ある日、地元の祭りに参加し、この地域の真の信仰を実感することで、南紀熊野の文化や精神性への理解を深めます。' where id = 'Ll6wlyT_Q7cT97uMUjyzo';
update content_bodies set title = 'The Path - My Journey of Life in Nanki Kumano', description = 'After living in Nanki Kumano for twenty years, the author still finds the local people''s faith to be a mystery. He embarks on a journey to explore the area''s waterfalls, stones, trees, and islands, discovering that these natural elements have been revered by the community for generations. During a local festival, he gains insight into the true essence of the area''s faith, deepening his understanding of the culture and spirituality that permeates Nanki Kumano.' where id = 'KD2VQlJ7KrRoGA4x1MvQw';
update content_bodies set title = 'ジオサイト鳴石', description = '南紀熊野ジオパークに位置するジオサイト「鳴石」を紹介する映像です。ジオパークの詳細については、公式ウェブサイト（http://nankikumanogeo.jp/）をご覧ください。' where id = 'eqiikv2vKMn6SZW4_QsPc';
update content_bodies set title = 'Naruishi Geosite', description = 'This is an introductory video about the Naruishi geosite, part of the Nanki Kumano Geopark.' where id = 'Sn5y5FODIhYjjGwMJW6di';
update content_bodies set title = '十日町雪まつり', description = '十日町雪まつりは、豪雪地帯である十日町で開催される冬の一大イベントです。「雪を友とし、雪を楽しむ」という地元住民の想いから生まれました。市内のあちこちに設置された「おまつりひろば」でのイベントやおもてなし、市民の手による芸術的な雪像、そして雪で作られたステージで繰り広げられる「雪上カーニバル」など、多彩な催しが行われ、真冬の十日町を華やかに彩ります。' where id = 'Jf9_c3ByP8N8-8xABmar8';
update content_bodies set title = 'TOKAMACHI SNOW FESTIVAL', description = 'The Tokamachi Snow Festival is a major winter event in Tokamachi, a region known for its heavy snowfall. It originated from the local residents'' enthusiasm for enjoying snow as a friend. The festival features various events and entertainment, including festival fields set up throughout the city, artistic snow sculptures created by citizens, and a ''Snow Carnival'' showcasing performances on a magnificent snow stage. This celebration transforms Tokamachi into a vibrant winter wonderland.' where id = 'RnZ1v4T6wxdg3uDsnawXS';
update content_bodies set title = '雪とある日のとおかまち -long ver.-', description = 'この動画では、雪の日の十日町市を紹介しており、清津峡や美人林、信濃川などの観光スポットが取り上げられています。' where id = 'bAHePwc3Bgp-3TsmBrMiw';
update content_bodies set title = 'One snowy day in Tokamachi -long ver.-', description = 'This video introduces Tokamachi on a snowy day, highlighting various tourist spots such as Kiyotsukyo, Bijinbayashi, and the Shinano River.' where id = 'POKHhxDm0ilHWgeagouxm';
update content_bodies set title = '第１回新潟ふるさとCM大賞　十日町市CM作品', description = '第１回新潟ふるさとCM大賞に応募した十日町市の作品「＃あちこたねーよ！」は、太古の昔から受け継がれてきた十日町市の生活文化や里山の自然を30秒に凝縮し、雪国の魅力を伝えています。この大賞は、UX新潟テレビ21、新潟県、新潟県市町村振興協会が主催し、各市町村が地元愛あふれるCMを制作することで地域の一体化を図り、県内外への発信を通じて地域活性化を目指す事業です。応募作品の審査は令和2年11月19日に行われました。' where id = 'tivx252dzocvTtYXKSOxU';
update content_bodies set title = 'First Niigata Furusato CM Award - Tokamachi City CM Work', description = 'The CM work titled ''#Achikotaneyo!'' from Tokamachi City was submitted for the First Niigata Furusato CM Award. This 30-second video encapsulates the charm of the snow country, showcasing the living culture and natural beauty of the Satoyama region that has been passed down since ancient times. The Niigata Furusato CM Award is an initiative organized by UX Niigata Television 21, Niigata Prefecture, and the Niigata Prefectural Municipal Promotion Association. It aims to foster local community spirit through the production of heartfelt CMs by various municipalities in Niigata Prefecture and to revitalize the region through promotion both within and outside the prefecture. The judging for the submitted CM works took place on November 19, 2020.' where id = 'zsvVRs1Kbv72xHkNu8pPs';
update content_bodies set title = '願入集落 canvas 1 | 布施知子【越後妻有 この大地の里山は キャンバスになり 祭りがはじまる。】', description = '越後妻有地域は新潟県十日町市と津南町から成り、2000年から「大地の芸術祭」が開催されています。この祭りは、地域の人々の生活や四季折々の自然の豊かさを表現する場です。この映像作品は、地域をキャンバスとして捉え、そこで暮らす人々や自然、文化の魅力を再認識することを目的としています。地域の暮らしを主役にしたドキュメンタリーであり、祭りに訪れるアーティストたちが地域の魅力に触発される様子を描いています。監督は分部康仁、クリエーティブディレクターは引地央行、企画・プロデュースは酒井隆光が担当しています。人間と自然の関係性を探ることが、この地域の基本理念となっています。' where id = 'nAjNVouvs7hCE52jIzoCx';
update content_bodies set title = 'Negai Iri Settlement Canvas 1 | Tomoko Fuse [Echigo-Tsumari: This Land''s Satoyama Becomes a Canvas and the Festival Begins.]', description = 'The Echigo-Tsumari region, encompassing Tokamachi City and Tsunan Town in Niigata Prefecture, has hosted the "Echigo-Tsumari Art Triennale" since 2000. This festival showcases the lives of local residents and the rich natural environment throughout the seasons. The video work captures the region as a canvas, highlighting the charm of its people, nature, and culture. It serves as a documentary focusing on the local lifestyle, inspired by the artists who visit during the festival. Directed by Yasuhito Bunbe, with creative direction by Hiroyuki Hikichi, and produced by Takamitsu Sakai, the project aims to explore the relationship between humans and nature, reflecting the region''s philosophy that humans are inherently connected to nature.' where id = 'pF_1XMPciT9Y6d03SF-dY';
update content_bodies set title = 'そらにみつ あをによし -奈良観光 夏-', description = 'この映像は、奈良の観光をPRする自主制作のプロモーションビデオで、英語と繁体字の字幕が追加されています。シルクロードの終着点である奈良の旅を通じて、京都の華やかさとは異なる古都の魅力を探ります。若草山や鷺池、平城宮跡、東大寺などの名所を訪れ、地元の文化や奈良燈花会なども紹介されています。音楽にはチャイコフスキーの『くるみ割り人形』からの抜粋が使用されています。' where id = '7zKXdykO5P0jvWZGNNLSX';
update content_bodies set title = 'Glimpses of NARA, Japan', description = 'This is a self-produced promotional video for tourism in Nara, Japan, featuring English and Traditional Chinese subtitles. The film explores Nara, the final destination of the Silk Road, highlighting its unique charm that contrasts with the splendor of Kyoto. The journey includes various locations such as Mt. Wakakusa, Ukimido Gazebo, Heijo Palace Site, Todai-ji Temple, and more. The film also showcases local culture, including traditional sweets and the Nara To-Kae lantern festival. The music is an excerpt from Tchaikovsky''s ''The Nutcracker Suite.''' where id = '4dF8V-16L2AdY2s8KhbBq';
update content_bodies set title = '東北のまつりと文化・観光の魅力', description = 'この文章では、東北を代表する6つの祭り、すなわち「青森ねぶた祭」「秋田竿燈まつり」「盛岡さんさ踊り」「山形花笠まつり」「仙台七夕まつり」「福島わらじまつり」を紹介しています。さらに、東北の豊かな歴史や文化、絶景、そして食の魅力についても触れています。撮影地に関する情報は字幕でも提供されており、東北が持つ多彩な魅力を伝えています。' where id = 'odHvXQks62SGuS8ENa8K-';
update content_bodies set title = 'Festivals and Cultural Attractions of Tohoku', description = 'This text introduces six representative festivals of Tohoku: the Aomori Nebuta Festival, Akita Kanto Festival, Morioka Sansa Odori, Yamagata Hanagasa Festival, Sendai Tanabata Festival, and Fukushima Waraji Festival. It highlights the region''s rich history and culture, as well as its stunning landscapes and culinary delights. Information about shooting locations is also provided in subtitles, showcasing the diverse attractions that Tohoku has to offer.' where id = 'wuWPQzAbwYLAHg2lnkb0u';
update content_bodies set title = '自然を味わい、自然を愉しむ。', description = '奈良県十津川村に移住したジョラン氏のドキュメンタリー作品です。彼の自然環境との関わりや体験を捉えています。' where id = 'ADe_pRh8hd3LxjONqnEm9';
update content_bodies set title = 'Savoring and Enjoying Nature', description = 'This documentary features Mr. Jolan, who has relocated to Totsukawa Village in Nara Prefecture. It captures his experiences and interactions with the natural environment.' where id = 'UXcfF_kK1yS5REDNyZhGH';
update content_bodies set title = '北山村のVR体験', description = '紀伊半島に位置する秘境の飛び地村、和歌山県の北山村。初めて、筏師の目線で体験できる北山川の観光筏下り（イカダ下り）のVR映像が登場しました。360°の視点から、この秘境の美しい風景や、じゃばらの香りが漂う収穫の様子を楽しむことができます。まるでその場にいるかのような没入感を味わえます。本編は日本語、英語、中国語（繁体字）で視聴可能です。' where id = 'o6bL67IrRpj0O26bntVB_';
update content_bodies set title = 'VR experience for the enclave village Kitayama, WAKAYAMA', description = 'Kitayama Village, located in the Kii Peninsula, is a hidden enclave. For the first time, a VR experience of Ikada-Kudari, the Kitayama River Log Rafting, is presented from the unique perspective of an Ikada-shi, or raft master, offering a fully immersive 360° view. Viewers can enjoy the stunning scenery of this secluded village, including its beautiful landscapes and the refreshing aroma of the Jabara harvest, making it feel as if they are truly there. The full video is available in Japanese, English, and Traditional Chinese on this channel.' where id = '14xLnqaplMjXmwHmTvxm-';
update content_bodies set title = '【360°VR 全方位檢視】北山川観光木筏漂流', description = '【HMD視聴年齢制限：10歳以上】一般的な画面でも360度の視点で楽しめます。水しぶきや壮大な北山峡谷の岩壁、伝統技術で木筏を操る熟練の筏師の迫力あるシーンを体感できます。没入型VRを通じて、日本唯一の原木木筏漂流である北山川観光木筏漂流を体験し、まるで自分が筏に乗って激流を駆け抜けているかのような感覚を味わえます。この貴重な北山村の木筏文化は国内外で高く評価されており、壮麗な吉野熊野国立公園の自然景観と結びついています。ぜひ一緒にこの体験を楽しんでください。運営期間：5月3日～9月30日。' where id = 'j-5gojwTX5iJmElpnk0L8';
update content_bodies set title = '360° VR All-Around View: Kitayama River Rafting', description = 'Experience the splashing water, the magnificent cliffs of the Kitayama Gorge, and the stunning scenes of skilled rafters maneuvering traditional wooden rafts. With immersive VR, you can enjoy Japan''s only log rafting experience on the Kitayama River, making you feel as if you are riding the rapids yourself. This unique Kitayama village rafting culture is highly regarded both domestically and internationally, combined with the breathtaking natural scenery of Yoshino-Kumano National Park. Join us to appreciate and experience this adventure. Operating period: May 3 to September 30.' where id = 'iGfnF4PzVtmlCC2woxhcJ';
update content_bodies set title = '【360°VR 全方位檢視】北山村VR影片', description = '紀伊半島の深山に位置する北山村は、日本唯一の飛地村であり、小さくも驚きに満ちた隠れた秘境です。ここでは、刺激的な北山川の観光木筏漂流を体験でき、伝統的な原木筏に乗って流れ下ることができます。また、北山村は珍しい柑橘「じゃばら」の原産地であり、世間から隔絶された壮大な自然景観を有しています。没入型VRを通じて、日本の山間の静けさの美しさに浸り、大自然に癒される瞬間を感じることができます。' where id = 'c6-0I0Iy5jubpQI9dnyWe';
update content_bodies set title = '360° VR All-Around View: North Mountain Village VR Video', description = 'Located deep in the mountains of the Kii Peninsula, North Mountain Village is Japan''s only exclave village, a small yet surprising hidden gem. Here, you can experience the thrilling North Mountain River rafting, riding traditional wooden rafts downstream. Additionally, North Mountain Village is the birthplace of the rare citrus fruit ''Jabara'' and boasts magnificent natural scenery that feels isolated from the world. Through immersive VR, you can indulge in the tranquil beauty of Japan''s mountains and feel your spirit gently healed by nature.' where id = 'sXJJxSYp3h4iYouonJulw';
update content_bodies set title = '楽園へ続く船路 （鹿児島-奄美-沖縄航路）', description = '奄美の島々を巡るフェリーの旅は、単なる夢ではなく、実際に体験する冒険です。この公式サイトでは、奄美の美しい島々を探索し、地元の人々の文化や生活様式に触れることができます。この旅を通じて、忘れられない思い出や物語を作り、帰宅後にそれを共有することができるでしょう。このプロジェクトは、奄美群島航空・航路運賃軽減協議会や鹿児島県旅客船協会などのさまざまな団体の支援を受けており、地元のフェリー会社の協力も得ています。' where id = 'w-YwimliB3q7QczPn8epK';
update content_bodies set title = 'Ferry Journey to Paradise (Kagoshima-Amami-Okinawa Route)', description = 'The journey to the Amami Islands by ferry is not just a dream; it’s an adventure waiting to be experienced. This official site invites you to explore the beautiful islands of Amami, where you can see, touch, and feel the unique culture and lifestyle of the local people. By embarking on this journey, you will create unforgettable memories and stories to share upon your return. The project is supported by various organizations, including the Amami Islands Aviation and Ferry Fare Reduction Council and the Kagoshima Prefectural Passenger Ship Association, with cooperation from local ferry companies.' where id = 'p7SataZcx__EANVAzvgXz';
update content_bodies set title = 'こんな田舎なのに魅力たっぷりえびの市。知らなかった人損してますよ。', description = 'こんにちは！宮崎県えびの市観光商工課のPR担当、みなほです。えびの市をご存知ですか？この町は高いポテンシャルを持ちながら、知名度が上がらずにいます。観光地や美しい景色、特産品があるにもかかわらず、あまり知られていません。そこで、みなほはこの町の魅力を伝えるために動画配信を始めます。新型コロナウイルスの影響でアウトドア人気が高まる中、えびの高原キャンプ村が地元で盛り上がりました。えびの高原はキャンプやトレッキングに最適な場所で、四季折々の景色に囲まれたアウトドアアクティビティは非日常感にあふれ、ストレス解消に最適です。この動画を見て少しでも魅力を感じた方、えびの市はいつでも皆さんをお迎えする準備ができています。ぜひお越しください！' where id = 'XifZ6hghebGxhAdXEyccC';
update content_bodies set title = 'Ebino City: A Hidden Gem in the Countryside', description = 'Hello! I''m Minaho from the PR department of the Ebino City Tourism and Commerce Division in Miyazaki Prefecture. Are you familiar with Ebino City? Despite its high potential, this town struggles with low recognition. It boasts beautiful landscapes, tourist attractions, and local specialties that remain largely unknown. To raise awareness, I am starting a video series to showcase the town''s charm, which traditional information dissemination fails to convey in today''s world. During the COVID-19 pandemic, outdoor activities gained popularity, and the Ebino Kogen Camp Village became a local favorite. The Ebino Kogen area is perfect for camping and trekking, surrounded by seasonal beauty, offering a unique outdoor experience that serves as an excellent stress reliever. If you feel even a little intrigued by this video, Ebino City is always ready to welcome you! Please come visit us!' where id = 'fxxhKP17SLX8V1v4yaOL3';
update content_bodies set title = '山陰海岸', description = '日本の中国地方では、古くから中国山地の北側を山陰（山の陰）、南側を山陽（山の陽）と呼んできました。この地名の付け方は、古代中国の思想に基づいており、山の北と南を陰と陽、川の北と南を陽と陰で表現しています。北半球では、南天に太陽が昇るため、山の北側は影になり、南側は日が当たります。また、中国の川では、北と南で陰陽が表現される地域もあります。山陰地方の海岸は日本海に面しており、大陸から吹く風によって生じる荒波によって形成された美しい景観を楽しむことができます。' where id = 'H94iwdoQicRISvBSHejrz';
update content_bodies set title = 'Sanin Coast', description = 'In the Chugoku region of Japan, the area north of the Chugoku Mountains is known as Sanin (mountain’s yin), while the south is referred to as Sanyo (mountain’s yang). This naming convention is rooted in ancient Chinese philosophy, where the north and south of mountains are represented by yin and yang, respectively. In the northern hemisphere, the sun rises in the southern sky, casting shadows on the northern slopes of mountains. Similarly, rivers in China are described using yin and yang based on their northern and southern banks. The San''in coast, facing the Sea of Japan, is characterized by its scenic beauty shaped by the rough waves generated by continental winds. Visitors can enjoy the picturesque landscapes of this coastal region.' where id = 'Q39j5cK-t_zhvIBgLUhbX';
update content_bodies set title = 'JAPAN 山陰山陽 Praying Playing', description = '『国際平和都市』広島から発信する山陰山陽地域のダイジェストです。厳島、出雲、瀬戸内、中国地方の人々や文化、伝統、美しい自然、平和への祈り、神々への祈りを紹介しています。現在の姿をまとめた内容となっています。この作品は、登録者数が1000人に達したことへの感謝の気持ちを込めて制作されました。' where id = '28_iiB_Th0oetFYL33AGc';
update content_bodies set title = 'JAPAN Sanin Sanyo Praying Playing', description = 'This is a digest of the Sanin Sanyo region, including Itsukushima, Izumo, Setouchi, and the Chugoku area, originating from Hiroshima, known as the ''International Peace City.'' It highlights the local people, culture, traditions, beautiful nature, and prayers for peace and the gods. The content summarizes the current state of these regions. This work was created with gratitude for reaching 1,000 registrations.' where id = 'hXhK93zqjPxsdnl-0L-_f';
update content_bodies set title = '島根県 石見國 一宮 物部神社', description = '物部神社は、古代豪族物部氏の初代である宇摩志麻遅命を祀っています。宇摩志麻遅命は邇芸速日命の子であり、神武天皇の東征の際に長髄彦を討ち、物部氏を率いて皇城を守護したとされています。創建から1500年以上の歴史を持ち、本殿は出雲大社に次ぐ大きさで、春日造りの壮大な神殿です。御神紋である『ひおい鶴』は、宇摩志麻遅命が鶴に乗って降臨したという伝説に基づいており、日本唯一の御神紋とされています。' where id = 'Y43VK9ans2-swhrvERCZH';
update content_bodies set title = 'Ichinomiya Iwami Province Mononobe Shrine', description = 'The shrine is dedicated to Umashimaji no Mikoto, the founder of the ancient powerful Mononobe clan. He is the son of Nigihayahi no Mikoto and is known for defeating Nagasunehiko during Emperor Jimmu''s eastern expedition. Following this, he led the Mononobe clan in protecting the imperial castle. With a history spanning over 1500 years, the main shrine is the second largest in Japan, following Izumo Taisha, and features a grand structure built in the Kasuga style. The shrine''s crest, known as the ''Hioi Crane,'' is unique in Japan and is based on the legend of Umashimaji no Mikoto descending on a crane.' where id = 'RQMG7lYWv0ql7srzG51rE';
update content_bodies set title = 'VR 真冬の飛騨 雪の道 TEST.ver', description = '真冬の飛騨高山では、昼間でも氷点下に達する雪と氷の世界を体験できます。このVR体験では、雪と氷に覆われた冬の風景に没入することができます。' where id = 'RO8Hvnid7bW_AL4oUkKqQ';
update content_bodies set title = 'VR Midwinter HIDA - Snowy Road TEST.ver', description = 'Experience the world of snow and ice in Hida Takayama during midwinter, where temperatures drop below freezing even during the day. This VR experience immerses you in a winter landscape filled with snow and ice.' where id = 'nQbtkfDenTf6x2Yn-3eJ7';
update content_bodies set title = 'ココロに響く、岡山アートトリップ【full ver.】', description = '岡山県北部の奈義町は、注目のアートエリアです。体感型現代美術館「奈義町現代美術館（Nagi MOCA）」や秀峰・那岐山の美しい自然がアートとして楽しめます。訪れる人々は、自然の中で心を解放し、五感を刺激する出会いを体験しています。この美術館は、SNSでの映えが話題となり、全国的に注目を集めています。美術館の他にも、カフェ併設のギャラリーや企画展を行う観光案内所など、アートに関連するスポットが増えています。美術館は、建築家・磯崎新氏によるもので、3つの展示室があり、作品と建物が一体化しています。また、本格的なナポリピッツァを楽しめる「PIZZERIA La gita」や、シンプルなカフェ「cafe calme」もあります。自然を楽しむなら、40ｍの屋敷の滝や、900年以上の樹齢を誇るイチョウの木がある菩提寺もおすすめです。アートな旅を岡山で楽しんでください！' where id = 'Z5iqXIetfBfrdz0EMI6DU';
update content_bodies set title = 'Art Trip in Okayama that Resonates with the Heart [full ver.]', description = 'Nagi Town in northern Okayama Prefecture is an emerging art area. The pioneering experiential contemporary art museum, Nagi MOCA, along with the stunning natural landscapes created by the majestic Mt. Nagi, offers a unique artistic experience. Visitors can immerse themselves in nature, stimulating their senses and discovering new encounters. The Nagi MOCA has gained national attention for its photogenic qualities, attracting more visitors who make it their travel destination. In addition to the museum, there are art-related spots like a gallery café and a tourist information center hosting exhibitions. The museum, designed by Pritzker Prize-winning architect Arata Isozaki, features three exhibition rooms named ''Sun,'' ''Moon,'' and ''Earth,'' integrating art and architecture. Other attractions include PIZZERIA La gita, offering authentic Neapolitan pizza, and the serene cafe calme. Nature lovers can explore the 40-meter high Yashiki Falls and the ancient ginkgo tree at Bodai-ji Temple, a national natural monument. Plan your art-filled trip to Okayama!' where id = 'N60XkDiiNr8rBagpHgPQa';
update content_bodies set title = 'タイムラプス「時空の旅おかやま」', description = '岡山県内の観光地や美しい風景を新たな技術で短時間に凝縮し、迫力ある感動的な映像に仕上げました。この映像は、岡山の魅力を新しい視点から体験できる機会を提供します。岡山の観光情報は、公式ウェブサイトで確認できます。' where id = '36FMG7aBS0H9njVkNDEA9';
update content_bodies set title = 'Timelapse Okayama "The Landscapes of OKAYAMA beyond Time and Space"', description = 'This video showcases the stunning tourist spots and beautiful landscapes of Okayama Prefecture, condensed into a powerful and moving clip using new technology.' where id = 'pssyjcjM02qihp2OBqNGx';
update content_bodies set title = '西遊紀行 – 西日本を発見する', description = 'このタイトルは、西日本、特に岡山を探求することに焦点を当てています。ハッシュタグは、西日本の観光や文化体験を促進するキャンペーンやイニシアティブを示しており、人々にこの地域の独自の側面を発見することを奨励しています。' where id = 'DB8sujbAi6Y8FjMnrtnf4';
update content_bodies set title = 'Discovering West Japan - A Journey Through Okayama', description = 'The title suggests a focus on exploring the western region of Japan, specifically Okayama. The hashtags indicate a campaign or initiative aimed at promoting tourism and cultural experiences in West Japan, encouraging people to discover the unique aspects of this area.' where id = 'IK5EF7HktyG26uFZd1FLP';
update content_bodies set title = 'タイムラプス「瀬戸内時間」', description = 'この映像は、瀬戸内海の美しい風景を紹介しており、特に朝日や夕日の美しさを捉えています。潮の満ち干によって海上に現れる道や、島々の間を行き交うフェリーの様子を、タイムラプス映像と通常の映像で表現しています。時間の流れを凝縮した映像は、この地域の自然の美しさとダイナミックな環境を独自の視点で捉えています。' where id = 'm8ulTj96lkfBTJExDtoCm';
update content_bodies set title = 'The Passing of Time in Setouchi', description = 'This video showcases the stunning landscapes of the Seto Inland Sea, capturing the beauty of dawn and dusk. It features time-lapse footage that highlights the paths that emerge in the sea due to the ebb and flow of tides, as well as the movement of ferries traveling between islands. The combination of time-lapse and regular video provides a unique perspective on the natural beauty and dynamic environment of this region.' where id = 'Rta4h9NXbrKYXyZ5YraRo';
update content_bodies set title = '岡山後楽園•岡山城の四季2015', description = '日本三名園の一つで、ミシュラン・グリーンガイド・ジャポンで三つ星を獲得した「岡山後楽園」と、日本100名城の一つである「岡山城」の四季折々の美しい風景を、タイムラプス映像で楽しむことができます。' where id = '53hzF-Cdkm2aWgUW1SBzv';
update content_bodies set title = 'The Four Seasons of Okayama Kourakuen Garden and Okayama Castle', description = 'Enjoy the beautiful time-lapse scenery of each season at Okayama Kourakuen Garden, one of Japan''s Three Great Gardens and a recipient of a three-star rating in the Michelin Green Guide Japan, as well as Okayama Castle, one of Japan''s 100 famous castles.' where id = 'P-Z8wTaAoIp35V5Qg2qXd';
update content_bodies set title = '最高のおいしいを求めて　岡山グルメ旅', description = '岡山では、瀬戸内海の新鮮な魚介類や地元のブランド肉、旬の果物、老舗の銘菓、郷土料理など、豊かなグルメ体験が楽しめます。岡山の旅の思い出は、これらのおいしい記憶と共にあります。真庭市の割烹旅館や、備前市の日生カキオコ、岡山市のすし拓、倉敷市のくらしき桃子など、様々な名店が紹介されています。' where id = 'zprAzEWfmz71VuElVAFiB';
update content_bodies set title = 'Seeking the Best Deliciousness: Okayama Gourmet Trip', description = 'Okayama offers a delightful culinary experience with fresh seafood from the Seto Inland Sea, locally renowned brand meats, seasonal fruits, traditional sweets from long-established shops, and regional dishes. Memories of traveling in Okayama are intertwined with delicious experiences.' where id = 'WAQ9lCZfMX5-tk-Vk16__';
update content_bodies set title = 'タイムラプスおかやま「鬼ノ城」', description = '鬼ノ城は、温羅伝説の舞台とも言われる古代ロマンに満ちた山城の遺跡です。城壁に沿った2.8kmのハイキングコースからの眺望は素晴らしく、訪れる人々に感動を与えます。' where id = 'i2zGn5IwaKTeUTR32n0g5';
update content_bodies set title = 'Timelapse Okayama ''Kinojo Castle''', description = 'Kinojo Castle is a mountain castle ruin rich in ancient romance, believed to be the setting of the Ura legend. The 2.8km hiking course that encircles the castle walls offers an unparalleled view.' where id = 'CGK9PetuPWHU_KMPsMNaQ';
update content_bodies set title = 'タイムラプスおかやま「水島コンビナート」', description = '水島コンビナートは国内屈指の工業地帯であり、瀬戸内海を背景にした美しい夕景や、宝石のように輝く夜景が魅力です。最近では、産業観光やクルージングが人気を集めています。' where id = 'ZBopXttdB0Zrr__JSZslT';
update content_bodies set title = 'Timelapse Okayama "Mizushima Industrial Area"', description = 'The Mizushima Industrial Complex is one of Japan''s leading industrial districts, renowned for its stunning evening views set against the backdrop of the Seto Inland Sea, as well as its nightscape that sparkles like jewels. Recently, it has gained popularity for industrial tourism and cruising activities.' where id = 'lZtaAvRimC8jvlyis7_Cp';
update content_bodies set title = 'タイムラプスおかやま 「倉敷美観地区・鷲羽山」', description = '倉敷美観地区は、川沿いに立ち並ぶ白壁の土蔵やなまこ壁が特徴のレトロな街並みで、日本の歴史的な建築を感じられる場所です。また、鷲羽山からは瀬戸大橋や美しい瀬戸内海の多島美を一望でき、特に「日本の夕陽百選」にも選ばれた絶景スポットとして知られています。' where id = 'IMrk2HQ78QxjnL2fSXcX0';
update content_bodies set title = 'Time Lapse Okayama "Kurashiki Bikan Historical Quarter / Mt. Washu"', description = 'The Kurashiki Bikan Historical Quarter features a traditional townscape characterized by white-walled warehouses and namako walls along the riverside. It is a picturesque area that showcases Japan''s historical architecture. Additionally, Mt. Washuzan offers breathtaking views of the Seto Ohashi Bridge and the stunning islands of the Seto Inland Sea, recognized as one of Japan''s top sunset spots.' where id = 'W99oC2HvjRcSdd0sAfriy';
update content_bodies set title = 'タイムラプスおかやま 「岡山後楽園」', description = '岡山後楽園は日本三名園の一つであり、江戸時代を代表する回遊式の大名庭園です。四季折々の花木を楽しむことができ、訪れる人々にとって自然の美しさを堪能できる素晴らしい場所となっています。観光客や自然愛好者にとって魅力的な目的地です。' where id = 'ILoaXg_Wym1h2e-plLYoK';
update content_bodies set title = 'Time Lapse Okayama "Okayama Kourakuen Garden"', description = 'Okayama Kourakuen Garden is one of the Three Great Gardens of Japan, showcasing a circuit-style design typical of the Edo period. Visitors can enjoy a variety of blossoming trees throughout the seasons, making it a beautiful destination for nature lovers and tourists alike.' where id = 'C_PwbOvw6E1xo6P1kdTro';
update content_bodies set title = 'タイムラプスおかやま 「蒜山高原」', description = '蒜山高原は、西日本有数のリゾート地であり、雄大な蒜山三座の前に広がるのどかな高原が特徴です。この地域は、日本一のジャージー牛の酪農地帯としても知られています。' where id = '_JPWKeiZ5GcqXF5gZ0gE3';
update content_bodies set title = 'Time Lapse Okayama "Hiruzen Plateau"', description = 'Hiruzen Plateau is one of the premier resort areas in western Japan, featuring serene highlands that lie beneath the impressive three peaks of Mt. Hiruzen. This region is also recognized as Japan''s top Jersey cow dairy area.' where id = 'RxHGFO8gbhwML_GZIuJ27';
update content_bodies set title = 'タイムラプスおかやま 「旧閑谷学校」', description = '旧閑谷学校は、日本最古の庶民教育の学校として知られています。国宝に指定されている講堂は、備前焼の屋根瓦が使われており、その美しい建築が特徴です。また、近くにある楷の木は、特に秋の紅葉が美しいことで有名です。' where id = 'TvtbayNrH2FwuTYJu08eb';
update content_bodies set title = 'Time Lapse Okayama "The Shizutani School"', description = 'The Shizutani School is Japan''s oldest existing school for the common people. It is renowned for its auditorium, which is a national treasure featuring a roof made of Bizen ceramics. Additionally, the school is famous for the beautiful autumn colors of the nearby Chinese Pistache Tree.' where id = 'rPe1KKvzKslK6qmhsgDe8';
update content_bodies set title = '岡山｜日本 - 岡山の冬のイルミネーションをチェックしよう', description = 'この記事では、岡山の冬のイルミネーションを紹介します。西川運河公園では、無数の光が星のように輝き、まるで星空の下を旅しているかのような雰囲気を楽しむことができます。また、岡山森林公園ドイツの森では、エリアごとに異なるイルミネーションを楽しむことができ、視覚的な体験が多様です。岡山には他にも美しいイルミネーションを楽しめる場所がたくさんあり、これらの華やかな展示を探索することをお勧めします。' where id = 'VRqLepdHhW7hH7d2VJB4i';
update content_bodies set title = 'Okayama, Japan - Check out the best Okayama Winter Illuminations', description = 'This article introduces the stunning winter illuminations in Okayama, highlighting Nishigawa Canal Park, where countless lights create a starry atmosphere, making visitors feel as if they are walking under a night sky. Additionally, the Okayama Forest Park German Forest offers unique illuminations in different areas, providing a diverse visual experience. There are many other locations in Okayama where visitors can enjoy beautiful illuminations, encouraging exploration of these festive displays.' where id = '1y6m8jkJsj4T4ulkSuxty';
update content_bodies set title = '瀬戸内国際芸術祭 2019（SETOUCHI TRIENNALE） in 宇野港周辺【総集編】', description = '瀬戸内国際芸術祭2019では、宇野港周辺で春・夏・秋の各シーズンにわたり、さまざまな作品やイベントが展示されました。オープニングイベントは2019年4月27日に行われ、山地真美氏のピアノ演奏や市内高校吹奏楽部との合同演奏が行われました。春の会期（4月26日～5月26日）では、ラ・マル・ド・ボァでの「nomad note dance」やミシャ・クバルの「IN TRANSITION / IN PROGRESS」が注目されました。夏の会期（7月19日～8月25日）では、原口典之の「斜めの構成」や真庭のシシが展示されました。秋の会期（9月28日～11月4日）では、田上真貴の「たまべん」が登場し、旬の食材を活かしたお弁当が提供され、訪問者とのご縁に感謝する気持ちが込められています。' where id = 'hGjtz1TIzM_CxPWk-Bwz4';
update content_bodies set title = 'Setouchi Triennale 2019 (SETOUCHI TRIENNALE) Around Uno Port - Summary', description = 'The Setouchi Triennale 2019 showcased various artworks and events around Uno Port during the spring, summer, and autumn seasons. The opening event on April 27, 2019, featured a piano performance by Mami Yamachi and a joint performance with a local high school brass band. In spring, from April 26 to May 26, notable works included ''nomad note dance'' at La Mar de Bois and ''IN TRANSITION / IN PROGRESS'' by Misha Koval. The summer session, from July 19 to August 25, highlighted works like ''Diagonal Composition 1'' and ''Mannai''s Shishi'' by Yodogawa Technique. The autumn season, from September 28 to November 4, featured ''Tamaben'' by Maki Tagami, a bento inspired by seasonal ingredients, expressing gratitude for connections with visitors.' where id = 'D_Hkm8xW_JeWyyhYtsSZR';
update content_bodies set title = '金比羅火口災害遺構散策路', description = '金比羅火口災害遺構散策路では、2000年の噴火によって形成された火口や、熱泥流などの災害で被災した施設を見学することができ、災害遺構について学ぶことができます。この場所は、災害の教訓を学ぶための貴重な機会を提供しています。ぜひ訪れてみてください。' where id = 'wahIBJzy6kdCBzKJ_yOCr';
update content_bodies set title = 'The Scar Left Behind', description = 'The Konpira Crater Disaster Ruins Trail offers visitors the opportunity to explore the crater formed by the eruption in 2000, as well as facilities affected by disasters such as hot mud flows. It serves as an educational site for learning about disaster ruins.' where id = 'qERNXU6x4DJTqqKqztW3S';
update content_bodies set title = '江田船山古墳発掘１５０年記念編', description = '江田船山古墳は発掘から１５０年を迎えます。この重要な節目は、古墳の歴史的および考古学的な重要性を強調しており、古代の埋葬習慣や当時の文化に対する理解を深めるために貢献してきました。' where id = 'Vzm7cBQa7qvDEYIRNxo_b';
update content_bodies set title = 'Eta Funayama Kofun 150th Anniversary of Excavation', description = 'The Eta Funayama Kofun marks the 150th anniversary of its excavation. This significant milestone highlights the historical and archaeological importance of the site, which has contributed to our understanding of ancient burial practices and the culture of the time.' where id = '8TGkk5HgY_skIngnuSdt5';
update content_bodies set title = '東京国立博物館', description = '東京国立博物館は、日本の東京に位置する著名な博物館です。伝統的な日本の美術や工芸品、アジアの美術を収集、保存、展示することに特化しています。博物館には、陶磁器、武士の鎧、古代の巻物など、多様なアイテムが収蔵されており、重要な文化機関となっています。訪問者は、日本や他のアジア諸国の豊かな歴史と芸術的遺産を展示するさまざまなギャラリーを探索することができます。' where id = 'YwHurVw8XEodYZGEEH8KG';
update content_bodies set title = 'Tokyo National Museum', description = 'The Tokyo National Museum is a prominent museum located in Tokyo, Japan. It is dedicated to the collection, preservation, and exhibition of traditional Japanese art and artifacts, as well as Asian art. The museum houses a vast array of items, including ceramics, samurai armor, and ancient scrolls, making it a significant cultural institution. Visitors can explore various galleries that showcase the rich history and artistic heritage of Japan and other Asian countries.' where id = 'fiRg95bC43QJZdai65MNH';
update content_bodies set title = 'SL(パレオエクスプレス)', description = 'この動画では、SL(パレオエクスプレス)という蒸気機関車について紹介しています。' where id = 'Rmx3DjW1n2yNWDUNZ2dcx';
update content_bodies set title = 'SL (Paleo Express)', description = 'This video introduces the SL (Paleo Express), a steam locomotive.' where id = 'kv-d62Lh2UTjptbEWdqew';
update content_bodies set title = '魚沼市 枝折峠から見た滝雲', description = '魚沼市の枝折峠から見た滝雲の写真です。条件が整えば、7月でもこの美しい現象を見ることができます。撮影は朝の4時に行われており、早起きが必要です。' where id = 'SsNoehf9DB3tZD-vfrIQv';
update content_bodies set title = 'Waterfall Clouds Viewed from Oshirase Pass in Uonuma City', description = 'This is a view of waterfall clouds from Oshirase Pass in Uonuma City. These clouds can be seen in July if the conditions are right. The photo was taken at 4 AM, so an early wake-up is essential.' where id = 'k4DbD2_GSvnFRTskKI50B';
update content_bodies set title = 'デジタル体験ガイド（英語）-伝統的建物群の城東保存地区-', description = 'デジタル体験ガイドでは、津山城天守閣などの高精細3DCGによる再現が行われ、文化財の歴史解説が日本語、英語、中国語、韓国語、フランス語の5カ国語で提供される4K動画が用意されています。このコンテンツは、津山市内の3カ所に設置された55インチのタッチパネルによるデジタルサイネージでも視聴可能です。設置場所は、箕作阮甫旧宅、津山城内の備中櫓、作州民芸館の3カ所です。詳細は津山まちじゅう博物館のウェブサイトをご覧ください。' where id = 'V6YbfQ-0H-aFrwPW9yWsz';
update content_bodies set title = 'Digital Experience Guide(English)-Joto Preservation District for Groups of Traditional Buildings-', description = 'The Digital Experience Guide features high-resolution 3D CG recreations of historical sites, including Tsuyama Castle''s main keep, and offers cultural heritage history explanations in five languages: Japanese, English, Chinese, Korean, and French through 4K videos. This content is also available on 55-inch touch panel digital signage installed at three locations in Tsuyama City: the former residence of Mitsukuri Genpo, Bichu Yagura within Tsuyama Castle (Tsuruyama Park), and the Sakushu Folk Art Museum. For more information, visit the Tsuyama City Museum website.' where id = 'XWnCwDd9mQsyAoke7t8r1';
update content_bodies set title = '南砺の風景 - 藤棚（井波別院瑞泉寺）', description = '見頃は4月下旬から5月上旬で、撮影場所は井波別院瑞泉寺です。所在地は富山県南砺市井波3050、電話番号は0763-82-0004です。瑞泉寺は、天正9年、宝暦12年、明治12年の三度にわたり大きな火災に見舞われ、建物が焼失しましたが、その都度地域の人々の思いと共に再建されてきました。再建には京都の大工が派遣され、井波の大工に卓越した技術が伝えられました。このようにして、現在まで続く伝統工芸の井波彫刻は、京都の寺院建築や彫刻の技術と、瑞泉寺再建で培った井波大工の技術が融合して生まれたと考えられています。したがって、井波別院瑞泉寺は井波彫刻の発祥の地とも言われています。' where id = 'mqIFT9hXAWXbvXbBf81wz';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture - Wisteria Arbor (Zuisen-ji Temple, Inami)', description = 'The best time to visit is from late April to early May. The location is Zuisen-ji Temple, situated at 3050 Inami, Nanto City, Toyama Prefecture, with the phone number 0763-82-0004. Zuisen-ji Temple has experienced three major fires in its history (in 1579, 1645, and 1879), leading to the destruction of its buildings. Each time, the temple was rebuilt with the support of the local community, and skilled carpenters from Kyoto were sent to assist in the reconstruction. This collaboration helped to pass on exceptional techniques to local carpenters in Inami. The traditional craft of Inami carving, which continues to this day, is believed to have been developed through the fusion of techniques learned from Kyoto''s traditional temple architecture and the skills honed during the reconstruction of Zuisen-ji Temple. As a result, Zuisen-ji Temple is regarded as the birthplace of Inami carving.' where id = 'UCLsHfjHYQU7brJXNF-SX';
update content_bodies set title = '30秒で行く南砺の春旅', description = 'この映像は、富山県南砺市の春の旅を紹介しています。レンタサイクルで小矢部川沿いの千本桜と残雪の山々を眺めながらサイクリングを楽しむ様子が描かれています。また、桜ヶ池公園でのコーヒータイムや、木彫りのまち井波の散策、城端別院善徳寺での腕輪念珠づくり体験など、南砺の春の魅力が満載です。' where id = 'Y0REC3JLwr88v_Sn8V1Cg';
update content_bodies set title = '30 Seconds Trip to Nanto in Spring (30 seconds trip 4K)', description = 'This video showcases a spring trip in Nanto City, Toyama Prefecture, featuring cycling along the scenic Yabe River lined with cherry blossoms and snow-capped mountains. It includes a relaxing coffee break at Sakuragaike Park, a stroll through the wood-carving town of Inami, and a unique experience of making a personal prayer bead bracelet at Jōhan Betsuin Zentoku-ji Temple. The video highlights the many attractions of Nanto in spring.' where id = 'SVc4GcCNyGVjZwY-hAIbS';
update content_bodies set title = '城端曳山祭 ～曳山の巡行～', description = 'この動画では、城端曳山祭について紹介しており、曳山の巡行の様子を伝えています。' where id = 'otblA5BLwA7pgTgXbvGXN';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture', description = 'This video introduces the Juhon Hikiyama Festival, showcasing the procession of the hikiyama.' where id = 'C9Ry-WztHpkZX9GmFaPhn';
update content_bodies set title = '城端曳山祭 ～狭い路地の通過～', description = 'この動画では、城端曳山祭について詳しく紹介しています。祭りの魅力や特徴、狭い路地を通過する様子などが描かれ、地域の文化や伝統を感じることができます。' where id = 'PmqJE6Tc0Fu0KdzWF0Vf3';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture', description = 'This video introduces the Juhang Hikiyama Festival.' where id = 'cIoOVI8kY0q0qscGP5HTx';
update content_bodies set title = '美知の里（みちのさと）【福光】', description = '美知の里は、富山県南砺市下野285に位置する貸切宿・ゲストハウスです。郵便番号は939-1733で、問い合わせは090-3760-8345までどうぞ。詳細は公式ウェブサイト（http://michinosato.com/）をご覧ください。' where id = 'e501cGDUjZhQdUxaLxt0P';
update content_bodies set title = 'Michinosato (美知の里) - Fukumi', description = 'Michinosato is a private accommodation and guesthouse located at 285 Shimono, Nanto City, Toyama Prefecture, 939-1733, Japan. For inquiries, you can contact them at 090-3760-8345. More information can be found on their website: http://michinosato.com/' where id = 'KjidivgaFPrxeXmTi97AO';
