update content_bodies set title = 'Fukuno Town Hotel A-Mieu', description = 'Fukuno Town Hotel A-Mieu is located at 384-2 Jike Shin''yashiki, Nanto City, Toyama Prefecture, 939-1577, Japan. For inquiries, you can contact them at 0763-22-1414. More information can be found on their website: https://www.town-hotel.jp/' where id = 'Wft2ZPZeBNfnAmd8kM0tc';
update content_bodies set title = '民宿 五ヨ門（ごよもん）【五箇山】', description = '民宿五ヨ門は、富山県南砺市相倉438に位置しています。郵便番号は939-1915です。お問い合わせは0763-66-2154までどうぞ。詳細は公式ウェブサイト（http://www.goyomon.burari.biz/）をご覧ください。' where id = 'vc5UV8AeQ7k1CAs0p3qDf';
update content_bodies set title = 'Minpaku Goyomon (Goyomon) [Gokayama]', description = 'Minpaku Goyomon is located at 438 Aikura, Nanto City, Toyama Prefecture, 939-1915, Japan. For inquiries, you can reach them at 0763-66-2154. More information can be found on their website: http://www.goyomon.burari.biz/' where id = 'l8XB0tPUa6W1dNrtoGsEX';
update content_bodies set title = 'やましたや', description = 'やましたやは、富山県五箇山に位置するゲストハウスです。住所は、富山県南砺市皆葎839、郵便番号は939-1961です。お問い合わせは、電話番号0763-77-3264までどうぞ。詳細は公式ウェブサイト（https://www.gokayama-yamashitaya.com/index.html）をご覧ください。' where id = 'A2SjuX82Rf7xGjVbcgjxU';
update content_bodies set title = 'Guest House YAMASHITA-YA', description = 'Guest House YAMASHITA-YA is located in Gokayama, Toyama Prefecture, Japan. The address is 839 Minami-Taka, Nanto City, Toyama 939-1961. For inquiries, you can contact them at 0763-77-3264. More information can be found on their website: https://www.gokayama-yamashitaya.com/index.html.' where id = 'fQ5RkMTzkk1BrhoBWVwJn';
update content_bodies set title = '東山荘', description = '東山荘は、富山県南砺市井波3043に位置しています。郵便番号は932-0211です。問い合わせは0763-82-1013までどうぞ。詳細は公式ウェブサイト（http://www12.plala.or.jp/touzansou/）をご覧ください。' where id = 'fbjki7E6lo-gdut_Q5F77';
update content_bodies set title = 'Touzansou', description = 'Touzansou is located at 3043 Ina, Nanto City, Toyama Prefecture, 932-0211, Japan. For inquiries, you can reach them at 0763-82-1013. More information can be found on their website: http://www12.plala.or.jp/touzansou/' where id = 'cKJUuTbTjnj0n4ZAyWc8r';
update content_bodies set title = '料理旅館 万水閣', description = '料理旅館万水閣は、富山県南砺市に位置する伝統的な宿泊施設です。住所は富山県南砺市立野原東1525番地、電話番号は0763-62-1717です。この旅館は、1日1組限定の宿泊スタイルを提供しており、個別のサービスと静かな雰囲気を楽しむことができます。' where id = 'eSNkhYWRtlIub7-QkO2zK';
update content_bodies set title = 'Mansuikaku Ryokan', description = 'Mansuikaku is a traditional Japanese inn located in Johana, Toyama Prefecture. The address is 1525 Hiranohara Higashi, Nanto City, Toyama 939-1835, and the contact number is 0763-62-1717. The ryokan offers a unique experience by accommodating only one group per day, ensuring personalized service and a tranquil atmosphere.' where id = 'WQ3iUd2BXoS83oMfn7eKY';
update content_bodies set title = '民宿おかもと（おかもと）【利賀村】', description = '民宿おかもとは、富山県南砺市利賀村百瀬川390に位置しています。郵便番号は939-2511です。お問い合わせは0763-68-245までどうぞ。詳細は公式ウェブサイト（http://www1.tst.ne.jp/togaoka/）をご覧ください。' where id = '2vLln7qfdYZSmKzlkS3nu';
update content_bodies set title = 'Minpaku Okamoto (Okamoto) [Toga Village]', description = 'Minpaku Okamoto is located at 390 Momosegawa, Toga Village, Nanto City, Toyama Prefecture, 939-2511. For inquiries, you can reach them at 0763-68-245. More information can be found on their website: http://www1.tst.ne.jp/togaoka/' where id = 'BuTcu-d8OykQv2XFOTLy-';
update content_bodies set title = '民宿まござ（まござ）【利賀村】', description = '民宿まござは、富山県南砺市利賀村上百瀬236に位置しています。郵便番号は939-2513です。お問い合わせは0763-68-2767までどうぞ。詳細は公式ウェブサイト（https://www.tabi-nanto.jp/archives/1337）をご覧ください。' where id = 'CB5HhmADh7L1fM5gf8JiF';
update content_bodies set title = 'Minpaku Magoza (Magoza) [Toga Village]', description = 'Minpaku Magoza is located at 236 Kamihyakuse, Toga Village, Nanto City, Toyama Prefecture, 939-2513, Japan. For inquiries, you can contact them at 0763-68-2767. More information can be found on their website: https://www.tabi-nanto.jp/archives/1337.' where id = 'bUImgN1IiBJ9ad7UN7VkF';
update content_bodies set title = 'よしのや旅館（よしのや）【五箇山】', description = 'よしのや旅館は、富山県南砺市皆葎366に位置しています。郵便番号は939-1961です。問い合わせは0763-67-3227までどうぞ。詳細は公式ウェブサイト（http://www.yoshinoya.burari.biz/）をご覧ください。' where id = '4FYy5CrOo6x2OXbIZSyVo';
update content_bodies set title = 'Yoshinoya Ryokan (Yoshinoya) [Gokayama]', description = 'Yoshinoya Ryokan is located at 366 Minaritsu, Nanto City, Toyama Prefecture, 939-1961, Japan. For inquiries, you can reach them at 0763-67-3227. More information can be found on their website: http://www.yoshinoya.burari.biz/' where id = 'A6XSxX4EpapfDKQSomN3Y';
update content_bodies set title = '福野夜高祭り　～引き合い（通称：ケンカ）～', description = '福野夜高祭りは、福野神明社の春祭りで、5月1日・2日の夜高祭と3日の本祭りから成ります。宵祭りでは神を迎える行事が行われ、夜高行燈の練り回しや夜高太鼓の音が春の夜空に響き渡ります。2日目の見どころは引合い（ケンカ）で、神明社の女神が喧嘩を好むとされ、行燈がすれ違う瞬間に始まります。全町内が練り終わると、締めくくりの「しゃんしゃん」儀式が行われます。3日の本祭りでは、4町の曳山が神明社に参詣し、神輿が町内を巡行します。350年以上の歴史を持つこの祭りは、毎年4月30日に前夜祭が行われ、特に文久の大行灯が見どころです。' where id = '6kTTuUIXnKYWO6i8RyKhM';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture - Fukuno Yotaka Festival: The Fight (Kenka)', description = 'The Fukuno Yotaka Festival, held at Fukuno Shinmeisha Shrine, features a spring celebration with a night festival on May 1st and 2nd, followed by the main festival on May 3rd. The night festival includes the ceremonial welcoming of the deity, with vibrant lanterns and the energetic sounds of drums and chants filling the spring night sky. On the second day, the highlight is the ''Kenka'' or fight, where the goddess of the shrine is said to delight in the intensity of the competition. This event begins when the lanterns from different neighborhoods cross paths. The festival culminates with a closing ceremony where representatives gather to report the successful completion of the events. The main festival on May 3rd features four neighborhoods parading their floats to the shrine, accompanied by a procession of portable shrines. The festival, which has a history of over 350 years, showcases the grandeur of the Yotaka lanterns, with a special pre-festival event held on April 30th.' where id = 'cDT5PVSsSdWud1CT0rYMy';
update content_bodies set title = '福野夜高祭り　～前夜祭～', description = '福野夜高祭りは毎年4月30日にJR福野駅前広場で開催されます。目玉は文久の大行灯で、高さ約15メートルあり、南砺市福野地域で受け継がれる大行燈の2倍以上の大きさです。この行燈は電柱がない時代のものを再現しています。5月1日から始まる宵祭りでは、夜高行燈の練り回しが行われ、夜高太鼓と若衆の掛け声が響き渡ります。最大の見どころは、2日の23時頃から始まる引合い（ケンカ）で、若衆が相手の行燈を壊し合う迫力あるイベントです。本祭りでは、4町の曳山が神明社に参詣し、神輿が町内を巡行します。' where id = '2fAsWfe5w_Y3sQq_JTvob';
update content_bodies set title = 'Trip to Nanto City, Toyama Prefecture - Fukuno Yotaka Festival: Eve Festival', description = 'The Fukuno Yotaka Festival is held annually on April 30th at the JR Fukuno Station square. A highlight of the event is the Bunkyu giant lantern, which stands approximately 15 meters tall, more than double the size of the traditional giant lanterns still passed down in the Fukuno area of Nanto City. This lantern recreates the scale of those made in an era without utility poles. The evening festival, starting on May 1st, features the procession of Yotaka lanterns, accompanied by the powerful sounds of Yotaka drums and the spirited shouts of the young men. The main attraction occurs around 11 PM on the 2nd, when the ''Kenkai'' (fighting) event takes place, where young men compete to break each other''s lanterns, creating a thrilling spectacle. During the main festival, four town floats visit the Shinmei Shrine, and the portable shrine parades through the town.' where id = '5Z8Xe1cn_qwLlQDlyS-1c';
update content_bodies set title = 'KOKIRIKO -古代日本の民謡- ｜こきりこ　日本語版', description = '五箇山では、自然と調和した生活が代々受け継がれています。世界文化遺産の合掌造り集落と共に、こきりこは地元の人々によって忠実に守られています。こきりこは、約1400年前の大化の改新に起源を持つ演芸である田楽に根ざしたシンプルな民謡と舞踊で、日本最古の民謡とされています。その名は多くの古文書に登場します。特別な体験プランとして、世界遺産の合掌造りの家に宿泊し、伝統的なこきりこの演目を観ることができます。このツアーでは、五箇山の本質を体験し、古典的な日本文化の美しさに浸ることができます。' where id = 'drX1N5wsSNzICPBVtpczu';
update content_bodies set title = 'KOKIRIKO -The Ancient Japanese Folk Song- ｜こきりこ　English Ver.', description = 'In Gokayama, a harmonious lifestyle with nature has been preserved through generations. Kokiriko, considered Japan''s oldest folk song, is maintained by the local community alongside the World Cultural Heritage Gassho-style Village. This simple song and dance, rooted in the ancient performing art of Dengaku from around 1,400 years ago, is documented in many historical texts. A special experience is offered to visitors: staying in Gassho-style houses within the World Heritage Site and witnessing traditional Kokiriko performances. This tour allows guests to immerse themselves in the essence of Gokayama and appreciate the beauty of traditional Japanese culture.' where id = 'MbMxnHdyxV2LCbN0Z2MLC';
update content_bodies set title = 'こきりこ - 日本最古の民謡 -', description = '自然と共にある暮らしが続く五箇山は、世界文化遺産に登録された合掌造り集落と共に、地域住民によって大切に受け継がれている日本最古の民謡「こきりこ」の故郷です。「こきりこ」は、1400年前の大化の改新ごろに発祥した田楽踊りがルーツとされる素朴な唄踊りで、数々の古文献にもその名が残されています。特別なプランとして、合掌造りに宿泊し「こきりこ」を鑑賞するツアーが用意されており、五箇山の文化と人々の心を体験することができます。詳細は https://www.tabi-nanto.jp/kokiriko/ をご覧ください。' where id = 'JazFRpzph4C-4tgwiU_aC';
update content_bodies set title = 'KOKIRIKO -The Ancient Japanese Folk Song-', description = 'Gokayama, a region where life in harmony with nature continues, is home to the ancient Japanese folk song ''Kokiriko,'' which has been carefully passed down by local residents alongside the UNESCO World Heritage Site of the Gassho-zukuri villages. ''Kokiriko'' is believed to have originated around 1400 years ago during the Taika Reforms, stemming from a simple song and dance associated with rice planting. It is recognized as Japan''s oldest folk song, with its name appearing in various ancient texts. A special plan is available to experience the World Heritage Gokayama, including a stay in a Gassho-zukuri house and a performance of ''Kokiriko.'' This tour offers a unique opportunity to immerse oneself in the culture and spirit of Gokayama. For more details, visit https://www.tabi-nanto.jp/kokiriko/.' where id = 'G-tevUGKMCZurE3po8EhB';
update content_bodies set title = 'KOKIRIKO －古代日本の民謡－ 短編Ver.', description = 'KOKIRIKOは、古代日本の民謡を短編形式で紹介した作品です。伝統的な日本の音楽と文化の本質を捉えています。' where id = 'Kb6daGmY7jwh1Hi8WhlIm';
update content_bodies set title = 'KOKIRIKO - The Ancient Japanese Folk Song - Short Version', description = 'KOKIRIKO is an ancient Japanese folk song presented in a short version. It captures the essence of traditional Japanese music and culture.' where id = 'AB-MZLox-ylaOjgS-zN0z';
update content_bodies set title = '東京日帰り旅行 神奈川「発見の感覚」', description = '無人島を探検し、座禅を体験し、箱根の絶景を楽しむ旅に出かけませんか。神奈川の魅力を発見し、歴史や自然の美しさに親しむことができる特別な体験です。' where id = 'v4s5WPueY1I_qC83MGLIj';
update content_bodies set title = 'Tokyo Day Trip KANAGAWA "Feeling of Discovery"', description = 'This trip invites you to explore an uninhabited island, engage in Zen meditation, and enjoy breathtaking views of Hakone. Experience the unique charms of Kanagawa, Japan, and immerse yourself in its rich history and natural beauty.' where id = 'auRD_IO9_FCLVGOCjz519';
update content_bodies set title = 'EN（縁）', description = '福井県高浜町は、若狭湾と若狭富士「青葉山」に囲まれ、世界に禅を広めた釈宗演の生誕地です。釈宗演が幼少期を過ごしたこの町では、自然と人とのつながりを通じて心と体をリセットするZENの体験が今も息づいています。今回の動画は、陰陽の陽（春夏）を表現し、ZENの「縁」に出会うことを願っています。縁がつながり、新たな縁を紡いでいく高浜町で、ZENの体験や日本海の美味しい魚を味わい、ワーケーションを楽しむことをお勧めします。詳細は高浜町のワーケーションHPをご覧ください。' where id = 'HVV-ho4zt9yxNRfXfN4J4';
update content_bodies set title = 'EN (Connection)', description = 'Takahama Town in Fukui Prefecture, surrounded by Wakasa Bay and Aobayama, is the birthplace of Shaku Soen, a pioneer who first introduced Zen to the world. The town, where Shaku spent his childhood, is enveloped by nature, allowing for a reset of the mind and body through Zen experiences. This video, representing the positive aspects of Yin-Yang (spring and summer), invites viewers to encounter the concept of ''EN'' (connection) in Zen. As connections are made and new bonds are woven, visitors are encouraged to experience Zen, enjoy delicious seafood from the Sea of Japan, and engage in workation in Takahama. For more information, visit the Takahama workation website.' where id = '5gknUZ9hXXeubCeJNyfAm';
update content_bodies set title = '【福井県高浜町】難波江海水浴場', description = '難波江海水浴場はサーフィン愛好者に人気のビーチで、高浜町で唯一、砂浜まで車を乗り入れることができるアウトドア感覚のビーチです。ただし、海水浴開設期間中はサーフィンが禁止されています。' where id = 'rt6gYLDz24xUnl-euh_MX';
update content_bodies set title = 'Nabae Beach in Takahama, Fukui Prefecture', description = 'Nabae Beach is a popular spot for surfers and is the only beach in Takahama where vehicles can access the sandy shore, providing an outdoor experience. However, surfing is prohibited during the beach''s swimming season.' where id = 'lB64875jbbZEU6SOo5aip';
update content_bodies set title = '音海大断崖－福井県高浜町', description = '音海大断崖は、福井県にある高さ260mの絶壁で、県の名勝に指定されています。押廻埼灯台まで続く遊歩道が整備されており、途中からは大断崖の美しい景観を楽しむことができます。自然の雄大さを感じながら散策できるスポットです。' where id = 'VDkz68R2OpxbfozQ77qcv';
update content_bodies set title = 'Otomi Cliff in Takahama, Fukui Prefecture', description = 'Otomi Cliff is a designated scenic spot in Fukui Prefecture, featuring a dramatic vertical drop of 260 meters. A walking path extends to the Oshimawaki Lighthouse, allowing visitors to enjoy views of the cliff along the way.' where id = 'azNkltYFt2xpfjGJ7UUkB';
update content_bodies set title = '福井県高浜町 はまなすパーク海水浴場', description = 'はまなすパーク海水浴場は、波が穏やかで小さなお子様連れでも安心して楽しめる海水浴場です。海水浴期間中は砂浜全域でBBQが可能で、これも大きな魅力の一つです。また、1,400mにわたる遊歩道も整備されており、訪れる人々が楽しむことができます。' where id = 'T1GS334J8xVyrAVMuZ3Ux';
update content_bodies set title = 'Hamanasu Park Beach in Takahama, Fukui Prefecture', description = 'Hamanasu Park Beach is a safe swimming area, especially suitable for families with small children due to its calm waves. One of its attractions is that barbecuing is allowed on the entire sandy beach during the swimming season. Additionally, there is a 1,400-meter-long promenade for visitors to enjoy.' where id = 'j29q6wuxDoJ2ckISFhvaI';
update content_bodies set title = '【福井県高浜町】城山海水浴場', description = '城山海水浴場は、波が穏やかで磯遊びができる岩場があり、小さなお子様を連れたファミリーに人気です。高浜町の名勝「明鏡洞」がある城山公園がすぐ隣にあり、芝生広場なども楽しめます。城山公園は日本の夕日百選にも選ばれており、美しい景観を楽しむことができます。' where id = 'OQAUscd3Sq6zP-m-GWyC4';
update content_bodies set title = 'Shiroyama Beach in Takahama, Fukui Prefecture', description = 'Shiroyama Beach is popular among families with small children due to its calm waves and rocky areas suitable for tide pooling. Located next to Shiroyama Park, which features the scenic Meikyo Cave, visitors can also enjoy grassy areas and beautiful views. Shiroyama Park has been selected as one of Japan''s top 100 sunset spots, making it a great place to appreciate the scenery.' where id = '0HfjUOk7XMLlEf_IQKUm4';
update content_bodies set title = 'EN（縁）short', description = '福井県高浜町は、若狭湾と若狭富士の青葉山に囲まれた美しい場所です。海と山の両方の素晴らしい景色を楽しむことができ、グルメやさまざまな体験も豊富にあります。ぜひ高浜町にお越しください。' where id = 'iJozFzhEqO6v0F2l4AqM2';
update content_bodies set title = 'EN（縁）short', description = 'Takahama Town in Fukui Prefecture is surrounded by the beautiful Wakasa Bay and Aobayama, also known as Wakasa Fuji. Visitors can enjoy stunning views of both the sea and mountains, as well as a variety of gourmet food and experiences. We invite you to come and explore Takahama Town.' where id = 'U0bXRk6HxrCXG0hYms4F2';
update content_bodies set title = '城ケ島/Kanagawa, Japan (東京から一時間、癒される自然島)', description = '神奈川県の「新たな観光の核」候補である城ケ島を紹介する映像です。横浜・箱根・鎌倉に次ぐ観光地として、自然の美しさと癒しの目的地としての可能性を示しています。東京からわずか一時間の距離に位置しています。' where id = 'tV3zYPdu74RtJt9uYTLbS';
update content_bodies set title = 'Jogashima/Kanagawa, Japan (One hour from Tokyo, a Healing Island with Rich Nature)', description = 'This is an introduction video of Jogashima, a candidate for a new tourism hub in Kanagawa Prefecture, following Yokohama, Hakone, and Kamakura. The video showcases the island''s natural beauty and its potential as a healing destination, located just one hour from Tokyo.' where id = 'DZqX8XTLkekonnICIcSyR';
update content_bodies set title = '森の中を空中移動「フォレストアドベンチャー・小田原」で未病を改善！', description = '「未病いやしの里の駅」に位置するフォレストアドベンチャー・小田原の紹介です。神奈川県県西地域にあり、自然に囲まれた環境で健康を促進することを目的としています。この施設では、様々な森林浴の体験ができ、未病の改善を目指しています。「未病いやしの里の駅」についての詳細は、提供されたリンクを参照してください。また、県西地域活性化プロジェクトについては、公式ウェブサイトやSNSを通じて情報を得ることができます。' where id = 'WyoTzoBadYjTUlgq_o3sp';
update content_bodies set title = 'Forest Adventure Odawara: Improving Pre-illness through Aerial Movement in the Woods!', description = 'This is an introduction to Forest Adventure Odawara, located at the ''Pre-illness Healing Station'' in Kanagawa Prefecture. Surrounded by nature, it aims to improve health in the Ken-sei region. The facility offers various forest bathing experiences, promoting wellness and vitality. For more information about the ''Pre-illness Healing Station,'' visit the provided link. Additionally, explore the Ken-sei Regional Revitalization Project through their official website and social media platforms.' where id = 'onaxOmeeokE8bLJTPpPxu';
update content_bodies set title = '「I LOVE AIKAWA-MACHI 愛川町の魅力がいっぱい」', description = '愛川町をロケ地とした初の動画コンテスト「愛川レッドカーペット」では、「私が感じた愛川町の魅力」をテーマに60秒以内の作品を募集しました。応募全34作品の中から、片山憲一さんの「I LOVE AIKAWA-MACHI 愛川町の魅力がいっぱい」が次点の優秀賞を受賞しました。この作品は、一般公募のロケ地めぐり企画「ロケ地にゴー！」に参加した際に撮影したスポットや、再訪時に撮影したスポットを盛り込んでいます。光を生かした描写や巧みなつなぎ方により、愛川町の魅力が存分に表現された作品となっています。' where id = 'SSX842KpDzWogNncBwtm6';
update content_bodies set title = 'I LOVE AIKAWA-MACHI: A Showcase of Aikawa Town''s Charms', description = 'The first video contest featuring Aikawa Town as a filming location, titled ''Aikawa Red Carpet,'' invited submissions under the theme ''The Charms of Aikawa Town'' with a 60-second time limit. Among 34 entries, Kenichi Katayama''s work, ''I LOVE AIKAWA-MACHI: A Showcase of Aikawa Town''s Charms,'' won the runner-up award. The piece showcases various filming spots from a public location tour project called ''Go to Filming Locations!'' and includes scenes captured during a subsequent visit to the town. The effective use of light and creative transitions highlight the town''s attractions, making it a captivating representation of Aikawa.' where id = 'ZLQF7iT47_qaZkMZ6KX7x';
update content_bodies set title = '【東北・山形】「EMMA」山形県最上町プロモーション動画', description = '最上町は古来より馬の産地であり、名馬・小国駒の故郷として知られています。このプロモーション動画は、馬と深い関わりを持つ町の歴史を背景にした感動的な短編物語です。主なロケ地は、馬の守り神として崇拝される富山馬頭観音の東善院と、観光地としての前森高原で、どちらも桜の名所としても知られています。物語は、馬、桜、女性をテーマに、主人公の過去から未来へとつながるストーリーを描き、町の魅力的な風景を活かして制作されています。' where id = 'fQQ95K3fWXEIDv-AEsoX-';
update content_bodies set title = 'Promotion Video for Mogami Town, Yamagata (Tohoku, Japan)', description = 'This promotional video presents a moving short story set in Mogami Town, Yamagata Prefecture, which has a rich history as a horse-breeding area. Known for the famous Oguni Koma horse, the town has fostered a deep connection with horses throughout its history. The video features two main locations: Tozen-in Temple of Tomiyama Bato Kannon, a revered guardian deity of horses, and Maemori Plateau, a modern tourist destination linked to horses. Both sites are also celebrated for their cherry blossoms. The narrative intertwines themes of horses, cherry blossoms, and femininity, showcasing the protagonist''s journey through the past, present, and future, all while highlighting the town''s beautiful scenery.' where id = 'qn4KbJcAnQEgBzxDFePu9';
update content_bodies set title = '三重県を体験する', description = '三重県は日本に位置し、多様な観光名所や体験を提供しています。主な見どころには、精神的な重要性を持つ伊勢神宮や、伝統的な街並みのあるおはらい町・おかげ横丁があります。訪問者は、伊勢焼陶芸体験工房での陶芸体験や、伊勢型紙版画工房での独特な型紙印刷を楽しむことができます。また、ミキモト真珠島では真珠の養殖が紹介されています。自然愛好者には、三多気の桜や美しい赤目四十八滝が楽しめます。冒険を求める人には、忍者体験やナガシマスパーランドのスリリングなアトラクションがあります。さらに、リゾートや田舎ツーリズムの機会もあり、あらゆる旅行者にとって多様な目的地となっています。' where id = 'yRwuluxLMvZ6qwLZhRY4R';
update content_bodies set title = 'Experience Mie Japan - 三重県', description = 'Mie Prefecture, located in Japan, offers a variety of attractions and experiences. Key highlights include the Ise Jingu shrine, known for its spiritual significance, and the traditional streets of Oharai Machi and Okage Yokocho. Visitors can engage in hands-on activities like ceramic art at the Ise Ceramic Art studio and explore the unique craft of katagami printing at Ise Katagami Tsukushiya. Mie is also home to Mikimoto Pearl Island, where pearl cultivation is showcased. Nature lovers can enjoy the cherry blossoms at Mitake and the scenic Akame 48 Waterfalls. For adventure seekers, there are ninja experiences and the thrilling Nagashima Spa Land amusement park. The region also features beautiful resorts and rural tourism opportunities, making it a diverse destination for all types of travelers.' where id = 'dtMokQilVW7eVH4_ERLny';
update content_bodies set title = '200年の日本の食文化を持つ伊賀焼窯元・長谷園', description = '三重県北部の穏やかな里山に位置する伊賀焼の里、丸柱にある長谷園は、1832年の創業以来、耐火性の高い陶器を製造してきました。この地の陶土を使った直火用の土鍋や土瓶は、古くから親しまれています。本プログラムでは、8代目当主による特別な案内で登り窯を見学し、伊賀焼にまつわる秘話を聞くことができます。また、長谷園の代表的な土鍋を使った炊飯実演も体験でき、炊き立ての美味しいご飯を味わうことができます。伊賀焼の豊かな食文化と技術を体感できる貴重な機会です。' where id = 'qNHTImrMWhBzWsV-kkAIc';
update content_bodies set title = 'Nagatanien, the Iga ware kiln with 200 years of Japanese culinary history', description = 'Nagatanien, located in the Iga ware village of Marubashira in northern Mie Prefecture, has been crafting highly flame-resistant pottery since its establishment in 1832. This pottery is renowned for its use in cooking, particularly clay pots and teapots. The program offers a unique opportunity to tour the climbing kilns with the eighth-generation head of Nagatanien, who shares intriguing stories about Iga ware. Participants can also experience cooking rice in a traditional Nagatanien clay pot, allowing them to savor the delicious taste of freshly cooked rice. This experience highlights the rich culinary history and craftsmanship of Iga ware, making it a must-try for visitors.' where id = 'bjuLFTc7JGuMneE2RpMOP';
update content_bodies set title = 'リアルな日本を自転車で巡る三重の旅', description = 'cazacle（カザクル）は、予約制で新しい体験を提供するガイド付きサイクリングツアーを開催しています。地域をゆっくりと巡るには自転車旅が最適で、風を感じながら地域の人々との温かい交流を楽しむことができます。日常生活に溶け込むような体験ができるツアーです。' where id = 'vOUPaO0jppurGzTQyLXqB';
update content_bodies set title = 'Visit Mie Cycling in real Japan', description = 'Cazacle offers guided cycling tours by reservation, providing a unique experience. Cycling is recommended for exploring the region at a leisurely pace. The tours allow participants to enjoy the breeze while fostering warm interactions with the local community, creating an immersive experience in everyday life.' where id = 'YQzieqvAETdWO6ov2vtxL';
update content_bodies set title = '三重県 8K HDR - 三重県', description = '三重県の観光に関する公式サイトでは、英語、繁体字、簡体字、タイ語、韓国語、日本語など、複数の言語で情報を提供しています。サイトでは、三重県の旅行機会や観光名所についての情報を得ることができます。また、三重県はFacebook、Instagram、YouTubeなどのさまざまなSNSでも発信しており、地域の文化や自然の美しさに興味を持つ世界中の人々に向けて情報を発信しています。' where id = 't1RG1-lIkmg-ghcwV_0ES';
update content_bodies set title = 'Mie, Japan 8K HDR - Mie Prefecture', description = 'Discover Mie Prefecture through its official tourism site, which provides information in multiple languages including English, Traditional Chinese, Simplified Chinese, Thai, Korean, and Japanese. The site offers insights into travel opportunities and attractions in Mie. Additionally, Mie Prefecture maintains a presence on various social media platforms such as Facebook, Instagram, and YouTube, catering to a global audience interested in exploring the region''s culture and natural beauty.' where id = 'Jv3ynFLeXPBZCaVeoSOai';
update content_bodies set title = '三重県', description = '三重県は日本に位置し、観光情報を提供する公式サイトがあります。このサイトでは、英語、繁体字、簡体字、タイ語、韓国語、日本語など、さまざまな言語で情報を得ることができます。また、Facebook、Instagram、YouTubeなどのSNSへのリンクもあり、三重県の最新の観光名所やイベントをチェックできます。文化体験や自然の美しさ、グルメなど、三重県は訪れる人々に多様な魅力を提供しています。' where id = 'emuY8MKjUXPcHc-I1-uxC';
update content_bodies set title = 'Mie, Japan 8K HDR', description = 'Mie Prefecture, located in Japan, offers a wealth of travel information through its official tourism site. Visitors can explore various resources available in multiple languages, including English, Traditional Chinese, Simplified Chinese, Thai, Korean, and Japanese. The site provides links to social media platforms such as Facebook, Instagram, and YouTube, allowing travelers to stay updated on the latest attractions and events in Mie. Whether you are looking for cultural experiences, natural beauty, or culinary delights, Mie Prefecture has something to offer for everyone.' where id = 'be3-f8tv-7bEGmV09jSki';
update content_bodies set title = '『初期設定』松阪市プロモーションCM動画', description = '松阪市と地元の高校が共同で、プロモーション動画のコンテストを開催しています。動画のテーマは土偶、綿、そして山の自然です。現在、参加者である高校生からのコメントやフィードバックを募集しており、彼らの貢献をより良くするための意見を求めています。' where id = 'xWie8SjC5xQcjNFYKn7t8';
update content_bodies set title = 'Matsusaka City Promotion Commercial Video Clip', description = 'Matsusaka city, in collaboration with local high schools, has launched a contest for a promotional video clip. The theme of the video focuses on Dogu clay figures, cotton, and the natural beauty of the mountains. The city is currently seeking comments and feedback from participants, specifically high school students, to enhance their contributions.' where id = 'D5BFL3cZbMFr1-sLhJ1Uv';
update content_bodies set title = '『ほっさかさん』', description = '松阪市と地元の高校が共同で、松阪市のプロモーションビデオクリップコンテストを開催しています。ビデオのテーマは土偶、綿、そして山の自然です。現在、参加者である高校生からのコメントやフィードバックを募集しており、彼らの創作活動を支援することを目的としています。' where id = 'je39JdHCj070e3jxBYXvq';
update content_bodies set title = 'Matsusaka city promotion commercial video clip', description = 'Matsusaka city, in collaboration with local high schools, has launched a contest for a promotional video clip. The theme of the video focuses on Dogu clay figures, cotton, and the natural beauty of the mountains. The city is currently seeking comments and feedback from participants, specifically high school students, to enhance their creative efforts.' where id = 'Wl-zEB2P2ry5tIfNARzf3';
update content_bodies set title = '『土ヤタ男』Matsusaka市プロモーションCM動画コンテスト', description = 'Matsusaka市と地元の高校が協力して、プロモーション動画コンテストを開催しています。動画のテーマは、土偶、綿、そして山の自然の美しさです。現在、参加者である高校生からのコメントやフィードバックを募集しており、彼らの体験を向上させ、提出物の質を高めることを目指しています。' where id = 'JRof2Z0-nIQwfXrryvP_-';
update content_bodies set title = 'Matsusaka city promotion commercial video clip contest', description = 'Matsusaka city, in collaboration with local high schools, has launched a contest for promotional video clips. The theme of the videos revolves around Dogu clay figures, cotton, and the natural beauty of the mountains. The city is currently seeking comments and feedback from participants, specifically high school students, to enhance their experience and the quality of the submissions.' where id = 'Qzk7mbwxN0a8nSDGZGkI_';
update content_bodies set title = '善光寺僧侶による参向ビジネスセミナー', description = '善光寺永代宿坊「玉照院」の山ノ井住職が主催するこのセミナーでは、仏教の教義に基づき、心身の調和と働くことの意義を探求します。参加者は、日常生活に心の整え方を取り入れる方法を学びます。住職は、ミズノ認定のウォーキング指導員でもあり、「静」の坐禅と「動」のウォーキングを通じて心身の調和を整える方法を指導します。さらに、仏教の視点から働くことの真の意味を考察します。大手企業や行政自治体での研修実績が10年以上あるこのセミナーは、職場でのストレスを抱える方や、仕事に対して興味を失っている方、心身の健康が気になる方に最適です。' where id = 'cFfSCg3FkeTGWoCOykWXN';
update content_bodies set title = 'Business Seminar by Zenkoji Monks', description = 'This seminar, led by the head priest of Zenkoji Eitai Shukubo ''Gyokushoin'', explores the significance of work and the harmony of mind and body based on Buddhist teachings. Participants will learn how to incorporate mental alignment into their daily lives. The priest, also a certified walking instructor by Mizuno, will guide attendees through ''static'' zazen meditation and ''dynamic'' walking to achieve this harmony. The seminar aims to delve into the true meaning of work from a Buddhist perspective. With over ten years of experience conducting training for major corporations and local governments, this seminar is designed for those facing workplace stress, finding work unfulfilling, or concerned about their mental and physical health.' where id = 'UAQcZGsPFRumRcZeOShLn';
update content_bodies set title = '京都市観光PR映像本編 - どの角でも発見がある街', description = 'この観光PR映像では、京都の歴史的な街を旅する二人の旅行者、マックとカレンの物語が描かれています。日本に住むマックは、親友の娘であるカレンを案内し、京都の美しさを紹介します。旅は京都駅でマックが荷物を預けるところから始まりますが、カレンは観光案内所にたどり着けず、二人の道はすぐに分かれます。マックは計画通り伏見稲荷大社を訪れ、カレンは直感に導かれながら一人で冒険を始めます。二人は時折交差しながら、異なる視点で京都の魅力を発見していきます。最後の夜、着物を着て京懐石を楽しみ、幻想的な東山を散策しながら地元のバーで旅の思い出を語り合います。一年後、カレンは再び京都を訪れ、静かな朝の光の中で寺を歩き、新たな出会いに心を躍らせます。' where id = 'Hg0Rt_hYA6AuuFWaZF44O';
update content_bodies set title = 'Kyoto Promotional Movie - Where Every Corner Sparks Discovery', description = 'In this promotional video, two travelers, Mac and Karen, explore the historical city of Kyoto. Mac, a local resident, guides Karen, his best friend''s daughter, through the city''s beauty. Their journey begins at Kyoto Station, where Mac checks his luggage, while Karen struggles to find the meeting point. As Mac follows a planned itinerary to Fushimi Inari Shrine, Karen embarks on her own adventure, driven by instinct. Their paths occasionally cross as they discover Kyoto''s charms from different perspectives. On their last evening, they enjoy a traditional kaiseki meal in kimonos and stroll through the enchanting Higashiyama district. They share stories at a local bar, marking the end of their journey. A year later, Karen returns to Kyoto, walking through a temple in the serene morning light, excited for new experiences.' where id = 'AYytH0Yt3OENLaYr9we1H';
update content_bodies set title = '【総集編】Be.Okinawa つぎなる旅先、沖縄へ', description = '『Be.Okinawa つぎなる旅先、沖縄へ』は、佐藤健寿の特別トークイベントで公開されたスペシャルムービーの総集編です。この映像では、沖縄の美しいスポットが紹介されており、ピナイサーラの滝、水納島、慶佐次湾のヒルギ林、古宇利大橋などが登場します。「Be.Okinawa」は、観光客を迎える沖縄の気持ちを表現しており、訪れる人々が美しい自然と温かい人々に囲まれて本来の自分を取り戻せる島であることを示しています。「Be」は「そこにある、存在する」を意味し、行動を促す言葉です。' where id = '0rspvvn50M25U_E-nrdRr';
update content_bodies set title = 'Be.Okinawa: The Next Travel Destination, Okinawa', description = 'This is a compilation of a special movie presented at the talk event by Kenji Sato, titled ''Be.Okinawa: The Next Travel Destination, Okinawa.'' The video features stunning locations in Okinawa, including Pinai Sara Falls, Minna Island, the mangrove forest in Kezashi Bay, and the Kouri Bridge. ''Be.Okinawa'' conveys the welcoming spirit of Okinawa towards tourists, emphasizing the island as a place where visitors can reconnect with their true selves amidst beautiful nature and warm people. The term ''Be'' signifies existence and encourages action, inviting travelers to experience the unique charm of Okinawa.' where id = 'wKqve5aHJKyU0l7yEwPEM';
update content_bodies set title = '沖縄を発見: グルメ編', description = 'この動画では、沖縄のグルメについて紹介しています。沖縄の独自の食文化や特産品、地元の料理を通じて、視聴者に沖縄の魅力を伝える内容となっています。沖縄の食材や料理の特徴、そしてそれらがどのように地域の文化と結びついているのかを探ることで、沖縄の豊かな食体験を感じることができるでしょう。' where id = '94XfI-BGpUOTPG0fsp-en';
update content_bodies set title = 'Discover Okinawa: Gourmet Edition', description = 'This video introduces the gourmet food of Okinawa.' where id = 'XA39Oab7HgvN4ikV4yJEW';
update content_bodies set title = 'VRで感じる宮津グルメ！～こっぺがに～', description = 'この動画では、VRを通じて宮津のグルメ、特にこっぺがにについて紹介しています。視聴者は、VR技術を利用して、宮津の美味しい料理を体験することができます。こっぺがには、宮津の特産品として知られており、その魅力をVRで感じることができる内容となっています。' where id = 'Tsex1i486XTx_JMZsBFAM';
update content_bodies set title = 'VR Experience of Miyazu Gourmet! - Koppu Crab', description = 'This video introduces the VR experience of Miyazu gourmet, specifically focusing on Koppu Crab.' where id = 'lhwXu5AjltdGagwWcr34i';
update content_bodies set title = '宮津の歴史・伝統文化', description = '宮津市は、江戸時代に栄えた城下町であり、歴史的な風習や伝統が色濃く残っています。日本海と美しい山々に囲まれたこの街には、悠久の古刹があり、自然と共存しています。また、数々の伝承や神話に彩られた文化的景観が広がっており、宮津の豊かな遺産を感じることができます。独自の伝統文化が息づく宮津をぜひ訪れてみてください。' where id = 'Qp-2-nYcESSnd3ZyXH_N4';
update content_bodies set title = 'TRADITIONAL CULTURE OF MIYAZU CITY', description = 'Miyazu City is a castle town that thrived during the Edo period, characterized by its historical customs and traditions. The city is beautifully situated between the Sea of Japan and majestic mountains, housing ancient temples that have coexisted with nature for centuries. The cultural landscape of Miyazu is rich with numerous legends and myths, adding depth to its heritage. Visitors are encouraged to explore Miyazu, where unique traditional culture remains vibrant and well-preserved.' where id = 'RXRc_xi9fhQBtAtBhcnY0';
update content_bodies set title = '宮津の食文化', description = '宮津市は、日本海の恵みである丹後の極上の海の幸で知られています。この地域は豊潤な自然環境を活かしたこだわりの酒造りが行われており、質の高い日本酒が生産されています。宮津には上質な食文化が根付いており、食に興味のある方々にとって訪れる価値のある場所です。' where id = 'w8PlBGlLlPe0FpicACJQr';
update content_bodies set title = 'FOOD CULTURE OF MIYAZU CITY', description = 'Miyazu City is renowned for its exceptional seafood, a true treasure of the Sea of Japan, particularly the Tango region. The area boasts a rich natural environment that contributes to the production of high-quality sake, crafted with great care and attention to detail. Visitors are encouraged to experience the unique and refined food culture that thrives in Miyazu, making it a must-visit destination for food enthusiasts.' where id = 'O17a1xOmxwzqDlXcckUDc';
update content_bodies set title = '甲冑×乗馬×富山城', description = '2018年3月21日（水・祝）に、富山城にて甲冑の着付けや騎乗体験ができる施設がオープンします。' where id = 'dYrZVtxdYuoJ7xWyi33to';
update content_bodies set title = 'Samurai Experience Toyama: Armor, Horse Riding, and Toyama Castle', description = 'On March 21, 2018, a facility will open at Toyama Castle where visitors can experience wearing samurai armor and riding horses.' where id = '5TJxQTOwlcds0ByK2d3sI';
update content_bodies set title = '函館市観光PR動画　＃函館旅部　「Oh！Yunokawa！」泉質篇', description = 'この動画は、函館市の観光をPRするもので、＃函館旅部の「Oh！Yunokawa！」泉質篇を紹介しています。函館の温泉の魅力や泉質についての情報が盛り込まれており、観光客に向けて函館の魅力を伝える内容となっています。' where id = 'Zosh2JcBeqUNxJ2F2cUpV';
update content_bodies set title = 'Hakodate City Tourism PR Video #HakodateTravelClub ''Oh! Yunokawa!'' Onsen Quality Edition', description = 'This video is a tourism PR piece for Hakodate City, introducing the ''Oh! Yunokawa!'' Onsen Quality Edition from the #HakodateTravelClub.' where id = 'TQRsa30T3Tetjx04ugqIE';
update content_bodies set title = 'ベスト・ツーリズム・ビレッジ2024', description = '西川町は、国連世界観光機関（UN Tourism）によって「ベストツーリズムビレッジ2024」に認定されました。このプロジェクトは、観光を通じて文化遺産の保全や持続可能な開発に取り組む地域を評価するもので、持続可能な開発目標（SDGs）に沿った活動を行っていることが求められます。' where id = 'dmmsplfRlAmOdmFy7Gqpg';
update content_bodies set title = 'Best Tourism Village 2024', description = 'Nishikawa Town has been recognized by the United Nations World Tourism Organization (UN Tourism) as one of the ''Best Tourism Villages 2024.'' This project aims to acknowledge regions that engage in the preservation of cultural heritage and sustainable development through tourism, in alignment with the Sustainable Development Goals (SDGs).' where id = 'uv02sYNhY8QFGkKAN0x2D';
update content_bodies set title = '【PV】にしかわぐらし', description = '山形県西川町は春夏秋冬それぞれ異なる魅力を持つ町です。特に冬には隠れ積雪日本一となるこの町に住む人々に焦点を当て、西川町での暮らしや移住体験談を紹介します。動画には、聴雪窯の土田健さん、地域おこし協力隊の伊東広さん、月山トラヤワイナリーの大泉匡寛さん、taro農場の細谷信太郎さん、紙屋作左ヱ門の渋谷尚子さん、地域おこし協力隊の渡邉健二さん、清水屋旅館の今野和久さんなど、地域の様々な協力者が出演しています。' where id = 'lSWcvCz0mggYYNrxS16iq';
update content_bodies set title = 'Nishikawa Living', description = 'Nishikawa Town in Yamagata Prefecture showcases different faces across the four seasons. This video focuses on the residents of Nishikawa, highlighting their lives and experiences of relocating to this town, which is known for its heavy snowfall in winter. The video features various local contributors, including Ken Tsuchida from Shoyukigama, Hiroshi Ito from the regional revitalization team, Masahiro Oizumi from Gassan Toraya Winery, Shintaro Hosoya from Taro Farm, Naoko Shibuya from Kamiyasan Sakuzaemon, Kenji Watanabe from the regional revitalization team, and Kazuhisa Konno from Shimizuya Ryokan.' where id = '-ft4R6K08lUlvWdFO1qPM';
update content_bodies set title = '名所名宿名物まで美濃路の魅力を余すとこなくお伝えします！', description = 'この記事では、岐阜県の南部に位置する美濃を訪れた様子を紹介しています。著者は長良川沿いのお宿『鵜匠の家 すぎ山』に宿泊した際、大雨の日であったため、通常は透き通った清流が魅力の長良川が濁流となってしまったことを残念に思っています。それでも、普段とは異なる川の姿を楽しむ貴重な体験を振り返っています。また、関ヶ原古戦場記念館や関鍛治伝承館、岐阜城、長良川うかいミュージアムなど、地域の名所も紹介されており、美濃の豊かな文化と歴史、地元の美味しい料理や宿泊施設が紹介されています。' where id = 'T7MciEhQEpvNsB2f4t-S7';
update content_bodies set title = 'Exploring the Charms of Mino: Famous Sites, Inns, and Local Delicacies!', description = 'This article recounts a visit to Mino, located in the southern part of Gifu Prefecture. The author describes their stay at ''Sugiyama'', an inn along the Nagara River, on a day marked by heavy rain, which obscured the usually clear waters of the river. Despite the weather, the author reflects on the unique experience of witnessing the river in its muddy state. The article also highlights various attractions in the area, including the Sekigahara Battlefield Memorial Museum, the Seki Swordsmith Heritage Museum, Gifu Castle, and the Nagara River Ukai Museum, among others. Local culinary delights and accommodations are also mentioned, showcasing the rich culture and history of Mino.' where id = 'H303hlYvwdjM8m9bDYhod';
update content_bodies set title = '瞬き厳禁?!のスピードで3Dキャラが美しい長崎の街や名物グルメをご紹介します！', description = 'こちらは長崎での3日間の訪問先の概要です。1日目はヒルトン長崎に宿泊し、共楽園でちゃんぽんを楽しんだ後、大浦天主堂、グラバー園、長崎伝統芸能館、長崎孔子廟、長崎新地中華街、出島、長崎平和記念公園を訪れ、夕食はざぼんで締めくくりました。2日目はロカンダ デル カンポでランチを取り、小浜温泉の足湯、ORANGE GELATOを楽しみ、雲仙宮崎旅館に宿泊し、雲仙地獄を訪れました。3日目は鯉の泳ぐまちを散策し、姫松屋で具雑煮を味わい、島原城を見学し、銀水でかんざらしを楽しみました。' where id = 'cFf6I8s-qCpE-upDbCH-H';
update content_bodies set title = 'Experience the Beauty of Nagasaki and Its Local Cuisine at Lightning Speed with 3D Characters!', description = 'This is a summary of the places visited over three days in Nagasaki. On Day 1, the itinerary included Hilton Nagasaki for accommodation, followed by local cuisine at Kyourakuen (Champon), visits to historical sites like Oura Church, Glover Garden, Nagasaki Traditional Performing Arts Center, Confucius Shrine, Nagasaki Shinchi Chinatown, Dejima, and Nagasaki Peace Park, ending with dinner at Zabonn. Day 2 featured lunch at Locanda Del Campo, a foot bath at Obama Onsen, Orange Gelato, and an overnight stay at Unzen Miyazaki Ryokan, with a visit to Unzen Hell. On Day 3, the highlights were the koi swimming town, a meal at Himematsuya (Guzukuri), and a visit to Shimabara Castle, concluding with dessert at Ginsui (Kanzarashi).' where id = 'Okk3GhYS-IwUoAIzwdSe6';
update content_bodies set title = '効能の高さで全国有数のラジウム温泉を求め阿賀野の里『五頭温泉郷』へ！', description = '皆さまこんにちは。ラジウム温泉に入ってみたくて新潟の村杉温泉へ行ってきました。宿泊先は角屋旅館で、もともと農家だった角屋さんは、今も自家栽培の野菜やお米を使った食事を提供しています。地産地消のお宿に惹かれ、こちらに決めました。ラジウム温泉は気体にラドンが多く含まれているので、訪れた際は温泉で深呼吸をたくさんしてください。私も過呼吸になるくらい深呼吸をして、とてもリフレッシュできました。元気になれました。' where id = 'xTWTIz9fTz01UrCxgrFSG';
update content_bodies set title = 'Visit the Renowned Radium Hot Springs of Gozu Onsen in Agano!', description = 'Hello everyone! I recently visited Muramatsu Onsen in Niigata, eager to experience the radium hot springs. I stayed at Kakuya Ryokan, which originally was a farm. They still grow their own vegetables and rice for meals, which attracted me to this farm-to-table accommodation. The radium hot springs here contain a high concentration of radon gas, so if you visit, make sure to take deep breaths while soaking in the onsen. I took so many deep breaths that I almost hyperventilated, but it was incredibly refreshing! I felt revitalized and full of energy.' where id = '8iyya6VUwlN9toXmtF68p';
update content_bodies set title = '【ドローン映像】長崎ばーどアイ4K　「緑のトンネル」', description = '『長崎ばーどアイ』では、四季折々の長崎の風景を4Kドローン映像で楽しむことができます。この映像は、2020年の初夏に雲仙市小浜町で撮影された「緑のトンネル」を紹介しています。長崎の美しい風景を堪能できる映像体験をお楽しみください。' where id = 'njac0-KmZZ-OMV6Ud61cr';
update content_bodies set title = 'NAGASAKI Bird''s Eye - 4K Drone Footage', description = 'Experience the stunning landscapes of Nagasaki through 4K drone footage. This video showcases the beauty of the ''Green Tunnel'' located in Obama, Nagasaki, captured in the summer of 2020. Enjoy a visual journey that highlights the unique charm of this region.' where id = 'j1iI-b0H5pliC-PsYJGB_';
update content_bodies set title = '【ドローン映像】長崎ばーどアイ4K　「長崎の夏景色」', description = '『長崎ばーどアイ』では、4Kドローン映像を通じて長崎の美しい夏の風景を楽しむことができます。2016年以降に撮影された長崎各所の映像が収められており、視聴者はこの地域の魅力を発見し、旅行気分を味わうことができます。' where id = 'aJlNMiAeUzBkIUnjoIkgr';
update content_bodies set title = 'NAGASAKI Bird''s Eye - 4K Drone Footage', description = 'Experience the stunning summer landscapes of Nagasaki through 4K drone footage. This video showcases various locations in Nagasaki, captured since 2016, allowing viewers to dream, travel, and discover the beauty of this region during the summer season.' where id = 'lk_RxajkYodZTR4s80vMs';
update content_bodies set title = '【Drone空撮映像】楽山園と煌', description = 'この映像は、甘楽町の名勝「楽山園」を空から捉え、新たな魅力を発見することを目的としています。楽山園は江戸時代初期に織田氏によって造られた庭園で、池泉回遊式の借景庭園として知られています。池を中心に景石が配置され、起伏のある地形が作られています。また、全国的に珍しい五角形の「腰掛茶屋」や「梅の茶屋」など、複数の茶屋が点在し、園路も工夫されています。さらに、4月20日から30日まで行われた楽山園のライトアップイベント「煌」の様子も収められています。撮影にはDJI Phantom 4 Pro V2.0を使用し、編集はAdobe Premiere Pro 2019で行いました。チャンネル登録もお願いします。' where id = 's4e3SKiUQxRfLJHxI8EqX';
update content_bodies set title = 'Drone Aerial Footage of Rakuzan-en and Kirameki', description = 'This video captures the beauty of Kanra Town from above, showcasing the scenic Rakuzan-en garden, a historic site established by the Oda clan in the early Edo period. The garden features a pond with carefully placed stones, creating a picturesque landscape with hills and various tea houses, including the unique pentagonal ''Koshikake Chaya.'' Additionally, the footage includes highlights from the ''Kirameki'' light-up event held at Rakuzan-en from April 20 to April 30. The aerial shots were taken using a DJI Phantom 4 Pro V2.0 and edited with Adobe Premiere Pro 2019. For more updates, please subscribe to the channel.' where id = 'W8RpbggDmoXEPLczQfxdH';
update content_bodies set title = 'サンセットカヤック', description = '上島町の離島エコツーリズムの一環として提供される「シーカヤック サンセットツアー」は、夕暮れ時の海でカヤックを楽しむ体験です。参加者は、美しい景色や自然環境を満喫しながら、このアウトドアアクティビティに参加することができます。' where id = 'yf4xTh4w9By4lJX1S57lA';
update content_bodies set title = 'Sunset Kayak', description = 'The Sunset Kayak tour is part of the eco-tourism offerings in Kamijima Town, focusing on the experience of sea kayaking during sunset. Participants can enjoy the beautiful scenery and natural environment of the islands while engaging in this outdoor activity.' where id = 'Yde2-ws4_mVNKtR5mLDGv';
update content_bodies set title = '【2023・厳選秋旅】高知県津野町・梼原町で自然やグルメ、芸術に触れてみよう', description = '秋旅におすすめの高知県津野町・梼原町の魅力を紹介します。自然の美しさや地元の美味しい料理、世界的建築家・隈研吾の建築物が揃い、訪れる価値があります。主なスポットには、四国カルストの天狗高原、静かな白龍湖、そして美しい長沢の滝があります。地元の味を楽しむなら農家レストラン「くさぶき」がおすすめです。また、アート好きには「雲の上のギャラリー」や「雲の上の図書館」があり、独自の芸術表現を楽しむことができます。双名島の美しい景色も見逃せないポイントです。この旅は自然、文化、グルメの素晴らしい体験を約束します。' where id = 'TpF_e46wdEUc8H1O6WsjN';
update content_bodies set title = 'Recommended Autumn Trip 2023: Experience Nature, Gourmet Food, and Art in Tsuno and Yusuhara Towns, Kochi Prefecture', description = 'This autumn, explore the captivating spots in Tsuno and Yusuhara towns in Kochi Prefecture. The area is rich in natural beauty, delicious local cuisine, and remarkable architecture by renowned architect Kengo Kuma. Key attractions include the Shikoku Karst at Tengu Plateau, the serene Hakuryuko Lake, and the stunning Nagasawa Falls. For a taste of local flavors, visit the farmer''s restaurant Kusabuki. Art enthusiasts can enjoy the Cloud Gallery and the Cloud Library, both showcasing unique artistic expressions. Don''t miss the scenic twin islands, which add to the charm of this region. This trip promises a delightful blend of nature, culture, and culinary experiences.' where id = '41CYSTOsJH7z6bspttY5C';
update content_bodies set title = '心で巡る、フラリ旅。in Kochi', description = 'ゴールデンウィークに高知県の黒潮町、四万十市、土佐清水市のおすすめスポットを紹介します。ひらひらなTシャツ、碧い海、新鮮な海の幸、ほっと一息つけるカフェなど、すべてがここにあります。幡多の大地を踏みしめて、あなたの休日をより素敵にしましょう。心のままに旅をし、高知の魅力を感じてください。いつでも帰りたくなる高知の今をお届けします。砂浜美術館や黒潮一番館、CAFE69LOGなど、取材協力のスポットも紹介しています。' where id = 'qHL9qoKVOTMCDmhdz7s_P';
update content_bodies set title = 'A Heartfelt Journey in Kochi', description = 'This Golden Week, explore the charming spots in Kochi Prefecture, including Kuroshio Town, Shimanto City, and Tosashimizu City. Experience the gentle breeze of T-shirts, the azure sea, fresh seafood, and cozy cafes—all waiting for you. Step onto the land of Hata and make your holiday even more wonderful. Travel freely, following your heart. Kochi offers a current glimpse of its beauty, making you want to return anytime. Discover the local attractions with the help of various partners, including Sunabi Art Museum, Kuroshio Ichibankan, and CAFE69LOG.' where id = '-3tpopzptby0qnJgjadSN';
update content_bodies set title = '仁淀川四季・春', description = '映画『竜とそばかすの姫』の舞台のモデルとなり話題となった″奇跡の清流″仁淀川。その美しさを集めたのが、春の″仁淀ブルー″です。″仁淀ブルー″の名付け親であるカメラマン高橋宣之さんが撮影した映像を通じて、春の仁淀川の魅力をお楽しみください。編集は細木拓也さんが担当しています。' where id = '_r3gX7moYI9VMm1fiT8UJ';
update content_bodies set title = 'Niyodo River Seasons - Spring', description = 'The Niyodo River, known as the ''miraculous clear stream,'' gained attention as a model for the setting of the movie ''Belle.'' This collection showcases the beauty of ''Niyodo Blue'' in spring, captured by photographer Nobuyuki Takahashi, who coined the term ''Niyodo Blue.'' The footage was edited by Takuya Hosoki.' where id = 'Od1LbnHQ1YVCSx3-FS44U';
update content_bodies set title = 'シラカバイク(e-Bike)で白樺高原を大満喫!', description = '観光やグルメ、アクティビティスポットを気ままに巡るにはe-Bikeが最適です。電動アシストにより、登り坂も楽々。太いタイヤで安定感も抜群です。高原を熟知したスタッフが厳選したコースをGPSがナビゲートしてくれるので、安心して楽しむことができます。' where id = '6qQvjNXKD6AmRM4ctVHpB';
update content_bodies set title = 'Enjoy the Shirakaba Plateau with Sherakabike (e-Bike)!', description = 'Exploring the various sightseeing, gourmet, and activity spots at your own pace is best done with an e-Bike! With electric assistance, even uphill climbs are a breeze. The wide tires provide excellent stability. You can feel secure as GPS navigation guides you along carefully selected routes by staff who know the plateau inside and out!' where id = 'nNXtjaSqN5bROpVmmScIY';
update content_bodies set title = '【絶景茨城】袋田の滝 氷瀑', description = '袋田の滝は日本三大名瀑の一つとして知られ、冬の厳しい寒さの中で滝全体が真っ白に凍結する美しい姿を見せます。また、大子町の風物詩である「大子来人～ダイゴライト～」では、自然と光が織りなす神秘的な空間が広がり、袋田の滝の新たな魅力を発見することができます。' where id = 'rzfGZlkP78fZCEyN4hKvW';
update content_bodies set title = 'Fukuroda Falls Icefall | VISIT IBARAKI, JAPAN', description = 'Fukuroda Falls is one of Japan''s three great waterfalls, renowned for its stunning beauty. During the harsh winter months, the entire waterfall freezes, creating a breathtaking sight. Additionally, the ''Daigo Light'' event in Daigo Town transforms the area into a mystical space where nature and light combine, revealing new charms of Fukuroda Falls.' where id = '7WeCjzzOuvfvyx0k6qPgk';
update content_bodies set title = '絶景茨城｜いばらきフラワーパーク', description = '2021年4月にリニューアルした「いばらきフラワーパーク」では、県花のバラ900品種を含む多様な花々を五感で楽しむことができます。春にはバラ、夏にはアジサイ、秋にはヒマワリやダリア、冬にはイルミネーションと、四季折々の見どころが用意されています。訪れることで、自然の美しさを存分に体感できる場所です。' where id = 'qv_PGCgJT1HRoDNPGl2Qh';
update content_bodies set title = 'Ibaraki Flower Park: A Scenic Spot in Ibaraki', description = 'Renewed in April 2021, Ibaraki Flower Park offers visitors the chance to enjoy a variety of flowers through their senses, including 900 varieties of the prefectural flower, roses. The park showcases seasonal highlights such as roses, hydrangeas, sunflowers, dahlias, cosmos, and winter illuminations, allowing guests to experience the beauty of nature throughout the year.' where id = 'sthg13DOZKKSAfnt4ZBtv';
update content_bodies set title = '【絶景茨城】日立市かみね動物園', description = '太平洋を望む絶好のロケーションに位置する日立市かみね動物園は、長年にわたり多くの人々に愛されてきました。ここでは、ゾウやリスザル、レッサーパンダ、キリン、ペンギン、カワウソ、イグアナなど、可愛い動物たちの姿を楽しむことができます。訪れる人々が動物たちの姿に癒されることを願っています。' where id = 'c9GeXEmT9ra-qqvPR3mHu';
update content_bodies set title = 'Hitachi City Kamine Zoo: A Scenic Spot in Ibaraki', description = 'Located with a stunning view of the Pacific Ocean, Hitachi City Kamine Zoo has been cherished for many years. Visitors can enjoy the sight of adorable animals such as elephants, squirrel monkeys, red pandas, giraffes, penguins, otters, and iguanas. The zoo aims to provide a heartwarming experience through its diverse animal exhibits.' where id = '_rEBJKQxY12WnYsSn3fZi';
update content_bodies set title = '祝・日本ジオパーク認定／絶景茨城：筑波山', description = '筑波山は「西の富士、東の筑波」として親しまれ、朝夕に色を変えることから「紫峰」とも呼ばれています。男体山と女体山の二つの峰を持ち、古くから信仰の対象として栄えてきました。登山道では、道標や江戸時代の町並みを楽しむことができ、年間を通じて登山やハイキングを通じて自然と親しむことができます。また、ケーブルカーやロープウェイを利用すれば、誰でも簡単に山頂にアクセスでき、美しい眺望を楽しむことができます。' where id = '5nqUwA6Aubcq2GTouqxPp';
update content_bodies set title = 'Tsukuba Mountain: A Certified Japan Geopark and Scenic Spot in Ibaraki', description = 'Tsukuba Mountain, affectionately known as ''the Fuji of the East,'' is renowned for its changing colors at dawn and dusk, earning it the nickname ''Purple Peak.'' It features two peaks, Nantai and Nyotai, and has been a site of worship for centuries. The hiking trails offer a glimpse into the historical Edo period with signposts and traditional townscapes. Visitors can enjoy nature year-round through hiking and climbing. For those seeking an easier ascent, a cable car and ropeway provide access to the summit, allowing everyone, from children to the elderly, to appreciate the stunning views.' where id = 'n00KMBOV734MwjsL8gX6f';
update content_bodies set title = '【絶景茨城／ユネスコ無形文化遺産】結城紬｜VISIT IBARAKI, JAPAN', description = '結城紬は、日本の絹織物の原点を今に伝える布であり、その制作工程はユネスコの無形文化遺産に登録されています。古くからの伝統と匠たちの技を収めた映像が紹介されており、結城紬の魅力を感じることができます。' where id = 'ruxK3SerwS8TP6GcMWqOQ';
update content_bodies set title = 'Spectacular Ibaraki / UNESCO Intangible Cultural Heritage: Yuki Tsumugi | VISIT IBARAKI, JAPAN', description = 'Yuki Tsumugi is a fabric that conveys the origins of Japanese silk weaving. Its production process is registered as a UNESCO Intangible Cultural Heritage. The video captures the scenery of traditional craftsmanship and the skills of artisans that have been passed down through generations.' where id = 'dS485YSMf5aZzUaFTGV37';
update content_bodies set title = '【絶景茨城】コキア｜VISIT IBARAKI, JAPAN', description = '国営ひたち海浜公園におけるコキアの夏と秋の美しい様子を紹介しています。夏の昼間には爽やかな緑色のコキアが広がり、夜には期間限定でライトアップされ、カラフルな景色が楽しめます。秋になると、コキアは深紅に染まり、絶景を提供します。ぜひその美しさを堪能してください。' where id = 'rBZY-SHpDYLKDNB4voNLK';
update content_bodies set title = 'Stunning Ibaraki: Kochia | VISIT IBARAKI, JAPAN', description = 'This captures the beauty of Kochia at the National Hitachi Seaside Park during summer and autumn. In summer, the vibrant green Kochia can be seen during the day, and at night, it is illuminated with colorful lights for a limited time. In autumn, the Kochia transforms into a deep crimson, offering a breathtaking view. Enjoy the stunning scenery!' where id = '2Atb6cbybz2u4iUfkluQd';
update content_bodies set title = '【絶景茨城】保和苑の紫陽花（あじさい）', description = '2015年6月16日撮影の保和苑は、名君・徳川光圀が愛した桂岸寺の庭園です。初夏には約6000株の色鮮やかなあじさいが咲き誇り、その絶景は訪れる人々を魅了します。' where id = 'F4po_6hghknTKNupwgRbZ';
update content_bodies set title = 'Stunning Hydrangeas at Howaen Garden, Ibaraki [4K]', description = 'On June 16, 2015, the Howaen Garden, associated with the famous Tokugawa Mitsukuni, showcases approximately 6,000 vibrant hydrangeas in early summer. This breathtaking view captivates many visitors who come to enjoy the beauty of the garden.' where id = 'oyOEBPbPtLvZf5BkFox6f';
update content_bodies set title = '【絶景茨城】桜［4K］茨城県土浦市', description = '2015年3月31日、茨城県土浦市で土浦桜まつりが開催され、多くの桜の名所が紹介されました。特に真鍋小学校にある樹齢約100年のソメイヨシノは県の天然記念物に指定されています。祭りの期間は2015年3月21日から4月12日までで、各所でライトアップやイベントが行われ、多くの人々で賑わいました。問い合わせは一般社団法人土浦市観光協会まで。' where id = 'q8P8iAcpSqQ1U-FKQrv6x';
update content_bodies set title = 'Stunning Ibaraki: Cherry Blossoms [4K] in Tsuchiura City, Ibaraki Prefecture', description = 'On March 31, 2015, the Tsuchiura Cherry Blossom Festival was held in Tsuchiura City, Ibaraki Prefecture, featuring numerous famous cherry blossom spots. Notably, the Somei Yoshino cherry tree at Manabe Elementary School, which is approximately 100 years old, is designated as a natural monument of the prefecture. During the festival period, from March 21 to April 12, various events and illuminations took place, attracting many visitors. For inquiries, contact the Tsuchiura City Tourism Association.' where id = 'YPWUlirjsF3bb9Ztn_tlK';
update content_bodies set title = '【絶景茨城】 茨城の水辺　- Relaxation in IBARAKI -', description = '茨城の美しい水辺、滝や渓谷を紹介します。大子町の月待の滝は、高さ17メートル、幅12メートルの三筋の滝で、裏側からも見ることができます。夏は子どもたちの水遊び、秋は紅葉、冬は氷瀑と、四季折々の姿を楽しめます。常陸太田市の竜神峡は、V字形の美しい渓谷で、竜神ダムの上に竜神大吊橋があります。亀ヶ淵では清らかな水を楽しめ、冬はバードウォッチング、春から秋は自然散策に最適です。高萩市の花貫渓谷では、大小さまざまな淵と滝が連なり、春の新緑や秋の紅葉、冬の雪景色を楽しむことができます。' where id = 'KeT7sANWjUBoTZKPX5hvu';
update content_bodies set title = 'Scenic Ibaraki: Water Landscapes - Relaxation in IBARAKI -', description = 'This article introduces the beautiful water landscapes of Ibaraki, including waterfalls and gorges. The Tsukimachi Falls in Daigo Town features a 17-meter high and 12-meter wide waterfall with three streams, offering views from behind the falls. In summer, children can play in the water, while autumn brings vibrant foliage and winter showcases ice falls. The Ryujin Gorge in Hitachiota City is a stunning V-shaped valley located in the Oku-Kuji Prefectural Natural Park, with the iconic Ryujin Big Suspension Bridge above the Ryujin Dam. Kamegabay, located centrally in the gorge, is accessible by foot and is perfect for birdwatching in winter and nature walks from spring to autumn. Finally, the Hanakuna Gorge in Takahagi City features various pools and waterfalls, allowing visitors to enjoy the changing nature through the seasons, from fresh greenery in spring to autumn leaves and winter snow scenes.' where id = 'FdAQlwHHF5lYBw1TpstYD';
update content_bodies set title = '【ドローン映像】長崎ばーどアイ4K　「光と風　諫早平野の夏」', description = '『長崎ばーどアイ』では、四季折々の長崎の風景を4Kドローン映像で楽しむことができます。この映像は2020年の夏に撮影されたもので、諫早平野の美しい光と風の様子を捉えています。長崎の素晴らしい景色を空から体験し、旅を楽しむことができる映像です。' where id = 'GsLa8EEJosWJC7hXdqazU';
update content_bodies set title = 'NAGASAKI Bird''s Eye - 4K Drone Footage', description = 'Experience the beauty of Nagasaki''s landscapes through stunning 4K drone footage. This video showcases the Isahaya Plain during the summer of 2020, highlighting the interplay of light and wind in this picturesque region. Discover and enjoy the amazing sights of Nagasaki as you travel through this breathtaking aerial view.' where id = 'zTgbQj5VduW9Bj_mdxeV7';
update content_bodies set title = 'ドローン映像　長崎ばーどアイ４K　島鉄南目線の風景', description = 'この映像は、長崎の美しい風景を4Kドローン映像で紹介しています。特に島鉄南の視点から捉えた景色が特徴で、地域の独特な風景や特徴を鮮明に映し出しています。長崎放送との関連があり、ドローン技術を用いて空からの視点で地域を表現しています。' where id = 'cVFx0mLet2ebUd_u20e6j';
update content_bodies set title = 'Drone Footage: Nagasaki Bird Eye 4K - Views from Shimakisen Minami', description = 'This video showcases stunning 4K drone footage of Nagasaki, specifically from the perspective of Shimakisen Minami. The visuals highlight the beauty of the region, capturing its unique landscapes and features. The content is associated with Nagasaki Broadcasting and emphasizes the use of drone technology to present the area from a bird''s-eye view.' where id = 'DRfboECuHCgTGbrf7bjp-';
update content_bodies set title = '宇和島城に行ってきました！(天守編)', description = '愛媛県宇和島市に位置する宇和島城は、標高80mの丘の上に築かれた平山城です。伊達氏の2代目、宗利によって大規模な改修が行われ、現在の形になりました。天守閣は国の重要文化財に指定されています。また、この動画の最後には、宇和島市で出会った猫の映像も収められています。登城編の動画は、こちらからご覧いただけます: https://youtu.be/bJbAEg2EYcE' where id = 'SPWxCvCRbU8zbx4wFK02G';
update content_bodies set title = 'Visit to Uwajima Castle! (Tenshu Edition)', description = 'This is Uwajima Castle located in Uwajima City, Ehime Prefecture. Uwajima Castle is a flat mountain castle built on a hill at an elevation of 80 meters. It was significantly renovated by the second generation of the Date clan, Muneyoshi, to take its current form. The main keep (tenshu) is designated as an important cultural property by the country. At the end of this video, there is footage of a cat found in Uwajima City, Ehime Prefecture. For the climbing edition, visit: https://youtu.be/bJbAEg2EYcE' where id = 'GspYfuJ4n3G1qBBcwJ3hQ';
update content_bodies set title = 'Hyperlapse Fukuoka City, Japan 4k (Ultra HD) - 福岡 Short ver.', description = '「Hyperlapse Fukuoka City」という観光プロモーション映像は、福岡市の美しさや魅力をハイパーラプス形式で紹介しています。映像は映像作家の栄川幸が監督し、音楽はWolves Unite Japan, Inc.が提供しています。福岡市についての詳細は、観光情報サイト「よかなび」や「gofukuoka.jp」を訪れることで得られます。動画のフルバージョンはYouTubeで視聴可能です。この映像は福岡市の観光促進活動の一環であり、著作権で保護されています。動画に関する問い合わせは、福岡市経済観光文化局に連絡してください。' where id = 'w1yg-4oHRU5XwFL9AaBQK';
update content_bodies set title = 'Hyperlapse Fukuoka City, Japan 4k (Ultra HD) - 福岡 Short ver.', description = 'This promotional video titled ''Hyperlapse Fukuoka City'' showcases the beauty and attractions of Fukuoka City, Japan, in an engaging hyperlapse format. Directed by Yuki Eikawa, the video features music by Wolves Unite Japan, Inc. For more information about Fukuoka City, viewers can visit the official tourism websites, including ''よかなび'' and ''gofukuoka.jp''. The full version of the video is available on YouTube. The video is part of Fukuoka City''s efforts to promote tourism and is protected by copyright. For inquiries regarding the video, contact the Fukuoka City Economic Tourism and Culture Bureau.' where id = '6Dx0n-W9B-OS6nNS5d1jV';
update content_bodies set title = 'Hyperlapse Fukuoka City, Japan 4k (Ultra HD) - 福岡 30s ver.(food)', description = '「Hyperlapse Fukuoka City」は、福岡市の魅力や観光名所を紹介するプロモーション映像です。監督は栄川幸で、音楽はWolves Unite Japan, Inc.が担当しています。この映像は、福岡市の観光を促進するための取り組みの一環として制作されました。詳細は、観光情報サイト「よかなび」や「FUKUOKA CITY Official Tourist Guide」を訪れることで確認できます。動画のフルバージョンはYouTubeで視聴可能で、さらに情報を得るためのSNSリンクも提供されています。著作権は福岡市に帰属します。' where id = 'ZnlcFzCkm2CIVeI0rGHQW';
update content_bodies set title = 'Hyperlapse Fukuoka City, Japan 4k (Ultra HD) - Fukuoka 30s ver.(food)', description = 'This promotional video titled ''Hyperlapse Fukuoka City'' showcases the vibrant culture and attractions of Fukuoka City, Japan. It is directed by Yuki Eikawa and features music by Wolves Unite Japan, Inc. The video is part of a tourism initiative to highlight the city''s offerings. For more information, viewers can visit the official tourism websites, including ''よかなび'' and ''FUKUOKA CITY Official Tourist Guide''. The full version of the video is available on YouTube, and there are various social media links provided for further engagement. The video is protected under Fukuoka City All Rights Reserved.' where id = 'i1JDgO6DVeewiBmFK2QjO';
update content_bodies set title = '大人気のモンブランクレープ＆かわいいチョークアートが魅力のカフェ🚙', description = '三重県亀山市関町にある「Poiont8」は、ドライブ中に訪れるべきカフェです。名阪関ドライブイン内に位置し、極細のモンブランクレープが人気で、オーガニック焼き栗を使用した濃厚な味わいが特徴です。また、季節ごとに変わるチョークアートはフォトスポットとしてもおすすめで、クレープと一緒に記念撮影を楽しむことができます。家族旅行やカップル、友人同士でも楽しめる、魅力的な体験が待っています。' where id = 'Wlx7d_6VF29QBvtTvzN9-';
update content_bodies set title = 'Popular Montblanc crepe & cute chalk art “Poiont8”', description = 'Located in Sekicho, Kameyama City, ''Poiont8'' is a must-visit café when driving through Mie Prefecture. Situated at the Meihan Seki Drive-in, this café is famous for its ultra-fine Mont Blanc crepe, generously filled with rich flavors from organic roasted chestnuts. The seasonal chalk art provides a charming backdrop for photos, making it a perfect spot for commemorative pictures with your crepe. This café is ideal for families, couples, and friends alike, offering a delightful experience for all visitors.' where id = 'qwJuDEvkvC3iukY2lQ8X_';
update content_bodies set title = 'ロープウエイで空中絶景散歩 #御在所岳', description = '三重県の菰野町湯の山温泉に位置する御在所岳は、旅行者にとって外せない観光スポットです。ここでは、季節ごとの美しい自然や巨大な岩を楽しむことができます。ロープウエイを利用して山頂まで登ると、展望台からは伊勢湾や知多半島の絶景が広がります。晴れた日には富士山も見ることができるかもしれません。三重県を訪れる際には、ぜひ立ち寄りたい場所です。' where id = 'isrqfNFKQcFUKGv2QA4OM';
update content_bodies set title = 'Scenic Walk on the Ropeway at Gozaisho-dake', description = 'Gozaisho-dake, located in Yunoyama Onsen, Komono Town, is a must-visit destination in Mie Prefecture. This popular scenic spot offers breathtaking views of seasonal nature and massive exposed rocks. Visitors can take a ropeway to the mountain''s summit, where an observation deck provides panoramic views of Ise Bay and the Chita Peninsula. On clear days, there is even a chance to see Mt. Fuji. This location is a highlight for anyone traveling in Mie Prefecture, showcasing the region''s natural beauty and attractions.' where id = 'oi6IosJfybq2HnrnvSFT8';
update content_bodies set title = '初心者やお子様も安心の快適すぎるグランピングが楽しめる施設！', description = '伊勢志摩エバーグレイズでは、初心者やお子様に最適な快適なグランピング体験が楽しめます。「アメリカンアウトドアリゾート」をテーマにした広大な敷地には、キャビンやテント、グランピングサイトが多数あります。その中でも人気の「カリブ」サイトは、朝日や星空を眺めながら入れる屋外バスタブや、室内にトイレ・シャワールームが完備されています。また、プライベートラグーンでのカヌーも楽しめます。美しい風景を独り占めできる完全プライベート空間で、夏の思い出を作りましょう。三重県志摩市に位置し、テントは4400円から、グランピングは33600円から利用可能です。チェックインは14:00から、チェックアウトは11:00までです。' where id = 'oxX0HVWuMk8zPWapJeQQA';
update content_bodies set title = 'Comfortable Glamping Experience for Beginners and Kids at Ise-Shima Everglades!', description = 'Ise-Shima Everglades offers a comfortable glamping experience suitable for beginners and children. The facility features a vast area themed around ''American Outdoor Resort,'' with numerous cabins, tents, and glamping sites. Among them, the popular ''Carib'' glamping site includes an outdoor bathtub for enjoying sunrises and starry skies, along with indoor toilet and shower facilities. Guests can also enjoy a private lagoon with unlimited canoeing. Create unforgettable summer memories in the beautiful private space of Ise-Shima Everglades. Located in Mie Prefecture, the facility offers various accommodations starting from 4,400 yen for tents and 33,600 yen for glamping. Check-in starts at 14:00, and check-out is until 11:00.' where id = 'rKYaaIn4-uVU9CYxADffw';
update content_bodies set title = 'Hyperlapse Fukuoka City, Japan 4k (Ultra HD) - 福岡 30s ver.(landmark)', description = '「Hyperlapse Fukuoka City」は、福岡市の美しさやランドマークをダイナミックなハイパーラプス形式で紹介する観光プロモーション映像です。この映像は、観光客を惹きつけることを目的としており、福岡市の魅力を強調しています。監督は栄川幸、音楽はWolves Unite Japan, Inc.が担当しています。福岡市に関する詳細は、提供された公式観光サイトを訪れることで確認できます。動画のフルバージョンはYouTubeで視聴可能で、さらなる情報を得るための各種SNSリンクも用意されています。この映像は福岡市の観光促進の一環であり、著作権で保護されています。' where id = 'OclpDp6G1wQYWsS3S2uSF';
update content_bodies set title = 'Hyperlapse Fukuoka City, Japan 4k (Ultra HD) - Fukuoka 30s ver.(landmark)', description = 'This promotional video titled ''Hyperlapse Fukuoka City'' showcases the beauty and landmarks of Fukuoka City in a dynamic hyperlapse format. It aims to attract tourists by highlighting the city''s attractions. The video is directed by Yuki Eikawa and features music by Wolves Unite Japan, Inc. For more information about Fukuoka City, viewers can visit the official tourism websites provided. The full version of the video is available on YouTube, and there are various social media links for further engagement. The video is part of Fukuoka City''s marketing efforts to promote tourism and is protected by copyright.' where id = 'vwOEesTjdUj-Hu5Ljqc5W';
update content_bodies set title = 'ハイパーラプス 福岡市 4k (ウルトラHD) - 福岡 30秒バージョン（伝統的）', description = '「ハイパーラプス 福岡市」というタイトルのこの動画は、福岡市の観光プロモーション映像です。ダイナミックなハイパーラプス形式で、福岡市の魅力を紹介しています。福岡市についての詳細は、公式観光サイト「よかなび」や「Go Fukuoka」を訪れることで学ぶことができます。映像は映像作家の栄川幸が監督し、音楽はWolves Unite Japan, Inc.が提供しています。動画のフルバージョンはYouTubeで視聴可能で、福岡市の公式YouTubeチャンネルでは登録を促しています。動画に関する問い合わせ先や、福岡市のSNSリンクも提供されています。' where id = 'yX5zRVgNBuaBk_W-7NA7F';
update content_bodies set title = 'Hyperlapse Fukuoka City, Japan 4k (Ultra HD) - Fukuoka 30s ver.(traditional)', description = 'The video titled ''Hyperlapse Fukuoka City'' serves as a promotional piece for tourism in Fukuoka City, Japan. It showcases the city''s attractions through a dynamic hyperlapse format. Viewers can learn more about Fukuoka City by visiting the official tourism websites, including ''Yokanavi'' and ''Go Fukuoka.'' The film is directed by Yuki Eikawa, with music provided by Wolves Unite Japan, Inc. The video is available in a full version on YouTube, and the official Fukuoka City YouTube channel encourages subscriptions. Additional contact information for inquiries about the video is provided, along with links to Fukuoka City''s social media platforms.' where id = '5lrLcrsjS8CDNwTrStbcE';
update content_bodies set title = 'Enchanting Tokyo 7分間の奇跡', description = 'アメリカ人のビデオ記者チャーリー・ジェームズさんが、東京での仕事を通じて「すごい！面白い！」と感じたことを取材しました。この動画では、新幹線の清掃 crew がわずか7分で清掃を終え、再び出発する様子を撮影しています。東京駅での迅速かつ正確な清掃作業は、快適な旅を実現するための重要な要素であり、このプロセスを「7分間の奇跡」として紹介しています。' where id = 'tJrHvvTeItovqPCrK4AD5';
update content_bodies set title = 'Enchanting Tokyo 7-Minute Miracle', description = 'Charli James, a journalist for Dateline Tokyo, explored the impressive efficiency of the Shinkansen bullet train cleaning crew in a video titled ''7-Minute Miracle.'' The footage captures the rapid turnaround process at Tokyo Station, showcasing how the crew completes thorough cleaning in just seven minutes, ensuring a comfortable travel experience for passengers. This remarkable feat highlights the dedication and precision of the cleaning team, contributing to the overall excellence of Japan''s transportation system.' where id = 'b_kX1WvMrdEbCFzqw317z';
update content_bodies set title = '【神楽男子】中江岩戸神楽今年初の定期公演', description = '令和3年4月4日、阿蘇市波野の中江神楽殿で、この地域に伝わる伝統芸能の中江岩戸神楽の今年度初の定期公演が開催されました。地域の文化を継承する重要なイベントであり、多くの観客が訪れ、伝統的な演目を楽しみました。' where id = 'aLcJGSrhjSQYzgPc4bHA2';
update content_bodies set title = 'Nakae Iwato Kagura''s First Regular Performance of the Year', description = 'On April 4, 2021, the first regular performance of the year for Nakae Iwato Kagura, a traditional performing art passed down in the region, was held at the Nakae Kagura Hall in Aso City, Namino.' where id = 'mKi8143nCLziRtUmZ7qvA';
update content_bodies set title = '【GOTO ISLAND】チルタイム', description = '五島列島、特に五島市と福江島がこの文脈で取り上げられています。この美しい地域でリラックスした時間を楽しむことに焦点が当てられています。' where id = 'rZXxHFq84LDE6BL8PxkY9';
update content_bodies set title = 'GOTO ISLAND - Chill Time', description = 'Goto Islands, specifically Goto City and Fukue Island, are highlighted in this context. The focus is on enjoying a relaxing time in this beautiful region.' where id = '1mquGu26XiaYdNp6AMKFM';
update content_bodies set title = '東京中央区観光紹介ムービー - 遊（アクティビティ）バージョン', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しており、特定の時期と場所でしか体験できない祭りやユニークなアクティビティに焦点を当てています。「遊」バージョンでは、夏と秋の祭りや、和紙作りや書道などの伝統的な技術が紹介されています。このビデオは、視聴者がこれらの体験に参加しているかのように感じられるように作られています。詳細については、東京中央区観光紹介ムービーのプレイリストにアクセスすることができ、さまざまな言語のバージョンが含まれています。' where id = 'UbQ75PxFAlstLi7frc6ln';
update content_bodies set title = 'Tokyo Chuo City Tourism Introduction Movie - Activity Version', description = 'This promotional video showcases the various tourist attractions of Tokyo Chuo City, focusing on unique experiences such as festivals and activities that can only be enjoyed at specific times and places. The ''Activity'' version highlights summer and fall festivals, as well as traditional crafts like paper making and Japanese lettering. The video aims to immerse viewers in these experiences, making them feel as if they have participated firsthand. For more information, viewers can access a playlist of the Tokyo Chuo City tourism introduction movies, which includes different versions in multiple languages.' where id = 'RBfAQSte4zlc7EOK9yL4y';
update content_bodies set title = '宇和島闘牛５月場所(2025.5.3)', description = '年に4回の晴れ舞台のひとつである宇和島闘牛5月場所が2025年5月3日に開催されました。闘牛のルールはシンプルで、牛同士が制限時間なしで戦い、逃げた方が敗けとなります。お天気にも恵まれ、ゴールデンウィーク中ということもあり、入場者数は2400人を超え、大盛況のうちに幕を閉じました。イベントは2時間半にわたり、主な戦いの箇所をまとめています。闘牛の魅力が少しでも伝わればと思っています。' where id = 'hJAKgmjYSe43NndPaR1iK';
update content_bodies set title = 'Uwajima Bullfighting May Tournament (May 3, 2025)', description = 'The Uwajima Bullfighting May Tournament, one of the four major events of the year, was held on May 3, 2025. The rules are straightforward: bulls fight without a time limit, and the one that flees loses. The event attracted over 2,400 attendees, benefiting from good weather during Japan''s Golden Week, making it a resounding success. Lasting two and a half hours, the tournament featured several key matches, which have been summarized. The aim is to share the appeal of bullfighting with a wider audience.' where id = 'r95pO2QtXuHCJlCQmRjIa';
update content_bodies set title = 'わかやまパンダファミリー（白浜アドベンチャーワールド）', description = '和歌山県インターネット放送局は、白浜アドベンチャーワールドにおけるわかやまパンダファミリーに関する情報やコンテンツを提供しています。' where id = 'uSyOFkyu5d5zdbnjV3ofY';
update content_bodies set title = 'Wakayama Panda Family (Shirahama Adventure World)', description = 'Wakayama Prefecture Internet Broadcasting Station provides information and content related to the Wakayama Panda Family at Shirahama Adventure World.' where id = '7UyWiaA_GA4jtAKmta0aU';
update content_bodies set title = '不忍池　上野公園の秋 | ボートライド', description = '上野公園にある不忍池で、秋の穏やかな風景を楽しみませんか。この歴史的な池は、蓮の池、ボートの池、鵜の池の3つのセクションに分かれています。ボートライドは、ボートの種類によって料金が異なり、サイクルボートは700円で2人、白鳥ボートは800円で3人、漕ぎボートは500円で3人が30分間楽しめます。池には、時には1万羽を超える渡り鳥や留鳥が生息しており、特にオナガガモやヒドリガモが多く見られます。また、池には多くの魚種が生息し、夏には蓮の花が水面を覆い尽くします。' where id = 'R9ENpXgbxn8TQn50bvr6f';
update content_bodies set title = 'Autumn at Shinobazu Pond | Boat Ride | Ueno Park', description = 'Experience the serene beauty of autumn at Shinobazu Pond, located in Ueno Park, Tokyo. This historically significant pond is divided into three sections: the Lotus Pond, the Boat Pond, and the Cormorant Pond. Visitors can enjoy boat rides with varying prices depending on the type of boat: cycle boats cost 700 yen for two adults, swan boats 800 yen for three adults, and row boats 500 yen for three adults, all for 30 minutes. The pond is home to numerous migratory and stationary birds, with populations sometimes exceeding ten thousand, including tufted ducks and northern pintails. The area also features a rich variety of fish and beautiful lotus flowers that bloom in summer, covering the water''s surface.' where id = 'hEmOM6MtuyWPPfAHuEbM_';
update content_bodies set title = '2021年度青函ツインシティ写真コンテスト・動画部門受賞作品（青森市民応募）', description = '2021年度青函ツインシティ写真コンテストの動画部門における受賞作品です。青森市民からの応募によるもので、地域の魅力や風景を映し出した作品が評価されました。' where id = '4vt0WDz094uUn8xcGMcFL';
update content_bodies set title = '2021 Aomori City Winners of the Seikan Twin City Photo Contest - Video Category', description = 'This is the award-winning work from the video category of the 2021 Seikan Twin City Photo Contest, submitted by Aomori City residents.' where id = 'uK-63WZkGVvxMGLrwn_io';
update content_bodies set title = 'ダイジェスト NISHITACHI', description = 'この動画は、ダイジェスト NISHITACHI を紹介しています。' where id = 'e-SKUpNVnQjJHMnyAm472';
update content_bodies set title = 'digest NISHITACHI', description = 'This video provides an introduction to digest NISHITACHI.' where id = 'PeKhWMd0iAuwgeplRzlwW';
update content_bodies set title = '【福島ヤバすぎ…】満腹確定！驚きのデカ盛りグルメ7選', description = '福島県の旅行や観光に役立つデカ盛りグルメスポットを7つ紹介する動画です。動画に載っていないおすすめがあれば、コメント欄でシェアしてください。旅行の達人チャンネルは、観光、宿泊、食事などの情報を提供し、旅行をより楽しくすることを目指しています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者に新しい可能性を発見することを促しています。公式SNSアカウントをフォローして、最新の旅行情報をチェックしてください。' where id = 'L698e7Swv5xiSKBt6OTIW';
update content_bodies set title = 'Fukushima''s Amazing Giant Portions: 7 Must-Try Gourmet Spots', description = 'This video introduces seven giant portion gourmet spots in Fukushima Prefecture, perfect for travelers and tourists. If you have any recommendations not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing various travel information, including sightseeing, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities. For more travel tips and updates, follow their official social media accounts.' where id = '-uN96ScZsuTXSl-69li4L';
update content_bodies set title = '長野で満喫できるランチグルメスポット７選', description = 'この動画では、長野県の旅行や観光に役立つランチスポットを7つ紹介しています。動画で紹介されていないおすすめがあれば、コメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、旅行をより楽しくすることを目指しています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを促しています。最新情報や旅行のヒントを得るために、公式のSNSアカウントをフォローすることもできます。' where id = 'kZqB-yfrTU3RtNNfi0zT9';
update content_bodies set title = '7 Lunch Gourmet Spots to Enjoy in Nagano', description = 'This video introduces seven recommended lunch spots in Nagano Prefecture, perfect for travelers and tourists. If you have any other recommendations not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to provide enjoyable travel information, covering various aspects such as sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. For more updates and travel tips, you can follow their official social media accounts.' where id = 'MPQ6DnhpjXJSpF6Z4l5Op';
update content_bodies set title = '【沖縄旅行】1泊2日のカップル旅行、レンタカーで巡る沖縄石垣島', description = 'この動画は沖縄県、特に石垣島をレンタカーで巡る旅行のガイドです。観光や旅行の参考にしていただければと思います。動画で紹介されていないおすすめスポットがあれば、ぜひコメント欄でシェアしてください。チャンネル「旅行の達人」は、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、旅行をより楽しくすることを目指しています。旅行を通じて人生を豊かにし、新しい可能性を発見することを促進することがミッションです。動画では、新石垣空港や絶景ポイント、地元の観光名所など、石垣島の主要なスポットについて詳しく紹介しています。' where id = 'VHMZrWG4P6Xryot4To5Ng';
update content_bodies set title = 'Okinawa Trip: A 1-Night, 2-Day Couple''s Journey Exploring Ishigaki Island by Rental Car', description = 'This video serves as a guide for traveling and sightseeing in Okinawa, specifically focusing on Ishigaki Island. It highlights the experience of exploring the island by rental car. Viewers are encouraged to share their own recommendations in the comments if they have suggestions not covered in the video. The channel, ''Travel Master,'' aims to provide enjoyable travel information, covering various aspects such as sightseeing, transportation, accommodation, and dining. The mission is to enrich lives through travel, encouraging viewers to discover new possibilities and enhance their experiences. The video includes details about key locations on Ishigaki Island, including the new Ishigaki Airport, scenic viewpoints, and local attractions.' where id = 'wEttUu0oe6EzH_YgtyXaL';
update content_bodies set title = '伊勢と奈良、神話からの古代の道', description = '伊勢と奈良は、日本の起源とされ、神話と精神性に満ちた地域です。伊勢神宮は神道の中心的な聖地であり、古代の墓や相撲、酒造りなどの伝統が、日本文化と政治の根源を反映しています。奈良は、歴史的な仏教寺院や神社で知られ、8世紀には日本の政治と宗教の中心地でした。奈良には世界最古の木造建築である法隆寺があり、シカが生息する緑豊かな公園に囲まれています。紀伊半島は、神聖な山々と古代の杉の森が広がり、数世紀にわたり神々が崇拝されてきました。伊勢神宮は日本の精神の揺りかごと見なされています。この地域は、修験道や相撲、海女文化などの古代の伝統を守り続けており、日本の最も古く、最も大切にされている伝統を体現しています。' where id = 'skM56l3nDzTOg6KXlifyD';
update content_bodies set title = 'ISE and NARA, Ancient paths from mythology', description = 'Ise and Nara are considered the origins of Japan, steeped in mythology and spirituality. Ise Jingu, a central site of Shintoism, along with ancient tombs and practices like Sumo and Sake, reflect the roots of Japanese culture and politics. Nara, known for its historic Buddhist temples and Shinto shrines, was the political and religious heart of Japan in the 8th century. The region is home to the oldest wooden building, Hōryū-ji, and is surrounded by lush parks inhabited by Sika deer. The Kii Peninsula, rich in sacred mountains and ancient cedar forests, is where kami have been worshipped for centuries. Ise Shrine is regarded as a cradle of the Japanese spirit. The area also preserves ancient traditions, including shugendō, Sumo, and the culture of ama, women divers who gather seafood. This region embodies Japan''s oldest and most cherished traditions.' where id = 'xvyFul46W_zbMXq7zx-Zt';
update content_bodies set title = '関西新発見の旅！「THE EXCITING KANSAI」福井編', description = '関西は、日本を代表する世界遺産や悠久の歴史に裏打ちされた伝統・文化が息づく地域です。今回は、まだ知られていない魅力を探る旅に出かけませんか？福井編では、太古には恐竜たちが生息し、美しい自然と豊かな水に恵まれたこの地のかけがえのない資源が、モノ作りに生かされてきた様子を紹介します。風土に合わせた様々な工芸品が作られてきた福井の魅力をお楽しみください。' where id = 'PtW1W3HOaNfm_m0C444OB';
update content_bodies set title = 'Discovering Exciting Kansai: Fukui Edition', description = 'Kansai, a region rich in Japan''s world heritage, history, and culture, invites you to explore its lesser-known attractions. This journey takes you to Fukui, a place where dinosaurs once roamed, surrounded by beautiful nature and abundant water resources. These invaluable assets have contributed to the creation of various crafts that reflect the local environment.' where id = 'H6rKBOcxztxnujxBdc4S4';
update content_bodies set title = '関西新発見の旅！「THE EXCITING KANSAI」山陰海岸編', description = '関西は、日本を代表する世界遺産や悠久の歴史に裏打ちされた伝統・文化が息づく地域です。ここにはまだ知られていない魅力がたくさんあり、それを探る楽しい旅に出かけませんか？今回は、山地が直接海に接する複雑に入り組んだ海岸、山陰海岸に焦点を当て、海からの豊かな恵みを受けながら、悠久の時を感じつつ自然を楽しむ旅をお届けします。' where id = '24pS9ew9juct7bc9zQZwv';
update content_bodies set title = 'Discover Exciting Kansai! The San''in Coast Edition', description = 'Kansai, a region rich in Japan''s world heritage, history, and culture, invites you to explore its many hidden charms. This journey focuses on the San''in Coast, where rugged mountains meet the sea, offering abundant natural blessings. Experience the timeless beauty and enjoy the nature of this unique coastal area.' where id = 'SfsUnG4DPTbv8W_fLWr0p';
update content_bodies set title = '関西新発見お旅！「THE EXCITING KANSAI」琵琶湖編', description = '日本の世界遺産や悠久の歴史、伝統文化が息づく関西には、まだ知られていない魅力がたくさんあります。今回は、豊かな水と自然に囲まれた滋賀県の琵琶湖に焦点を当て、楽しい旅に出かけることを提案します。この地域の魅力を探ることで、新たな発見が待っています。' where id = 'SEdmGWx1svXdO10hvDugu';
update content_bodies set title = 'Discover Exciting Kansai! Biwa Lake Edition', description = 'Kansai, a region rich in Japan''s world heritage, history, and culture, invites you to explore its many hidden charms. This edition focuses on Shiga Prefecture, home to the beautiful Biwa Lake, surrounded by abundant water and nature. Join us on a delightful journey to uncover the lesser-known attractions of this fascinating area.' where id = 'DfJ5jleOUim5x9nhJirQJ';
update content_bodies set title = '観光マナー映像「The Etiquette Guide to Fukuoka」（英語版）', description = 'このガイドは、福岡を訪れる際に役立つ重要なポイントを提供します。公共の場での行動、トイレの使い方、写真撮影のマナー、ゴミのポイ捨て禁止、喫煙ルールなど、地元の文化と良好な関係を築くためのマナーを解説しています。これらのガイドラインに従うことで、より良い体験ができるでしょう。福岡で素晴らしい時間をお過ごしください！' where id = 'Wk49EL-j91I0ir54-ZP6Q';
update content_bodies set title = 'The Etiquette Guide to Fukuoka (English Version)', description = 'This guide provides essential tips for enjoying your visit to Fukuoka. It covers important aspects of public behavior, including how to conduct oneself in public spaces, proper toilet usage, photography etiquette, littering prohibitions, and smoking regulations. Following these guidelines will enhance your experience and ensure a respectful interaction with the local culture. We wish you a wonderful time in Fukuoka!' where id = '3nXnnNh1zLBNxAzUuJ_KB';
update content_bodies set title = '【4,000株】春のバラまつり2022 in ASO MILK FACTORY', description = '阿蘇市小里に位置する観光施設「ASO MILK FACTORY」のローズガーデンでは、温室で育てられたバラが見頃を迎えています。開催期間は令和4年4月27日から6月12日までで、時間は9:30から17:00まで、バラドームは10:00から16:30まで開放されています。入場は無料で、売店ではバラの苗や肥料、バラに関連したグッズも販売されています。' where id = 'A4Tbc3PHF6ROeuv3xTd35';
update content_bodies set title = 'Spring Rose Festival 2022 at ASO MILK FACTORY', description = 'The Rose Garden at ASO MILK FACTORY in Aso City is showcasing roses grown in a greenhouse, which are now in full bloom. The festival runs from April 27, 2022, to June 12, 2022, and is open daily from 9:30 AM to 5:00 PM, with the rose dome accessible from 10:00 AM to 4:30 PM. Admission is free, and visitors can purchase rose seedlings, fertilizers, and rose-themed goods at the shop.' where id = 'Yg6wuREQ7g0FnnRRQkp-A';
update content_bodies set title = '【紅葉2021】阿蘇市の６スポット (モミジ/イチョウ/ススキ)', description = '2021年の阿蘇市における紅葉の様子を記録した動画です。美しい赤色のモミジや黄色のイチョウはもちろんのこと、カルデラの壮大な景色の中で黄金色に輝くススキも見どころです。来年以降の阿蘇市での紅葉散策の参考にぜひご覧ください。' where id = '8U57AOag7CPFF9T6bahE5';
update content_bodies set title = 'Autumn leaves in Aso City 2021 - 6 Spots (Maple/Ginkgo/Pampas Grass)', description = 'This video showcases the autumn leaves captured at six locations in Aso City in 2021. The vibrant red of the maple trees and the bright yellow of the ginkgoes are stunning, but the golden pampas grass shining in the vast caldera landscape is equally beautiful. This video serves as a reference for those planning to explore the autumn foliage in Aso City in the coming years.' where id = 'aJHFNkkKBKU3-NQCVDTWR';
update content_bodies set title = '令和3年 阿蘇市の桜', description = 'この動画は、令和3年の阿蘇市における桜の様子を撮影したものです。阿蘇体育館、年の神水源、浜神社、一の宮門前町商店街、坂梨公民館、浄土寺牧公園など、さまざまな場所が紹介されています。撮影日は3月29日と3月26日で、熊本県のこれらの地域における桜の美しさを映し出しています。' where id = '5enG1qIe9n9oa3-2uMFYP';
update content_bodies set title = 'Sakura in Aso City, 2021', description = 'This video captures the cherry blossoms in Aso City during 2021. It features various locations including Aso Gymnasium, the Year of the God Water Source, Hamajinja Shrine, Ichinomiya Monzen Town Shopping Street, Sakakari Community Center, and Jodoji Maki Park. The footage was taken on March 29 and March 26, showcasing the beauty of the cherry blossoms in these specific areas of Kumamoto Prefecture.' where id = 'Gx1XNH7W5Bh9N65HUE7Kv';
update content_bodies set title = '【優良賞】004 盛岡城 Let''s try『Tojo』', description = '南部家の居城である盛岡城は800年の歴史を持ち、日本100名城や東北三名城の一つに選ばれていますが、天守がないため知名度は低めです。しかし、盛岡城には独自の魅力があります。復元天守がなくても、江戸時代を感じることができる場所がここにあります。この思いから『登城』をテーマにしたプロモーション動画を制作しました。動画には日本語と英語の字幕が入っており、会社のPCやスマホでの視聴を想定しています。' where id = 'G8IHlNkRo4yhPoG_Cv97l';
update content_bodies set title = 'Morioka Castle: Let''s try ''Tojo'' - Award of Excellence', description = 'Morioka Castle, the residence of the Nanbu clan, boasts an 800-year history. Although it is recognized as one of Japan''s 100 Famous Castles and one of the three great castles of Tohoku, its lack of a main keep diminishes its name recognition. However, Morioka Castle has its own unique charm! Even without a reconstructed main keep, visitors can feel a connection to the Edo period. This inspired the creation of a promotional video themed around ''climbing the castle.'' The video includes subtitles in both Japanese and English, designed for viewing on company PCs and smartphones.' where id = '8Cp1n3Hocda-NDzGy1jNy';
update content_bodies set title = 'LOOK UP 熊本市 4K フルバージョン', description = '「見上げる」「良くなる」「元気を出す」という意味を持つ「LOOK UP」。旅人の女性が熊本市に降り立ち、風土に触れるうちに街に魅了され、軽快に前を向いて歩き出すストーリーです。終盤では、「パワー・元気」の象徴であるカラフルな風船が熊本城の上空に飛んでいきます。「落ちこんだり、元気がなくなったりした時は見上げてほしい。この街には私たちを支えてくれる熊本城がある。皆で上を向いて行こう！」というメッセージが込められています。' where id = 'rtxHCe7TMgEKZ_Lkjv9fo';
update content_bodies set title = 'LOOK UP Kumamoto City, JAPAN 4K Full ver', description = 'The title ''LOOK UP'' conveys meanings of ''looking up'', ''improving'', and ''gaining energy''. The story follows a female traveler who arrives in Kumamoto City and becomes enchanted by the local culture, walking forward with a light heart. In the finale, colorful balloons, symbolizing ''power and energy'', soar into the sky above Kumamoto Castle. The message encourages people to look up when feeling down, reminding them that Kumamoto Castle is there to support them. It invites everyone to keep looking up together!' where id = '_GKVcZi88z_GaRdgoIPho';
update content_bodies set title = '【東京中央区観光紹介ムービー】歩（Walk）バージョン（英語/3分バージョン）', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。「歩」バージョンでは、訪問者の視点から中央区での一日を描写し、代表的なエリアである日本橋、人形町、銀座、築地、佃、月島を歩きながら見る様子を捉えています。街中を散策しながら、歴史の伝統を感じ、最新のトレンドに触れることができる多様なシーンを通じて、中央区の魅力を体験することができます。' where id = '-3Nt191JFl8Xw-45b3Zkn';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie - Walk version (English/3min. version)', description = 'This promotional video showcases the tourist attractions of Tokyo Chuo City from a visitor''s perspective. The ''Walk'' version captures a day in Chuo City, highlighting key areas such as Nihonbashi, Ningyocho, Ginza, Tsukiji, Tsukuda, and Tsukishima. It presents the sights as if the viewer is strolling through the streets, experiencing the blend of historical traditions and modern trends. The video invites viewers to explore the diverse scenes of Chuo City, making it an engaging introduction to the area''s unique offerings.' where id = 'BbPtoHDd_1X64jykxj1NO';
update content_bodies set title = '【東京中央区観光紹介ムービー】遊（アクティビティ）バージョン', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。特に、特定の時期と場所でしか体験できない祭りやユニークなアクティビティに焦点を当てた「遊」バージョンでは、夏や秋の祭り、和紙作りや書道などの伝統的な体験が紹介されています。視聴者は、これらの体験に実際に参加しているかのように感じられる内容となっています。さらに、東京中央区観光紹介ムービーのプレイリストには、日本語、韓国語、中国語（繁体字・簡体字）バージョンも含まれています。' where id = 'hClPRruE_xNwB6sR7hJqG';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie - Activity version', description = 'This promotional video showcases various tourist attractions in Tokyo Chuo City, focusing on unique experiences such as festivals and activities that can only be enjoyed at specific times and places. The ''Activity'' version highlights summer and fall festivals, as well as traditional crafts like paper making and Japanese lettering. The video aims to immerse viewers in these experiences, making them feel as if they are participating firsthand. For more information, viewers can access a playlist of the Tokyo Chuo City tourism introduction movies, including versions in Japanese, Korean, and Chinese.' where id = 'bu4FdFtdv_lD6cSx6pUSd';
update content_bodies set title = '【東京中央区観光紹介ムービー】食（Food）バージョン', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。「食」バージョンは、「日本で食べたいものはすべて中央区にある」というコンセプトに基づいています。江戸時代から続く寿司、うなぎ、そば、天ぷらなどの「日本食」を中心に、ラーメンや地元の居酒屋、日本の和菓子など、地域の味も楽しめます。美味しそうな料理の美しい映像や、腕を振るうシェフ、見るだけでよだれが出るスイーツが満載で、実際に食べることなく中央区の豊かな食文化を体験できます。世界有数のグルメ都市の一つである中央区で、日本の多彩な料理を楽しんでください。' where id = 'Er9-_7Gu2FaRGrbQVdqCc';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie - Food version', description = 'This promotional video showcases the diverse tourist attractions of Tokyo Chuo City, focusing on its culinary offerings. The ''Food'' version emphasizes that Chuo City is a place where one can find all types of Japanese cuisine, including sushi, eel, soba, and tempura, which are part of Japan''s UNESCO Intangible Cultural Heritage. The video also highlights popular local dishes like ramen and traditional sweets. With stunning visuals of delectable food, talented chefs, and mouth-watering desserts, viewers can enjoy the essence of Chuo City''s rich gastronomic culture without tasting the food. As one of the world''s premier gourmet destinations, Chuo City offers a wide array of Japanese culinary experiences.' where id = 'Jhvq5fi-vEMJho7CJ04Dg';
update content_bodies set title = '【東京中央区観光紹介ムービー】食（Food）バージョン', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。「食」バージョンは、「日本で食べたいものはすべて中央区にある」というコンセプトに基づいています。ユネスコの無形文化遺産に登録された「和食」を中心に、江戸時代から続く寿司、うなぎ、そば、天ぷらなどの料理を楽しむことができます。また、ラーメンや地元の居酒屋、日本の和菓子など、地域の人々の味もテーマにしています。美味しそうな料理の美しい映像や、腕を振るうシェフの姿、見るだけでよだれが出るようなスイーツが楽しめ、実際に食べることなくとも、中央区の豊かな和食のバラエティを体験できます。' where id = 'C7yHtg8ulCq_3-0M0Pj82';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie - Food version', description = 'This promotional video showcases the diverse tourist attractions of Tokyo Chuo City, focusing on its culinary offerings. The ''Food'' version emphasizes that Chuo City is a place where you can find everything you want to eat in Japan. It highlights traditional Japanese cuisine, recognized as UNESCO Intangible Cultural Heritage, featuring dishes that date back to the Edo period, such as sushi, eel, soba, and tempura. The video also explores popular local foods like ramen and Japanese sweets, all presented through stunning visuals of delicious dishes and talented chefs. Viewers can enjoy the rich variety of Japanese food that Chuo City, known as one of the world''s great gourmet cities, has to offer.' where id = 'tlCjk9YkCQ1Ly4656L2bK';
update content_bodies set title = '東京中央区観光紹介ムービー - 遊（アクティビティ）バージョン', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しており、特定の時期と場所でしか楽しめないユニークな体験に焦点を当てています。「遊」バージョンでは、夏や秋の祭り、和紙作りや書道などの伝統的な活動が取り上げられています。視聴者がこれらの体験に実際に参加しているかのように感じられるように構成されており、東京中央区の活気ある文化や伝統を探求するための招待状となっています。' where id = 'pvwBo1gnMMBT5Looy7iaB';
update content_bodies set title = 'Tokyo Chuo City Tourism Introduction Movie - Activity Version', description = 'This promotional video showcases the various tourist attractions of Tokyo Chuo City, focusing on unique experiences that can only be enjoyed at specific times and places. The ''Activity'' version highlights special events such as summer and fall festivals, as well as traditional crafts like paper making and Japanese lettering. The video aims to immerse viewers in these experiences, making them feel as though they are participating in the activities firsthand. It serves as an invitation to explore the vibrant culture and traditions of Tokyo Chuo City.' where id = 'DL-eHQtc5PrPJGfUeTfUk';
update content_bodies set title = '【東京中央区観光紹介ムービー】歩（Walk）バージョン（15秒）', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。「歩」バージョンでは、訪問者の視点から中央区での一日を描写し、代表的なエリアである日本橋、人形町、銀座、築地、佃、月島を歩きながら見る様子を映し出しています。歩行者の目を通して中央区の多様な風景を体験し、歴史の伝統と最新のトレンドを感じることができます。' where id = 'yNcbu-78qD2gz8YI7VNCW';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie - Walk version (15sec.)', description = 'This promotional video showcases the tourist attractions of Tokyo Chuo City. The ''Walk'' version presents a day in Chuo City from a visitor''s perspective, highlighting key areas such as Nihonbashi, Ningyocho, Ginza, Tsukiji, Tsukuda, and Tsukishima. It captures the essence of Chuo City through the eyes of a pedestrian, allowing viewers to experience the blend of historical traditions and modern trends. The video invites viewers to take a stroll through the diverse scenes of Chuo City.' where id = 'UER8UcdKUItLaUN3Tlops';
update content_bodies set title = '【東京中央区観光紹介ムービー】食（Food）バージョン', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。「食」バージョンは、「日本で食べたいものはすべて中央区にある」というコンセプトに基づいています。江戸時代から続く寿司、うなぎ、そば、天ぷらなどの日本料理を中心に、ラーメンや地元の居酒屋、日本の和菓子など、地域の味も楽しめます。美味しそうな料理の美しい映像や、腕を振るうシェフ、見るだけでよだれが出るスイーツが満載で、実際に食べることなくとも、中央区の豊かな日本食のバラエティを体験できます。' where id = 'xC4as33sRnihHBExMdoNE';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie - Food version', description = 'This promotional video showcases the diverse tourist attractions of Tokyo Chuo City, emphasizing its culinary offerings. The ''Food'' version highlights the concept that all the delicious foods one might desire in Japan can be found in Chuo City. It features traditional Japanese cuisine, recognized as UNESCO Intangible Cultural Heritage, including sushi, eel, soba, and tempura, alongside popular local dishes like ramen and Japanese sweets. The video presents stunning visuals of appetizing food, talented chefs, and mouth-watering desserts, allowing viewers to appreciate the culinary delights of Chuo City, renowned as one of the world''s greatest gourmet destinations.' where id = 'EE5u1_HOqvqPUEDUlT31l';
update content_bodies set title = '【東京中央区観光紹介ムービー】彩（Colors）版', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。「彩」版では、著名なスポットを取り上げ、日本の文化と四季の融合をテーマに、その魅力を最大限に引き出しています。タイムラプスやドローン撮影などの多様な技術を駆使し、各スポットの独自の美しさを際立たせています。東京の中心で感じる四季の美しい色彩を、言葉を超えた壮大な映像で表現しています。' where id = '6CI9le8CdSGNcQVNe51RS';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie: Colors version', description = 'This promotional video showcases the various tourist attractions of Tokyo Chuo City. The ''Colors'' version highlights famous locations, emphasizing the blend of Japan''s culture with the changing seasons. It utilizes various filming techniques, including time-lapse and drone photography, to enhance the unique beauty of each site. The stunning visuals capture the vibrant colors of the seasons in the heart of Tokyo, presenting an awe-inspiring experience that speaks for itself without the need for words.' where id = '7C6l0zPJKWiT7hDKG1pvS';
update content_bodies set title = '桜の樹の下で関おどりwith郡上踊り', description = '令和6年3月31日(日)に岐阜県関市の観光施設「せきてらす」で開催された『桜の樹の下で関おどりwith郡上踊り』のPVが公開されました。当日は関おはやし会と郡上高校の生徒たちが参加し、関高校の生徒も集まって会場を盛り上げました。関市では毎年7月中旬から9月上旬にかけて盆おどりが開催されており、「郡上踊り」や「田原昔踊り」など、様々なおどりが楽しめるイベントです。今年の情報は指定されたURLからご確認ください。' where id = 'dhEPUurD3mo0o4WZIf2JU';
update content_bodies set title = 'Sakura no Ki no Shita de Seki Odori with Gujo Odori', description = 'On March 31, 2024, a promotional video for ''Sakura no Ki no Shita de Seki Odori with Gujo Odori'' was released, showcasing an event held at the ''Sekiterasu'' tourist facility in Seki City, Gifu Prefecture. The event featured performances by the Seki Hayashi Association and students from Gujo High School, with additional support from Seki High School students to enhance the atmosphere. Seki City hosts Bon Odori festivals from mid-July to early September each year, featuring various dances including ''Gujo Odori'' and ''Tahara Mukashi Odori,'' making it a diverse and exciting celebration. For this year''s information, please check the provided URLs.' where id = 'YA0Y9lp-kDQhM40S_RVvd';
update content_bodies set title = '【東京中央区観光紹介ムービー】人（People）バージョン（15秒バージョン）', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介するもので、地元の人々の自然な笑顔やプロフェッショナルな姿を撮影しています。異なる文化の体験や、日本のホスピタリティ「おもてなし」の雰囲気を表現することを目的としています。このビデオは、歩くこと、アクティビティ、食べ物、色彩など、異なるテーマを持つシリーズの一部であり、各テーマは15秒のフォーマットで提供されています。視聴者は、提供されたリンクを通じて、全プレイリストや他の言語バージョンにアクセスできます。' where id = 'MAiHVhM8cHXcB2Fi6I8-g';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie - People version (15sec. version)', description = 'This promotional video showcases various tourist attractions in Tokyo Chuo City, focusing on the natural smiles and professional appearances of local people. It aims to convey a simulated experience of different cultures and the essence of Japanese hospitality, known as ''Omotenashi''. The video is part of a series that includes different themes such as walking, activities, food, and colors, each presented in a 15-second format. Viewers can access the full playlist and additional versions in multiple languages through the provided links.' where id = 'HmNQq8rgXSRD7ZVowI6tL';
update content_bodies set title = '【鬼北のMMD】道の駅 日吉 夢産地でBAAM', description = '愛媛県北宇和郡鬼北町にある道の駅日吉夢産地には、鬼のモニュメント「柚鬼媛」が存在します。その前で、踊りを作成してみました。これは気まぐれなプロジェクトです。使用したモデルには、まっしゅ式の甘露寺蜜璃、おおかみ式の胡蝶しのぶ0.5、hoge式の禰豆子ver0.8があります。モーションはkimagureによって作成され、音楽にはMOMOLANDの「BAAM」を使用しています。この作品はMMDを使用した二次創作であり、鬼滅の刃の公式とは一切関係ありません。' where id = 'bgi62TfOaZPeMv32sPB4e';
update content_bodies set title = 'MMD at Michi no Eki Hiyoshi Yume Sanchi: BAAM', description = 'At the Michi no Eki Hiyoshi Yume Sanchi in Oni-kita, Ehime Prefecture, there is a monument of a demon named ''Yuki Hime''. In front of this monument, I decided to create a dance animation. This is a whimsical project. The models used include Mashu-style Kanroji Mitsuri, Okami-style Kochou Shinobu 0.5, and Hoge-style Nezuko ver0.8. The motion was created by Kimagure, and the music used is ''BAAM'' by MOMOLAND. Please note that this work is a derivative creation using MMD and is not affiliated with the official Demon Slayer franchise.' where id = 'BlyUOxKVm3g2kk_FjA3hI';
update content_bodies set title = '愛媛県南予SLのある風景(2024.5.9)', description = '愛媛県南予地方でSLが見られる場所を4箇所巡りました。訪れたのは、宇和島市の和霊公園、JR宇和島駅前、JR内子駅前、そして八幡浜市の王子の森公園です。音楽はBGMerによるものです。' where id = 'kNnp6DL3SeFZb5udmdGig';
update content_bodies set title = 'Scenery with SL in Minpyo, Ehime Prefecture (May 9, 2024)', description = 'I visited four locations in the Minpyo region of Ehime Prefecture where steam locomotives (SL) can be found. The sites include Uwajima City’s Warei Park, in front of JR Uwajima Station, in front of JR Uchiko Station, and Oji no Mori Park in Yawatahama City. The background music is provided by BGMer.' where id = 'qyfs1VohvJwuG1NOyqzTx';
update content_bodies set title = '遊子水荷浦の段畑までのドラレコ[BGMは配信楽曲](2025.2.2)', description = 'この動画は、宇和島観光PR CDの完成に関する簡単な告知を目的としています。このCDには、みーかんチャンネルの楽曲が収録されており、遊子水荷浦のだんだん茶屋で流されてきました。動画はCDの納品の様子を記録しています。宇和島観光PR CD「KISAIYA宇和島」は徐々に売れており、感謝の意が表されています。また、AI音楽の配信登録を試み、5曲ほどが今回の動画で流れています。視聴者には、利用している配信サイトで音楽を検索して聴くことが勧められています。BGMにはみーかんチャンネルのオリジナル楽曲が含まれており、著作権はみーかんチャンネルにあります。商用利用の場合は事前に連絡が必要です。' where id = 'D3FS0YBKXlUcS3Rg1W-Ti';
update content_bodies set title = 'Driving Record to Yusui Mizuhura''s Terraced Fields [BGM is Streaming Music] (2025.2.2)', description = 'This video serves as a brief announcement regarding the completion of the Uwajima Tourism PR CD. The CD features music from the Miikan Channel, which has been played at the Yusui Mizuhura Dandan Chaya. The video documents the delivery of the CD. The Uwajima Tourism PR CD ''KISAIYA Uwajima'' is gradually selling well, and the creator expresses gratitude for the support. Additionally, the creator has registered about five tracks for streaming, which are featured in this video. Viewers are encouraged to search for and listen to the music on their preferred streaming platforms. The background music includes original tracks from the Miikan Channel, and copyright is held by them. Commercial use requires prior contact.' where id = 'JSSDC8B6z0QpfTCvUyc13';
update content_bodies set title = 'KOYASAN【VR360°動画】', description = '画質設定を4K表示に変更することで、より鮮やかな映像を楽しむことができます。' where id = '6qrddfJetGM_1c1-3MRI4';
update content_bodies set title = 'KOYASAN【VR360°動画】', description = 'You can enjoy a more vibrant 4K video experience by changing the image quality settings.' where id = 'XwIzh0550DpF1fyu14v-P';
update content_bodies set title = 'KUMANOKODO【VR360°動画】', description = '画質設定を4K表示に変更することで、より鮮やかな映像を楽しむことができます。和歌山県インターネット放送局のウェブサイトでは、さまざまなコンテンツが提供されています。' where id = 'U3lqkpzQb3Jl6t44CZsI5';
update content_bodies set title = 'KUMANOKODO【VR360° Video】', description = 'You can enjoy a more vibrant 4K video experience by changing the image quality settings.' where id = '8TFw3b8RR8Q2KG0e2hs21';
update content_bodies set title = '六華苑はあの映画やドラマのロケ地としても有名！和洋折衷のモダンな建物です✨', description = '六華苑は、映画のロケ地として知られ、年間約5万人が訪れる人気スポットです。桑名の実業家、二代諸戸清六の新居として建てられ、洋館と和館は国の重要文化財に指定されています。イギリス人建築家ジョサイア・コンドルによって設計されたこの建物は、和洋折衷の美しいデザインが特徴です。場所は桑名市にあり、営業時間は9:00から17:00まで、入苑受付は16:00までです。料金は一般460円、中学生150円で、駐車場は30台分あります。' where id = 'hdFiaPGk-Goz15qbW4kAQ';
update content_bodies set title = 'Rokkaen: A Famous Filming Location for Movies and Dramas!', description = 'Rokkaen is a popular spot attracting around 50,000 visitors annually, known for being a filming location for various movies. Built as the new residence of businessman Shiroku Moroto in Kuwana, the building features a blend of Western and Japanese architectural styles and is designated as an Important Cultural Property. Designed by the British architect Josiah Conder, who is referred to as the ''Father of Modern Japanese Architecture,'' Rokkaen showcases a unique combination of traditional and modern elements. The site is located in Kuwana City and is open from 9:00 AM to 5:00 PM, with an admission fee of 460 yen for adults and 150 yen for middle school students.' where id = 'wkVXch9wCEeyVhTgVgsEl';
update content_bodies set title = '津市の絶景紅葉の名所！ #河内渓谷', description = 'まさに今が見頃の河内渓谷は、三重県津市芸濃町に位置する紅葉の名所です。渓谷入口の橋にかかる紅葉は、まるでアーチのように美しく、県内屈指の観光スポットとなっています。夜間のライトアップは2023年11月25日（土）まで行われており、日帰り観光や1泊2日の旅行にも最適です。三重県の観光情報はすべてここに集まっています！' where id = 'UAUn5_oPuWObXk3ZSCIbE';
update content_bodies set title = 'Kawachi Valley: A Scenic Spot for Autumn Leaves in Tsu City!', description = 'Now is the perfect time to visit Kawachi Valley, a renowned location for autumn foliage in Geinomachi, Tsu City, Mie Prefecture. The vibrant autumn leaves create an arch over the bridge at the valley''s entrance, making it one of the best spots in the prefecture for viewing fall colors. The night illumination is available until Saturday, November 25, 2023, making it an excellent choice for both day trips and overnight stays. Discover all the sightseeing opportunities in Mie Prefecture!' where id = 'oYrE2ft199BdgCPcTWzt0';
update content_bodies set title = '「ヒトとヒト・ヒトとモノ」がテーマの #おわせマルシェ', description = '「ヒトとヒト・ヒトとモノ」をテーマにした#おわせマルシェは、2021年3月にオープンしました。店内には、三重県のクリエイターによるオリジナル作品やユーズド商品を販売する物販エリア、子どもが楽しめるキッズスペース、オリジナルのフードや自家製スイーツを提供するカフェブースがあります。また、月に1回のイベントも開催されています。家族みんなで楽しめる「おわせマルシェ」にぜひ訪れてみてください。場所は三重県尾鷲市で、営業時間は11:00～18:00（金・土曜は22:00まで）で、月・火曜が定休日です。駐車場も完備されており、熊野尾鷲道路「尾鷲北IC」から車で約10分の距離です。' where id = '-eoWTpY5VzT0KwGbYFpR3';
update content_bodies set title = '#OwaseMarche: A Theme of ''People and Things''', description = '#OwaseMarche opened in March 2021, focusing on the theme of ''People and Things.'' The venue features a retail area showcasing original works and used items created by local artists from Mie Prefecture. There is also a kids'' space for children to enjoy and a café booth offering original food and homemade sweets. Additionally, the facility hosts monthly events. It''s a great place for families to visit and experience the excitement of #OwaseMarche! Located in Owase City, Mie Prefecture, it operates from 11:00 AM to 6:00 PM (until 10:00 PM on Fridays and Saturdays) and is closed on Mondays and Tuesdays. Parking is available, and it is about a 10-minute drive from the Owase North IC on the Kumano Owase Road.' where id = 'XwO6driZOmZZYphLjp9v1';
update content_bodies set title = 'ナガシマスパーランド　ジャンボ海水プールに新アトラクション「ジャパーーーン」登場', description = 'ナガシマスパーランドのジャンボ海水プールに新アトラクション「ジャパーーーン」が登場しました。このアトラクションでは、約3トンの水が巨大なバケツから一気に流れ落ちる仕組みになっており、訪れる人々にスリリングな体験を提供します。世界最大級の海水プールでの新たな楽しみとして、多くの観光客に期待されています。' where id = 'cAcZJWH1AX1C-tC60_ZKx';
update content_bodies set title = 'New Attraction ''Japaaan'' at Nagashima Spa Land''s Jumbo Sea Water Pool', description = 'A new attraction named ''Japaaan'' has been introduced at Nagashima Spa Land''s Jumbo Sea Water Pool, one of the largest in the world. This exciting feature involves approximately three tons of water cascading down from a giant bucket, providing a thrilling experience for visitors.' where id = 'gNko1sCi5rdVl0Lslowat';
update content_bodies set title = '六本木ヒルズでのドラえもんの侵略', description = '東京の六本木ヒルズでは、2022年の夏、8月末までドラえもんの侵略イベントが開催されます。ドラえもんファンは、敷地内に散らばる可愛い青いロボット猫たちと一緒に思い出に残る写真を撮るチャンスをお見逃しなく。このイベントはドラえもんの誕生日を祝うもので、訪れる人々に楽しい体験を提供します。ドラえもんの魅力を楽しむこのユニークな機会をお見逃しなく！' where id = 'KyDUPT8Vn4aUydNQewfz7';
update content_bodies set title = 'Doraemon Invasion at Roppongi Hills', description = 'This summer, until the end of August, Roppongi Hills in Tokyo is hosting a Doraemon invasion. Fans of the beloved blue cat robot should not miss this opportunity to take memorable photos with various Doraemon figures scattered throughout the premises. The event is a celebration of Doraemon, coinciding with his birthday, and promises a fun experience for visitors. Don''t miss out on this unique chance to enjoy the charm of Doraemon in a vibrant setting!' where id = 'Aog8PTXelBXBWhpi9qrjg';
update content_bodies set title = '日光の訪れるべき場所 日本 パート1 | 旅行ガイド', description = '日光（Nikkō）は日光国立公園の入り口に位置する町で、日本で最も豪華に装飾された神社である東照宮と、徳川幕府の創始者である徳川家康の霊廟で知られています。東照宮が建設される前の1600年代以前から、日光は数世紀にわたり神道と仏教の山岳信仰の中心地でした。現在、日光国立公園は美しい山々の風景、湖、滝、温泉、野生の猿、数多くのハイキングコースを提供しています。このビデオでは、日光の美しさを探るためのシンプルな旅行ガイドを紹介しています。' where id = 'pcR3TaFErwL57W-NdkoqU';
update content_bodies set title = 'Places to Visit in Nikko Japan Part1 | Travel Guide', description = 'Nikko is a town located at the entrance of Nikko National Park, renowned for Toshogu, the most elaborately decorated shrine in Japan and the mausoleum of Tokugawa Ieyasu, the founder of the Tokugawa shogunate. Before the construction of Toshogu in the 1600s, Nikko was a significant site for Shinto and Buddhist mountain worship for centuries. Today, Nikko National Park offers stunning mountainous landscapes, lakes, waterfalls, hot springs, wild monkeys, and numerous hiking trails. This video provides a simple travel guide to explore the beauty of Nikko, Japan.' where id = 'DmN_6oucaZNYaHt4rF0xo';
update content_bodies set title = '相模湖ウィンターイルミネーション | プレジャーフォレスト | セーラームーンイルミネーション', description = '相模湖プレジャーフォレストでは、温泉、キャンプ、ドローン体験などの多様なレジャー活動が楽しめるほか、メインの遊園地もあります。冬のイルミネーションイベントは2021年11月13日から2022年4月3日まで開催され、営業時間は午後4時から午後9時までです。入場料は大人（シニア含む）が1,500円、子供が1,100円で、ナイトフリーパスは大人2,800円、子供2,200円です。入場料にはリフト乗車料金が含まれています。雨天でもイベントは開催されますが、悪天候により販売が延期される場合があります。昼間の遊園地のフリーパスチケットは夜のアトラクションでも使用可能です。リゾートは神奈川県相模原市に位置し、新宿から車で約50分、または相模湖駅からアクセス可能です。' where id = '7kX6a7j1kY93LRXD5RJ4F';
update content_bodies set title = 'Sagamiko Resort Winter Illumination | Pleasure Forest | Sailor Moon Illumination', description = 'Sagamiko Pleasure Forest offers a variety of leisure activities, including hot springs, camping, and drone experiences, alongside its main amusement park. The winter illumination event runs from November 13, 2021, to April 3, 2022, and is open from 4 PM to 9 PM. Admission fees are 1,500 yen for adults (including seniors) and 1,100 yen for children, with a night free pass available for 2,800 yen for adults and 2,200 yen for children. The entrance fee includes the lift ride. The event is held regardless of rainy weather, although sales may be postponed due to severe conditions. Free pass tickets for daytime amusement park attractions can also be used for nighttime events. The resort is located in Sagamihara, Kanagawa, approximately 50 minutes by car from Shinjuku, or accessible via Sagamiko Station.' where id = 'wzuGTbIX7EZibWgYaGHUh';
update content_bodies set title = '秋の八海庭園 | 彦兵衛邸 | 秋の忍野八海', description = 'この動画では、秋の八海庭園の美しさを紹介し、忍野八海の素晴らしい風景を強調しています。映像には、クリエイティブ・コモンズ・ライセンスのもとでライセンスされた音楽が使用されており、視覚的な楽しさを引き立てています。日本の旅行、特に秋の季節や富士山の美しい景色を探索することを視聴者に促しています。また、コラボレーションや製品レビューの依頼も受け付けており、すべてのコンテンツはエンターテインメント目的で使用され、著作権侵害は意図していないことを明記しています。' where id = 'NtbxNAXAvnD_p-w5XANqd';
update content_bodies set title = 'Hakkai Garden in Autumn | Hikobei Residence | Oshino Hakkai Garden in Autumn | 忍野八海', description = 'This video showcases the beauty of Hakkai Garden during autumn, highlighting the stunning scenery of Oshino Hakkai. The content is enriched with music licensed under a Creative Commons License, providing an enjoyable backdrop for the visuals. The video aims to promote travel in Japan, particularly focusing on the autumn season and the picturesque views of Mount Fuji. It encourages viewers to explore Japan''s natural beauty and cultural heritage. The channel also invites collaborations and product reviews, while ensuring that all content is used for entertainment purposes only, with no copyright infringement intended.' where id = 'U5gdDy9IvGqufB21Rkgnc';
update content_bodies set title = '日本で最も急な斜面 | 高尾山ケーブルカーの旅 | 秋の色彩', description = 'この動画では、日本で最も急な斜面を持つ高尾山を紹介します。視聴者は、山頂から山麓までのケーブルカーの旅を通じて、美しい秋の紅葉を楽しむことができます。高尾山は、東京都八王子市に位置し、599メートルの高さを誇り、明治の森高尾国定公園の一部です。年間250万人以上の訪問者があり、人気のハイキングスポットとなっています。また、この山は日本の民間伝承に登場する天狗と関連があり、運を祈るための高尾山薬王院という寺院も存在します。動画にはリラックスできる音楽が含まれており、自然の美しさを楽しむための穏やかな体験を提供します。' where id = 'LYuT3z3teW61sl3SLiEZh';
update content_bodies set title = 'Steepest Slope in Japan | Mount Takao Cable Car Ride | Autumn Colors', description = 'This video showcases the steepest slope in Japan, located at Mount Takao. Viewers are invited to experience a cable car ride from the mountain''s peak to its base, enjoying the stunning autumn foliage along the way. Mount Takao, standing at 599 meters, is situated in Hachiōji, Tokyo, and is part of the Meiji no Mori Takao Quasi-National Park. It is a popular destination for hiking, attracting over 2.5 million visitors annually. The mountain is also significant in Japanese folklore, associated with the tengu, and features the Takaosan Yakuōin Yūkiji temple, a site for prayer and good fortune. The video includes relaxing music and aims to provide a serene experience of nature''s beauty.' where id = 'UrvTFOdizyORB7UUIcAx4';
update content_bodies set title = '富士河口湖紅葉まつり 2021', description = '富士河口湖紅葉まつりは、日本で最も人気のある秋のイベントの一つで、富士五湖の一つである河口湖の北岸で毎年開催されます。2021年の祭りは10月30日から11月23日まで行われます。美しい紅葉とともに、バックには富士山の絶景が広がります。祭りの中心は「もみじ回廊」で、60本以上のもみじの木が並ぶ約2kmの遊歩道です。イベントは午前9時から始まり、夕方から夜10時までライトアップが行われます。また、季節の食べ物や地元の手作りの土産物を販売する屋台も出店します。' where id = '9x3PHQlKYZB5mHOitO8Q5';
update content_bodies set title = 'Fujikawaguchiko Autumn Leaves Festival 2021', description = 'The Fujikawaguchiko Autumn Leaves Festival is a renowned annual event held at the northern shore of Lake Kawaguchi, part of the Fuji Five Lakes. In 2021, the festival runs from October 30 to November 23. Visitors can enjoy vibrant autumn foliage against the backdrop of Mt. Fuji. The festival''s highlight is the ''Momiji Corridor,'' a 2km walkway lined with over 60 maple trees showcasing stunning red, yellow, and orange leaves. The event starts at 9:00 AM, with evening illuminations from sunset until 10:00 PM. Attendees can also explore food stalls offering seasonal delicacies and local handmade souvenirs.' where id = '9p7v77nBZ6LI-Ej15wBXS';
update content_bodies set title = '上野公園の秋', description = '上野公園は、東京の中心部にある上野駅の隣に位置する大きな公園で、もともとは江戸時代における重要な寺院であった寛永寺の一部でした。戊辰戦争での破壊を経て、1873年に日本初の西洋式公園として一般に開放されました。公園内には、上野の戦いの将軍である西郷隆盛の像があり、寛永寺の栄光を思い起こさせる不忍池もあります。上野公園は東京国立博物館や日本初の動物園である上野動物園など、多くの博物館があることで知られています。また、1000本以上の桜の木が並ぶため、毎年3月下旬から4月初旬にかけて多くの花見客が訪れる人気のスポットでもあります。' where id = '4I_VhGdFIA4WhC-bmD7BM';
update content_bodies set title = 'Autumn at Ueno Park Tokyo', description = 'Ueno Park, located next to Ueno Station in central Tokyo, is a large public park that was originally part of Kaneiji Temple, a significant temple during the Edo Period. After suffering destruction during the Boshin Civil War, the grounds were transformed into one of Japan''s first Western-style parks, opening to the public in 1873. The park features a statue of Saigo Takamori, a general from the Battle of Ueno, and is home to Shinobazu Pond, which reflects the former grandeur of Kaneiji Temple. Ueno Park is renowned for its museums, including the Tokyo National Museum and Ueno Zoo, Japan''s first zoological garden. It is also a popular cherry blossom viewing spot, with over 1000 cherry trees blooming in late March and early April.' where id = 'pjbxUmlcrUdtBwh2CnCHK';
update content_bodies set title = '東京皇居周辺の秋の紅葉 | 日本の秋の色', description = 'この動画では、東京皇居周辺の美しい秋の紅葉を紹介しています。暖かく鮮やかな色合いが多くの人々を魅了しています。東京皇居は、東京都千代田区に位置し、日本の天皇の主な住居です。広大な公園のようなエリアで、主殿や皇族の住居、アーカイブ、博物館、行政オフィスなどが含まれています。皇居は旧江戸城の跡地に建てられており、面積は1.15平方キロメートルです。1980年代のバブル期には、皇居の敷地の価値がカリフォルニア州全体の不動産の価値を上回るとされていました。この動画はエンターテインメント目的で制作されており、音楽はVlog No Copyright Musicから提供されています。' where id = 'b2VfS4N5fEbzSXv89Awz0';
update content_bodies set title = 'Fall Foliage Around Tokyo Imperial Palace | Autumn Colors | Japan', description = 'This video showcases the stunning autumn foliage around the Tokyo Imperial Palace, featuring vibrant colors that attract many viewers. The Tokyo Imperial Palace, located in the Chiyoda district of Tokyo, serves as the main residence of the Emperor of Japan. It is a large park-like area that includes the main palace, residences of the Imperial Family, archives, museums, and administrative offices, all built on the site of the former Edo Castle. The palace grounds cover an area of 1.15 square kilometers. During the 1980s property bubble, the value of the palace grounds was estimated to exceed that of all real estate in California. The video is intended for entertainment purposes and includes music provided by Vlog No Copyright Music.' where id = 'ck0xejCD18Oz4Eei3nFBR';
update content_bodies set title = '富士芝桜祭り2021 | 富士山ツアー | 富士芝桜', description = '富士芝桜祭り2021は、日本の山梨県で開催され、ピンク、白、紫の花々で彩られた美しいフィールドを展示します。芝桜はモスフロックスとも呼ばれ、祭りは4月中旬から6月初旬まで行われ、最も花が見頃を迎えるのは通常5月の最初の3週間です。入場料は子供250円、大人800円で、営業時間は午前8時から午後3時までです。祭りの初期には花がまだ満開ではありませんでしたが、富士山を背景にした景色は非常に美しいです。来場者は多様なメニューを提供するフードトラックを楽しんだり、芝桜をテーマにしたお土産や地元の産物を購入することができます。約80万本の芝桜が5種類展示され、色とりどりの美しい景観を作り出しています。' where id = '2Y5nIWSB703sXHijpamyN';
update content_bodies set title = 'Fuji Shibazakura Festival 2021 | Mt. Fuji Tour | 富士芝桜', description = 'The Fuji Shibazakura Festival 2021, held in Yamanashi, Japan, showcases stunning fields of pink, white, and purple flowers known as Shibazakura or Moss Phlox. The festival runs from mid-April to early June, with the best viewing typically in the first three weeks of May. Entrance fees are 250 yen for children and 800 yen for adults, with festival hours from 8 AM to 3 PM. Although the flowers were not fully bloomed during the early days of the festival, the sight of Mt. Fuji in the background enhances the beauty of the landscape. Visitors can enjoy food trucks offering various menus and purchase Shibazakura-themed souvenirs and local produce. The festival features approximately 800,000 stalks of Shibazakura in five varieties, creating a vibrant display of colors.' where id = '3BqFBf4BwIhO9oUQBh4Jx';
update content_bodies set title = '鴨川シーワールド | Kamogawa Seaworld | 日本旅行', description = 'この動画は2年前に撮影されたもので、千葉県の鴨川シーワールドでの家族の一日を紹介しています。水族館は広大で、展示やアクティビティ、パフォーマンス、プログラムをすべて見るには一日では足りませんでした。特に小さな娘にとっては、さまざまな海洋生物やその行動、環境との反応、美しい色合いの魚や水生動物、彼らの才能や能力を観察できたことが素晴らしい体験でした。家族は、視聴者がこの動画を楽しんでくれることを願っています。' where id = '9lPuLHFkGrB1NRBIkdkL9';
update content_bodies set title = 'Kamogawa Seaworld | 鴨川シーワールド| Japan Travel', description = 'This video showcases a family day out at Kamogawa Seaworld in Chiba Prefecture, Japan, taken two years ago. The aquarium park is vast, and a single day is insufficient to explore all the exhibits, activities, performances, and programs available. The experience was particularly enjoyable for the family, especially their little girl, as they observed a variety of marine animals, their behaviors, and interactions with their environment. The vibrant colors of different fish and aquatic creatures, along with their talents and abilities, made for a memorable day. The family hopes viewers enjoy the video as much as they did.' where id = 'eWkbtU8H95KnJvI15PZWx';
update content_bodies set title = '白糸の滝 | Shiraito Falls | Mt. Fuji Tour', description = '白糸の滝（Shiraito no Taki）は、静岡県富士宮市に位置し、富士山の近くにある美しい滝です。この滝は、富士箱根伊豆国立公園の一部であり、1936年から日本の天然記念物として保護されています。白糸の滝は、富士信仰の下で神聖視されていました。また、近くには音止の滝（Otodome Falls）があり、徒歩約5分の距離にあります。1990年には環境省によって「日本の滝100選」に選ばれ、1927年には東京日日新聞と大阪毎日新聞によって「日本の風景100選」にも選ばれました。2013年には、富士山文化遺産の一部として世界遺産リストに登録されました。' where id = 'BbjrgO_BvLVREoQAVxwKO';
update content_bodies set title = 'Shiraito no Taki | Shiraito Falls | 白糸の滝 | Mt. Fuji Tour', description = 'Shiraito Falls, located in Fujinomiya, Shizuoka Prefecture, near Mount Fuji, is a stunning waterfall that is part of Fuji-Hakone-Izu National Park. Designated as a Japanese Natural Monument since 1936, it holds cultural significance, having been regarded as sacred by the Fuji cult. The falls are approximately a five-minute walk from another waterfall, Otodome Falls. Recognized as one of Japan''s Top 100 Waterfalls by the Ministry of the Environment in 1990, Shiraito Falls was also included in the 100 Landscapes of Japan by major newspapers in 1927. In 2013, it was added to the World Heritage List as part of the Fujisan Cultural Site.' where id = 'IzNHibwyqj3nSXulFnPMI';
update content_bodies set title = '高尾山紅葉', description = 'この動画では、日本で最も急な斜面を持つ高尾山を紹介します。視聴者は、山頂から山麓までの6分間のケーブルカーの旅を通じて、美しい秋の紅葉を楽しむことができます。高尾山は東京都八王子市に位置し、高さ599メートルで、年間250万人以上の訪問者を迎える人気のハイキングスポットです。明治の森高尾国定公園に属し、神道と仏教の伝説、特に天狗と深く結びついています。山には多くの訪問者が天狗のご加護を求める高尾山薬王院という仏教寺院もあります。動画ではリラックスできる音楽が流れ、自然の美しさが強調されています。' where id = 'PtbEZVOXU-soko7yyc54Z';
update content_bodies set title = 'Mt. Takao Autumn Foliage', description = 'This video showcases Mt. Takao, known for having the steepest slope in Japan. Viewers are invited to experience a six-minute cable car ride from the mountain''s peak to its base, enjoying the stunning autumn foliage along the way. Located in Hachiōji, Tokyo, Mt. Takao stands at 599 meters and is a popular hiking destination, attracting over 2.5 million visitors annually. The mountain is part of Meiji no Mori Takao Quasi-National Park and is associated with Shinto-Buddhist folklore, particularly the tengu. A significant Buddhist temple, Takaosan Yakuōin Yūkiji, is situated on the mountain, drawing visitors who seek blessings from the tengu. The video features relaxing music and emphasizes the natural beauty of the area.' where id = 'sUUv8iMRLIkjO1-jPF0Pq';
update content_bodies set title = 'むつ湾一周サイクリングコースPR動画', description = 'この動画は、むつ湾一周サイクリングコースについて紹介しており、コースの魅力や特徴を伝えています。サイクリングを楽しむための情報が盛り込まれており、観光客や地元の人々にとって魅力的なアクティビティとして提案されています。' where id = 'xY62WXq8PufYwhrZ8jh2s';
update content_bodies set title = 'MUTSU BAY CYCLING COURSE (Promotional Video)', description = 'This video introduces the Mutsu Bay Cycling Course.' where id = 'Ltvw3vnDbWhrC_f-2-Y3H';
update content_bodies set title = 'むつ湾一周サイクリングコース', description = 'この動画は、むつ湾一周サイクリングコースを紹介しており、美しい景色を楽しむことができるルートを紹介しています。' where id = 'm3B7jxDbv1Z-2RD6MHMT7';
update content_bodies set title = 'MUTSU BAY CYCLING COURSE', description = 'This video introduces the Mutsu Bay Cycling Course, showcasing the scenic route around Mutsu Bay.' where id = 'BaCQNEaXRKEpX6HcmIYLM';
update content_bodies set title = '東広島の自然～安芸津～', description = '安芸津は、ひろしま杜氏のふるさとであり、穏やかな海岸線からは瀬戸内海の美しい島々を眺めることができます。特に、5月中旬から6月上旬にかけては、赤崎海岸でじゃがいもの白い花が一面に咲き誇り、訪れる人々を楽しませます。' where id = 'SsOBzC9cdKuzgSSKKZslH';
update content_bodies set title = 'Nature of Higashihiroshima - Aki-tsu', description = 'Aki-tsu, the hometown of Hiroshima''s sake brewers, offers a gentle coastline where one can admire the beauty of the islands in the Seto Inland Sea. From mid-May to early June, the white flowers of potatoes bloom abundantly along Akasaki Beach.' where id = '7MB9H14Wta-Xv6W-Bs9SE';
update content_bodies set title = 'クローズアップコザ（沖縄市観光促進DVD5）', description = 'このDVDは沖縄市に焦点を当て、その魅力や文化的なハイライトを紹介する観光促進用の作品です。コザの独自の側面を深く掘り下げ、観光や地域の探索を促すことを目的としています。' where id = 'Pd2R2JQKF6icU4OS3cnB2';
update content_bodies set title = 'Closeup Koza (Okinawa City Tourism Promotional DVD5)', description = 'This is a promotional DVD focused on Okinawa City, showcasing its attractions and cultural highlights. The DVD aims to provide viewers with an in-depth look at the unique aspects of Koza, encouraging tourism and exploration of the area.' where id = 'FUtASEn0_7CYSBaT4_VMM';
update content_bodies set title = 'SHOCHU TOURISM ～宮崎文化を焼酎で発見～ 県西＆県南エリア', description = '宮崎県は、本格焼酎の出荷量が9年連続で日本一を誇る焼酎の産地です。県では、焼酎づくり体験に加え、夜神楽の鑑賞や、通常は飲食に使われない文化財を会場にしたメーカーズプレミアムディナーなどを通じて、焼酎の魅力とともに宮崎の歴史・文化を感じるインバウンド向けの酒蔵ツーリズムを推進しています。宮崎の大自然や伝統と共に、個性豊かな蔵元の見学や、宮崎グルメとの焼酎のペアリングをぜひ体験してみてください。' where id = 'NMHN1_3_Ii1Ul7oAaDVIR';
update content_bodies set title = 'SHOCHU TOURISM ～Discover Miyazaki Culture With Shochu～ Western & Southern Area', description = 'Miyazaki Prefecture is renowned for being Japan''s top producer of authentic shochu, holding the largest shipment for nine consecutive years. To promote Shochu Tourism, the prefecture offers various experiences, including shochu-making workshops, watching traditional Yokagura performances, and enjoying Premium Dinners with shochu craftsmen at cultural heritage sites typically not used for dining. Visitors can immerse themselves in the rich history and culture of Miyazaki while discovering the unique charms of shochu. The tour includes visits to distinctive distilleries that reflect Miyazaki''s beautiful nature and traditions, along with opportunities to pair shochu with local culinary delights.' where id = 'eTfP_SVitRusG461g9CIn';
update content_bodies set title = '長崎県 壱岐 湯ノ本温泉 日帰り温泉 ６選', description = '湯ノ本温泉は長崎県壱岐に位置する人気の温泉地で、日帰りで楽しめる6つの温泉があります。このエリアはリラックスできる雰囲気と癒しの湯で知られています。訪れる人々は、温泉の周囲に広がる自然の美しさを楽しみながら、心身をリフレッシュすることができます。湯ノ本温泉の詳細はGoogleマップで確認できます。また、著者はインスタグラムアカウントを開設し、体験を共有しています。さらに、オリジナルのオレンジタオルが販売されているリンクもいくつか提供されています。' where id = '-MyX9MuYmaH3b3OOFrwx0';
update content_bodies set title = 'Iki Yunomoto Onsen: 6 Hot Springs for Day Visits', description = 'Yunomoto Onsen is a popular hot spring destination in Iki, Nagasaki Prefecture, offering six options for day visits. The area is known for its relaxing atmosphere and therapeutic waters. Visitors can enjoy the natural beauty surrounding the hot springs while indulging in a rejuvenating experience. For more information, you can find Yunomoto Onsen on Google Maps. Additionally, the author has started an Instagram account to share more about their experiences. There are also original orange towels available for purchase through various links provided.' where id = 'Lnqz7IZm0a4tNfc9wQ06T';
update content_bodies set title = '長野県 別所温泉 共同湯', description = '別所温泉には、全3つの公衆浴場（共同湯）があり、伝統的な日本の温泉体験を提供しています。訪れる人々は、自然の温泉水でリラックスし、地域の美しい景観や歴史的な魅力を楽しむことができます。これらの公衆浴場はアクセスが良く、地元の文化やおもてなしを体験する貴重な機会を提供しています。また、日本秘湯を攻める会のオリジナルオレンジタオルが、オンラインで購入可能です。' where id = 'mmmx63ZLXa3l5nahEFqkM';
update content_bodies set title = 'Public Bathhouses in Bessho Onsen, Nagano Prefecture', description = 'Bessho Onsen is home to three public hot springs, known as ''Sotoyu.'' These baths offer a traditional Japanese onsen experience, allowing visitors to relax and enjoy the natural hot spring waters. The area is known for its scenic beauty and historical significance, making it a popular destination for both locals and tourists. The public baths are easily accessible, providing a unique opportunity to experience Japanese culture and hospitality. For those interested in supporting local artisans, original orange towels from the Nihon Hito Onsen Association are available for purchase through various online links.' where id = 'K-NmYtKQr0Ud7ukU1mnra';
update content_bodies set title = '青森県平川市の共同湯', description = '青森県平川市（平賀町）には、全10湯の公衆浴場、いわゆる「共同湯」があります。これらの温泉は地域文化の重要な一部であり、訪れる人々にユニークな体験を提供します。平川市は美しい風景とリラックスした雰囲気で知られています。日本の温泉に興味がある方には、平川市でさまざまな温泉を探索し楽しむ機会があります。また、日本秘湯を攻める会のオリジナルオレンジタオルが販売されており、複数のセットオプションが提供されています。' where id = 'jDQNpX_aM-G--hRvEvg8n';
update content_bodies set title = 'Public Hot Springs in Hirakawa City, Aomori Prefecture', description = 'Hirakawa City, located in Aomori Prefecture, features a total of ten public hot springs, known as ''kyoudou-yu''. These hot springs are a significant part of the local culture and provide a unique experience for visitors. The city is situated in Hiraga Town, which is known for its beautiful landscapes and relaxing atmosphere. For those interested in Japanese hot springs, Hirakawa City offers a variety of options to explore and enjoy. Additionally, there are original orange towels available for purchase from the Japan Hidden Hot Springs Association, with various set options listed on the provided links.' where id = 'CjTOE-pH78xMK2aZznI1m';
update content_bodies set title = '山形県 肘折温泉 共同湯', description = '肘折温泉は、山形県に位置する9つの公衆浴場が特徴の温泉地です。自然の温泉が豊富で、訪れる人々にリラクゼーションとリフレッシュを提供します。共同湯は地域文化の重要な一部であり、ミネラル豊富な温泉の治療効果を楽しむことができます。これらの温泉を探索したい方は、Googleマップで詳細情報を確認できます。また、日本秘湯を攻める会では、オリジナルのオレンジタオルが販売されており、さまざまなセットが提供されています。' where id = 'VNT1H3T1DikldJnxCJsTR';
update content_bodies set title = 'Public Hot Springs in Hijiori Onsen, Yamagata Prefecture', description = 'Hijiori Onsen is known for its nine public hot springs, offering a unique experience for visitors. Located in Yamagata Prefecture, this area is famous for its natural hot springs, providing relaxation and rejuvenation. The public baths, or ''sotoyu'', are a significant part of the local culture, allowing guests to enjoy the therapeutic benefits of the mineral-rich waters. For those interested in exploring these hot springs, detailed information can be found on Google Maps. Additionally, the Japan Secret Hot Springs Association offers original orange towels for sale, available in various sets through provided links.' where id = 'KBhHKvgXi0nW5_tJO2i8m';
update content_bodies set title = '栃木県 那須湯本温泉 共同湯', description = '那須湯本温泉には、訪れる人々に日本の伝統的な入浴文化を体験させるための3つの公衆浴場があります。この地域は自然の温泉で知られ、地元の人々や観光客にリラックスできる雰囲気を提供しています。温泉はアクセスが良く、リラクゼーションやリフレッシュを求める人々に人気のある目的地です。また、日本秘湯を攻める会のオリジナルオレンジタオルなど、購入可能な商品もいくつかあり、リンクから確認できます。' where id = '20_HsrTPmyv68Yabrx2ao';
update content_bodies set title = 'Public Hot Springs in Nasu Yumoto Onsen, Tochigi Prefecture', description = 'Nasu Yumoto Onsen is home to three public hot springs, offering visitors a chance to experience traditional Japanese bathing culture. The area is known for its natural hot springs, providing a relaxing atmosphere for both locals and tourists. The hot springs are easily accessible, making it a popular destination for those seeking relaxation and rejuvenation. Additionally, there are various products available for purchase, including original orange towels from the Nihon Hito Onsen Attack Club, which can be found through the provided links.' where id = 'yOLms2kv5_-6RRin7AdPl';
update content_bodies set title = '大分県 長湯温泉 共同湯', description = '長湯温泉には、全10湯の共同浴場（共同湯）があり、独特の入浴体験を提供しています。アクセスはGoogleマップで確認でき、訪れる際に便利です。また、日本秘湯を攻める会では、オリジナルのオレンジタオルを販売しており、2本、3本、5本セットのリンクが用意されています。これらのタオルはメルカリで購入可能で、訪問者が体験の一部を持ち帰る手段となっています。' where id = 'Ziswk7rfejreaBJK1-cj7';